def keys_status() -> list[dict]:
    """Estado de cada clave SIN exponer su valor (solo si está y cuántos caracteres tiene)."""
    out = []
    for envs, name, what, cost, url in API_KEYS:
        vals = [os.getenv(e) for e in envs]
        out.append({"env": " + ".join(envs), "name": name, "what": what, "cost": cost, "url": url,
                    "ok": all(vals), "partial": any(vals) and not all(vals),
                    "len": sum(len(v) for v in vals if v)})
    return out

def log_keys_status() -> None:
    st = keys_status()
    on = [k["name"] for k in st if k["ok"]]
    off = [k["name"] for k in st if not k["ok"]]
    log.info(f"[CLAVES] {len(on)} configuradas" + (f": {', '.join(on)}" if on else "") + f" · {len(off)} sin configurar" + (f": {', '.join(off)}" if off else ""))
    if ENV_IGNORED:
        log.warning(f"[CLAVES] ignoradas por parecer texto de relleno: {', '.join(ENV_IGNORED)} (pon el valor real o déjalas vacías)")
    for k in st:
        if k["partial"]:
            log.warning(f"[CLAVES] {k['name']}: falta alguna de {k['env']} (se necesitan todas)")
def _persistent_secret() -> str:
    """JWT_SECRET del .env; si no hay, se genera UNA vez y se guarda (permisos 600) para que las sesiones sobrevivan a los reinicios."""
    env = os.getenv("JWT_SECRET")
    if env:
        return env
    f = Path(".nexus_jwt_secret")
    try:
        if f.exists() and len(f.read_text().strip()) >= 32:
            return f.read_text().strip()
        val = secrets.token_hex(32)
        f.write_text(val)
        try:
            os.chmod(f, 0o600)
        except Exception:
            pass
        return val
    except Exception:
        return secrets.token_hex(32)          # disco de solo lectura: como antes (aleatorio por arranque)
