class _RedactFilter(logging.Filter):
    """Nunca deja claves en el log: ni las de tu .env ni parámetros típicos de URL (key=, token=, api_key=…; httpx registra las URL)."""
    _RX = re.compile(r"(?i)((?:api[_-]?key|apikey|key|token|auth[_-]?key|password|passwd|secret|access_token)=)[^&\s'\"]+")
    _BOT = re.compile(r"bot\d{6,}:[A-Za-z0-9_-]{20,}")
    _SK = re.compile(r"\bsk-[A-Za-z0-9_-]{16,}")
    def __init__(self):
        super().__init__()
        self.vals = []
    def refresh(self):
        names = ("OPENAI_API_KEY", "TELEGRAM_BOT_TOKEN", "NASA_FIRMS_MAP_KEY", "OPENSKY_PASS", "FRED_API_KEY", "EIA_API_KEY", "ACLED_PASSWORD",
                 "AISSTREAM_API_KEY", "ADSB_API_KEY", "REDDIT_CLIENT_SECRET", "ABUSECH_AUTH_KEY", "JWT_SECRET", "ADMIN_PASSWORD",
                 "OPENAQ_API_KEY", "CLOUDFLARE_API_TOKEN", "OPENSANCTIONS_API_KEY", "RANSOMWARE_LIVE_KEY", "UCDP_ACCESS_TOKEN")
        self.vals = [v for v in (os.getenv(n) for n in names) if v and len(v) >= 6]
    def filter(self, record: logging.LogRecord) -> bool:
        try:
            msg = record.getMessage()
            for v in self.vals:
                if v in msg:
                    msg = msg.replace(v, "***")
            msg = self._RX.sub(r"\1***", self._BOT.sub("bot***", self._SK.sub("sk-***", msg)))
            record.msg, record.args = msg, None
        except Exception:
            pass
        return True
_REDACT = _RedactFilter(); _REDACT.refresh()
for _h in logging.getLogger().handlers:
    _h.addFilter(_REDACT)

