async def _rotate_ua(request) -> None:
    host = (getattr(request.url, "host", "") or "").lower()
    if any(host == h or host.endswith("." + h) for h in FIXED_UA_HOSTS):
        request.headers["User-Agent"] = FIXED_UA
        request.headers["Api-User-Agent"] = FIXED_UA
        return
    request.headers["User-Agent"] = random.choice(UA_POOL)
    request.headers["Accept-Language"] = random.choice(ACCEPT_LANGS)

HTTP = httpx.AsyncClient(
    event_hooks={"request": [_rotate_ua]},
    timeout=25,
    headers={"User-Agent": "NEXUS-OSINT/3.1"},
    follow_redirects=True,
    limits=httpx.Limits(max_connections=100, max_keepalive_connections=20),
)
