# Referencias a tareas en segundo plano (evita que el GC las cancele)
BG_TASKS: set = set()

def _spawn(coro) -> asyncio.Task:
    t = asyncio.create_task(coro)
    BG_TASKS.add(t)
    t.add_done_callback(BG_TASKS.discard)
    return t

