# § 0.bis. HELPERS GENERALES
# ═══════════════════════════════════════════════════════════════════════

def _num(v, default: float = 0.0) -> float:
    """Convierte a float tratando None/NaN/valores inválidos como default."""
    try:
        f = float(v)
        return default if math.isnan(f) else f
    except (TypeError, ValueError):
        return default

def _str(v) -> str:
    """Devuelve v si es str; si es None/NaN/otro tipo devuelve ''."""
    return v if isinstance(v, str) else ""

def _records(df: pd.DataFrame) -> list[dict]:
    """DataFrame -> lista de dicts JSON-safe (NaN -> None)."""
    if df is None or df.empty:
        return []
    return df.astype(object).where(pd.notna(df), None).to_dict("records")


# ═══════════════════════════════════════════════════════════════════════
# § 1. AUTENTICACIÓN
# ═══════════════════════════════════════════════════════════════════════

def _safe_eq(a: str, b: str) -> bool:
    return hmac.compare_digest((a or "").encode(), (b or "").encode())

def make_token(username: str) -> str:
    payload = {
        "sub": username,
        "iat": datetime.now(timezone.utc),
        "exp": datetime.now(timezone.utc) + timedelta(hours=JWT_EXP_HOURS),
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGO)

def verify_token(token: str) -> Optional[str]:
    try:
        payload = jwt.decode(token, JWT_SECRET, algorithms=[JWT_ALGO])
        return payload.get("sub")
    except jwt.PyJWTError:
        return None

def _default_pw_blocked(request: Optional[Request]) -> bool:
    """Con la contraseña por defecto (admin123) solo se entra desde este equipo: desde fuera no sirve aunque la sepan."""
    if not DEFAULT_PW or request is None:
        return False
    host = request.client.host if request.client else ""
    return host not in LOOPBACK_HOSTS or any(h in request.headers for h in ("x-forwarded-for", "x-real-ip", "forwarded"))

async def current_user(
    request: Request,
    basic: Optional[HTTPBasicCredentials] = Depends(BASIC_AUTH),
    bearer: Optional[HTTPAuthorizationCredentials] = Depends(BEARER),
) -> Optional[str]:
    if bearer and bearer.credentials:
        user = verify_token(bearer.credentials)
        if user:
            return user
    if basic and _safe_eq(basic.username, ADMIN_USER) and _safe_eq(basic.password, ADMIN_PASSWORD) and not _default_pw_blocked(request):
        return ADMIN_USER
    return None

async def require_user(user: Optional[str] = Depends(current_user)) -> str:
    if not user:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Autenticación requerida",
            headers={"WWW-Authenticate": "Basic"},
        )
    return user

# Desde el propio equipo (loopback) no se pide usuario/contraseña para el dashboard.
# Desde cualquier otra IP, o detrás de un proxy inverso, sigue exigiéndose autenticación.
# Para desactivarlo: NEXUS_LOCAL_NOAUTH=0 en el .env
LOCAL_NOAUTH = os.getenv("NEXUS_LOCAL_NOAUTH", "1") != "0"
LOOPBACK_HOSTS = {"127.0.0.1", "::1", "localhost"}

def _is_local(request: Request) -> bool:
    host = request.client.host if request.client else ""
    if host not in LOOPBACK_HOSTS:
        return False
    if any(h in request.headers for h in ("x-forwarded-for", "x-real-ip", "forwarded", "x-forwarded-host", "via")):  # tras un proxy inverso no es local de verdad
        return False
    # Anti-CSRF / DNS-rebinding: una web ajena abierta en tu navegador también llega desde
    # 127.0.0.1, así que solo se acepta si el origen y el Host son del propio servidor.
    host_hdr = (request.headers.get("host") or "").rsplit(":", 1)[0].strip("[]").lower()
    if host_hdr not in LOOPBACK_HOSTS:
        return False
    origin = request.headers.get("origin")
    if origin and urlparse(origin).netloc != request.headers.get("host", ""):
        return False
    if request.headers.get("sec-fetch-site", "same-origin") not in ("same-origin", "none"):
        return False
    return True

async def require_user_or_local(
    request: Request, user: Optional[str] = Depends(current_user),
) -> str:
    if user:
        return user
    if LOCAL_NOAUTH and _is_local(request):
        return "local"
    raise HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Autenticación requerida",
        headers={"WWW-Authenticate": "Basic"},
    )


# ═══════════════════════════════════════════════════════════════════════
# § 2. CACHÉ Y CIRCUIT BREAKER
# ═══════════════════════════════════════════════════════════════════════

def cache_get(key: str) -> Optional[Any]:
    entry = CACHE.get(key)
    if not entry:
        return None
    ts, val = entry
    if time.time() - ts > CACHE_TTL:
        CACHE.pop(key, None)
        return None
    return val

def cache_set(key: str, val: Any) -> None:
    CACHE[key] = (time.time(), val)

def cache_clear() -> None:
    CACHE.clear()

def circuit_is_open(source: str) -> bool:
    until = CIRCUIT_OPEN.get(source)
    return until is not None and time.time() < until

def circuit_record(source: str, success: bool, duration_ms: int) -> None:
    h = SOURCE_HEALTH[source]
    if success:
        h["ok"] += 1
        h["last_ok"] = datetime.now(timezone.utc).isoformat()
        h["fail"] = max(0, h["fail"] - 1)
        CIRCUIT_OPEN.pop(source, None)
    else:
        h["fail"] += 1
        h["last_fail"] = datetime.now(timezone.utc).isoformat()
        if h["fail"] >= CIRCUIT_FAIL_THRESHOLD:
            CIRCUIT_OPEN[source] = time.time() + CIRCUIT_OPEN_SECONDS
            log.warning(f"[CIRCUIT] Abierto para {source} por {CIRCUIT_OPEN_SECONDS}s")
    h["avg_ms"] = int(0.8 * h["avg_ms"] + 0.2 * duration_ms) if h["avg_ms"] else duration_ms


