SCHEMA = """
PRAGMA journal_mode = WAL;
PRAGMA synchronous = NORMAL;
CREATE TABLE IF NOT EXISTS events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sweep_id TEXT NOT NULL,
    timestamp TEXT NOT NULL,
    domain TEXT NOT NULL,
    source TEXT NOT NULL,
    lat REAL NOT NULL,
    lon REAL NOT NULL,
    severity TEXT NOT NULL,
    title TEXT,
    description TEXT,
    url TEXT,
    entities TEXT,
    sentiment REAL DEFAULT 0,
    tags TEXT,
    raw_hash TEXT UNIQUE
);
CREATE INDEX IF NOT EXISTS idx_events_ts ON events(timestamp);
CREATE INDEX IF NOT EXISTS idx_events_domain ON events(domain);
CREATE INDEX IF NOT EXISTS idx_events_source ON events(source);
CREATE INDEX IF NOT EXISTS idx_events_severity ON events(severity);
CREATE TABLE IF NOT EXISTS correlations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sweep_id TEXT,
    timestamp TEXT,
    domain_a TEXT, source_a TEXT,
    domain_b TEXT, source_b TEXT,
    lat REAL, lon REAL,
    distance REAL,
    score INTEGER,
    description TEXT
);
CREATE INDEX IF NOT EXISTS idx_corr_score ON correlations(score);
CREATE TABLE IF NOT EXISTS sweeps (
    sweep_id TEXT PRIMARY KEY,
    started_at TEXT, finished_at TEXT,
    event_count INTEGER, correlation_count INTEGER,
    duration_ms INTEGER, errors TEXT
);
CREATE TABLE IF NOT EXISTS source_health (
    source TEXT PRIMARY KEY,
    ok INTEGER, fail INTEGER,
    last_ok TEXT, last_fail TEXT, avg_ms INTEGER
);
CREATE TABLE IF NOT EXISTS anomalies (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT, domain TEXT, metric TEXT,
    value REAL, zscore REAL, description TEXT
);
CREATE TABLE IF NOT EXISTS geo_cache (
    ip TEXT PRIMARY KEY, lat REAL, lon REAL, ts TEXT, cc TEXT
);
CREATE TABLE IF NOT EXISTS group_ips (
    ip TEXT, grp TEXT, kind TEXT, role TEXT, cc TEXT, lat REAL, lon REAL,
    source TEXT, url TEXT, conf TEXT, first_seen TEXT, last_seen TEXT, live_seen TEXT,
    PRIMARY KEY (ip, grp)
);
CREATE INDEX IF NOT EXISTS idx_gips_grp ON group_ips(grp);
CREATE TABLE IF NOT EXISTS group_names (
    name TEXT PRIMARY KEY, kind TEXT, first_seen TEXT
);
CREATE TABLE IF NOT EXISTS app_kv (
    k TEXT PRIMARY KEY, v TEXT
);
CREATE TABLE IF NOT EXISTS group_detections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ts TEXT, grp TEXT, kind TEXT, atype TEXT, src_kind TEXT, source TEXT, title TEXT, url TEXT,
    victims TEXT, nips INTEGER, health INTEGER, energy INTEGER, detected TEXT,
    UNIQUE (url, grp)
);
CREATE INDEX IF NOT EXISTS idx_gdet_ts ON group_detections(ts);
CREATE TABLE IF NOT EXISTS group_candidates (word TEXT PRIMARY KEY, freq INTEGER, last_seen TEXT);
CREATE TABLE IF NOT EXISTS audit_log (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT, user TEXT, action TEXT, detail TEXT, ip TEXT
);
"""

def db_conn() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH, timeout=20)
    conn.row_factory = sqlite3.Row
    try:
        conn.execute("PRAGMA busy_timeout = 20000")
        conn.execute("PRAGMA synchronous = NORMAL")      # con WAL es seguro y evita esperas de disco lentas
    except sqlite3.Error:
        pass
    return conn

_DB_WRITE_LOCK = threading.RLock()      # una sola escritura a la vez dentro de NEXUS: el barrido y el detector ya no se pisan
def db_write(fn):
    """Serializa las escrituras y reintenta si SQLite responde «database is locked» (otro proceso, disco lento…)."""
    @functools.wraps(fn)
    def _w(*a, **k):
        for i in range(5):
            try:
                with _DB_WRITE_LOCK:
                    return fn(*a, **k)
            except sqlite3.OperationalError as e:
                if "locked" not in str(e).lower() or i == 4:
                    raise
                time.sleep(0.5 * (i + 1))
    return _w

def _migrate_schema(conn: sqlite3.Connection) -> None:
    """★ NUEVO: una BD creada con una versión anterior no tiene las columnas nuevas (entities, tags…) y todos los
    INSERT fallaban con «no column named entities». Se añaden las columnas que falten, sin tocar los datos."""
    for tbl, body in re.findall(r"CREATE TABLE IF NOT EXISTS (\w+) \((.*?)\n\);", SCHEMA, re.S):
        have = {r[1] for r in conn.execute(f"PRAGMA table_info({tbl})").fetchall()}
        if not have:
            continue
        for part in body.split(","):
            toks = part.strip().split()
            if len(toks) < 2 or toks[0].upper() in ("PRIMARY", "UNIQUE", "FOREIGN", "CHECK"):
                continue
            name, typ = toks[0], toks[1]
            if name in have:
                continue
            default = ""
            m = re.search(r"DEFAULT\s+(\S+)", part, re.I)
            if m:
                default = f" DEFAULT {m.group(1)}"
            try:
                conn.execute(f"ALTER TABLE {tbl} ADD COLUMN {name} {typ}{default}")
                log.warning(f"[DB] migración: añadida columna {tbl}.{name}")
                have.add(name)
            except sqlite3.OperationalError as e:
                log.error(f"[DB] no se pudo añadir {tbl}.{name}: {e}")
    try:
        conn.execute("CREATE UNIQUE INDEX IF NOT EXISTS idx_events_hash ON events(raw_hash)")
    except sqlite3.OperationalError as e:
        log.warning(f"[DB] índice único de raw_hash no creado: {e}")

def init_db() -> None:
    conn = db_conn()
    conn.executescript(SCHEMA)
    _migrate_schema(conn)
    try:
        conn.execute("ALTER TABLE group_ips ADD COLUMN live_seen TEXT")      # BD creada con la versión anterior
    except sqlite3.OperationalError:
        pass
    conn.commit()
    try:     # geolocalizaciones ya conocidas: sobreviven a los reinicios y ahorran peticiones a ip-api
        for ip, la, lo, cc in conn.execute("SELECT ip, lat, lon, cc FROM geo_cache").fetchall():
            _GEO_CACHE[ip] = (float(la), float(lo))
            if cc:
                _GEO_CC[ip] = cc
        if _GEO_CACHE:
            log.info(f"[GEO] {len(_GEO_CACHE)} IPs en la caché persistente")
    except sqlite3.Error as e:
        log.warning(f"[GEO] no se pudo cargar la caché: {e}")
    conn.close()

@db_write
def db_audit(user: str, action: str, detail: str = "", ip: str = "") -> None:
    conn = db_conn()
    conn.execute(
        "INSERT INTO audit_log (timestamp,user,action,detail,ip) VALUES (?,?,?,?,?)",
        (datetime.now(timezone.utc).isoformat(), user, action, detail[:500], ip),
    )
    conn.commit()
    conn.close()

# ─── ★ NUEVO · PRENSA SIN RUIDO: UNA HISTORIA = UN PUNTO ─────────────────────────────────────────────────────────────────────────
# Cada periódico geocodifica el titular y pone su propio punto donde ocurre el hecho; la huella de cada evento incluye la fuente, así que 8 medios
# contando el mismo ataque dan 8 puntos apilados. Aquí se agrupan por HISTORIA (mismo lugar + titular parecido + ventana de tiempo): se conserva la
# fuente más fiable como representante y las demás se cuentan como corroboración («También: X, Y» y etiqueta corrob:N). Solo afecta a la prensa
# (etiqueta «prensa»): sensores, DDoS, IPs, etc. no se tocan. NEXUS_PRESS_DEDUP=0 lo apaga.
PRESS_DEDUP = os.getenv("NEXUS_PRESS_DEDUP", "1") != "0"
try:
    PRESS_SIM = float(os.getenv("NEXUS_PRESS_SIM", "0.80"))
    PRESS_WINDOW_H = float(os.getenv("NEXUS_PRESS_WINDOW_H", "48"))
except ValueError:
    PRESS_SIM, PRESS_WINDOW_H = 0.80, 48.0
_PRESS_STATE = ("xinhua", "irna", "sana", "tass", "press tv", "presstv", "anadolu", "cgtn", "global times", "tasnim", "sputnik", "kcna", "ria novosti")
_PRESS_WIRE = ("reuters", "associated press", "ap news", "deutsche welle", "france 24", "france24", "guardian", "al jazeera", "aljazeera", "noticias onu", "un news",
               "euronews", "kyodo", "nhk", "ansa", "bbc")
_PRESS_STOP = {"the", "los", "las", "una", "uno", "and", "con", "por", "para", "from", "del", "after", "says", "dice", "tras", "sobre", "about", "news", "noticias"}

def press_rank(source: str) -> int:
    """0 = agencia / servicio público internacional · 1 = resto de prensa · 2 = medio estatal (sirve, pero con sesgo de gobierno)."""
    s = f" {(source or '').lower()} "
    if any(w in s for w in _PRESS_STATE):
        return 2
    if any(w in s for w in _PRESS_WIRE) or re.search(r"\b(dw|ap|afp|npr|efe|rfi)\b", s):
        return 0
    return 1

def _pnorm(t: str) -> str:
    import unicodedata
    t = unicodedata.normalize("NFKD", (t or "").lower()).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]+", " ", t)).strip()

def _pproper(t: str) -> set:
    """Nombres propios (lugares, personas, grupos): casi no cambian de idioma, por eso sirven para reconocer la misma historia en español y en inglés."""
    words = [m.group(0) for m in re.finditer(r"[A-ZÁÉÍÓÚÜÑ][\w'’\-]{2,}", t or "") if m.start() > 0]    # la palabra con la que EMPIEZA el titular va en mayúscula siempre: no cuenta
    return {w for w in (_pnorm(x) for x in words) if w and w not in _PRESS_STOP}

_PRESS_NUMW = {"three": "3", "tres": "3", "four": "4", "cuatro": "4", "five": "5", "cinco": "5", "six": "6", "seis": "6", "seven": "7", "siete": "7", "eight": "8", "ocho": "8",
               "nine": "9", "nueve": "9", "ten": "10", "diez": "10", "eleven": "11", "once": "11", "twelve": "12", "doce": "12", "twenty": "20", "veinte": "20",
               "thirty": "30", "treinta": "30", "fifty": "50", "cincuenta": "50", "hundred": "100", "cien": "100", "ciento": "100"}

def _pnums(t: str) -> set:
    """Cifras del titular (también escritas con letras, en inglés y español), sin separadores: «6,1» y «6.1» son lo mismo. Ignora 0, 1 y 2 (demasiado comunes)."""
    nums = {re.sub(r"\D", "", n) for n in re.findall(r"\d[\d.,]*\d|\d", t or "")}
    nums |= {_PRESS_NUMW[w] for w in _pnorm(t).split() if w in _PRESS_NUMW}
    return nums - {"", "0", "1", "2"}

def press_same(a: str, b: str) -> bool:
    """¿Es el mismo hecho contado por dos medios? Titular casi igual, o mismos nombres propios (mín. 3, o 2 si coinciden casi todos), o un nombre propio y la misma cifra.
    Si ambos traen cifras y no comparten ninguna, NO es la misma historia."""
    import difflib
    nua, nub = _pnums(a), _pnums(b)
    if nua and nub and not (nua & nub):                 # cifras distintas («3 muertos» / «5 muertos»): son partes distintos, aunque el titular sea casi igual
        return False
    na, nb = _pnorm(a), _pnorm(b)
    if na and nb and difflib.SequenceMatcher(None, na, nb).ratio() >= PRESS_SIM:
        return True
    pa, pb = _pproper(a), _pproper(b)
    inter = pa & pb
    union = pa | pb
    if len(inter) >= 3 or (len(inter) >= 2 and len(inter) / max(1, len(union)) >= 0.75):
        return True
    return bool(inter and (nua & nub))

def _press_merge_text(desc: str, tags: str, sev: str, others: list) -> tuple:
    """Añade «También: …» y corrob:N al representante, y sube la gravedad al máximo que haya visto cualquiera de los medios."""
    srcs = list(dict.fromkeys(o for o, _ in others))
    prev = re.search(r"corrob:(\d+)", tags or "")
    n = (int(prev.group(1)) if prev else 0) + len(srcs)
    tags = re.sub(r",?corrob:\d+", "", tags or "") + f",corrob:{n}"
    tags = tags.lstrip(",")
    if srcs:
        add = " · También: " + ", ".join(srcs[:5]) + ("…" if len(srcs) > 5 else "")
        desc = ((desc or "") + add)[:600]
    best = min([sev] + [s for _, s in others], key=lambda x: _SEV_RANK.get(x, 4))
    return desc, tags, best

def press_dedup(conn, rows: list) -> list:
    """Quita de la tanda las noticias que repiten una historia ya contada (en esta tanda o en las últimas horas de la base de datos).
    Las que SÍ se insertan salen enriquecidas con sus corroboraciones; si el duplicado es de algo ya guardado, se actualiza esa fila."""
    if not PRESS_DEDUP or not rows:
        return rows
    idx = [i for i, r in enumerate(rows) if "prensa" in (r.get("tags") or "").split(",")]
    if not idx:
        return rows
    since = (datetime.now(timezone.utc) - timedelta(hours=PRESS_WINDOW_H)).isoformat()
    cells: dict = {}
    cell = lambda la, lo: (int(la // 0.5), int(lo // 0.5))
    try:
        for e in conn.execute("SELECT id, lat, lon, source, title, description, tags, severity FROM events WHERE timestamp >= ? AND tags LIKE '%prensa%' "
                              "ORDER BY id DESC LIMIT 6000", (since,)).fetchall():
            cells.setdefault(cell(e[1], e[2]), []).append({"db": e[0], "lat": e[1], "lon": e[2], "src": e[3], "title": e[4], "desc": e[5], "tags": e[6], "sev": e[7], "others": []})
    except sqlite3.Error:
        pass
    drop: set = set()
    for i in sorted(idx, key=lambda i: (press_rank(rows[i].get("source")), i)):          # primero las fuentes más fiables: ellas serán las representantes
        r = rows[i]
        try:
            la, lo = float(r["lat"]), float(r["lon"])
        except (TypeError, ValueError, KeyError):
            continue
        cx, cy = cell(la, lo)
        hit = None
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                for c in cells.get((cx + dx, cy + dy), []):
                    if abs(c["lat"] - la) <= 0.35 and abs(c["lon"] - lo) <= 0.35 and press_same(c["title"], r.get("title", "")):
                        hit = c
                        break
                if hit: break
            if hit: break
        if hit is None:
            cells.setdefault((cx, cy), []).append({"db": None, "row": r, "lat": la, "lon": lo, "src": r.get("source"), "title": r.get("title", ""), "others": []})
        else:
            drop.add(i)
            hit["others"].append((r.get("source") or "?", r.get("severity") or "BAJA"))
    for lst in cells.values():
        for c in lst:
            others = [o for o in c["others"] if o[0] != c["src"]]
            if not c["others"]:
                continue
            if c["db"] is None:
                r = c["row"]
                r["description"], r["tags"], r["severity"] = _press_merge_text(r.get("description", ""), r.get("tags", ""), r.get("severity", "BAJA"), others)
            else:
                d, t, s = _press_merge_text(c["desc"], c["tags"], c["sev"], others)
                try:
                    conn.execute("UPDATE events SET description=?, tags=?, severity=? WHERE id=?", (d, t, s, c["db"]))
                except sqlite3.Error:
                    pass
    if drop:
        log.info(f"[PRENSA] {len(drop)} noticias repetidas se funden con la historia que ya contaba otro medio (de {len(idx)} de prensa en la tanda)")
    return [r for i, r in enumerate(rows) if i not in drop]

@db_write
def db_save_events(sweep_id: str, rows: list[dict]) -> int:
    """Inserta eventos nuevos y marca con r['_new']=True los que realmente se insertaron."""
    if not rows:
        return 0
    conn = db_conn()
    cur = conn.cursor()
    try:
        rows = press_dedup(conn, rows)             # una historia = un punto (solo prensa)
    except Exception as e:
        log.warning(f"[PRENSA] no se pudo agrupar por historia: {type(e).__name__}: {e}")
    n = 0
    for r in rows:
        h = hashlib.sha256(
            f"{r['domain']}|{r['source']}|{r['lat']:.4f}|{r['lon']:.4f}|{r.get('title','')}".encode()
        ).hexdigest()
        try:
            cur.execute(
                """INSERT INTO events
                (sweep_id,timestamp,domain,source,lat,lon,severity,title,description,url,entities,sentiment,tags,raw_hash)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                (
                    sweep_id, r["timestamp"], r["domain"], r["source"], r["lat"], r["lon"],
                    r["severity"], r.get("title", ""), r.get("description", ""),
                    r.get("url", ""), r.get("entities", ""), _num(r.get("sentiment", 0.0)),
                    r.get("tags", ""), h,
                ),
            )
            r["_new"] = True
            n += 1
        except sqlite3.IntegrityError:
            pass
    conn.commit()
    conn.close()
    return n

@db_write
def db_save_correlations(sweep_id: str, corrs: list[dict]) -> None:
    if not corrs:
        return
    conn = db_conn()
    since = (datetime.now(timezone.utc) - timedelta(hours=24)).isoformat()
    for c in corrs:
        if conn.execute(
            "SELECT 1 FROM correlations WHERE timestamp > ? AND domain_a=? AND source_a=? AND domain_b=? AND source_b=? "
            "AND ABS(lat-?)<0.05 AND ABS(lon-?)<0.05 AND description=? LIMIT 1",
            (since, c["domain_a"], c["source_a"], c["domain_b"], c["source_b"], c["lat"], c["lon"], c["description"]),
        ).fetchone():
            continue          # la misma correlación ya está guardada (los barridos repiten eventos viejos)
        conn.execute(
            """INSERT INTO correlations
            (sweep_id,timestamp,domain_a,source_a,domain_b,source_b,lat,lon,distance,score,description)
            VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
            (sweep_id, c["timestamp"], c["domain_a"], c["source_a"], c["domain_b"],
             c["source_b"], c["lat"], c["lon"], c["distance"], c["score"], c["description"]),
        )
    conn.commit()
    conn.close()

