def _build_where(hours: Optional[int], domains: Optional[list[str]],
                 severities: Optional[list[str]], sources: Optional[list[str]],
                 search: Optional[str]) -> tuple[str, list]:
    q = " WHERE 1=1"
    p: list = []
    if hours:
        since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()
        q += " AND timestamp > ?"
        p.append(since)
    if domains:
        q += f" AND domain IN ({','.join(['?'] * len(domains))})"
        p.extend(domains)
    if severities:
        q += f" AND severity IN ({','.join(['?'] * len(severities))})"
        p.extend(severities)
    if sources:
        q += f" AND source IN ({','.join(['?'] * len(sources))})"
        p.extend(sources)
    if search:
        q += " AND (title LIKE ? OR description LIKE ? OR tags LIKE ?)"
        like = f"%{search}%"
        p.extend([like, like, like])
    return q, p

def db_query_events(
    hours: Optional[int] = 6, domains: Optional[list[str]] = None,
    severities: Optional[list[str]] = None, sources: Optional[list[str]] = None,
    search: Optional[str] = None, limit: int = 800,
) -> pd.DataFrame:
    conn = db_conn()
    where, p = _build_where(hours, domains, severities, sources, search)
    q = "SELECT * FROM events" + where + " ORDER BY id DESC LIMIT ?"
    p.append(limit)
    df = pd.read_sql(q, conn, params=p)
    conn.close()
    return apply_mutes(df)

def db_query_correlations(hours: int = 24, min_score: int = 0, limit: int = 100) -> pd.DataFrame:
    conn = db_conn()
    since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()
    df = pd.read_sql(
        "SELECT * FROM correlations WHERE timestamp > ? AND score >= ? ORDER BY score DESC LIMIT ?",
        conn, params=(since, min_score, limit),
    )
    conn.close()
    return df

def db_query_anomalies(hours: int = 24, limit: int = 50) -> pd.DataFrame:
    conn = db_conn()
    since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()
    df = pd.read_sql(
        "SELECT * FROM anomalies WHERE timestamp > ? ORDER BY zscore DESC LIMIT ?",
        conn, params=(since, limit),
    )
    conn.close()
    return df

def db_stats() -> dict:
    conn = db_conn()
    total = conn.execute("SELECT COUNT(*) FROM events").fetchone()[0]
    by_dom = {r[0]: r[1] for r in conn.execute("SELECT domain, COUNT(*) FROM events GROUP BY domain").fetchall()}
    by_sev = {r[0]: r[1] for r in conn.execute("SELECT severity, COUNT(*) FROM events GROUP BY severity").fetchall()}
    by_src = {r[0]: r[1] for r in conn.execute("SELECT source, COUNT(*) FROM events GROUP BY source").fetchall()}
    last_sweep = conn.execute("SELECT finished_at FROM sweeps ORDER BY started_at DESC LIMIT 1").fetchone()
    conn.close()
    return {
        "total_events": total, "by_domain": by_dom, "by_severity": by_sev,
        "by_source": by_src,
        "last_sweep": last_sweep[0] if last_sweep else None,
    }


GROUP_IP_KEEP_DAYS = int(os.getenv("NEXUS_GROUP_IP_KEEP_DAYS", "30"))    # las IPs de grupos son TEMPORALES: se borran si no se vuelven a ver en N días (0 = nunca)
GROUP_IP_CAP = int(os.getenv("NEXUS_GROUP_IP_CAP", "1500"))               # máx. IPs por grupo (se quedan las más recientes)
GROUP_FRESH_HOURS = float(os.getenv("NEXUS_GROUP_FRESH_HOURS", "72"))     # «fresca» = vista EN VIVO en las últimas N horas

@db_write
def db_upsert_group_ips(rows: list[dict]) -> int:
    """Registro TEMPORAL de IPs atribuidas a grupos (una fila por IP y grupo). Cada fila lleva `live`: True si la IP se ha visto EN VIVO
    ahora (monitor de listas frescas, mensaje de Telegram, noticia). Las de listas históricas (live=False) no se «refrescan» solas."""
    if not rows:
        return 0
    now = datetime.now(timezone.utc).isoformat()
    conn = db_conn()
    conn.executemany(
        """INSERT INTO group_ips (ip,grp,kind,role,cc,lat,lon,source,url,conf,first_seen,last_seen,live_seen)
           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)
           ON CONFLICT(ip,grp) DO UPDATE SET kind=excluded.kind, cc=excluded.cc, lat=excluded.lat, lon=excluded.lon,
             last_seen=CASE WHEN excluded.live_seen IS NOT NULL THEN excluded.last_seen ELSE group_ips.last_seen END,
             live_seen=CASE WHEN excluded.live_seen IS NOT NULL THEN excluded.live_seen ELSE group_ips.live_seen END,
             role=CASE WHEN excluded.live_seen IS NOT NULL OR group_ips.live_seen IS NULL THEN excluded.role ELSE group_ips.role END,
             source=CASE WHEN excluded.live_seen IS NOT NULL OR group_ips.live_seen IS NULL THEN excluded.source ELSE group_ips.source END,
             url=CASE WHEN excluded.live_seen IS NOT NULL OR group_ips.live_seen IS NULL THEN excluded.url ELSE group_ips.url END,
             conf=CASE WHEN group_ips.conf='feed' AND excluded.conf!='feed' THEN group_ips.conf ELSE excluded.conf END""",
        [(r["ip"], r["grp"], r.get("kind", ""), r.get("role", ""), r.get("cc", ""), r["lat"], r["lon"],
          r.get("source", ""), r.get("url", ""), r.get("conf", "feed"), now, now, now if r.get("live") else None) for r in rows])
    conn.executemany("INSERT OR IGNORE INTO group_names (name,kind,first_seen) VALUES (?,?,?)",     # el NOMBRE del grupo se recuerda siempre (aunque sus IPs caduquen)
                     [(r["grp"], r.get("kind", ""), now) for r in rows])
    conn.commit()
    conn.close()
    return len(rows)

def db_group_ips(group: str = "", limit: int = 6000, fresh_hours: float = GROUP_FRESH_HOURS) -> tuple[list[dict], list[dict]]:
    """(IPs, resumen por grupo ORDENADO POR NOMBRE). fresh_hours>0: solo IPs vistas en vivo en esas horas; 0 = todas (incluye listas históricas)."""
    conn = db_conn()
    w, wp = "", []
    if fresh_hours and fresh_hours > 0:
        w = " WHERE live_seen > ?"
        wp = [(datetime.now(timezone.utc) - timedelta(hours=fresh_hours)).isoformat()]
    cnt = {r[0]: (r[1] or "", r[2], r[3]) for r in conn.execute(
        f"SELECT grp, MAX(kind), COUNT(*), COUNT(DISTINCT cc) FROM group_ips{w} GROUP BY grp", wp).fetchall()}
    names = {n: k for n, k in ((a[0], a[1]) for a in ACTOR_GROUPS)}                  # catálogo completo de grupos
    for n, k in conn.execute("SELECT name, kind FROM group_names").fetchall():       # + todo grupo al que alguna vez se asignaron IPs
        names.setdefault(n, k or "")
    for n, k in conn.execute("SELECT DISTINCT grp, MAX(kind) FROM group_ips GROUP BY grp").fetchall():
        names.setdefault(n, k or "")
    summ = [{"name": n, "kind": (cnt.get(n, ("",))[0] or names[n] or ""), "n": cnt.get(n, ("", 0, 0))[1], "countries": cnt.get(n, ("", 0, 0))[2]}
            for n in sorted(names, key=str.lower)]
    q, p = "SELECT ip,grp,kind,role,cc,lat,lon,source,url,conf,live_seen,last_seen FROM group_ips" + w, list(wp)
    if group:
        q += (" AND" if w else " WHERE") + " grp = ?"
        p.append(group)
    q += " ORDER BY grp COLLATE NOCASE, COALESCE(live_seen, last_seen) DESC LIMIT ?"
    p.append(max(1, min(int(limit), 20000)))
    now = datetime.now(timezone.utc)
    def age_h(ts):
        try:
            return round((now - datetime.fromisoformat(ts)).total_seconds() / 3600, 1)
        except Exception:
            return None
    ips = [{"ip": r[0], "g": r[1], "k": r[2] or "", "r": r[3] or "", "cc": r[4] or "", "la": round(r[5], 3), "lo": round(r[6], 3),
            "s": r[7] or "", "u": _safe_url(r[8]), "f": "l" if r[10] else "h", "rep": r[9] == "reportada", "h": age_h(r[10] or r[11])}
           for r in conn.execute(q, p).fetchall() if r[5] is not None and r[6] is not None]      # una IP sin geolocalizar no puede romper toda la respuesta
    conn.close()
    return ips, summ

RETENTION_DAYS = int(os.getenv("NEXUS_RETENTION_DAYS", "120"))   # 4 meses: cubre la ventana de 3 meses del panel

SHIP_KEEP_HOURS = int(os.getenv("NEXUS_SHIP_KEEP_HOURS", "48"))        # horas que se guardan las posiciones de barcos
KEEP_CYBER = os.getenv("NEXUS_KEEP_CYBER", "important").lower()    # important (por defecto) | all | off
_CYBER_ALWAYS = ("cibercrimen", "ransomware")

def protected_events_sql() -> str:
    """Condición SQL de los eventos de cibercrimen que NUNCA se borran (ni por retención ni por el botón de reset).
    important: cibercrimen y ransomware (todo), más ataques/malware/exploits/phishing/DDoS con severidad ALTA/CRÍTICA o reivindicados por un grupo.
    all: todo el dominio cibernético. off: nada protegido."""
    if KEEP_CYBER == "off":
        return "0"
    q = lambda xs: ",".join("'" + x + "'" for x in xs)
    if KEEP_CYBER == "all":
        return f"domain IN ({q(CYBER_DOMAINS)})"
    return (f"(domain IN ({q(_CYBER_ALWAYS)}) OR (domain IN ({q(CYBER_DOMAINS)}) AND "
            f"(severity IN ('CRITICA','ALTA') OR tags LIKE '%grupo:%' OR tags LIKE '%reivindicado%')))")

@db_write
def db_prune(days: int = RETENTION_DAYS) -> dict:
    """★ NUEVO: borra eventos/correlaciones/anomalías más antiguos que `days` (0 = no borrar nunca)."""
    try:     # los barcos son posiciones (una fila por barco y barrido ≈ 40.000 al día): solo se guardan unas horas, el resto del historial no se toca
        conn0 = db_conn()
        n_sh = conn0.execute("DELETE FROM events WHERE domain='maritimo' AND timestamp < ?", ((datetime.now(timezone.utc) - timedelta(hours=SHIP_KEEP_HOURS)).isoformat(),)).rowcount
        conn0.commit(); conn0.close()
        if n_sh:
            log.info(f"[DB] posiciones de barcos antiguas borradas: {n_sh}")
    except Exception as ex:
        log.warning(f"[DB] limpieza de barcos: {type(ex).__name__}: {ex}")
    if days <= 0:
        return {"events": 0, "correlations": 0, "anomalies": 0}
    since = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat()
    conn = db_conn()
    out = {}
    for t in ("events", "correlations", "anomalies", "audit_log"):
        extra = f" AND NOT {protected_events_sql()}" if t == "events" else ""     # la intel de cibercrimen no se purga nunca
        out[t] = conn.execute(f"DELETE FROM {t} WHERE timestamp < ?{extra}", (since,)).rowcount
    if GROUP_IP_KEEP_DAYS > 0:
        gs = (datetime.now(timezone.utc) - timedelta(days=GROUP_IP_KEEP_DAYS)).isoformat()
        out["group_ips"] = conn.execute("DELETE FROM group_ips WHERE COALESCE(live_seen, last_seen) < ?", (gs,)).rowcount
        out["group_ips"] += conn.execute(           # tope por grupo: se quedan las más recientes
            """DELETE FROM group_ips WHERE rowid IN (SELECT rowid FROM (
                 SELECT rowid, ROW_NUMBER() OVER (PARTITION BY grp ORDER BY COALESCE(live_seen, last_seen) DESC) rn FROM group_ips) WHERE rn > ?)""",
            (GROUP_IP_CAP,)).rowcount
        conn.execute("DELETE FROM audit_log WHERE rowid NOT IN (SELECT rowid FROM audit_log ORDER BY rowid DESC LIMIT 50000)")    # tope: nunca más de 50.000 filas
        if KEEP_CYBER == "off":      # el historial de detecciones de grupos también se conserva (salvo NEXUS_KEEP_CYBER=off)
            conn.execute("DELETE FROM group_detections WHERE ts < ?", ((datetime.now(timezone.utc) - timedelta(days=GROUP_IP_KEEP_DAYS * 3)).isoformat(),))
    conn.commit()
    try:
        conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
    except Exception:
        pass
    conn.close()
    if any(out.values()):
        log.info(f"[DB] retención {days}d: {out}")
    return out


# ═══════════════════════════════════════════════════════════════════════
# § 4. GEOLOCALIZACIÓN MULTI-PROVEEDOR
# ═══════════════════════════════════════════════════════════════════════

def init_geo() -> None:
    global GEO_READER
    try:
        GEO_READER = geoip2.database.Reader("GeoLite2-City.mmdb")
        log.info("[GEO] GeoLite2 cargado")
    except FileNotFoundError:
        GEO_READER = None
        log.warning("[GEO] GeoLite2 no encontrado, se usará ip-api.com (límite 45 req/min)")

_GEO_CACHE: dict[str, Optional[tuple[float, float]]] = {}   # solo aciertos
_GEO_CC: dict[str, str] = {}                                  # IP -> país ISO2 (cuando el proveedor lo da)
_GEO_MISS: dict[str, float] = {}                              # fallos: se reintentan pasada 1 h
GEO_MISS_TTL = 3600
_GEO_RATE_LOCK = asyncio.Lock()
_GEO_LAST_CALL = 0.0
GEO_MIN_INTERVAL = 4.3   # ip-api.com /batch admite 15 peticiones/min (100 IPs cada una)

def _valid_public_ip(ip: str) -> bool:
    try:
        return ipaddress.ip_address(ip.strip()).is_global
    except ValueError:
        return False

def _geo_local(ip: str) -> Optional[tuple[float, float]]:
    if not GEO_READER:
        return None
    try:
        resp = GEO_READER.city(ip)
        lat, lon = resp.location.latitude, resp.location.longitude
        if lat is not None and lon is not None and (abs(lat) > 0.01 or abs(lon) > 0.01):
            try:
                if resp.country.iso_code:
                    _GEO_CC[ip] = resp.country.iso_code.upper()
            except Exception:
                pass
            return (float(lat), float(lon))
    except Exception:
        pass
    return None

_IPAPI_BLOCK_UNTIL = 0.0   # tras un 429 se deja de usar ip-api durante un minuto y se usa el proveedor de reserva

@db_write
def _geo_store(hits: dict) -> None:
    if not hits:
        return
    try:
        conn = db_conn()
        ts = datetime.now(timezone.utc).isoformat()
        conn.executemany("INSERT OR REPLACE INTO geo_cache (ip,lat,lon,ts,cc) VALUES (?,?,?,?,?)",
                         [(ip, c[0], c[1], ts, _GEO_CC.get(ip)) for ip, c in hits.items()])
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        log.warning(f"[GEO] no se pudo guardar la caché: {e}")

def _geo_ok(lat, lon) -> bool:
    try:
        lat, lon = float(lat), float(lon)
    except (TypeError, ValueError):
        return False
    return abs(lat) <= 90 and abs(lon) <= 180 and (abs(lat) > 0.01 or abs(lon) > 0.01)

async def _geo_ipapi(chunk: list[str]) -> dict:
    """ip-api.com/batch (100 IPs, 15 peticiones/min). Devuelve {ip: (lat, lon)}; vacío si falla o hay límite."""
    global _GEO_LAST_CALL, _IPAPI_BLOCK_UNTIL
    if time.time() < _IPAPI_BLOCK_UNTIL:
        return {}
    async with _GEO_RATE_LOCK:
        wait = GEO_MIN_INTERVAL - (time.time() - _GEO_LAST_CALL)
        if wait > 0:
            await asyncio.sleep(wait)
        _GEO_LAST_CALL = time.time()
        try:
            r = await HTTP.post("http://ip-api.com/batch?fields=status,lat,lon,query,countryCode", json=chunk, timeout=20)
            if r.status_code == 429:
                _IPAPI_BLOCK_UNTIL = time.time() + 65
                log.warning("[GEO] ip-api.com limita las peticiones (429): uso el proveedor de reserva durante 1 min")
                return {}
            rows = r.json()
        except Exception as e:
            log.warning(f"[GEO] ip-api falló: {type(e).__name__}: {e}")
            return {}
    out = {}
    for d in (rows if isinstance(rows, list) else []):
        if isinstance(d, dict) and d.get("status") == "success" and d.get("query") and _geo_ok(d.get("lat"), d.get("lon")):
            out[d["query"]] = (float(d["lat"]), float(d["lon"]))
            if d.get("countryCode"):
                _GEO_CC[d["query"]] = str(d["countryCode"]).upper()
    return out

async def _geo_geojs(chunk: list[str]) -> dict:
    """Proveedor de reserva sin clave: get.geojs.io admite varias IPs separadas por comas."""
    out = {}
    for i in range(0, len(chunk), 50):
        part = chunk[i:i + 50]
        try:
            r = await HTTP.get("https://get.geojs.io/v1/ip/geo.json", params={"ip": ",".join(part)}, timeout=20)
            rows = r.json()
        except Exception as e:
            log.warning(f"[GEO] geojs falló: {type(e).__name__}: {e}")
            continue
        for d in rows if isinstance(rows, list) else [rows]:
            if isinstance(d, dict) and d.get("ip") and _geo_ok(d.get("latitude"), d.get("longitude")):
                out[d["ip"]] = (float(d["latitude"]), float(d["longitude"]))
                if d.get("country_code"):
                    _GEO_CC[d["ip"]] = str(d["country_code"]).upper()
    return out

async def geo_batch(ips) -> None:
    """Resuelve muchas IPs de golpe y rellena la caché (también en disco): GeoLite2 si existe, si no
    ip-api.com/batch y, si este limita o falla, get.geojs.io. Los fallos se reintentan pasada 1 h."""
    todo, now = [], time.time()
    for ip in dict.fromkeys(i.strip() for i in ips if i):
        if ip in _GEO_CACHE or now - _GEO_MISS.get(ip, 0) < GEO_MISS_TTL or not _valid_public_ip(ip):
            continue
        c = _geo_local(ip)
        if c:
            _GEO_CACHE[ip] = c
        else:
            todo.append(ip)
    new: dict = {}
    for i in range(0, len(todo), 100):
        chunk = todo[i:i + 100]
        got = await _geo_ipapi(chunk)
        rest = [ip for ip in chunk if ip not in got]
        if rest:
            got.update(await _geo_geojs(rest))
        _GEO_CACHE.update(got)
        new.update(got)
        for ip in chunk:
            if ip not in _GEO_CACHE:
                _GEO_MISS[ip] = time.time()
        if got:
            await asyncio.to_thread(_geo_store, got)           # se guarda cada lote: si el trabajo se corta (tiempo, red), lo ya resuelto no se pierde
    # (el guardado se hace lote a lote, arriba)

async def ip_to_coords(ip: Optional[str]) -> Optional[tuple[float, float]]:
    """NUNCA devuelve (0,0). Si no resuelve, devuelve None.
    Orden: caché -> GeoLite2 local -> ip-api.com (vía geo_batch, respetando su límite)."""
    if not ip:
        return None
    ip = ip.strip()
    if ip not in _GEO_CACHE:
        await geo_batch([ip])
    return _GEO_CACHE.get(ip)


