POSITIVE_WORDS = {
    "peace", "agreement", "growth", "recovery", "success", "positive",
    "progress", "improve", "gain", "boost", "paz", "acuerdo", "crecimiento",
    "recuperación", "éxito", "progreso",
}
NEGATIVE_WORDS = {
    "attack", "war", "conflict", "crisis", "collapse", "threat", "kill",
    "bomb", "explosion", "sanction", "panic", "fear", "recession", "ataque",
    "guerra", "conflicto", "crisis", "colapso", "amenaza", "asesinato",
    "bomba", "explosión", "sanción", "pánico", "recesión",
}

def sentiment_score(text: str) -> float:
    if not text:
        return 0.0
    words = re.findall(r"\w+", text.lower())
    if not words:
        return 0.0
    pos = sum(1 for w in words if w in POSITIVE_WORDS)
    neg = sum(1 for w in words if w in NEGATIVE_WORDS)
    return (pos - neg) / max(len(words), 1) * 100

