_COUNTRY_TERMS = {**_NAME_TO_ISO, **_COUNTRY_ALIASES}
_COUNTRY_RE = re.compile(
    r"(?<![\w])(" + "|".join(re.escape(t) for t in sorted(_COUNTRY_TERMS, key=len, reverse=True)) + r")(?![\w])",
    re.IGNORECASE,
)
# Abreviaturas: solo en MAYÚSCULAS ("us" en minúsculas es un pronombre)
_ABBR_RE = re.compile(r"(?<![\w.])(US|USA|U\.S\.A?\.?|UK|U\.K\.|UAE)(?![\w])")
_ABBR_MAP = {"US": "US", "USA": "US", "U.S.": "US", "U.S.A.": "US", "UK": "GB", "U.K.": "GB", "UAE": "AE"}

def find_countries(text: str) -> list[str]:
    """Códigos ISO2 de los países mencionados, en orden de aparición y sin repetir."""
    if not text:
        return []
    hits: list[tuple[int, str]] = []
    for m in _COUNTRY_RE.finditer(text):
        hits.append((m.start(), _COUNTRY_TERMS[m.group(1).lower()]))
    for m in _ABBR_RE.finditer(text):
        iso = _ABBR_MAP.get(m.group(1))
        if iso:
            hits.append((m.start(), iso))
    out: list[str] = []
    for _, iso in sorted(hits):
        if iso not in out:
            out.append(iso)
    return out

def country_coords(iso: str) -> Optional[tuple[float, float]]:
    v = COUNTRY_DB.get((iso or "").upper())
    return (v[1], v[2]) if v else None

_SMALL_COUNTRY = {"IL": (0.18, 0.55), "PS": (0.12, 0.2), "LB": (0.15, 0.3), "QA": (0.1, 0.25), "BH": (0.03, 0.05), "KW": (0.25, 0.2),
                  "CY": (0.4, 0.15), "JO": (0.5, 0.6), "SG": (0.05, 0.03), "MT": (0.05, 0.05), "AE": (0.6, 0.4), "SY": (1.0, 0.8), "TW": (0.3, 0.8),
                  "SI": (0.4, 0.2), "ME": (0.2, 0.2), "AL": (0.2, 0.5), "BE": (0.5, 0.3), "NL": (0.5, 0.4), "DK": (0.6, 0.4), "LU": (0.1, 0.1),
                  "HK": (0.05, 0.05), "BN": (0.15, 0.15), "TL": (0.3, 0.1), "DJ": (0.2, 0.2), "GM": (0.5, 0.05), "SV": (0.3, 0.2), "JM": (0.5, 0.15)}

def jitter_coords(lat: float, lon: float, key: str, deg: float = 1.6) -> tuple[float, float]:
    """Dispersión determinista alrededor del centroide para que 40 noticias del mismo país
    no se apilen en un único punto (y sigan siendo estables entre barridos)."""
    h = hashlib.md5(key.encode("utf-8", "ignore")).digest()
    rx = ry = deg
    for iso, (cx, cy) in _SMALL_COUNTRY.items():      # países pequeños/costeros: la dispersión se limita a su tamaño (si no, los puntos caían al mar)
        c = COUNTRY_DB.get(iso)
        if c and abs(lat - c[1]) < 0.6 and abs(lon - c[2]) < 0.6:
            rx, ry = min(deg, cx), min(deg, cy)
            break
    dx = (h[0] / 255.0 - 0.5) * 2 * rx
    dy = (h[1] / 255.0 - 0.5) * 2 * ry
    return (max(-85.0, min(85.0, lat + dy)), ((lon + dx + 180) % 360) - 180)

