CITY_DB: dict[str, tuple[str, str, float, float]] = {}      # nombre/alias -> (nombre canónico, ISO2, lat, lon)
for _ln in _CITY_TABLE.strip().splitlines():
    _names, _iso, _la, _lo = _ln.split("|")
    _canon = _names.split("/")[0]
    for _n in _names.split("/"):
        CITY_DB[_n] = (_canon, _iso, float(_la), float(_lo))
# Nombres con mayúscula inicial y límites de palabra (para no confundir «cali», «salvador», «lima»… en minúsculas)
_CITY_RE = re.compile(r"(?<![\w])(" + "|".join(re.escape(n) for n in sorted(CITY_DB, key=len, reverse=True)) + r")(?![\w])")

def find_cities(text: str) -> list[tuple[int, str, int]]:
    """[(inicio, nombre_canónico, fin)] de las ciudades mencionadas (sensible a mayúsculas)."""
    seen, out = set(), []
    for m in _CITY_RE.finditer(text or ""):
        canon = CITY_DB[m.group(1)][0]
        if canon not in seen:
            seen.add(canon)
            out.append((m.start(), canon, m.end()))
    return out

def _country_positions(text: str) -> list[tuple[int, str]]:
    out = []
    for m in _COUNTRY_RE.finditer(text or ""):
        out.append((m.start(), _COUNTRY_TERMS[m.group(1).lower()]))
    for m in _ABBR_RE.finditer(text or ""):
        iso = _ABBR_MAP.get(m.group(1))
        if iso:
            out.append((m.start(), iso))
    return sorted(out)

def geocode_text(text: str, default_iso: Optional[str] = None, key: str = "") -> Optional[tuple[float, float, str]]:
    """Ubica un texto: primero por CIUDAD (si la menciona y no contradice al país citado) y si no por el primer país.
    Devuelve (lat, lon, nombre) o None."""
    cities = find_cities(text)
    if cities:
        cps = _country_positions(text)
        mentioned = {iso for _, iso in cps}
        pick = None
        # «Valencia, Venezuela»: si justo detrás de la ciudad viene OTRO país, la ciudad es la de ese país (no la de mi tabla)
        def _contradicted(c, end):
            return any(0 <= p - end <= 4 and iso != CITY_DB[c][1] for p, iso in cps)
        cand = [(p, c, e) for p, c, e in cities if not _contradicted(c, e)]
        if not cand:
            pick = None
        elif not mentioned:
            pick = cand[0][1]
        else:
            same = [c for _, c, _e in cand if CITY_DB[c][1] in mentioned]
            if same:
                pick = same[0]                                        # «España: disturbios en Bilbao» -> Bilbao
            elif cand[0][0] < cps[0][0]:
                pick = cand[0][1]                                     # «Madrid-based firm hit by Russian hackers» -> Madrid
        if pick:
            _, ciso, cla, clo = CITY_DB[pick]
            la, lo = jitter_coords(cla, clo, key or text, deg=0.04)  # dispersión mínima: se queda en la ciudad
            cname = COUNTRY_DB.get(ciso, (ciso,))[0]
            return (la, lo, f"{pick}, {cname}")
    isos = find_countries(text)
    iso = isos[0] if isos else default_iso
    c = country_coords(iso) if iso else None
    if not c:
        return None
    la, lo = jitter_coords(c[0], c[1], key or text)
    return (la, lo, COUNTRY_DB[iso][0])

def extract_entities(text: str) -> list[str]:
    if not text:
        return []
    entities = {COUNTRY_DB[i][0] for i in find_countries(text)}
    for ip in re.findall(r"\b(?:\d{1,3}\.){3}\d{1,3}\b", text):
        entities.add(f"ip:{ip}")
    for cve in re.findall(r"CVE-\d{4}-\d{4,7}", text, re.IGNORECASE):
        entities.add(cve.upper())
    return sorted(entities)[:10]

def extract_tags(text: str, domain: str) -> list[str]:
    tags = {domain}
    if not text:
        return list(tags)
    t = text.lower()
    KEY_TAGS = {
        "c2": ["c2", "command and control", "botnet"],
        "ransomware": ["ransomware", "encrypt", "ransom"],
        "phishing": ["phishing", "credential", "login"],
        "0day": ["0day", "zero-day", "0-day", "exploit"],
        "malware": ["malware", "trojan", "worm", "backdoor"],
        "breach": ["data breach", "leaked", "data leak", "exposed database", "stolen data"],
        "ddos": ["ddos", "denial-of-service", "denial of service"],
        "fraud": ["fraud", "scam", "money laundering", "laundering", "swindle"],
        "trafficking": ["trafficking", "smuggling", "cartel", "narco", "drug bust"],
        "terror": ["terror", "bombing", "suicide attack", "jihadist"],
        "election": ["election", "vote", "electoral"],
        "military": ["military", "troops", "army", "navy", "air force"],
        "nuclear": ["nuclear", "atomic", "radiological"],
        "protest": ["protest", "demonstration", "riot"],
    }
    for tag, kws in KEY_TAGS.items():
        if any(kw in t for kw in kws):
            tags.add(tag)
    return list(tags)[:8]


