SEVERITY_ORDER = {"BAJA": 1, "MEDIA": 2, "ALTA": 3, "CRITICA": 4}

GEO_ALIAS = {
    "usa": "United States", "eeuu": "United States", "us": "United States",
    "reino unido": "United Kingdom", "uk": "United Kingdom",
    "rusia": "Russia", "ucrania": "Ukraine", "china": "China",
    "irán": "Iran", "israel": "Israel", "palestina": "Palestine",
}

def normalize_entities(raw: str) -> str:
    raw = _str(raw)
    if not raw:
        return ""
    parts = set()
    for token in raw.split(","):
        t = token.strip()
        if not t:
            continue
        tl = t.lower()
        parts.add(GEO_ALIAS.get(tl, t))
    return ",".join(sorted(parts))

def _simhash(text: str, bits: int = 64) -> int:
    if not text:
        return 0
    tokens = re.findall(r"\w+", text.lower())
    if not tokens:
        return 0
    v = [0] * bits
    for tok in tokens:
        h = int(hashlib.md5(tok.encode()).hexdigest(), 16)
        for i in range(bits):
            v[i] += 1 if (h >> i) & 1 else -1
    out = 0
    for i in range(bits):
        if v[i] > 0:
            out |= (1 << i)
    return out

def _hamming(a: int, b: int) -> int:
    x = a ^ b
    return bin(x).count("1")

# ─── ★ NUEVO · DEDUPE POR HISTORIA: la misma noticia en 10 medios = UN punto (y una sola ✖/🎒), con «fuentes:N» para no perder la corroboración ───
STORY_DOMAINS = frozenset(("conflicto", "terrorismo", "detencion_terror", "alerta_bomba", "disturbios", "crimen", "crimen_urbano", "humanitario", "noticias",
                           "alerta_viaje", "geopolitica", "alerta_civil"))
_STORY_STOP = frozenset("""para como pero sobre entre desde hasta contra tras ante bajo segun cuando donde porque esta este esto estos estas esos esas
una unos unas del los las que por con sin mas muy ser son fue han hay sus tambien aunque durante despues antes tras the and for with from that this have has been were was
will after over into about their they them than then also more says said say news una uno las les des une dans pour avec sur par aux que qui sont der die das und
nicht mit von den dem ein eine auf ist sind wird nach nell della delle degli che per con sono dopo gli una uno""".split())
_STORY_CACHE: dict = {"loaded": False, "items": {}, "idx": {}}      # items: dominio -> [(tokens, lat, lon, epoch, hash)]; idx: dominio -> {palabra: [posiciones]} (índice invertido)

def _story_add(dom: str, rec: tuple) -> None:
    lst = _STORY_CACHE["items"].setdefault(dom, [])
    lst.append(rec)
    ix = _STORY_CACHE["idx"].setdefault(dom, {})
    for w in rec[0]:
        ix.setdefault(w, []).append(len(lst) - 1)
_STORY_LOCK = threading.RLock()

def _story_tokens(title: str) -> frozenset:
    t = unicodedata.normalize("NFKD", (title or "").lower()).encode("ascii", "ignore").decode()
    return frozenset(w for w in re.findall(r"[a-z0-9]{4,}", t) if w not in _STORY_STOP)

def _story_hash(e: dict) -> str:
    return hashlib.sha256(f"{e['domain']}|{e['source']}|{_num(e.get('lat')):.4f}|{_num(e.get('lon')):.4f}|{e.get('title','')}".encode()).hexdigest()

def _story_ts(e: dict) -> float:
    try:
        return datetime.fromisoformat(_str(e.get("timestamp")).replace("Z", "+00:00")).timestamp()
    except Exception:
        return time.time()

def _story_load() -> None:
    if _STORY_CACHE["loaded"]:
        return
    _STORY_CACHE["loaded"] = True
    try:
        conn = db_conn()
        cut = (datetime.now(timezone.utc) - timedelta(hours=120)).isoformat()
        ph = ",".join("?" * len(STORY_DOMAINS))
        for r in conn.execute(f"SELECT domain,title,lat,lon,timestamp,raw_hash FROM events WHERE timestamp>=? AND domain IN ({ph}) ORDER BY id DESC LIMIT 12000", (cut, *STORY_DOMAINS)):
            tk = _story_tokens(r["title"])
            if len(tk) >= 3:
                try:
                    ep = datetime.fromisoformat(r["timestamp"].replace("Z", "+00:00")).timestamp()
                except Exception:
                    ep = time.time()
                _story_add(r["domain"], (tk, r["lat"], r["lon"], ep, r["raw_hash"]))
        conn.close()
    except Exception as ex:
        log.debug(f"[HISTORIAS] caché: {ex}")

def story_dedupe(events: list[dict]) -> list[dict]:
    """Descarta los eventos que cuentan la MISMA historia que otro ya visto (este barrido o los últimos 5 días): mismo dominio, titular casi idéntico
    (≥50 % de palabras clave comunes en alertas de bomba/detenciones, ≥60 % en el resto), cerca (≤4° / ≤1,6°) y en ≤4 días. Al conservado se le suma «fuentes:N»."""
    with _STORY_LOCK:
        _story_load()
        bumps: dict[str, tuple[int, set]] = {}
        out = []
        for e in events:
            dom = e.get("domain")
            if dom not in STORY_DOMAINS or e.get("source", "").startswith(("Estado ", "WAR Oficial")):
                out.append(e)
                continue
            tk = _story_tokens(_str(e.get("title")))
            if len(tk) < 3:
                out.append(e)
                continue
            la, lo, ep = _num(e.get("lat")), _num(e.get("lon")), _story_ts(e)
            new_dom = dom in ("alerta_bomba", "detencion_terror")
            thr_sim, thr_deg = (0.5, 4.0) if new_dom else (0.6, 1.6)
            hit = None
            items, ix = _STORY_CACHE["items"].get(dom, ()), _STORY_CACHE["idx"].get(dom, {})
            cnt: Counter = Counter()
            for w in tk:
                post = ix.get(w)
                if post and len(post) <= 600:               # las palabras muy comunes no discriminan y costarían O(n)
                    cnt.update(post)
            for pos, c_ in cnt.most_common(40):
                if c_ < 3:
                    break
                tk2, la2, lo2, ep2, h2 = items[pos]
                if abs(ep2 - ep) > 96 * 3600 or abs(la2 - la) > thr_deg or abs(lo2 - lo) > thr_deg:
                    continue
                inter = len(tk & tk2)
                if inter >= 4 and inter / max(1, len(tk | tk2)) >= thr_sim or (inter >= 3 and len(tk) <= 5 and inter / max(1, len(tk | tk2)) >= 0.75):
                    hit = h2
                    break
            if hit:
                n0, srcs = bumps.get(hit, (1, set()))
                srcs.add(_str(e.get("source")))
                bumps[hit] = (n0 + 1, srcs)
                NOISE_STATS["story"] = NOISE_STATS.get("story", 0) + 1
                continue
            _story_add(dom, (tk, la, lo, ep, _story_hash(e)))
            out.append(e)
        if bumps:
            try:
                conn = db_conn()
                for h, (n, srcs) in bumps.items():
                    row = conn.execute("SELECT tags FROM events WHERE raw_hash=?", (h,)).fetchone()
                    if not row:
                        continue                  # el original aún no está en la BD (mismo barrido): se cuenta al guardarlo
                    tg = re.sub(r"(?:^|,)fuentes:\d+", "", row["tags"] or "").strip(",")
                    old = re.search(r"fuentes:(\d+)", row["tags"] or "")
                    tot = (int(old.group(1)) if old else 1) + n - 1
                    conn.execute("UPDATE events SET tags=? WHERE raw_hash=?", ((tg + "," if tg else "") + f"fuentes:{tot}", h))
                conn.commit()
                conn.close()
            except Exception as ex:
                log.debug(f"[HISTORIAS] no se pudo anotar fuentes: {ex}")
        return out

def dedupe_events(events: list[dict], threshold: int = 6) -> list[dict]:
    return story_dedupe(_dedupe_events_sem(events, threshold))

def _dedupe_events_sem(events: list[dict], threshold: int = 6) -> list[dict]:
    """Dedupe semántico: solo se consideran duplicados eventos del MISMO dominio,
    en la misma zona (<1°) y con texto casi idéntico. Se compara solo con los ya aceptados de las
    celdas contiguas de 1° (antes era O(n²) sobre todo el barrido y se disparaba con miles de eventos)."""
    cells: dict[tuple, list[int]] = {}
    out: list[dict] = []
    for e in events:
        sig = _simhash(f"{e.get('title','')} {e.get('description','')}")
        dom, la, lo = e.get("domain"), _num(e.get("lat")), _num(e.get("lon"))
        ci, cj = math.floor(la), math.floor(lo)
        is_dup = False
        for di in (-1, 0, 1):
            for dj in (-1, 0, 1):
                for s_, k_la, k_lo in cells.get((dom, ci + di, cj + dj), ()):
                    if abs(k_la - la) < 1.0 and abs(k_lo - lo) < 1.0 and _hamming(sig, s_) <= threshold:
                        is_dup = True
                        break
                if is_dup:
                    break
            if is_dup:
                break
        if not is_dup:
            cells.setdefault((dom, ci, cj), []).append((sig, la, lo))
            out.append(e)
    return out

def relevance_score(event: dict, corr_hits: int = 0) -> float:
    sev = SEVERITY_ORDER.get(event.get("severity", "BAJA"), 1) / 4.0
    sent = abs(_num(event.get("sentiment", 0))) / 100.0
    ents = len([x for x in _str(event.get("entities")).split(",") if x])
    ent_w = min(ents / 5.0, 1.0)
    corr_w = min(corr_hits / 3.0, 1.0)
    score = (0.40 * sev + 0.20 * sent + 0.15 * ent_w + 0.25 * corr_w) * 100
    return round(score, 1)

def escalate_severity(event: dict) -> str:
    sev = event.get("severity", "BAJA")
    title_raw = _str(event.get("title"))
    txt = f"{title_raw} {_str(event.get('description'))}".lower()
    tags = _str(event.get("tags")).lower()

    if any(k in txt for k in ("nuclear", "cbrn", "radiological")):
        return "CRITICA"
    if "0day" in tags or "zero-day" in txt:
        return "CRITICA"
    if "c2" in tags and sev in ("ALTA", "CRITICA"):
        return sev
    if "ransomware" in tags and "hospital" in txt:
        return "CRITICA"
    # Magnitud sísmica: se busca en el título ORIGINAL (con "M" mayúscula) y solo en terremotos
    if event.get("domain") == "terremoto":
        m = re.match(r"\s*M(\d+(?:\.\d+)?)", title_raw)
        if m and float(m.group(1)) >= 7.0:
            return "CRITICA"
    if _num(event.get("sentiment", 0)) < -5 and sev == "MEDIA":
        return "ALTA"
    return sev

def enrich_events(events: list[dict]) -> list[dict]:
    for e in events:
        e["entities"] = normalize_entities(e.get("entities", ""))
        e["severity"] = escalate_severity(e)
        e["relevance"] = relevance_score(e)
    return events

