async def fetch_feodo() -> list[dict]:
    r = await _get("https://feodotracker.abuse.ch/downloads/ipblocklist.json")
    out = []
    items = r.json()[:150]
    await geo_batch(i.get("ip_address") for i in items)
    for item in items:
        coords = await ip_to_coords(item.get("ip_address"))
        if not coords:
            continue
        t = f"C2 {item.get('malware', '?')}"
        out.append({
            "domain": "ciberataque", "source": "Feodo",
            "lat": coords[0], "lon": coords[1], "severity": "ALTA",
            "title": t, "description": f"{item.get('ip_address')}:{item.get('port')}",
            "url": "", "sentiment": sentiment_score(t),
            "entities": ",".join(extract_entities(t) + [f"ip:{item.get('ip_address')}"]),
            "tags": ",".join(extract_tags(t, "ciberataque")),
        })
    return out

