AIS_BOXES = {   # [[lat, lon], [lat, lon]] — zonas calientes (se leen unos segundos por barrido); NEXUS_AIS_BOXES="lat1,lon1,lat2,lon2;lat1,lon1,lat2,lon2" para las tuyas
    "Ormuz y golfo de Omán": [[22.5, 50.0], [28.0, 60.5]],
    "Mar Rojo y golfo de Adén": [[11.0, 32.0], [30.0, 50.0]],
    "Mediterráneo oriental": [[31.0, 28.0], [37.0, 36.5]],
    "Mar Negro": [[41.0, 27.0], [47.0, 42.0]],
    "Estrecho de Taiwán": [[21.0, 117.0], [26.5, 123.0]],
    "Báltico": [[53.5, 10.0], [60.5, 25.0]],
}
AIS_LISTEN_S = float(os.getenv("NEXUS_AIS_SECONDS", "20"))

async def fetch_maritime() -> list[dict]:
    """Barcos EN VIVO con AISStream (WebSocket, clave gratuita en https://aisstream.io/). Escucha AIS_LISTEN_S segundos por barrido en las zonas de AIS_BOXES
    y guarda la última posición de cada barco con su RUMBO (etiqueta rumbo:N) para dibujarlo como flecha. SIN verificar contra el servicio real desde aquí."""
    if not AISSTREAM_KEY:
        return []
    try:
        import websockets
    except ImportError:
        raise RuntimeError("falta la librería websockets: pip install websockets")
    boxes = list(AIS_BOXES.values())
    env = os.getenv("NEXUS_AIS_BOXES", "").strip()
    if env:
        try:
            boxes = [[[float(v) for v in bb.split(",")[:2]], [float(v) for v in bb.split(",")[2:4]]] for bb in env.split(";") if bb.strip()]
        except ValueError:
            log.warning("[AIS] NEXUS_AIS_BOXES mal formada (usa lat1,lon1,lat2,lon2;lat1,lon1,lat2,lon2): se usan las zonas de serie")
    ships: dict[str, dict] = {}
    types: dict[str, int] = {}

    async def listen():
        async with websockets.connect("wss://stream.aisstream.io/v0/stream", open_timeout=15, max_size=2 ** 20) as ws:
            await ws.send(json.dumps({"APIKey": AISSTREAM_KEY, "BoundingBoxes": boxes, "FilterMessageTypes": ["PositionReport", "ShipStaticData"]}))
            async for raw in ws:
                try:
                    m = json.loads(raw)
                except ValueError:
                    continue
                if m.get("error") or m.get("Error"):
                    raise RuntimeError(f"AISStream: {m.get('error') or m.get('Error')}")
                md, pr = m.get("MetaData") or {}, ((m.get("Message") or {}).get("PositionReport") or {})
                mmsi = str(md.get("MMSI") or "")
                sd = (m.get("Message") or {}).get("ShipStaticData")
                if sd is not None:                                     # tipo de barco (35 = militar); llega aparte de la posición
                    types[mmsi] = int(_num(sd.get("Type")))
                    continue
                la, lo = md.get("latitude"), md.get("longitude")
                if mmsi and la is not None and lo is not None:
                    hd = pr.get("TrueHeading")
                    if hd is None or hd >= 360:
                        hd = pr.get("Cog")
                    ships[mmsi] = {"n": (md.get("ShipName") or "").strip(), "la": float(la), "lo": float(lo), "hd": hd, "sog": pr.get("Sog"), "st": pr.get("NavigationalStatus")}
                if len(ships) >= 800:
                    return
    try:
        await asyncio.wait_for(listen(), AIS_LISTEN_S)
    except asyncio.TimeoutError:
        pass                                    # tiempo de escucha cumplido: es lo normal
    if not ships:
        raise RuntimeError("AISStream no envió posiciones (¿clave inválida, zonas vacías o sin conexión?)")
    out = []
    for mmsi, v in ships.items():
        hd = v["hd"] if isinstance(v["hd"], (int, float)) and 0 <= v["hd"] < 360 else None
        mil = types.get(mmsi) == 35
        tg = ["maritimo", "barco", f"mmsi:{mmsi}"] + (["militar"] if mil else []) + ([f"rumbo:{int(hd)}"] if hd is not None else []) + ([f"vel:{v['sog']}"] if v["sog"] is not None else [])
        out.append(_mk("maritimo", "AISStream", v["la"], v["lo"], "MEDIA" if mil else "BAJA", f"{'⚓ Buque MILITAR' if mil else 'Buque'} {v['n'] or mmsi}",
                       f"MMSI {mmsi} · rumbo {int(hd) if hd is not None else '?'}° · {v['sog'] if v['sog'] is not None else '?'} nudos",
                       f"https://www.vesselfinder.com/vessels/details/{mmsi}", [v["n"]] if v["n"] else [], tg))
    return out

_DIGI_NAMES: dict = {"t": 0.0, "d": {}, "ty": {}}

def ais_cat(t: int) -> tuple[str, str]:
    """Tipo AIS (0-99) → (categoría, etiqueta). Categorías: M militar · A autoridad/rescate · P pesquero · C carga · T tanque · V pasaje · O otros."""
    if t == 35: return "M", "MILITAR"
    if t in (51, 55, 53, 50, 58): return "A", {51: "Búsqueda y rescate", 55: "Policía/guardacostas", 53: "Servicio portuario", 50: "Práctico", 58: "Sanitario"}[t]
    if t == 30: return "P", "Pesquero"
    if 70 <= t <= 79: return "C", "Carga"
    if 80 <= t <= 89: return "T", "Petrolero/tanque"
    if 60 <= t <= 69: return "V", "Pasaje"
    if t in (31, 32, 52): return "O", "Remolcador"
    if t in (36, 37): return "O", "Recreo/vela"
    if 40 <= t <= 49: return "O", "Alta velocidad"
    return "O", ""

async def fetch_ais_digitraffic() -> list[dict]:
    """Barcos del Báltico/Finlandia SIN clave ni cuenta: datos abiertos de Digitraffic (Fintraffic) con la última posición AIS de cada barco → flechas con rumbo.
    Cobertura: aguas finlandesas y Báltico (NO Ormuz ni Mar Rojo: para eso AISStream con clave). Sin verificar en vivo desde aquí."""
    hdr = {"Accept-Encoding": "gzip", "Digitraffic-User": "NEXUS-OSINT"}
    r = await _get("https://meri.digitraffic.fi/api/ais/v1/locations", headers=hdr, timeout=40)
    feats = (r.json() or {}).get("features", [])
    if time.time() - _DIGI_NAMES["t"] > 86400:                      # nombres de barcos: una vez al día
        try:
            rv = await _get("https://meri.digitraffic.fi/api/ais/v1/vessels", headers=hdr, timeout=60)
            vl = [v for v in rv.json() if isinstance(v, dict)]
            _DIGI_NAMES["d"] = {str(v.get("mmsi")): (v.get("name") or "").strip() for v in vl}
            _DIGI_NAMES["ty"] = {str(v.get("mmsi")): int(_num(v.get("shipType"))) for v in vl}
            _DIGI_NAMES["t"] = time.time()
        except Exception as e:
            log.debug(f"[AIS-fi] nombres: {type(e).__name__}")
            _DIGI_NAMES["t"] = time.time() - 82800                     # reintento en 1 h
    now_ms = time.time() * 1000
    rows, n_old = [], 0
    for f in feats:
        p_ = f.get("properties") or {}
        g = (f.get("geometry") or {}).get("coordinates") or []
        mmsi = str(p_.get("mmsi") or f.get("mmsi") or "")
        if len(g) < 2 or not mmsi:
            continue
        ts = _num(p_.get("timestampExternal") or p_.get("timestamp"))
        if ts and ts < 1e11:
            ts *= 1000                                                 # segundos → ms (por si el servicio cambia de unidad)
        if ts and now_ms - ts > 3 * 3600 * 1000:                       # solo posiciones de las últimas 3 h
            n_old += 1
            continue
        rows.append((mmsi, float(g[1]), float(g[0]), p_.get("heading"), p_.get("cog"), p_.get("sog")))
    rows.sort(key=lambda x: -(_num(x[5]) or 0))                        # los que se mueven primero
    log.info(f"[AIS-fi] {len(feats)} posiciones recibidas · {n_old} descartadas por antiguas (>3 h) · {len(rows)} usadas")
    out = []
    for mmsi, la, lo, hd, cog, sog in rows[:400]:
        h = hd if isinstance(hd, (int, float)) and 0 <= hd < 360 else (cog if isinstance(cog, (int, float)) and 0 <= cog < 360 else None)
        name = _DIGI_NAMES["d"].get(mmsi, "")
        try:
            cat, lab = ais_cat(int(_num(_DIGI_NAMES["ty"].get(mmsi)) or 0))
        except Exception:
            cat, lab = "O", ""                                          # un tipo raro nunca debe tirar el barco
        mil = cat == "M"                                                # tipo AIS 35 = operaciones militares
        tg = ["maritimo", "barco", f"mmsi:{mmsi}", f"tipo:{cat}"] + (["militar"] if mil else []) + ([f"rumbo:{int(h)}"] if h is not None else []) + ([f"vel:{sog}"] if sog is not None else [])
        out.append(_mk("maritimo", "Digitraffic AIS (Finlandia)", la, lo, "MEDIA" if mil else "BAJA", f"{'⚓ Buque MILITAR' if mil else ('Buque · ' + lab) if lab else 'Buque'} {name or mmsi}",
                       f"{lab + ' · ' if lab else 'tipo AIS no declarado · '}MMSI {mmsi} · rumbo {int(h) if h is not None else '?'}° · {sog if sog is not None else '?'} nudos · datos abiertos Fintraffic",
                       f"https://www.vesselfinder.com/vessels/details/{mmsi}", [name] if name else [], tg))
    return out

