async def fetch_yahoo_finance() -> list[dict]:
    symbols = ["SPY", "QQQ", "BTC-USD", "GC=F", "CL=F", "^VIX"]
    out = []
    last_err: Optional[Exception] = None
    # Yahoo rechaza User-Agents no reconocidos, y un símbolo caído no debe tumbar al resto
    yh_headers = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"}
    for sym in symbols:
        try:
            try:
                r = await _get(
                    f"https://query1.finance.yahoo.com/v8/finance/chart/{quote(sym, safe='')}",
                    headers=yh_headers,
                )
            except Exception:
                await asyncio.sleep(1.5)
                r = await _get(
                    f"https://query2.finance.yahoo.com/v8/finance/chart/{quote(sym, safe='')}?interval=1d&range=1d",
                    headers=yh_headers,
                )
            meta = ((r.json().get("chart", {}).get("result") or [{}])[0]).get("meta", {})
            price = meta.get("regularMarketPrice")
            if not price:
                continue
            out.append({
                "domain": "mercado", "source": "Yahoo Finance",
                "lat": 40.7128, "lon": -74.0060, "severity": "BAJA",
                "title": f"{sym}: {price}", "description": "",
                "url": "", "sentiment": 0.0,
                "entities": f"symbol:{sym}",
                "tags": f"mercado,{sym.lower()}",
            })
        except Exception as e:
            last_err = e
            log.debug(f"[yahoo:{sym}] {e}")
    if not out and last_err:
        raise last_err
    return out


