# ─── Tier 7: Cibercrimen, crimen mundial y alertas  ★ NUEVO ──────────────
# Ningún colector de este bloque necesita API key (salvo Ransomware.live, opcional).
# Los formatos de estas APIs pueden cambiar: si una falla verás el motivo en la pestaña «Fuentes».

RANSOMWARE_LIVE_KEY = os.getenv("RANSOMWARE_LIVE_KEY")
RSS_HEADERS = {"User-Agent": "Mozilla/5.0 (compatible; NEXUS-OSINT/3.1)", "Accept": "application/rss+xml, application/xml, text/xml, */*"}

def _mk(domain: str, source: str, lat: float, lon: float, severity: str, title: str,
        description: str = "", url: str = "", extra_entities=(), extra_tags=(), fixed: bool = False) -> dict:
    """Construye un evento con entidades, etiquetas y sentimiento calculados a partir del texto."""
    text = f"{title} {description}"
    ents = list(extract_entities(text)) + list(extra_entities)
    tags = list(extract_tags(text, domain)) + list(extra_tags)
    return {
        "_fixed_sev": fixed,
        "domain": domain, "source": source, "lat": lat, "lon": lon, "severity": severity,
        "title": (title or "")[:200], "description": (description or "")[:300],
        "url": url or "", "sentiment": sentiment_score(text),
        "entities": ",".join(dict.fromkeys(ents)), "tags": ",".join(dict.fromkeys(tags)),
    }

def _defang(u: str) -> str:
    """hxxp://ejemplo[.]com — evita que una URL maliciosa sea clicable al copiarla."""
    return (u or "").replace("http", "hxxp", 1).replace(".", "[.]")

def _strip_html(s: str) -> str:
    s = htmllib.unescape(re.sub(r"<[^>]+>", " ", s or ""))
    return re.sub(r"\s+", " ", s).strip()

def _text_lines(txt: str) -> list[str]:
    return [l.strip() for l in txt.splitlines() if l.strip() and not l.lstrip().startswith(("#", ";", "//"))]

def _norm_ip(s: str) -> str:
    """Quita ceros a la izquierda (el API del ISC devuelve 061.177.172.160)."""
    s = (s or "").strip()
    try:
        return ".".join(str(int(p)) for p in s.split(".")) if s.count(".") == 3 else s
    except ValueError:
        return s

async def _ip_list_source(url: str, source: str, severity: str, title_fmt: str, limit: int,
                          tags: list[str], domain: str = "ciberataque") -> list[dict]:
    """Lista de IPs en texto plano -> muestra aleatoria -> geolocalizada por lotes."""
    r = await _get(url, headers=RSS_HEADERS, follow_redirects=True)
    ips = []
    for l in _text_lines(r.text):
        ip = _norm_ip(re.split(r"[\s,;]", l)[0].split("/")[0])
        if _valid_public_ip(ip):
            ips.append(ip)
    if len(ips) > limit:
        ips = random.sample(ips, limit)
    await geo_batch(ips)
    out = []
    for ip in ips:
        c = _GEO_CACHE.get(ip)
        if c:
            out.append(_mk(domain, source, c[0], c[1], severity, title_fmt.format(ip=ip), ip, "", [f"ip:{ip}"], tags))
    return out

