async def fetch_cloudflare_ddos() -> list[dict]:
    """Cloudflare Radar: países origen y objetivo de los ataques DDoS (capas 3 y 7) de las últimas 24 h.
    Necesita un token gratuito de Cloudflare con permiso Radar (CLOUDFLARE_API_TOKEN)."""
    if not CLOUDFLARE_API_TOKEN:
        return []
    hdr = {"Authorization": f"Bearer {CLOUDFLARE_API_TOKEN}"}
    out, errors = [], []
    for layer in ("layer7", "layer3"):
        for side in ("origin", "target"):
            try:
                r = await _get(f"https://api.cloudflare.com/client/v4/radar/attacks/{layer}/top/locations/{side}",
                               params={"dateRange": "1d", "limit": 15, "format": "json"}, headers=hdr)
                res = r.json().get("result") or {}
                lst = next((v for v in res.values() if isinstance(v, list)), [])
            except Exception as e:
                errors.append(f"{layer}/{side}: {type(e).__name__}: {e}")
                continue
            for it in lst:
                iso = next((str(v).upper() for k, v in it.items() if k.lower().endswith("alpha2")), "")
                c = country_coords(iso)
                if not c:
                    continue
                pct = _num(it.get("value"))
                la, lo = jitter_coords(c[0], c[1], f"{layer}{side}{iso}", deg=0.8)
                what = "origen" if side == "origin" else "objetivo"
                out.append(_mk("ddos", "Cloudflare Radar", la, lo, "CRITICA" if pct >= 30 else "ALTA" if pct >= 12 else "MEDIA" if pct >= 4 else "BAJA",
                               f"DDoS {layer.upper()} — {COUNTRY_DB[iso][0]} ({what}) {pct:.1f}%",
                               f"{pct:.1f}% del tráfico de ataque DDoS {layer.upper()} en 24 h",
                               "https://radar.cloudflare.com/security-and-attacks", [COUNTRY_DB[iso][0]],
                               ["ddos", layer, side, f"pct:{pct:.1f}"], fixed=True))
    # Pares REALES origen → objetivo medidos por Cloudflare (alimentan los arcos del mapa)
    for layer in ("layer7", "layer3"):
        try:
            r = await _get(f"https://api.cloudflare.com/client/v4/radar/attacks/{layer}/top/attacks",
                           params={"dateRange": "1d", "limit": 25, "format": "json"}, headers=hdr)
            res = r.json().get("result") or {}
            lst = next((v for v in res.values() if isinstance(v, list)), [])
        except Exception as e:
            errors.append(f"{layer}/pares: {type(e).__name__}: {e}")
            log.warning("[CLOUDFLARE] pares %s: %s", layer, e)
            continue
        for it in lst:
            if not isinstance(it, dict):
                continue
            o = next((str(v).upper() for k, v in it.items() if k.lower().startswith("origin") and k.lower().endswith("alpha2")), "")
            t = next((str(v).upper() for k, v in it.items() if k.lower().startswith("target") and k.lower().endswith("alpha2")), "")
            if o not in COUNTRY_DB or t not in COUNTRY_DB or o == t:
                continue
            pct = _num(it.get("value"))
            c = country_coords(t)
            la, lo = jitter_coords(c[0], c[1], f"{layer}{o}{t}", deg=0.8)
            out.append(_mk("ddos", "Cloudflare Radar", la, lo,
                           "ALTA" if pct >= 2 else "MEDIA" if pct >= 0.5 else "BAJA",
                           f"DDoS {layer.upper()} — {COUNTRY_DB[o][0]} → {COUNTRY_DB[t][0]} {pct:.2f}%",
                           f"{pct:.2f}% del tráfico de ataque DDoS {layer.upper()} (24 h): origen {COUNTRY_DB[o][0]}, objetivo {COUNTRY_DB[t][0]}",
                           "https://radar.cloudflare.com/security-and-attacks", [COUNTRY_DB[o][0], COUNTRY_DB[t][0]],
                           ["ddos", layer, flow_tag(o, t), f"pct:{pct:.2f}"], fixed=True))
    if not out and errors:
        raise RuntimeError("; ".join(errors)[:300])
    return out

# ── RSS de seguridad y crimen ──

def _entry_age_hours(e) -> float:
    t = e.get("published_parsed") or e.get("updated_parsed")
    if not t:
        return 0.0
    try:
        return (time.time() - calendar.timegm(t)) / 3600.0
    except Exception:
        return 0.0

_BROWSER_ACCEPT = "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8"

_PUB_BY_LINK: dict = {}

def _pub_for(ev: dict, now: str = "") -> str:
    ts = _PUB_BY_LINK.get(ev.get("url") or "")
    if not ts:
        return now
    return min(ts, now) if now else ts            # una fecha futura (reloj mal puesto en el feed) se recorta a «ahora»

async def _fetch_rss_direct(url: str):
    try:
        return await _get(url, headers=RSS_HEADERS, follow_redirects=True, timeout=18)
    except httpx.HTTPStatusError as ex:
        if ex.response.status_code not in (403, 406):
            raise
        pu = urlparse(url)                          # algunos sitios (p. ej. Euronews) rechazan el «Accept» de lector RSS: reintento con cabeceras de navegador
        return await _get(url, headers={"Accept": _BROWSER_ACCEPT, "Referer": f"{pu.scheme}://{pu.netloc}/"}, follow_redirects=True, timeout=18)

async def _fetch_rss(url: str) -> list:
    try:
        r = await _fetch_rss_direct(url)
    except (httpx.HTTPStatusError, httpx.TransportError) as ex:
        host = urlparse(url).netloc
        blocked = isinstance(ex, httpx.TransportError) or ex.response.status_code in (403, 404, 406, 410, 451)
        if "news.google." in url or not host or not blocked:
            raise
        # ★ RESPALDO: el sitio bloquea el feed (403/406/404) o no responde desde tu red → se leen sus titulares por Google News (site:host). Mismo medio, solo titulares.
        log.info(f"[RSS] {host}: {type(ex).__name__} → respaldo por Google News")
        r = await _fetch_rss_direct(_gnews(f"site:{host.removeprefix('www.')}", 2))
        url = _gnews(f"site:{host}", 2)
    parsed = await asyncio.to_thread(feedparser.parse, r.content)
    ents = list(parsed.entries)[:60]
    if "news.google." in url:                       # «Titular - New York Post»: el NOMBRE DEL MEDIO no es un lugar de la noticia (ponía los eventos en Nueva York, Washington, Jerusalén…)
        for e in ents:
            try:
                ti = e.get("title", "") or ""
                pub = ""
                src = e.get("source")
                if isinstance(src, dict):
                    pub = (src.get("title") or "").strip()
                if pub and ti.endswith(" - " + pub):
                    ti = ti[: -len(pub) - 3]
                elif " - " in ti and len(ti.rsplit(" - ", 1)[1]) <= 45:
                    pub, ti = ti.rsplit(" - ", 1)[1], ti.rsplit(" - ", 1)[0]
                e["title"] = ti.strip()
                sm = e.get("summary", "") or ""
                if pub:
                    sm = re.sub(r"(?:&nbsp;|\s)*<font[^>]*>\s*" + re.escape(pub) + r"\s*</font>", "", sm)
                    sm = re.sub(r"\s*" + re.escape(pub) + r"\s*$", "", _strip_html(sm)) if "<" not in sm else sm
                e["summary"] = sm
                e["pub_name"] = pub
            except Exception:
                pass
    for e in ents:                                  # fecha REAL de publicación → se usa como «timestamp» del evento (no la hora del barrido)
        t = e.get("published_parsed") or e.get("updated_parsed")
        lk = e.get("link")
        if t and lk:
            try:
                _PUB_BY_LINK[lk] = datetime.fromtimestamp(calendar.timegm(t), timezone.utc).isoformat()
            except Exception:
                pass
    if len(_PUB_BY_LINK) > 20000:
        for k in list(_PUB_BY_LINK)[:10000]:
            _PUB_BY_LINK.pop(k, None)
    return ents

def make_rss_collector(name: str, url: str, domain: str, severity: str = "MEDIA",
                       default_iso: Optional[str] = None, extra_tags=(), max_age_h: float = 72, limit: int = 25):
    """Un feed RSS -> eventos ubicados por el primer país que mencionan (o default_iso).
    Las noticias sin país reconocible se descartan: no se inventan ubicaciones."""
    async def _collector() -> list[dict]:
        out = []
        for e in await _fetch_rss(url):
            if _entry_age_hours(e) > max_age_h:
                continue
            title = _strip_html(e.get("title", ""))
            summ = _strip_html(e.get("summary", ""))[:300]
            g = geocode_text(f"{title}. {summ}", default_iso, key=title)
            if not g or not title:
                continue
            out.append(_mk(domain, name, g[0], g[1], severity, title, summ or g[2],
                           e.get("link") or "", [g[2]], extra_tags))
            if len(out) >= limit:
                break
        return out
    _collector.__name__ = "fetch_" + re.sub(r"\W+", "_", name.lower())
    return _collector

