async def fetch_travel_advisories() -> list[dict]:
    """Avisos de viaje del Departamento de Estado: nivel 4 = «No viajar» (suele indicar violencia/inestabilidad)."""
    out = []
    for e in await _fetch_rss("https://travel.state.gov/_res/rss/TAsTWs.xml"):
        title = _strip_html(e.get("title", ""))
        m = re.search(r"Level\s*(\d)", title, re.IGNORECASE)
        level = int(m.group(1)) if m else 0
        if level < 2:
            continue
        g = geocode_text(re.split(r"\s+[-–—]\s+", title)[0], None, key=title)
        if not g:
            continue
        out.append(_mk("alerta_viaje", "US Travel", g[0], g[1], {4: "ALTA", 3: "MEDIA"}.get(level, "BAJA"),
                       title, _strip_html(e.get("summary", ""))[:250], e.get("link") or "", [g[2]], [f"nivel{level}"]))
    return out

# ── GDELT: noticias de crimen (DOC API) y focos geográficos (GEO API) ──
# GDELT pide como máximo 1 petición cada 5 s, por eso todo va en un único colector secuencial.

# ★ Cliente GDELT «a la Andrómeda»: cabeceras de navegador reales (UA, Accept-Language y Referer de gdeltproject.org), caché por URL, reintento con espera
#   si responde 429 o una página HTML de límite, y mensaje de error claro. Además: un único carril con ≥5,5 s entre peticiones y pausa común tras un 429.
_GDELT_HEADERS = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64; rv:128.0) Gecko/20100101 Firefox/128.0", "Accept": "application/json, text/plain, */*",
                  "Accept-Language": "en-US,en;q=0.9,es;q=0.8", "Referer": "https://www.gdeltproject.org/"}
_GDELT_GAP, _GDELT_TTL = 5.5, 600.0
_GDELT_CACHE: dict = {}
_GDELT_STATE = {"last": 0.0, "block": 0.0, "lock": None}

async def _gdelt_json(url: str, params: dict) -> dict:
    key = url + "?" + "&".join(f"{k}={params[k]}" for k in sorted(params))
    hit = _GDELT_CACHE.get(key)
    if hit and time.time() - hit[0] < _GDELT_TTL:
        return hit[1]
    if _GDELT_STATE["lock"] is None:
        _GDELT_STATE["lock"] = asyncio.Lock()
    async with _GDELT_STATE["lock"]:
        hit = _GDELT_CACHE.get(key)                                  # otro colector pudo traerla mientras esperábamos
        if hit and time.time() - hit[0] < _GDELT_TTL:
            return hit[1]
        last_err = "sin respuesta"
        for attempt in range(3):
            wait_block = _GDELT_STATE["block"] - time.time()
            if wait_block > 0:
                if attempt == 0 and wait_block > 45:
                    raise RuntimeError(f"GDELT limita las peticiones (429): en pausa {int(wait_block)} s")
                await asyncio.sleep(min(wait_block, 45))
            gap = _GDELT_GAP - (time.time() - _GDELT_STATE["last"])
            if gap > 0:
                await asyncio.sleep(gap)
            _GDELT_STATE["last"] = time.time()
            try:
                r = await HTTP.get(url, params=params, headers=_GDELT_HEADERS, timeout=30)
            except Exception as e:
                last_err = f"{type(e).__name__}"
                await asyncio.sleep(1.2 * (attempt + 1))
                continue
            if r.status_code == 429 or (r.status_code == 200 and not r.text.lstrip()[:1] in ("{", "[")):
                last_err = "429 Too Many Requests" if r.status_code == 429 else "respuesta no JSON (¿límite GDELT?): " + _strip_html(r.text)[:80]
                _GDELT_STATE["block"] = time.time() + 8.0 * (attempt + 1)          # espera común: 8 s, luego 16 s
                continue
            r.raise_for_status()
            data = r.json()
            _GDELT_CACHE[key] = (time.time(), data)
            if len(_GDELT_CACHE) > 40:
                for k in sorted(_GDELT_CACHE, key=lambda k: _GDELT_CACHE[k][0])[:20]:
                    _GDELT_CACHE.pop(k, None)
            return data
        _GDELT_STATE["block"] = time.time() + 90.0                        # tras 3 intentos fallidos: pausa larga para todos los colectores
        raise RuntimeError(f"GDELT no respondió: {last_err}")

GDELT_CRIME_QUERIES = [
    ('(cybercrime OR ransomware OR "data breach" OR hackers) sourcelang:english', "cibercrimen", "MEDIA"),
    ('("drug trafficking" OR cartel OR "human trafficking" OR smuggling) sourcelang:english', "crimen", "MEDIA"),
    ('(ddos OR "denial of service" OR "cyberattack" OR hacktivist) sourcelang:english', "ddos", "MEDIA"),
    ('(malware OR botnet OR infostealer OR trojan) sourcelang:english', "malware", "MEDIA"),
    ('(terrorism OR "terror attack" OR bombing OR kidnapping) sourcelang:english', "terrorismo", "ALTA"),
    ('(homicide OR "organized crime" OR "money laundering" OR extortion) sourcelang:english', "crimen", "MEDIA"),
    ('(riots OR unrest OR looting OR "clashes with police" OR "tear gas") sourcelang:english', "disturbios", "MEDIA"),
    ('(disturbios OR saqueos OR altercados OR "coches quemados" OR "cargas policiales") sourcelang:spanish', "disturbios", "MEDIA"),
]

async def fetch_gdelt_crime() -> list[dict]:
    out, errors = [], []
    for i, (q, domain, sev) in enumerate(GDELT_CRIME_QUERIES):
        try:
            data = await _gdelt_json("https://api.gdeltproject.org/api/v2/doc/doc", {
                "query": q, "mode": "ArtList", "format": "json",
                "maxrecords": 40, "timespan": "24h", "sort": "DateDesc",
            })
            arts = data.get("articles", [])
        except Exception as e:
            errors.append(f"{domain}: {type(e).__name__}: {e}")
            continue
        for a in arts:
            title = _strip_html(a.get("title") or "")
            if not title:
                continue
            g = geocode_text(title, None, key=title)
            approx = ""
            if not g:  # sin país en el titular: se usa el país del medio, marcado como aproximado
                g = geocode_text(_str(a.get("sourcecountry")), None, key=title)
                approx = " (ubicación aprox.: país del medio)"
            if not g:
                continue
            out.append(_mk(domain, "GDELT Crimen", g[0], g[1], sev, title,
                           f"{_str(a.get('domain'))} · {g[2]}{approx}", a.get("url") or "", [g[2]]))
    try:
        gdata = await _gdelt_json("https://api.gdeltproject.org/api/v2/geo/geo", {
            "query": "(crime OR cartel OR trafficking OR kidnapping OR homicide)",
            "format": "GeoJSON", "timespan": "24h",
        })
        for f in (gdata.get("features") or [])[:80]:
            coords = (f.get("geometry") or {}).get("coordinates") or []
            props = f.get("properties") or {}
            if len(coords) < 2:
                continue
            n = int(_num(props.get("count")))
            name = _strip_html(props.get("name") or "lugar")
            out.append(_mk("crimen", "GDELT GEO", float(coords[1]), float(coords[0]),
                           "ALTA" if n >= 25 else "MEDIA", f"Foco de actividad delictiva: {name}",
                           f"{n} artículos en 24 h", "", [name]))
    except Exception as e:
        errors.append(f"geo: {type(e).__name__}: {e}")
    if not out and errors:
        raise RuntimeError("; ".join(errors)[:300])
    return out

