def _crime_severity(cat: str) -> str:
    c = (cat or "").upper()
    if any(k in c for k in _CRIME_HIGH):
        return "ALTA"
    if any(k in c for k in _CRIME_MED):
        return "MEDIA"
    return "BAJA"

async def fetch_crime_cities() -> list[dict]:
    out, errors = [], []
    for city, url, params, pick in CRIME_CITIES:
        try:
            r = await _get(url, params=params, headers=RSS_HEADERS)
            for row in r.json():
                cat, desc, when, lat, lon = pick(row)
                try:
                    lat, lon = float(lat), float(lon)
                except (TypeError, ValueError):
                    continue
                cat = _str(cat) or "Incidente"
                out.append(_mk("crimen_urbano", f"Policía {city}", lat, lon, _crime_severity(cat),
                               f"{cat.title()} — {city}", f"{_str(desc).title()} · {_str(when)[:10]}", "", [], ["crimen"]))
        except Exception as e:
            errors.append(f"{city}: {type(e).__name__}: {e}")
    if not out and errors:
        raise RuntimeError("; ".join(errors)[:300])
    return out


