_FBI_CLOSED = ("captured", "recovered", "located", "surrendered", "deceased", "convicted", "pending extradition")

async def fetch_fbi_wanted() -> list[dict]:
    """FBI «Wanted»: buscados, Most Wanted, terroristas, cibercriminales, desaparecidos y «se busca información».
    API pública sin clave. Si no hay ubicación concreta se usa la de la oficina de campo (o EE. UU., marcado como aprox.)."""
    out = []
    for page in (1, 2):
        r = await _get("https://api.fbi.gov/wanted/v1/list", params={"page": page, "pageSize": 50, "sort_on": "modified", "sort_order": "desc"})
        for it in r.json().get("items", []):
            if _str(it.get("status")).lower() in _FBI_CLOSED:
                continue
            title = _strip_html(it.get("title") or "")
            if not title:
                continue
            subjects = " ".join(it.get("subjects") or [])
            cls = _str(it.get("poster_classification")).lower()
            body = _strip_html(it.get("description") or it.get("caution") or "")
            where = " ".join(_str(x) for x in (it.get("locations"), it.get("place_of_birth")))
            g = geocode_text(where, None, key=title) if where.strip() else None
            approx = ""
            if g:
                la, lo = g[0], g[1]
            else:
                office = next((FBI_OFFICES[re.sub(r"\W", "", _str(o).lower())] for o in (it.get("field_offices") or [])
                               if re.sub(r"\W", "", _str(o).lower()) in FBI_OFFICES), None)
                base = office or (39.8, -98.6)
                la, lo = jitter_coords(base[0], base[1], title, deg=0.25 if office else 6.0)
                approx = " (ubicación aprox.)"
            low = f"{subjects} {title} {cls}".lower()
            if "cyber" in low:
                dom, sev = "cibercrimen", "ALTA"
            elif "terror" in low:
                dom, sev = "terrorismo", "ALTA"
            elif cls == "missing" or "missing" in low or "kidnap" in low:
                dom, sev = "crimen", "MEDIA"
            else:
                dom, sev = "crimen", "ALTA" if cls in ("ten", "most wanted") or "murder" in low else "MEDIA"
            reward = _strip_html(it.get("reward_text") or "")[:80]
            out.append(_mk(dom, "FBI Wanted", la, lo, sev, f"FBI busca: {title}"[:200],
                           f"{subjects[:120]} · {reward}{approx}".strip(" ·"), it.get("url") or "", [], ["fbi", "wanted", cls or "wanted"]))
    return out

