_WIKI_CAT = (("armed conflicts", "conflicto", "ALTA"), ("disasters", "evento_natural", "MEDIA"),
             ("law and crime", "crimen", "MEDIA"), ("health", "salud", "MEDIA"))

async def fetch_wikipedia_events() -> list[dict]:
    """Wikipedia · Portal:Current events (hoy y ayer): conflictos, desastres, crimen y salud, ubicados por el país mencionado."""
    out = []
    now = datetime.now(timezone.utc)
    for back in (0, 1):
        d = now - timedelta(days=back)
        page = f"Portal:Current_events/{d.year}_{d.strftime('%B')}_{d.day}"
        try:
            r = await _get("https://en.wikipedia.org/w/api.php", params={"action": "parse", "page": page, "prop": "text", "format": "json", "formatversion": 2, "redirects": 1})
        except httpx.HTTPStatusError as ex:
            if ex.response.status_code == 403 and NEXUS_CONTACT.endswith("@localhost"):
                raise MissingKey("NEXUS_CONTACT=tu_correo_real (Wikipedia bloquea el contacto genérico)")     # su política exige un contacto real en el User-Agent
            raise
        html = ((r.json().get("parse") or {}).get("text")) or ""
        cat = None
        for m in re.finditer(r"<(?:p|div)[^>]*>\s*<b>([^<]{3,60})</b>|<li>(.*?)</li>", html, re.S | re.I):
            if m.group(1):
                low = m.group(1).strip().lower()
                cat = next((c for c in _WIKI_CAT if c[0] in low), None)
                continue
            if not cat:
                continue
            txt = _strip_html(m.group(2))
            if len(txt) < 25:
                continue
            g = geocode_text(txt, None, key=txt)
            if not g:
                continue
            link = re.search(r'href="(https?://[^"]+)"', m.group(2))
            out.append(_mk(cat[1], "Wikipedia", g[0], g[1], cat[2], txt[:200], g[2],
                           link.group(1) if link else f"https://en.wikipedia.org/wiki/{page}", [g[2]], ["wikipedia"]))
    return out[:80]

