# ── ₿ CRIPTO: noticias relevantes (hackeos, estafas, regulación, caídas/subidas fuertes). Sin clave; solo RSS públicos ──
_CRYPTO_RX = re.compile(r"bitcoin|\bbtc\b|ethereum|\beth\b|crypto|cripto|stablecoin|\bdefi\b|blockchain|\btoken|binance|coinbase|kraken|bybit|\bokx\b|kucoin|upbit|bithumb|"
                        r"solana|\bxrp\b|ripple|tether|\busdt\b|\busdc\b|\bnft\b|\bwallet|ledger|metamask|uniswap|lazarus|mixer|tornado cash|rug ?pull|exchange hack|\bsec\b.*(?:crypto|etf)|mica\b", re.I)
_CRYPTO_HACK = re.compile(r"hack|exploit|drain|stolen|steal|theft|breach|attack|rug ?pull|exit scam|insolven|collapse|fraud|scam|ponzi|seiz|hackeo|robo|estafa|robad|vaci", re.I)
_CRYPTO_BIG = re.compile(r"\$\s?\d{3,}(?:[.,]\d+)?\s?(?:m\b|million|millones)|\$\s?\d+(?:[.,]\d+)?\s?(?:b\b|billion|bn|mil millones)|\d{3,}\s?(?:million|millones)", re.I)
_CRYPTO_REG = re.compile(r"regulat|\bban\b|prohib|lawsuit|sues|\bsec\b|\bcftc\b|\bdoj\b|sanction|\betf\b|mica\b|license|licence|arrest|indict|charged|fine[ds]?\b|laundering|regulaci|demanda|sanci", re.I)
_CRYPTO_MKT = re.compile(r"crash|plunge|plummet|tumble|surge|soar|rall(?:y|ies)|record high|all-time|liquidat|depeg|de-peg|bank run|sell-?off|desplom|dispara|cae\b|hundim", re.I)
# ancla geográfica cuando el texto no nombra un lugar: autoridades y sedes conocidas (NO se inventa ubicación: sin ancla ni lugar, la noticia no se mapea)
_CRYPTO_ANCHORS = [
    (r"\bSEC\b|CFTC|\bDOJ\b|Justice Department|Treasury|OFAC|Federal Reserve|\bFBI\b|Congress|Senate|White House", 38.9, -77.04, "Washington"),
    (r"\bFCA\b|Bank of England|\bUK regulator", 51.51, -0.09, "London"),
    (r"\bECB\b|BaFin|Bundesbank", 50.11, 8.68, "Frankfurt"),
    (r"\bESMA\b|\bAMF\b|\bMiCA\b|Ledger\b", 48.86, 2.35, "Paris"),
    (r"\bMAS\b(?: regulator)?|Crypto\.com", 1.29, 103.85, "Singapore"),
    (r"\bSFC\b|Hong Kong", 22.32, 114.17, "Hong Kong"),
    (r"Upbit|Bithumb|Korbit|\bFSS\b|\bFSC\b", 37.57, 126.98, "Seoul"),
    (r"bitFlyer|Coincheck|\bDMM Bitcoin|\bFSA\b|Bank of Japan", 35.68, 139.69, "Tokyo"),
    (r"WazirX|CoinDCX|\bRBI\b", 19.08, 72.88, "Mumbai"),
    (r"Bybit|\bVARA\b|Dubai", 25.2, 55.27, "Dubai"),
    (r"Kraken|Coinbase|Ripple|Circle\b|Gemini|Robinhood", 37.77, -122.42, "San Francisco"),
    (r"Bitstamp", 49.61, 6.13, "Luxembourg"),
    (r"Lazarus|North Korea|Corea del Norte|\bDPRK\b", 39.02, 125.75, "Corea del Norte (atribuido)"),
    (r"Ethereum Foundation|Zug\b", 47.17, 8.52, "Zug"),
]
_CRYPTO_ANCHORS = [(re.compile(rx, re.I if "SEC" not in rx else 0), la, lo, nm) for rx, la, lo, nm in _CRYPTO_ANCHORS]

def crypto_classify(text: str) -> tuple[str, list[str]]:
    """(severidad, etiquetas) de una noticia cripto."""
    hack, big, reg, mkt = bool(_CRYPTO_HACK.search(text)), bool(_CRYPTO_BIG.search(text)), bool(_CRYPTO_REG.search(text)), bool(_CRYPTO_MKT.search(text))
    tags = ["prensa", "cripto"] + (["hackeo-cripto"] if hack else []) + (["regulacion"] if reg else []) + (["mercado"] if mkt else [])
    if hack and big:
        return "CRITICA", tags
    if hack:
        return "ALTA", tags
    if reg or (mkt and big):
        return "MEDIA", tags
    return "BAJA", tags

def crypto_geocode(text: str, key: str) -> Optional[tuple[float, float, str]]:
    g = geocode_text(text, None, key=key)
    if g:
        return g
    for rx, la, lo, nm in _CRYPTO_ANCHORS:
        if rx.search(text):
            la2, lo2 = jitter_coords(la, lo, key, deg=0.03)
            return la2, lo2, nm
    if _CRYPTO_MKT.search(text) and re.search(r"bitcoin|\bbtc\b|ethereum|\beth\b|crypto|cripto|stablecoin|tether", text, re.I):
        la2, lo2 = jitter_coords(40.707, -74.011, key, deg=0.05)      # mercado global sin lugar propio: se ancla (y se rotula) en Wall Street
        return la2, lo2, "Mercado global (ref. Wall Street)"
    return None

def make_crypto_collector(name: str, url: str, limit: int = 40, max_age_h: float = 36, need_kw: bool = True):
    async def _collector() -> list[dict]:
        out = []
        for e in await _fetch_rss(url):
            if _entry_age_hours(e) > max_age_h:
                continue
            title = _strip_html(e.get("title", ""))
            summ = _strip_html(e.get("summary", ""))[:300]
            text = f"{title}. {summ}"
            if not title or (need_kw and not _CRYPTO_RX.search(text)):
                continue
            g = crypto_geocode(text, title)
            if not g:
                continue
            sev, tags = crypto_classify(text)
            out.append(_mk("cripto", name, g[0], g[1], sev, title, summ or g[2], e.get("link") or "", [g[2]], tags))
            if len(out) >= limit:
                break
        return out
    _collector.__name__ = "fetch_crypto_" + re.sub(r"\W+", "_", name.lower())
    return _collector

