# ─── ★ NUEVO · WAR desde canales de Telegram oficiales/de guerra (sin clave): se leen igual que los de grupos y pasan por war_classify ───
WAR_TG_CHANNELS = list(dict.fromkeys(["kpszsu", "idfofficial", "mod_russia", "CENTCOM", "IDF_Arabic", "ukraine_defence", "OperativnyiZSU", "Ukraine_NOW_EN", "iranintl_en", "TasnimNews_EN", "presstv_telegram"]
                                     + [c.strip().lstrip("@") for c in os.getenv("NEXUS_WAR_TG_CHANNELS", "").split(",") if c.strip()]))
_WAR_TG_SEEN: set = set()
_WAR_TG_LAST = [0.0]

async def fetch_war_telegram() -> list[dict]:
    """Mensajes recientes de canales públicos (Fuerza Aérea de Ucrania, IDF, Min. Defensa ruso…) clasificados como ataque/explosión/aviso.
    Los canales que no existan o no tengan vista pública se apartan solos (se ven en 🩺 Fuentes). Nombres de canal sin verificar: añade los tuyos con NEXUS_WAR_TG_CHANNELS."""
    if os.getenv("NEXUS_TG_OFF") or time.time() - _WAR_TG_LAST[0] < WAR_POLL_MIN * 60:
        return []
    _WAR_TG_LAST[0] = time.time()
    out: list[dict] = []
    sem = asyncio.Semaphore(3)
    now = time.time()
    chans = [c for c in WAR_TG_CHANNELS if _TG_STATE.get(c, {}).get("dead_until", 0) <= now]       # los apartados (sin vista pública…) no se reintentan cada 8 min
    async def one(ch: str):
        async with sem:
            try:
                msgs, total = await asyncio.wait_for(_tg_channel(ch), 30)
                _tg_record(ch, total=total)
            except Exception as ex:
                _tg_record(ch, exc=ex)
                log.debug(f"[war_tg] {ch}: {type(ex).__name__}")
                return []
            return msgs
    for ch, msgs in zip(chans, await asyncio.gather(*[one(c) for c in chans])):
        for m in msgs:
            key = (m["chan"], m["id"])
            if key in _WAR_TG_SEEN or m["age"] > 40:
                continue
            _WAR_TG_SEEN.add(key)
            txt = (m["text"] or "").strip()
            if len(txt) < 25:
                continue
            title = txt.split("\n")[0][:160]
            c = war_classify(txt[:600])
            g = war_geocode(txt[:600], title) if c else None
            if not c or not g:
                continue
            dom, sev, tags = c
            out.append(_mk(dom, f"Telegram @{m['chan']}", g[0], g[1], sev, title, txt[:300], f"https://t.me/{m['chan']}/{m['id']}", [g[2]], tags + ["telegram", "sin-verificar"]))
    if len(_WAR_TG_SEEN) > 20000:
        _WAR_TG_SEEN.clear()
    return out

# ─── ★ NUEVO · sirenas de Israel (Tzeva Adom): alerta OFICIAL en tiempo real de cohetes/misiles/aeronaves hostiles. Endpoint comunitario sin verificar desde aquí ───
_TZEVA_SEEN: set = set()

async def fetch_tzevaadom() -> list[dict]:
    r = await _get("https://api.tzevaadom.co.il/notifications", timeout=15, headers={"Referer": "https://www.tzevaadom.co.il/", "User-Agent": "Mozilla/5.0"})
    data = r.json()
    out: list[dict] = []
    for n in data if isinstance(data, list) else []:
        nid = n.get("notificationId") or n.get("id")
        if not nid or nid in _TZEVA_SEEN or n.get("isDrill"):
            continue
        t = _num(n.get("time"))
        if t and time.time() - t > 6 * 3600:
            continue
        _TZEVA_SEEN.add(nid)
        cities = [str(c) for c in (n.get("cities") or [])][:12]
        threat = int(_num(n.get("threat")))
        kind = {0: "cohetes/misiles", 5: "aeronave hostil (dron)"}.get(threat, "alerta")
        la, lo = 31.5, 34.9
        for c in cities:
            g = geocode_text(c, "IL", key=f"{nid}{c}")
            if g:
                la, lo = g[0], g[1]
                break
        out.append(_mk("alerta_civil", "Tzeva Adom (sirenas Israel)", la, lo, "ALTA" if threat in (0, 5) else "MEDIA",
                       f"Sirenas en Israel: {kind} · {', '.join(cities[:4]) or 'varias zonas'}",
                       f"Alerta oficial del Mando del Frente Interno: {kind}. Zonas: {', '.join(cities)}", "https://www.tzevaadom.co.il/",
                       ["Israel"], ["guerra", "guerra:combate", "alarma:sirenas", "oficial", f"ataque:{'dron' if threat == 5 else 'misil'}"]))
    return out

NEWS_SOURCES.update({"war_telegram": fetch_war_telegram, "tzevaadom": fetch_tzevaadom})

# ─── ★ NUEVO: detector de alarmas ───
# Una «alarma» es lo que pide acción o atención inmediata: etiqueta alarma:<tipo> (WAR: ataque masivo, nuclear, movilización, evacuación…),
# y los eventos CRÍTICOS de conflicto, terrorismo, desastres naturales, salud, radiación y clima espacial. El ciber queda fuera (ya tiene su panel y sus CRÍTICOS).
ALARM_CRIT_DOMAINS = {"conflicto": "guerra", "terrorismo": "terrorismo", "geopolitica": "guerra", "alerta_civil": "guerra",
                      "explosion": "explosion", "internet": "caida", "terremoto": "desastre", "incendio": "desastre", "meteorologico": "desastre", "evento_natural": "desastre",
                      "radiacion": "radiacion", "salud": "salud", "espacio": "espacio", "humanitario": "humanitario", "aire": "aire"}

# ─── ★ NUEVO · terrorismo: un ATENTADO real (explosión, tiroteo, apuñalamiento, atropello, rehenes) sube a alarma aunque no llegue a CRÍTICO ───
_TERR_ATTACK = re.compile(
    r"\b(?:suicide (?:bomb(?:er|ing)?|attack|vest)|car bomb\w*|truck bomb\w*|bomb(?:ing)? (?:attack|blast)|bombs? (?:explod\w+|went off|kill\w+|rip\w+|rock\w+)|"
    r"(?:terror(?:ist)?|jihadist|islamist|extremist)s?\s+(?:attack|assault|strike|bomb\w*|shoot\w*|stabb\w*)\w*|"
    r"(?:mass |deadly |gun|knife|machete|stabbing|shooting|ramming|vehicle|car|truck|van)[- ]?(?:shooting|stabbing|attack|ramming|rampage|spree)|"
    r"(?:gunmen|gunman|attackers?|assailants?|militants?|extremists?|bombers?)\s+(?:\w+\s+){0,3}?(?:opened fire|open fire|stormed|storm|attacked|kill\w*|shot|stabbed|seized|took|detonat\w+|blew)|"
    r"hostage[- ](?:taking|crisis|siege|situation)|took (?:\w+ )?hostages?|taken hostage|IED (?:blast|explosion|attack)|\bIEDs?\b.{0,25}\b(?:kill\w*|blast|explod\w+)|"
    r"(?:blast|explosion|bomb)s?\s+(?:at|in|near|outside|inside)\s+(?:a |the )?(?:market|mosque|church|temple|synagogue|shrine|school|station|bus|stadium|concert|festival|hotel|mall|embassy|checkpoint)|"
    r"atentados?|ataque terrorista|coche bomba|terroristas? (?:atac|mat|ejecut)\w+|kamikaze|ataque suicida|toma de rehenes|attentat|attaque terroriste|Anschlag|attentato|"
    r"claims? responsibility|reivindic\w+ (?:el )?(?:ataque|atentado))\b", re.I)
_TERR_HARM = re.compile(r"\b(?:kill\w*|dead|death|died|wound\w*|injur\w*|casualt\w*|victims?|hostages?|muert\w+|herid\w+|v[ií]ctimas|fallecid\w+|morts?|bless[ée]s?|Tote|verletzt\w*|feriti|morti)\b", re.I)
_TERR_NOT = re.compile(
    r"\b(?:investigat\w+|trial|sentenc\w+|convict\w+|court|jury|prosecut\w+|charged|indict\w+|extradit\w+|anniversary|remembr\w+|memorial|commemorat\w+|"
    r"foil\w*|thwart\w*|prevent\w*|plot\w*|planned|suspected of|arrest\w*|detained|verdict|jail\w*|pleads?|pleaded|"
    r"war on terror|drill|exercise|simulat\w+|film|movie|series|documentary|novel|opinion|analysis|explainer|podcast|review|"
    r"aniversari\w*|juicio|condena\w*|investigaci[oó]n|frustr\w+|desarticul\w+|detenid\w+|cyber|hack\w*|ransomware|malware|phishing|ddos)\b", re.I)
_TERR_MASS = re.compile(r"\b(?:at least (?:[2-9]\d|\d{3,})|(?:[2-9]\d|\d{3,}) (?:people |civilians |worshippers |soldiers )?(?:were )?(?:killed|dead|murdered)|massacre|dozens (?:killed|dead)|scores (?:killed|dead)|hundreds (?:killed|dead)|decenas de muertos|masacre)\b", re.I)

def terror_classify(text: str) -> Optional[tuple[str, str, str]]:
    """(severidad, tipo, motivo) si el texto describe un atentado ocurrido; None si es investigación, juicio, amenaza, simulacro o ruido."""
    if not text or not _TERR_ATTACK.search(text):
        return None
    head = text[:400]
    if _TERR_NOT.search(head):
        return None                      # investigación, juicio, aniversario, complot frustrado, ciber…: no es un atentado nuevo
    if _STK_HYP.search(head) and not _TERR_HARM.search(head):
        return None
    cas = _war_casualties(text)
    if _TERR_MASS.search(text) or cas >= 20:
        sev = "CRITICA"
    elif _TERR_HARM.search(text) or cas > 0:
        sev = "ALTA"
    else:
        sev = "ALTA" if re.search(r"suicide|car bomb|truck bomb|hostage|rehenes|terror attack|ataque terrorista|atentado|attentat|Anschlag|attentato", text, re.I) else "MEDIA"
    if re.search(r"bomb|blast|explo|IED|detonat|kamikaze|suicide|atentado|coche bomba", text, re.I):
        kind = "explosion"
    elif re.search(r"hostage|rehenes", text, re.I):
        kind = "rehenes"
    elif re.search(r"stab|knife|machete|apu[ñn]al", text, re.I):
        kind = "apunalamiento"
    elif re.search(r"ramm|vehicle|truck|van\b|atropell", text, re.I):
        kind = "atropello"
    else:
        kind = "tiroteo"
    return sev, kind, "cas%d" % cas

_ARR_VERB = re.compile(r"\b(?:arrest\w*|detain\w*|apprehend\w*|taken into custody|custody|raid\w*|dismantl\w*|foil\w*|thwart\w*|nabbed|held on suspicion|detenid\w+|detenci[oó]n\w*|detienen|detiene|arrestad\w+|capturad\w+|desarticul\w+|redada|festgenommen|festnahme\w*|verhaftet|festnahmen|razzia|gefasst|interpell\w+|arr[eê]t[eé]\w*|garde à vue|garde a vue|interpel\w+|d[eé]mantel\w+|arrestat\w+|fermat\w+|fermo|blitz|zatrzyman\w+|gripna\w*|aresztowan\w*|aangehouden|opgepakt|arrestaties?|gripn\w+)\b", re.I)
_ARR_TERR = re.compile(r"(?:terror\w*|jihad\w*|jihadi\w*|yihad\w*|djihad\w*|d[ji]hadis\w*|islamist\w*|islamis\w+|islamic state|estado isl[aá]mico|[eé]tat islamique|islamischer staat|stato islamico|\bISIS\b|\bISIL\b|daesh|\bIS\b-|al[- ]?qaeda|al[- ]?qaida|al[- ]?shabaab|boko haram|hezbollah|hizb\w*|radicali[sz]\w+|extremis\w+|Terrorverd\w*|Terrorzelle|Anschlagspl\w+|attentat|atentado|terroriste|terrorista|cellule|c[eé]lula|\bcell\b|plot)", re.I)
_ARR_NOT = re.compile(r"\b(?:sentenc\w+|convicted|condenad\w+|condamn\w+|verurteilt\w*|condannat\w+|trial|juicio|proceso|procès|prozess|processo|acquitt\w+|absuelt\w+|released|liberad\w+|extradit\w+|anniversary|aniversario|movie|film|series|novel|drug|narco|cannabis|cocaine|football|soccer|match|fraud|estafa|fire|wildfire|incendio)\b", re.I)

def arrest_classify(text: str) -> Optional[str]:
    """'celula' | 'detenido' si el titular habla de una DETENCIÓN/desarticulación por terrorismo o yihadismo; None si no (condenas, juicios, noticias sin detención)."""
    if not text:
        return None
    head = text[:300]
    if not (_ARR_VERB.search(head) and _ARR_TERR.search(head)) or _ARR_NOT.search(head):
        return None
    if re.search(r"\b(?:cell|cells|c[eé]lula\w*|cellule\w*|Zelle\w*|network|red\b|r[eé]seau|rete\b|ring|plot\w*|complot|Anschlagspl\w+|dismantl\w+|desarticul\w+|d[eé]mantel\w+|foil\w+|thwart\w+|frustr\w+|sventat\w+|raids?|redada|razzia|blitz)\b", head, re.I):
        return "celula"
    return "detenido"

# ─── ★ NUEVO · ALERTAS DE BOMBA: mochilas/paquetes/vehículos sospechosos, amenazas de bomba, TEDAX, artefactos hallados y FALSAS ALARMAS ───
_BS_OBJ = re.compile(r"(?:(?:mochila|maleta|bolsa|bolso|paquete|bulto|objeto|veh[ií]culo|furgoneta|coche|equipaje|carta|sobre|caja|malet[ií]n)s?\s+(?:sospechos\w+|abandonad\w+|olvidad\w+|extra[nñ]\w+)"
                     r"|(?:suspicious|abandoned|unattended|unclaimed)\s+(?:backpack|rucksack|bag|package|parcel|object|vehicle|suitcase|luggage|device|item)s?"
                     r"|(?:backpack|rucksack|bag|package|parcel|suitcase|luggage)\s+(?:was\s+)?(?:left|found)\s+(?:unattended|abandoned)"
                     r"|artefacto\s+(?:explosivo|sospechoso|incendiario|casero)|dispositivo\s+(?:explosivo|sospechoso)|explosivos?\s+(?:hallad\w+|encontrad\w+)"
                     r"|(?:explosive|incendiary|improvised)\s+device|\bIED\b|pipe bomb|\bbomb\b(?!\s+(?:cyclone|calorimeter))|bomba\b|\bbombe\b|\bbomba(?:rdeo)?\b"
                     r"|amenaza\s+de\s+bomba|aviso\s+de\s+bomba|llamada\s+(?:de\s+)?(?:amenaza|aviso)|bomb\s+(?:threat|scare|hoax|alert|squad|disposal)|Bombendrohung|Bombenalarm|Sprengsatz|verd[aä]chtig\w+\s+(?:Gep[aä]ck|Rucksack|Koffer|Paket|Gegenstand)"
                     r"|alerte\s+(?:à|a)\s+la\s+bombe|colis\s+suspect|sac\s+suspect|bagage\s+abandonn\w+|objet\s+suspect|engin\s+explosif"
                     r"|allarme\s+bomba|pacco\s+sospetto|zaino\s+sospetto|valigia\s+sospett\w+|borsa\s+sospett\w+|ordigno|pakket\s+verdacht|verdacht\s+pakket|verdachte\s+(?:tas|koffer|rugzak|voorwerp)"
                     r"|\bTEDAX\b|artificier\w+|desactivadores\s+de\s+explosivos|\bEOD\b|bomb\s+disposal|d[eé]mineurs|Entsch[aä]rf\w+|artificieri|explosi[oó]n\s+controlada|controlled\s+(?:explosion|detonation)|detonaci[oó]n\s+controlada)", re.I)
_BS_ACT = re.compile(r"\b(?:controlled|controlada|desaloj\w+|desalojo|evacu\w+|cortad\w+|cierr\w+|cierre|acordon\w+|per[ií]metro|alert\w+|aviso|amenaza|hallaz\w+|halla\w*|hallad\w+|encuentr\w+|localiz\w+|detect\w+|desactiv\w+|neutraliz\w+|desarm\w+|revis\w+|inspecc\w+|investig\w+|falsa alarma|false alarm|evacuat\w+|cordon\w*|closed|shut|found|defus\w+|disarm\w+|detonat\w+|threat|scare|hoax|sealed off|alarm\w*|fausse alerte|falso allarme|Fehlalarm|gesperrt|ger[aä]umt|r[eé]cup[eé]r\w+|ritrovat\w+|sgomber\w+|évacu\w+|bouclé\w*)\b", re.I)
_BS_FALSE = re.compile(r"(?:falsa\s+alarma|false\s+alarm|fausse\s+alerte|falso\s+allarme|Fehlalarm|no\s+(?:era|era\s+una|resultó\s+ser|conten[ií]a|hab[ií]a)\s+(?:ninguna\s+)?(?:bomba|explosivo|nada)|nada\s+peligros\w+|sin\s+peligro|inofensiv\w+|no\s+supon\w+\s+(?:ning[uú]n\s+)?(?:peligro|riesgo)|resultó\s+(?:ser\s+)?(?:una\s+)?(?:falsa|inofensiv\w+|broma)|hoax|prank|broma|nothing\s+(?:dangerous|suspicious)|turned\s+out\s+to\s+be|no\s+threat|all\s+clear|sin\s+riesgo|ropa|material\s+escolar|objetos\s+personales|\bbenign\b|harmless|rien\s+de\s+dangereux|nulla\s+di\s+pericoloso)", re.I)
_BS_REAL = re.compile(r"(?:(?:hallan|halla|hallado|hallaron|encuentran|encontraron|encontrado|localizan|localizaron|descubren|descubrieron|detectan|incautan|intervienen|desactivan|desactivaron|neutralizan|neutralizaron|found|discover\w+|defus\w+|disarm\w+|seiz\w+|recover\w+|r[eé]cup[eé]r\w+|d[eé]couvert\w+|trouv\w+|ritrovat\w+|gefunden|entsch[aä]rft)\b[^.]{0,80}?(?:artefacto\s+explosivo|dispositivo\s+explosivo|explosive\s+device|\bIED\b|pipe bomb|\bbomba\b|\bbomb\b|explosivos?|engin\s+explosif|ordigno|Sprengsatz|bombe)|(?:artefacto\s+explosivo|dispositivo\s+explosivo|explosive\s+device|engin\s+explosif|ordigno|Sprengsatz)\b[^.]{0,60}?(?:hallad\w+|encontrad\w+|desactivad\w+|found|defused|neutralis\w+|neutraliz\w+|trouv\w+|ritrovat\w+|gefunden|entsch[aä]rft))", re.I)
_BS_ATTACK = re.compile(r"\b(?:muert\w+|fallecid\w+|herid\w+|v[ií]ctimas?|killed|dead|wounded|injured|casualt\w+|blast kills|explot[oó]|estall[oó]|detonó|exploded|atentado|attack|suicide|kamikaze|bombing|bombardeo|airstrike|missile|misil|dron\w*|drone|rocket|cohete|Gaza|Ukrain\w+|Ucrania|Rusia|Russia|Israel|Hamas|Hezbol\w+|Yemen|Sudan|S[uú]dan|Siria|Syria|Ir[aá]n|guerra|war|frente|front|bomba\s+at[oó]mica|nuclear|dirty bomb|cyber|ciber|bomb\s+cyclone|bomba\s+de\s+racimo|cluster)\b", re.I)
_BS_NOT = re.compile(r"\b(?:pel[ií]cula|film|movie|serie|videojuego|game|album|canci[oó]n|song|bath\s*bomb|bomba\s+de\s+ba[nñ]o|bomb\s+cyclone|ciclón\s+bomba|tormenta|f[uú]tbol|football|baloncesto|bomba\s+(?:calor|de\s+calor)|calorimet\w+|vino|bodega|receta|carne|bombazo|fichaje|cantante|actor|actriz|goal|gol\b)\b", re.I)

def bombscare_classify(text: str) -> Optional[tuple[str, str]]:
    """(tipo, severidad) si el titular trata de una alerta de bomba / objeto sospechoso: 'falsa' (falsa alarma), 'real' (artefacto hallado/desactivado) o 'sospechoso'.
    None si no lo es (atentados con víctimas, guerra, metáforas, deporte, cine…)."""
    if not text:
        return None
    head = text[:320]
    if not _BS_OBJ.search(head) or _BS_NOT.search(head):
        return None
    if _BS_ATTACK.search(head) and not _BS_FALSE.search(head):
        return None                       # atentados / guerra: van por su propio circuito (terrorismo, conflicto)
    if _BS_FALSE.search(head):
        return ("falsa", "BAJA")
    if not _BS_ACT.search(head):
        return None                       # menciona la palabra, pero no hay acción (evacuación, hallazgo, aviso…)
    if _BS_REAL.search(head):
        return ("real", "ALTA")
    return ("sospechoso", "MEDIA")

def bombscare_mark(e: dict) -> None:
    if e.get("domain") not in ("alerta_bomba", "noticias", "crimen", "crimen_urbano", "terrorismo", "disturbios", "alerta_civil", "geopolitica"):
        return
    r = bombscare_classify(f"{e.get('title','')}. {e.get('description','')}")
    if not r:
        return
    kind, sev = r
    e["domain"] = "alerta_bomba"
    rank = {"BAJA": 0, "MEDIA": 1, "ALTA": 2, "CRITICA": 3}
    if kind != "falsa" and rank[sev] > rank.get(e.get("severity"), 0):
        e["severity"] = sev
    elif kind == "falsa":
        e["severity"] = "BAJA"            # una falsa alarma no puede quedar como ALTA aunque la fuente la marcara así
    tg = _str(e.get("tags"))
    if "alerta-bomba" not in tg:
        e["tags"] = (tg + "," if tg else "") + f"alerta-bomba,bomba:{kind}"

def terror_mark(e: dict) -> None:
    """Reclasifica a terrorismo los atentados reales (aunque la fuente los pusiera en crimen/conflicto/disturbios) y les da severidad y alarma."""
    if e.get("domain") not in ("terrorismo", "crimen", "crimen_urbano", "conflicto", "disturbios", "alerta_civil", "noticias", "geopolitica"):
        return
    if e.get("domain") == "conflicto" and "ataque:" in _str(e.get("tags")):
        return                           # los ataques de guerra ya tienen su propio circuito (WAR)
    text = f"{e.get('title','')}. {e.get('description','')}"
    r = terror_classify(text)
    if not r:
        a = arrest_classify(text)           # detención/desarticulación de células: marca roja ✖ en el mapa, sin alarma de atentado
        if a:
            e["domain"] = "detencion_terror"
            if e.get("severity") in (None, "", "BAJA", "MEDIA"):
                e["severity"] = "ALTA" if a == "celula" else "MEDIA"
            tg = _str(e.get("tags"))
            if "detencion" not in tg:
                e["tags"] = (tg + "," if tg else "") + "detencion,terror:detencion" + (",celula" if a == "celula" else "")
        return
    sev, kind, _why = r
    rank = {"BAJA": 0, "MEDIA": 1, "ALTA": 2, "CRITICA": 3}
    e["domain"] = "terrorismo"
    if rank[sev] > rank.get(e.get("severity"), 0):
        e["severity"] = sev
    tg = _str(e.get("tags"))
    add = []
    if "terror:" not in tg:
        add.append("terror:" + kind)
    if "ataque:" not in tg:
        add.append("ataque:" + ("explosion" if kind == "explosion" else "general"))
    if "alarma:" not in tg and sev in ("ALTA", "CRITICA"):
        add.append("alarma:terrorismo")
    if add:
        e["tags"] = (tg + "," if tg else "") + ",".join(add)

def alarm_mark(e: dict) -> None:
    """Añade la etiqueta alarma:<tipo> a los eventos que merecen aviso inmediato."""
    tg = _str(e.get("tags"))
    if "alarma:" in tg:
        return
    if e.get("severity") == "CRITICA" and e.get("domain") in ALARM_CRIT_DOMAINS:
        e["tags"] = (tg + "," if tg else "") + "alarma:" + ALARM_CRIT_DOMAINS[e["domain"]]

def alarm_kind(tags: str) -> str:
    m = re.search(r"alarma:([\w-]+)", tags or "")
    return m.group(1) if m else ""

# ─── ★ NUEVO · confianza por evento y agrupación de duplicados ───
CONF_NAME = {"of": "oficial", "es": "estatal", "se": "sensor/dato", "pr": "prensa", "sv": "sin verificar"}
_SENSOR_SRC = ("USGS", "EMSC", "GDACS", "Estado ", "Digitraffic", "AISStream", "NOAA", "NASA", "IODA", "Cloudflare", "Safecast", "NIFC", "CAL FIRE", "Tzeva", "UCDP", "ACLED",
               "CISA", "URLhaus", "ThreatFox", "Feodo", "MalwareBazaar", "Spamhaus", "SANS", "Ráfaga")

def event_conf(tags: str, source: str = "") -> str:
    """Nivel de confianza por el ORIGEN del dato (no por si es verdad): of oficial · es estatal · se sensor/dato instrumental · pr prensa · sv sin verificar (Telegram, ráfagas). '' = sin clasificar."""
    t = "," + (tags or "") + ","
    if ",oficial," in t:
        return "of"
    if ",estatal," in t:
        return "es"
    if ",sin-verificar," in t or ",telegram," in t or ",rafaga-somera," in t:
        return "sv"
    if ",sensor-sismico," in t or _str(source).startswith(_SENSOR_SRC):
        return "se"
    if ",prensa," in t:
        return "pr"
    return ""

_GRP_STOP = frozenset("the and for with from after over into near says said that this have has was were are new les des une pour dans sur con los las del por una tras sobre como".split())
def _title_words(t: str) -> frozenset:
    return frozenset(w for w in re.findall(r"[a-záéíóúñüçäöß0-9]{4,}", (t or "").lower()) if w not in _GRP_STOP)

def group_items(items: list[dict], tk: str = "t", lat: str = "la", lon: str = "lo", src: str = "src", thr: float = 0.5, radius: float = 4.0) -> list[dict]:
    """Junta titulares que cuentan lo mismo (parecidos y cerca): un incidente con «N fuentes» en vez de N filas. El primero de cada grupo (el más prioritario) es el representante."""
    groups: list[dict] = []
    for it in items:
        w = _title_words(_str(it.get(tk)))
        hit = None
        for g in groups:
            if abs(_num(g["_la"]) - _num(it.get(lat))) > radius or abs(_num(g["_lo"]) - _num(it.get(lon))) > radius:
                continue
            gw = g["_w"]
            if w and gw and len(w & gw) / max(1, min(len(w), len(gw))) >= thr and len(w & gw) >= 2:
                hit = g
                break
        if hit is None:
            g = dict(it)
            g.update({"_w": w, "_la": it.get(lat), "_lo": it.get(lon), "n": 1, "srcs": [_str(it.get(src))] if it.get(src) else []})
            groups.append(g)
        else:
            hit["n"] += 1
            sname = _str(it.get(src))
            if sname and sname not in hit["srcs"]:
                hit["srcs"].append(sname)
    for g in groups:
        for k in ("_w", "_la", "_lo"):
            g.pop(k, None)
        g["srcs"] = g["srcs"][:6]
        g["ns"] = len(g["srcs"])
    return groups

def db_alarms(hours: int = 3, limit: int = 60) -> dict:
    hours = max(1, min(int(hours), 72))
    df = db_query_events(hours=hours, search="alarma:", limit=400)
    since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()
    conn = db_conn()
    try:
        n_sweeps = conn.execute("SELECT COUNT(DISTINCT sweep_id) FROM events WHERE timestamp > ?", (since,)).fetchone()[0]
    finally:
        conn.close()
    items, kinds = [], Counter()
    for r in df.to_dict("records"):
        k = alarm_kind(_str(r.get("tags")))
        if not k:
            continue
        kinds[k] += 1
        if len(items) < limit:
            items.append({"id": int(_num(r.get("id"))), "k": k, "sev": _str(r.get("severity")), "src": _str(r.get("source")), "d": _str(r.get("domain")),
                          "t": _str(r.get("title"))[:160], "u": _safe_url(r.get("url")), "la": _num(r.get("lat")), "lo": _num(r.get("lon")),
                          "a": _ago(r.get("timestamp")), "ts": _str(r.get("timestamp"))[:16].replace("T", " "),
                          "cf": event_conf(_str(r.get("tags")), _str(r.get("source")))})
    raw = len(items)
    items = group_items(items)
    return {"hours": hours, "sweeps": int(n_sweeps or 0), "n": int(sum(kinds.values())), "kinds": dict(kinds), "items": items, "grouped": raw - len(items)}


