# ★ NUEVO · WAR 2: sensores de explosiones, aviones militares, UCDP, radar de tensión, indicadores de aviso y parte de situación
# ════════════════════════════════════════════════════════
UCDP_KEY = os.getenv("UCDP_ACCESS_TOKEN")           # UCDP (Uppsala) exige un token gratuito que se pide por correo al mantenedor

async def fetch_explosiones() -> list[dict]:
    """Explosiones registradas por redes SÍSMICAS públicas (catálogo USGS ComCat, tipo «explosion» y «nuclear explosion»), últimos 2 días.
    Los sensores detectan la onda, no la causa: puede ser una voladura minera/industrial o un ataque. Por eso se filtran las de magnitud < 2,5
    (ruido de canteras) y la descripción lo avisa. Una «nuclear explosion» es siempre CRÍTICA y dispara alarma."""
    start = (datetime.now(timezone.utc) - timedelta(days=2)).strftime("%Y-%m-%dT%H:%M:%S")
    out = []
    for et, nuclear in (("explosion", False), ("nuclear explosion", True)):
        r = await _get("https://earthquake.usgs.gov/fdsnws/event/1/query",
                       params={"format": "geojson", "starttime": start, "eventtype": et, "orderby": "time", "limit": 200}, timeout=30)
        for f in r.json().get("features", []):
            p, g = f.get("properties") or {}, (f.get("geometry") or {}).get("coordinates") or []
            if len(g) < 2:
                continue
            lon, lat = float(g[0]), float(g[1])
            mag = _num(p.get("mag"), 0.0)
            if not nuclear and mag < 2.5:
                continue
            when = _ms_to_str(p.get("time"))
            place = _str(p.get("place")) or "ubicación sin nombre"
            sev = "CRITICA" if nuclear else "ALTA" if mag >= 4.0 else "MEDIA" if mag >= 3.0 else "BAJA"
            out.append(_mk("explosion", "USGS sísmico", lat, lon, sev,
                           (f"EXPLOSIÓN NUCLEAR detectada (sísmica) · M{mag:.1f} — {place}" if nuclear else f"Explosión detectada por sensores sísmicos · M{mag:.1f} — {place}"),
                           f"Registrada {when} UTC · profundidad {_num(g[2] if len(g) > 2 else 0):.0f} km · los sensores detectan la onda, no la causa: puede ser voladura minera/industrial o un ataque",
                           _str(p.get("url")) or "https://earthquake.usgs.gov/earthquakes/map/", [], ["explosion", "sensor-sismico", f"mag:{mag:.1f}"]
                           + (["guerra:nuclear", "alarma:nuclear"] if nuclear else []), fixed=True))
    return out

_BURST_BOXES = [(12.5, 40.0, 34.0, 64.0), (44.0, 57.0, 22.0, 48.0), (23.0, 38.0, 62.5, 81.0)]     # Oriente Medio/Golfo, Ucrania–Rusia, Afganistán–Pakistán–Cachemira

async def fetch_rafaga_somera() -> list[dict]:
    """Ráfagas de sismos SOMEROS (≤10 km) en zonas de guerra: ≥3 sismos pequeños casi en el mismo sitio en pocas horas (USGS + EMSC).
    Un sismo natural suele venir con réplicas más profundas; una serie de microsismos muy someros y agrupados es compatible con explosiones…
    pero también con enjambres naturales o voladuras mineras: se marca como POSIBLE, nunca como alarma. Si hay noticias de ataque cerca, sube de nivel."""
    start = datetime.now(timezone.utc) - timedelta(hours=12)
    evs: list[tuple[float, float, float, float, datetime]] = []      # lat, lon, mag, prof, hora
    for la0, la1, lo0, lo1 in _BURST_BOXES:
        try:
            r = await _get("https://earthquake.usgs.gov/fdsnws/event/1/query", params={
                "format": "geojson", "starttime": start.strftime("%Y-%m-%dT%H:%M:%S"), "minlatitude": la0, "maxlatitude": la1, "minlongitude": lo0,
                "maxlongitude": lo1, "minmagnitude": 1.5, "orderby": "time", "limit": 400}, timeout=30)
            for f in r.json().get("features", []):
                p_, g = f.get("properties") or {}, (f.get("geometry") or {}).get("coordinates") or []
                if len(g) >= 3 and p_.get("time"):
                    evs.append((float(g[1]), float(g[0]), _num(p_.get("mag")), _num(g[2]), datetime.fromtimestamp(float(p_["time"]) / 1000, timezone.utc)))
        except Exception as ex:
            log.debug(f"[rafaga] USGS: {type(ex).__name__}")
        try:
            r = await _get("https://www.seismicportal.eu/fdsnws/event/1/query", params={
                "format": "json", "start": start.strftime("%Y-%m-%dT%H:%M:%S"), "minlat": la0, "maxlat": la1, "minlon": lo0, "maxlon": lo1,
                "minmag": 1.5, "limit": 400}, timeout=30)
            for f in r.json().get("features", []):
                p_, g = f.get("properties") or {}, (f.get("geometry") or {}).get("coordinates") or []
                t = pd.to_datetime(p_.get("time"), utc=True, errors="coerce")
                if len(g) >= 2 and not pd.isna(t):
                    evs.append((float(p_.get("lat", g[1])), float(p_.get("lon", g[0])), _num(p_.get("mag")), abs(_num(p_.get("depth"), _num(g[2] if len(g) > 2 else 99))), t.to_pydatetime()))
        except Exception as ex:
            log.debug(f"[rafaga] EMSC: {type(ex).__name__}")
    shallow = sorted((e for e in evs if e[3] <= 10), key=lambda e: e[4])
    used, out = set(), []
    for i, a in enumerate(shallow):
        if i in used:
            continue
        grp = [j for j, b in enumerate(shallow) if j not in used and abs(b[0] - a[0]) <= 0.4 and abs(b[1] - a[1]) <= 0.45 and abs((b[4] - a[4]).total_seconds()) <= 3 * 3600]
        # el mismo sismo puede venir de USGS y de EMSC: se cuentan solo los distintos (a más de 90 s o 5 km de otro ya contado)
        uniq: list = []
        for j in grp:
            b = shallow[j]
            if not any(abs((b[4] - u[4]).total_seconds()) < 90 and abs(b[0] - u[0]) < 0.05 and abs(b[1] - u[1]) < 0.05 for u in uniq):
                uniq.append(b)
        if len(uniq) < 3:
            continue
        used.update(grp)
        la, lo = sum(u[0] for u in uniq) / len(uniq), sum(u[1] for u in uniq) / len(uniq)
        mx = max(u[2] for u in uniq)
        near = False
        try:
            sdf = await asyncio.to_thread(db_query_events, hours=24, domains=["conflicto", "geopolitica", "explosion"], search="ataque:", limit=300)
            for r_ in sdf.to_dict("records") if sdf is not None and not sdf.empty else []:
                if abs(_num(r_.get("lat")) - la) <= 1.8 and abs(_num(r_.get("lon")) - lo) <= 2.2:
                    near = True
                    break
        except Exception:
            pass
        sev = "ALTA" if (near or len(uniq) >= 6 or mx >= 4.0) else "MEDIA"
        t0 = min(u[4] for u in uniq).strftime("%H:%M")
        t1 = max(u[4] for u in uniq).strftime("%H:%M")
        out.append(_mk("explosion", "Ráfaga sísmica somera", la, lo, sev,
                       f"Ráfaga de {len(uniq)} sismos someros (≤10 km, máx. M{mx:.1f}) · posible explosión" + (" · con noticias de ataque cerca" if near else ""),
                       f"{t0}–{t1} UTC · series de microsismos muy superficiales y agrupados son compatibles con explosiones, pero también con enjambres naturales o voladuras mineras: "
                       f"NO es una confirmación; contrasta con prensa y fuentes oficiales" + (" (hay titulares de ataque en la zona en las últimas 24 h)" if near else ""),
                       "https://www.emsc-csem.org/Earthquake_map/", [], ["explosion", "sensor-sismico", "rafaga-somera", f"mag:{mx:.1f}"] + (["corroborado-prensa"] if near else []), fixed=True))
    return out

# Tipos ICAO de aeronaves militares de alto interés (reabastecedores, AWACS, reconocimiento, bombarderos, drones grandes, patrulla marítima)
_MIL_TYPES = {
    "K35R": "reabastecedor", "K35T": "reabastecedor", "K35E": "reabastecedor", "KC10": "reabastecedor", "KC46": "reabastecedor", "A332": "reabastecedor/transporte",
    "E3CF": "AWACS", "E3TF": "AWACS", "E3": "AWACS", "E6": "mando nuclear (TACAMO)", "E8": "JSTARS", "A50": "AWACS ruso", "R135": "reconocimiento (RC-135)", "U2": "reconocimiento (U-2)",
    "Q4": "dron estratégico (RQ-4)", "MQ9": "dron (MQ-9)", "B52": "bombardero", "B1": "bombardero", "B2": "bombardero", "B21": "bombardero",
    "T95": "bombardero ruso", "T160": "bombardero ruso", "P8": "patrulla marítima", "P3": "patrulla marítima",
}
_MIL_PRIO = ("bombardero", "mando nuclear", "reconocimiento", "dron", "AWACS", "JSTARS")

async def fetch_mil_flights() -> list[dict]:
    """Aviones militares con transponder ADS-B visibles ahora (adsb.lol, API pública sin clave). Solo tipos de ALTO INTERÉS (bombarderos, AWACS,
    reconocimiento, reabastecedores…). Cobertura parcial: los militares suelen apagar el transponder, y la receptores se concentran en EE. UU. y Europa.
    Posición redondeada a 0,5° para no llenar la base de datos con un registro por cada movimiento."""
    r = await _get("https://api.adsb.lol/v2/mil", timeout=30)
    rows = []
    for a in r.json().get("ac", []) or []:
        t = _str(a.get("t")).upper()
        kind = _MIL_TYPES.get(t)
        la, lo = a.get("lat"), a.get("lon")
        if not kind or la is None or lo is None or _str(a.get("alt_baro")).lower() == "ground":
            continue
        rows.append((0 if any(k in kind for k in _MIL_PRIO) else 1, a, t, kind, float(la), float(lo)))
    rows.sort(key=lambda x: x[0])
    out = []
    for _, a, t, kind, la, lo in rows[:150]:
        call = _str(a.get("flight")).strip() or _str(a.get("hex")).upper()
        la5, lo5 = round(la * 2) / 2, round(lo * 2) / 2
        hi = any(k in kind for k in _MIL_PRIO)
        hx = _str(a.get("hex")).upper()
        det = [f"tipo: {t} ({kind})"]
        for lab, val in (("matrícula", _str(a.get("r"))), ("ICAO", hx), ("altitud", (_str(a.get("alt_baro")) + " ft") if a.get("alt_baro") not in (None, "") else ""),
                         ("velocidad", (f"{float(a.get('gs')):.0f} kt") if isinstance(a.get("gs"), (int, float)) else ""),
                         ("rumbo", (f"{float(a.get('track')):.0f}°") if isinstance(a.get("track"), (int, float)) else ""), ("squawk", _str(a.get("squawk")))):
            if val:
                det.append(f"{lab}: {val}")
        out.append(_mk("vuelo_militar", "adsb.lol", la5, lo5, "MEDIA" if hi else "BAJA", f"{call} · {t} ({kind})",
                       " · ".join(det) + " · posición aproximada (±0,5°) · cobertura ADS-B parcial",
                       (f"https://globe.adsb.lol/?icao={hx.lower()}" if hx else "https://globe.adsb.lol/?mil"), [], ["vuelo", "militar", "alto-interes", f"aero:{kind}"] + ([f"hex:{hx}"] if hx else []), fixed=True))
    return out

async def fetch_ucdp() -> list[dict]:
    """UCDP (Universidad de Uppsala): eventos violentos georreferenciados con muertos, versión candidata (mensual). Necesita UCDP_ACCESS_TOKEN.
    Campos supuestos según su documentación; no verificado con una respuesta real."""
    if not UCDP_KEY:
        raise MissingKey("UCDP_ACCESS_TOKEN")
    now = datetime.now(timezone.utc)
    start, end = (now - timedelta(days=21)).strftime("%Y-%m-%d"), now.strftime("%Y-%m-%d")
    data = None
    for back in (1, 2, 3):                                       # la versión es AA.0.M del último mes publicado: prueba hacia atrás
        m, y = now.month - back, now.year
        while m < 1:
            m, y = m + 12, y - 1
        try:
            r = await _get(f"https://ucdpapi.pcr.uu.se/api/gedevents/{y % 100}.0.{m}", params={"pagesize": 1000, "page": 1, "StartDate": start, "EndDate": end},
                           headers={"x-ucdp-access-token": UCDP_KEY}, timeout=40)
            data = r.json().get("Result")
            if data:
                break
        except Exception as ex:
            if back == 3:
                raise
            log.warning(f"[ucdp] versión {y % 100}.0.{m}: {type(ex).__name__}")
    out = []
    for it in data or []:
        try:
            la, lo = float(it["latitude"]), float(it["longitude"])
        except (KeyError, TypeError, ValueError):
            continue
        best = int(_num(it.get("best")))
        a, b = _str(it.get("side_a")), _str(it.get("side_b"))
        place = _str(it.get("where_coordinates")) or _str(it.get("country"))
        sev = "CRITICA" if best >= 50 else "ALTA" if best >= 5 else "MEDIA"
        out.append(_mk("conflicto", "UCDP", la, lo, sev, f"{a} vs {b} — {place}"[:160],
                       f"{best} muertos (estimación UCDP; civiles {int(_num(it.get('deaths_civilians')))}) · inicio {_str(it.get('date_start'))[:10]} · {_str(it.get('source_headline'))[:150]}",
                       "https://ucdp.uu.se/", [_str(it.get("country"))], ["guerra", "ucdp", "oficial"] + ([f"bajas:{best}"] if best else [])
                       + (["alarma:ataque"] if sev == "CRITICA" else []), fixed=True))
    return out

# ─── Radar de tensión por teatro de operaciones + indicadores de aviso + parte de situación ───
# Teatros = cajas geográficas aproximadas (la primera que encaja gana). Es una heurística de lectura rápida, no una frontera política.
WAR_THEATRES = [
    ("Sudán", [(8, 23, 21, 38.5)], (15.5, 30.0)),
    ("Cáucaso", [(38.5, 44.5, 40, 51)], (41.5, 45.0)),
    ("Ucrania–Rusia", [(44, 53, 22, 40), (50, 57, 36, 48)], (49.0, 35.0)),
    ("Báltico, Polonia y Norte de Europa", [(53, 72, 5, 36), (47, 53, 14, 22)], (56.0, 21.0)),
    ("Balcanes", [(39, 47, 13, 30)], (43.5, 21.0)),
    ("Libia–Magreb", [(19, 38, -17, 34)], (30.0, 15.0)),
    ("Oriente Medio", [(12.5, 40, 34, 64)], (32.0, 42.0)),
    ("Cuerno de África", [(-2, 12.5, 34, 52)], (6.0, 45.0)),
    ("Sahel y África Occidental", [(4, 19, -18, 22)], (14.0, 2.0)),
    ("RD Congo y Grandes Lagos", [(-14, 8, 12, 36)], (-2.0, 26.0)),
    ("Myanmar", [(9, 29, 92, 102)], (21.0, 96.0)),
    ("Sur de Asia (Afganistán–Pakistán–Cachemira)", [(23, 38, 62.5, 81)], (32.0, 70.0)),
    ("Indo-Pacífico (Taiwán, Corea, mar de China)", [(0, 46, 105, 150)], (28.0, 122.0)),
    ("Latinoamérica", [(-56, 33, -118, -34)], (8.0, -70.0)),
]

def war_theatre(lat: float, lon: float) -> str:
    for name, boxes, _ in WAR_THEATRES:
        for a, b, c, d in boxes:
            if a <= lat <= b and c <= lon <= d:
                return name
    return "Resto del mundo"

def _war_weight(domain: str, sev: str, tags: str) -> float:
    s = _SEV_PTS.get(sev, 1.0)
    if domain == "vuelo_militar":
        return 0.15
    if domain == "explosion":
        return s * (2.0 if "alarma:nuclear" in tags else 0.8)
    if "guerra:nuclear" in tags:
        return s * 2.5
    if "guerra:escalada" in tags or "guerra:movilizacion" in tags:
        return s * 2.0
    if "guerra:aviso-civil" in tags:
        return s * 0.8
    if "guerra:diplomacia" in tags:
        return s * 0.3
    if "guerra:hibrida" in tags:
        return s * 1.0
    m = re.search(r"bajas:(\d+)", tags)
    if "guerra:combate" in tags or "ucdp" in tags:
        return s + (min(int(m.group(1)), 300) / 25.0 if m else 0.0)
    return s * 0.6            # conflicto/terrorismo sin clasificar (GDELT, ACLED…)

def _war_level_label(score: float) -> tuple[str, str]:
    return ("🔴", "CRÍTICA") if score >= 120 else ("🟠", "ALTA") if score >= 45 else ("🟡", "TENSIÓN") if score >= 12 else ("🟢", "CALMA")

_WAR_INDICATORS = [      # (nombre, predicado(domain, tags, sev), qué significa)
    ("Retórica o pruebas nucleares", lambda d, t, s: "guerra:nuclear" in t, "Amenazas, alertas o pruebas con armas nucleares."),
    ("Movilización, ley marcial, declaraciones de guerra", lambda d, t, s: "guerra:movilizacion" in t or "guerra:escalada" in t, "Pasos que suelen preceder a una guerra abierta."),
    ("Avisos de gobiernos a la población", lambda d, t, s: d == "alerta_civil", "Provisiones, refugios, evacuación (no implica guerra inminente)."),
    ("Guerra híbrida (GPS, sabotaje, espacio aéreo)", lambda d, t, s: "guerra:hibrida" in t, "Interferencias, cables cortados, drones sobre bases."),
    ("Combates con bajas", lambda d, t, s: ("guerra:combate" in t and "bajas:" in t) or "ucdp" in t, "Ataques con muertos reportados."),
    ("Explosiones detectadas por sensores", lambda d, t, s: d == "explosion", "Ondas sísmicas de explosiones (minería o ataques)."),
    ("Aviones militares de alto interés", lambda d, t, s: d == "vuelo_militar", "Bombarderos, AWACS, reconocimiento y reabastecedores con ADS-B."),
    ("Ceses el fuego o negociaciones rotas", lambda d, t, s: "guerra:diplomacia" in t and s == "MEDIA", "Treguas que fallan, rechazos, violaciones."),
]
_WAR_RADAR_CACHE: dict = {"t": 0.0, "v": None}

def war_radar(force: bool = False) -> dict:
    """Panorama de las últimas 24 h frente a las 24 h anteriores y a la media diaria de la semana previa. Heurístico: sirve para saber DÓNDE mirar, no predice."""
    if not force and _WAR_RADAR_CACHE["v"] and time.time() - _WAR_RADAR_CACHE["t"] < 60:
        return _WAR_RADAR_CACHE["v"]
    df = db_query_events(hours=192, domains=DOMAIN_GROUPS["war"], limit=40000)
    res = {"level": 1, "label": "NORMAL", "reasons": [], "theatres": [], "indicators": [], "digest": [], "n": 0,
           "generated": datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M")}
    if df is None or df.empty:
        res["reasons"] = ["Sin datos de guerra en la base: lanza un barrido."]
        _WAR_RADAR_CACHE.update(t=time.time(), v=res)
        return res
    ts = _dt(df["timestamp"])
    age = (pd.Timestamp.now(tz="UTC") - ts).dt.total_seconds() / 3600.0
    df = df.assign(_age=age).dropna(subset=["_age"])
    cur, prev, base = df[df["_age"] <= 24], df[(df["_age"] > 24) & (df["_age"] <= 48)], df[(df["_age"] > 24)]
    th: dict = {}
    def acc(frame, key):
        for r in frame.to_dict("records"):
            name = war_theatre(_num(r.get("lat")), _num(r.get("lon")))
            tg = _str(r.get("tags")); dom = _str(r.get("domain"))
            t = th.setdefault(name, {"name": name, "score": 0.0, "prev": 0.0, "n": 0, "combate": 0, "bajas": 0, "alarmas": 0, "mil": 0, "expl": 0, "esc": 0, "civil": 0, "last": None, "lw": -1.0})
            w = _war_weight(dom, _str(r.get("severity")), tg)
            t[key] += w
            if key != "score":
                continue
            t["n"] += 1
            t["alarmas"] += "alarma:" in tg
            t["mil"] += dom == "vuelo_militar"; t["expl"] += dom == "explosion"; t["civil"] += dom == "alerta_civil"
            t["esc"] += ("guerra:nuclear" in tg or "guerra:escalada" in tg or "guerra:movilizacion" in tg)
            t["combate"] += dom in ("conflicto", "terrorismo")
            m = re.search(r"bajas:(\d+)", tg)
            if m:
                t["bajas"] = max(t["bajas"], int(m.group(1)))
            if dom != "vuelo_militar" and w >= t["lw"]:
                t["lw"], t["last"] = w, r
    acc(cur, "score"); acc(prev, "prev")
    rows = []
    for t in th.values():
        if t["score"] <= 0 and t["prev"] <= 0:
            continue
        ic, lab = _war_level_label(t["score"])
        trend = (t["score"] - t["prev"]) / max(t["prev"], 5.0) * 100.0
        center = next((c for n, _, c in WAR_THEATRES if n == t["name"]), (20.0, 0.0))
        last = t.pop("last", None); t.pop("lw", None)
        rows.append(dict(t, icon=ic, level=lab, trend=round(trend), arrow="▲" if trend >= 25 else "▼" if trend <= -25 else "▶",
                         score=round(t["score"], 1), prev=round(t["prev"], 1), lat=center[0], lon=center[1],
                         last_t=_str(last.get("title"))[:150] if last else "", last_u=_safe_url(last.get("url")) if last else "",
                         last_ago=_ago(last.get("timestamp")) if last else ""))
    rows.sort(key=lambda x: -x["score"])
    mx = max([r["score"] for r in rows] or [1])
    for r in rows:
        r["pct"] = max(3, int(100 * r["score"] / mx))
    res["theatres"] = rows[:12]
    # indicadores de aviso: 24 h frente a la media diaria de los 7 días previos
    days_base = max(1.0, min(7.0, float(base["_age"].max() - 24) / 24.0)) if not base.empty else 1.0
    for name, pred, what in _WAR_INDICATORS:
        def cnt(fr):
            return int(sum(1 for r in fr.to_dict("records") if pred(_str(r.get("domain")), _str(r.get("tags")), _str(r.get("severity")))))
        n24, nb = cnt(cur), cnt(base)
        avg = nb / days_base
        factor = n24 / max(avg, 0.5)
        sig = "⚠ PICO" if (n24 >= 3 and factor >= 2.0) else "↑" if (n24 >= 2 and factor >= 1.5) else "↓" if (factor <= 0.5 and avg >= 2) else "="
        res["indicators"].append({"name": name, "what": what, "n24": n24, "avg": round(avg, 1), "factor": round(factor, 1), "sig": sig})
    ind = {i["name"]: i for i in res["indicators"]}
    # nivel global 1-5
    al = int(sum(r["alarmas"] for r in rows)); crit = [r for r in rows if r["level"] == "CRÍTICA"]; alta = [r for r in rows if r["level"] == "ALTA"]
    nuc_hard = any("alarma:nuclear" in _str(x) for x in cur["tags"].tolist()) if not cur.empty else False
    war_decl = any("alarma:escalada" in _str(x) for x in cur["tags"].tolist()) if not cur.empty else False
    level, reasons = 1, []
    if nuc_hard or war_decl:
        level = 5; reasons.append("alarma de nivel máximo en 24 h: " + ("explosión/amenaza nuclear dura" if nuc_hard else "declaración de guerra o ley marcial"))
    elif al >= 3 or len(crit) >= 2:
        level = 4; reasons.append(f"{al} alarmas y {len(crit)} teatro(s) en estado crítico")
    elif crit or ind["Movilización, ley marcial, declaraciones de guerra"]["n24"] >= 2:
        level = 3; reasons.append("un teatro crítico" if crit else "movilizaciones o escaladas repetidas")
    elif alta or ind["Avisos de gobiernos a la población"]["n24"] >= 3:
        level = 2; reasons.append("teatros en estado alto o varios avisos de gobiernos")
    for i in res["indicators"]:
        if i["sig"] == "⚠ PICO":
            reasons.append(f"pico en «{i['name']}»: {i['n24']} en 24 h (×{i['factor']} su media)")
    res["level"], res["label"] = level, {1: "NORMAL", 2: "ELEVADO", 3: "ALTO", 4: "MUY ALTO", 5: "CRÍTICO"}[level]
    res["n"] = int(len(cur))
    # parte de situación en frases
    dg = [f"Nivel global NEXUS {level}/5 ({res['label']}): " + ("; ".join(reasons) if reasons else "sin picos ni alarmas en las últimas 24 h") + "."]
    for r in rows[:5]:
        s = f"{r['icon']} {r['name']} ({r['level'].lower()}, {r['arrow']} {r['trend']:+d} % frente a las 24 h previas): {r['n']} eventos"
        if r["combate"]:
            s += f", {r['combate']} de combate" + (f" (hasta {r['bajas']} bajas en uno)" if r["bajas"] else "")
        if r["esc"]: s += f", {r['esc']} señal(es) de escalada"
        if r["civil"]: s += f", {r['civil']} aviso(s) a la población"
        if r["expl"]: s += f", {r['expl']} explosión(es) sísmica(s)"
        if r["alarmas"]: s += f", {r['alarmas']} alarma(s)"
        dg.append(s + ".")
    picks = [f"{i['name']} ×{i['factor']}" for i in res["indicators"] if i["sig"] in ("⚠ PICO", "↑")]
    dg.append("Indicadores al alza: " + ("; ".join(picks) if picks else "ninguno destacado") + ".")
    dg.append("Es un índice heurístico por reglas y palabras clave sobre titulares y sensores públicos: sirve para saber dónde mirar, no predice una guerra.")
    res["digest"] = dg
    _WAR_RADAR_CACHE.update(t=time.time(), v=res)
    return res

