_DD_UNITS = {"tbps": ("gbps", 1000.0), "tb/s": ("gbps", 1000.0), "gbps": ("gbps", 1.0), "gb/s": ("gbps", 1.0), "mbps": ("gbps", 0.001), "mb/s": ("gbps", 0.001),
             "bpps": ("pps", 1e9), "mpps": ("pps", 1e6), "kpps": ("pps", 1e3), "mrps": ("rps", 1e6), "krps": ("rps", 1e3), "rps": ("rps", 1.0)}
_DD_MAG = re.compile(r"(\d+(?:[.,]\d+)?)\s*(tbps|tb/s|gbps|gb/s|mbps|bpps|mpps|kpps|mrps|krps|rps)\b", re.I)
_DD_MAG_WORDS = re.compile(r"(\d+(?:[.,]\d+)?)\s*(million|billion)\s+(requests|packets)\s+per\s+second", re.I)
_DD_VECTORS = [
    ("syn-flood", r"\bsyn[- ]?flood|\bsyn attack"), ("udp-flood", r"\budp[- ]?flood"), ("ack-flood", r"\back[- ]?flood"), ("icmp-flood", r"\bicmp[- ]?flood|ping flood"),
    ("dns-amplificacion", r"dns (?:amplification|reflection)|\bdns flood|water torture"), ("ntp-amplificacion", r"\bntp (?:amplification|reflection)"),
    ("memcached", r"memcached"), ("ldap-reflexion", r"cldap|ldap (?:reflection|amplification)"), ("ssdp", r"\bssdp\b"),
    ("http2-rapid-reset", r"rapid reset|http/2 (?:rapid|attack)"), ("http-flood-l7", r"\bhttp[s]?[- ]?flood|layer ?7|\bl7\b|application[- ]layer|capa 7|\bget flood|\bpost flood"),
    ("slowloris", r"slowloris|slow(?:-| )?(?:read|post)"), ("tcp-reflexion", r"tcp (?:reflection|amplification)|\btcp flood"),
    ("carpet-bombing", r"carpet[- ]bombing"), ("reflexion-amplificacion", r"amplification|reflection attack|reflexi[oó]n"),
    ("botnet-iot", r"mirai|aisuru|eleven11|mylobot|kimwolf|gafgyt|bashlite|\biot botnet|botnet de iot"), ("booter-stresser", r"\bbooter|\bstresser"),
    ("volumetrico", r"volumetric|volum[eé]trico|saturaci[oó]n de (?:ancho|banda)"),
]
_DD_VEC_RX = [(n, re.compile(rx, re.I)) for n, rx in _DD_VECTORS]
_DD_SECTORS = [
    ("gobierno", r"government|ministry|parliament|municipal|city council|gobierno|ministerio|parlamento|ayuntamiento|gouvernement|regierung"),
    ("banca-finanzas", r"\bbank\w*|financial|payment|stock exchange|banco|bolsa|finanz|banque"),
    ("telecom-isp", r"telecom|\bisp\b|internet provider|operador|telefónica|mobile network"),
    ("gaming", r"gaming|steam|xbox|playstation|riot games|blizzard|\bgame servers?"),
    ("medios", r"news (?:site|outlet|agency)|newspaper|broadcaster|medios|periódico|televisi[oó]n"),
    ("salud", r"hospital|health(?:care)?|sanidad|santé|klinik"), ("transporte-aeropuertos", r"airport|airline|railway|port authority|aeropuerto|ferrocarril|renfe|aena"),
    ("educacion", r"universit\w+|school|education|universidad|colegio"), ("energia", r"energy|power grid|electric\w*|utility|oil|gas company|energ[ií]a"),
    ("cripto", r"crypto|exchange|blockchain|defi|wallet"),
]
_DD_SEC_RX = [(n, re.compile(rx, re.I)) for n, rx in _DD_SECTORS]
_DD_DUR = re.compile(r"(?:lasted|lasting|for|durante|durant)\s+(?:about |around |nearly |casi |unos )?(\d+(?:[.,]\d+)?)\s*(seconds?|minutes?|hours?|days?|segundos?|minutos?|horas?|d[ií]as?)", re.I)

def ddos_enrich(e: dict) -> None:
    """Etiqueta un evento DDoS con lo que se pueda documentar: vector(es), magnitud (Gbps/pps/rps), duración, grupo atribuido y sector. Todo por texto; no inventa."""
    if e.get("domain") != "ddos":
        return
    text = f"{e.get('title', '')}. {e.get('description', '')}"
    have = set(_str(e.get("tags")).split(","))
    add: list[str] = []
    for n, rx in _DD_VEC_RX:
        if rx.search(text) and f"vec:{n}" not in have and len([a for a in add if a.startswith("vec:")]) < 3:
            add.append(f"vec:{n}")
    best: dict[str, float] = {}
    for m in _DD_MAG.finditer(text):
        unit, mult = _DD_UNITS[m.group(2).lower()]
        v = float(m.group(1).replace(",", ".")) * mult
        best[unit] = max(best.get(unit, 0.0), v)
    for m in _DD_MAG_WORDS.finditer(text):
        v = float(m.group(1).replace(",", ".")) * (1e6 if m.group(2).lower() == "million" else 1e9)
        k = "rps" if m.group(3).lower() == "requests" else "pps"
        best[k] = max(best.get(k, 0.0), v)
    for unit, v in best.items():
        add.append(f"{unit}:{v:.0f}" if unit != "gbps" else f"gbps:{v:.1f}")
    d = _DD_DUR.search(text)
    if d:
        add.append(f"dur:{d.group(1).replace(',', '.')}{d.group(2).lower()[:3]}")
    low = text.lower()
    if not any(t.startswith("grupo:") for t in have):
        for name, _kind, _iso, aliases in ACTOR_GROUPS:
            if name.lower() in low or any(a in low for a in aliases):
                add.append(f"grupo:{name}")
                break
    for n, rx in _DD_SEC_RX:
        if rx.search(text):
            add.append(f"sec:{n}")
            break
    if "gbps" in "".join(add) or "rps:" in "".join(add):                       # un ataque que declara su tamaño se documenta con más gravedad
        g = best.get("gbps", 0.0)
        if g >= 1000 and e.get("severity") in ("BAJA", "MEDIA"):
            e["severity"] = "ALTA"
    if add:
        e["tags"] = ",".join(x for x in [_str(e.get("tags"))] + add if x)

_DD_REPORT_RX = re.compile(r"ddos|denial[- ]of[- ]service|botnet|\bflood\b|tbps|amplification|rapid reset|hacktivis", re.I)

def make_ddos_report_collector(name: str, url: str, limit: int = 15, max_age_h: float = 24 * 21):
    """Blog/informe de un proveedor anti-DDoS: solo las entradas que hablan de DDoS, ubicadas por el primer país que citan (si no hay país, se descartan)."""
    async def _collector() -> list[dict]:
        out = []
        for e in await _fetch_rss(url):
            if _entry_age_hours(e) > max_age_h:
                continue
            title = _strip_html(e.get("title", ""))
            summ = _strip_html(e.get("summary", ""))[:400]
            if not title or not _DD_REPORT_RX.search(f"{title} {summ}"):
                continue
            g = geocode_text(f"{title}. {summ}", None, key=title)
            if not g:
                continue
            out.append(_mk("ddos", name, g[0], g[1], "MEDIA", title, summ or g[2], e.get("link") or "", [g[2]], ["ddos", "informe", "proveedor"]))
            if len(out) >= limit:
                break
        return out
    _collector.__name__ = "fetch_ddosrep_" + re.sub(r"\W+", "_", name.lower())
    return _collector

