def _ddos_row(r: dict) -> dict:
    tg = _str(r.get("tags")).split(",")
    pick = lambda p: [t[len(p):] for t in tg if t.startswith(p)]
    fl = next((t for t in tg if t.startswith("flow:")), "")
    org, dst = (fl[5:].split(">") + [""])[:2] if fl else ("", "")
    gb = next(iter(pick("gbps:")), "")
    return {"ts": _str(r.get("timestamp"))[:16].replace("T", " "), "source": _str(r.get("source")), "severity": _str(r.get("severity")),
            "title": _str(r.get("title")), "description": _str(r.get("description")), "url": _safe_url(r.get("url")),
            "origin": org, "target": dst, "group": next(iter(pick("grupo:")), ""), "vectors": ";".join(pick("vec:")),
            "gbps": gb, "pps": next(iter(pick("pps:")), ""), "rps": next(iter(pick("rps:")), ""), "duration": next(iter(pick("dur:")), ""),
            "sector": next(iter(pick("sec:")), ""), "lat": _num(r.get("lat")), "lon": _num(r.get("lon")), "id": int(_num(r.get("id")))}

def ddos_dossier(days: int = 30, q: str = "") -> dict:
    days = max(1, min(int(days), 365))
    df = db_query_events(hours=days * 24, domains=["ddos"], search=q or None, limit=20000)
    rows = [_ddos_row(r) for r in df.to_dict("records")] if df is not None and not df.empty else []
    top = lambda key, n=8: [{"k": k_, "n": c} for k_, c in Counter(x for r in rows for x in ((r[key].split(";") if key == "vectors" else [r[key]])) if x).most_common(n)]
    big = max(rows, key=lambda r: float(r["gbps"] or 0), default=None)
    perday = Counter(r["ts"][:10] for r in rows)
    return {"days": days, "n": len(rows), "groups": top("group"), "vectors": top("vectors"), "targets": top("target"), "origins": top("origin"), "sectors": top("sector"),
            "sources": top("source"), "biggest": big if big and big["gbps"] else None, "withsize": sum(1 for r in rows if r["gbps"] or r["pps"] or r["rps"]),
            "perday": sorted(perday.items())[-30:], "rows": rows}

def _csv_safe(v) -> str:
    s = "" if v is None else str(v)
    return "'" + s if s[:1] in ("=", "+", "-", "@", "\t", "\r") else s       # evita que Excel ejecute fórmulas de texto de internet

