# ── ★ INTERPOL (notificaciones rojas), sanciones de la ONU y RansomLook — todo público, sin clave ──
INTERPOL_NATIONALITIES = ["MX", "CO", "BR", "RU", "CN", "US", "IT", "FR", "TR", "UA", "IN", "NG", "VE", "AR", "PE", "EC", "ES", "DE",
                          "GB", "AL", "RO", "PK", "ZA", "TH", "PH", "ID", "IR", "IQ", "SY", "EG", "MA", "DZ", "KZ", "GE", "BG", "RS"]

async def fetch_interpol() -> list[dict]:
    """INTERPOL · notificaciones rojas (API pública). La API limita cada consulta, así que cada barrido pide
    unas cuantas nacionalidades distintas (rotan) y se obtiene una muestra variada. Ubicación = país de nacionalidad."""
    out, errors, seen = [], [], set()
    picks = random.sample(INTERPOL_NATIONALITIES, 6)
    for i, nat in enumerate(picks):
        try:
            r = await _get("https://ws-public.interpol.int/notices/v1/red", params={"nationality": nat, "resultPerPage": 20, "page": 1},
                           headers={"Accept": "application/json", "Origin": "https://www.interpol.int", "Referer": "https://www.interpol.int/"})
            items = ((r.json().get("_embedded") or {}).get("notices")) or []
        except Exception as e:
            errors.append(f"{nat}: {type(e).__name__}: {e}")
            continue
        for it in items:
            eid = _str(it.get("entity_id"))
            if not eid or eid in seen:
                continue
            seen.add(eid)
            name = f"{_str(it.get('forename'))} {_str(it.get('name'))}".strip()
            nats = [n for n in (it.get("nationalities") or []) if isinstance(n, str)] or [nat]
            base = country_coords(nats[0]) or country_coords(nat)
            if not base:
                continue
            la, lo = jitter_coords(base[0], base[1], eid, deg=2.5)
            dob = _str(it.get("date_of_birth"))
            out.append(_mk("crimen", "INTERPOL", la, lo, "ALTA", f"INTERPOL notificación roja: {name}"[:200],
                           f"Nacionalidad: {', '.join(nats)}" + (f" · nac. {dob}" if dob else "") + " · ubicación aproximada (país)",
                           "https://www.interpol.int/How-we-work/Notices/Red-Notices/View-Red-Notices#" + eid.replace("/", "-"),
                           [COUNTRIES.get(nats[0], nats[0])], ["interpol", "red_notice", "wanted"]))
        await asyncio.sleep(0.6)
    if not out and errors:
        raise RuntimeError("; ".join(errors[:2]))
    return out

UN_SANCTIONS_URL = "https://scsanctions.un.org/resources/xml/en/consolidated.xml"

async def fetch_un_sanctions() -> list[dict]:
    """ONU · Lista Consolidada del Consejo de Seguridad (XML público). Se toman las inclusiones más recientes."""
    import xml.etree.ElementTree as ET
    r = await _get(UN_SANCTIONS_URL, timeout=60, headers={"Accept": "application/xml,text/xml,*/*"})
    root = ET.fromstring(r.content)
    rows = []
    for kind, tag in (("persona", "INDIVIDUAL"), ("entidad", "ENTITY")):
        for el in root.iter(tag):
            g = lambda t: _str((el.findtext(t) or "")).strip()
            name = " ".join(x for x in (g("FIRST_NAME"), g("SECOND_NAME"), g("THIRD_NAME"), g("FOURTH_NAME")) if x) or g("FIRST_NAME")
            if not name:
                continue
            listed = g("LISTED_ON")
            list_type = g("UN_LIST_TYPE")
            iso, nat = None, ""
            for tagc in (".//NATIONALITY/VALUE", ".//INDIVIDUAL_ADDRESS/COUNTRY", ".//ENTITY_ADDRESS/COUNTRY", ".//INDIVIDUAL_PLACE_OF_BIRTH/COUNTRY"):
                v = el.findtext(tagc)
                if not v:
                    continue
                hit = find_countries(v) or find_countries(" ".join(reversed([x.strip() for x in v.split(",")])))   # «Korea, North» -> «North Korea»
                if hit:
                    iso, nat = hit[0], v.strip()
                    break
            if not iso:
                continue
            rows.append((listed, kind, name, list_type, iso, nat, g("REFERENCE_NUMBER"), g("COMMENTS1")))
    rows.sort(key=lambda x: x[0], reverse=True)
    out = []
    for listed, kind, name, lt, iso, nat, ref, com in rows[:40]:
        base = country_coords(iso)
        la, lo = jitter_coords(base[0], base[1], ref or name, deg=1.2)
        terror = bool(re.search(r"al-?qaida|isil|da.?esh|taliban|boko|shabaab", lt + " " + com, re.I))
        out.append(_mk("sanciones", "ONU Sanciones", la, lo, "ALTA" if terror else "MEDIA", f"Sanción ONU ({kind}): {name}"[:200],
                       f"{lt} · incluido {listed} · {nat}" + (f" · {com[:120]}" if com else ""), "https://main.un.org/securitycouncil/en/content/un-sc-consolidated-list",
                       [COUNTRIES.get(iso, iso)], ["onu", "sanciones"] + (["terrorismo"] if terror else [])))
    return out

_TLD_ISO = {"uk": "GB"}

def _tld_country(text: str) -> Optional[str]:
    """ccTLD de un dominio citado en el texto (p. ej. «empresa.com.br» -> BR). None si no hay."""
    for m in re.finditer(r"\b[\w-]+(?:\.[\w-]+)*\.([a-z]{2})\b", text.lower()):
        iso = _TLD_ISO.get(m.group(1), m.group(1).upper())
        if iso in COUNTRY_DB:
            return iso
    return None

async def fetch_ransomlook() -> list[dict]:
    """RansomLook · publicaciones recientes de víctimas de ransomware (API pública, sin clave).
    Solo se ubican las víctimas cuyo dominio/nombre revela el país (ccTLD o país citado); el resto se descarta."""
    r = await _get("https://www.ransomlook.io/api/recent", timeout=40, headers={"Accept": "application/json"})
    data = r.json()
    if isinstance(data, dict):
        data = next((v for v in data.values() if isinstance(v, list)), [])
    out = []
    for it in (data or [])[:300]:
        if not isinstance(it, dict):
            continue
        victim = _str(it.get("post_title") or it.get("title") or it.get("victim"))
        group = _str(it.get("group_name") or it.get("group"))
        if not victim:
            continue
        iso = _tld_country(victim) or (find_countries(victim) or [None])[0]
        base = country_coords(iso) if iso else None
        if not base:
            continue
        la, lo = jitter_coords(base[0], base[1], victim + group, deg=1.5)
        out.append(_mk("ransomware", "RansomLook", la, lo, "ALTA", f"Ransomware {group}: {victim}"[:200],
                       f"Víctima publicada en el sitio de filtraciones de {group} · ubicación por dominio/país", "https://www.ransomlook.io/recent",
                       [group] if group else [], ["ransomware", "leak_site"] + ([group.lower()] if group else [])))
        if len(out) >= 60:
            break
    return out

