def _actor_rx(alias: str) -> str:
    toks = re.findall(r"[a-z0-9]+", alias.lower())
    return r"[\s_.\-]*".join(re.escape(t) for t in toks)

_ACTOR_RX = []      # (canon, regex): coincidencia con límites de palabra
_ACTOR_LOOSE = []   # (canon, alias normalizado): para nombres de canal (nn05716chat, killnet_reservs…)
for _n, _k, _h, _als in ACTOR_GROUPS:
    for _a in [_n] + list(_als):
        _p = _actor_rx(_a)
        if _p and len(re.sub(r"[^a-z0-9]", "", _a.lower())) >= 5:
            _ACTOR_RX.append((_n, re.compile(r"(?<![a-z0-9])" + _p + r"(?![a-z0-9])", re.I)))
            _ACTOR_LOOSE.append((_n, re.sub(r"[^a-z0-9]", "", _a.lower())))
_ACTOR_LOOSE.sort(key=lambda x: -len(x[1]))

def identify_group(text: str, loose: bool = False) -> Optional[str]:
    """Nombre canónico del grupo mencionado (o None). loose=True para nombres de canal de Telegram."""
    if not text:
        return None
    if loose:
        t = re.sub(r"[^a-z0-9]", "", text.lower())
        for canon, a in _ACTOR_LOOSE:
            if a in t:
                return canon
        return None
    for canon, rx in _ACTOR_RX:
        if rx.search(text):
            return canon
    return None

