_IPV4 = re.compile(r"(?<![\d.])(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)(?![\d]|\.\d)")

def _ips_in(text: str) -> list[str]:
    t = re.sub(r"\[\.\]|\(\.\)|\[dot\]|\(dot\)", ".", text or "", flags=re.I)
    out = []
    for ip in dict.fromkeys(m.group(0) for m in _IPV4.finditer(t)):
        if _valid_public_ip(ip):
            out.append(ip)
    return out



def _group_local_files() -> list[tuple[str, str, list[str]]]:
    """Ficheros grupo_<slug>.txt de tu carpeta intel/ de Andrómeda -> (grupo, origen, ips)."""
    out = []
    if not GROUP_IP_DIR or not os.path.isdir(GROUP_IP_DIR):
        return out
    for fn in sorted(os.listdir(GROUP_IP_DIR)):
        m = re.match(r"grupo_(.+)\.txt$", fn)
        if not m:
            continue
        slug = m.group(1)
        canon = identify_group(slug.replace("-", " ")) or identify_group(slug, loose=True) or slug.replace("-", " ").title()
        try:
            with open(os.path.join(GROUP_IP_DIR, fn), "r", encoding="utf-8", errors="ignore") as f:
                ips = sorted(_ips_in(f.read()))[:GROUP_IP_MAX]
        except OSError:
            continue
        if ips:
            out.append((canon, f"IP denunciada públicamente bajo este nombre (no verificada) · {fn}", ips))
    return out

_GIPS_DIAG: dict = {"t": "", "feeds_ok": 0, "feeds": 0, "seeds": 0, "ips": 0, "geo": 0, "err": ""}

async def _group_feed_ips(url: str) -> list[str]:
    hit = _GRP_FEED_CACHE.get(url)
    if hit and time.time() - hit[0] < _GRP_UA_DAYS:
        return hit[1]
    key = "gfeed:" + hashlib.md5(url.encode()).hexdigest()[:12]
    try:
        r = await _get(url, timeout=25, follow_redirects=True)
        ips = sorted(_ips_in(r.text))[:GROUP_IP_MAX]
        if ips:
            _GRP_FEED_CACHE[url] = (time.time(), ips)
            try:
                await asyncio.to_thread(kv_set, key, json.dumps({"t": time.time(), "ips": ips}))     # copia en disco: si mañana no responde, se usa esta
            except Exception:
                pass
        return ips
    except Exception:
        try:
            d = json.loads(kv_get(key) or "null")
        except ValueError:
            d = None
        if d and d.get("ips"):
            log.warning(f"[GRUPOS] {url.split('/')[2]} no responde: uso la copia guardada ({len(d['ips'])} IPs)")
            return d["ips"]
        raise

async def fetch_group_ips() -> list[dict]:
    """Mapa de IPs por grupo: se agrupan por país y celda de 4° (no un punto por IP). Si el feed dice a quién atacó (p. ej. el CERT suizo) se marca el
    flujo real país de la IP → víctima. Orden pensado para que NUNCA se quede vacío: 1) tus IPs en memoria (semillas) y archivos locales, que son pocas
    y se registran al momento; 2) los feeds públicos, que se descargan A LA VEZ y se geolocalizan por lotes guardando cada lote."""
    errors: list[str] = []
    seed_jobs: list = []
    for group, role, ips in _group_local_files():
        seed_jobs.append((group, role, None, ips, "local"))
    if os.getenv("NEXUS_GROUP_SEEDS", "1") != "0":             # tus IPs en memoria: ahora ENCENDIDAS por defecto (NEXUS_GROUP_SEEDS=0 las apaga)
        for group, role, ips in GROUP_IP_SEEDS:
            seed_jobs.append((group, role, None, [i for i in ips if _valid_public_ip(i)], "seed"))
    res = await asyncio.gather(*[_group_feed_ips(f[0]) for f in GROUP_IP_FEEDS], return_exceptions=True)
    feed_jobs: list = []
    for (url, group, role, victim), r in zip(GROUP_IP_FEEDS, res):
        if isinstance(r, BaseException):
            errors.append(f"{group}: {type(r).__name__}: {r}")
        else:
            feed_jobs.append((group, role, victim, r, url))
    jobs = seed_jobs + feed_jobs
    allips = list(dict.fromkeys(ip for j in jobs for ip in j[3]))
    _GIPS_DIAG.update(t=datetime.now(timezone.utc).isoformat(), feeds=len(GROUP_IP_FEEDS), feeds_ok=len(feed_jobs), seeds=sum(len(j[3]) for j in seed_jobs),
                      ips=len(allips), err="; ".join(errors)[:240])
    if not jobs:
        if errors:
            raise RuntimeError("; ".join(errors)[:300])
        return []

    async def register(part: list) -> None:
        ips = list(dict.fromkeys(ip for j in part for ip in j[3]))
        for ip in ips:                       # caché antigua sin país: se vuelve a resolver
            if ip in _GEO_CACHE and ip not in _GEO_CC:
                _GEO_CACHE.pop(ip, None)
        await geo_batch(ips)
        reg = []                       # registro permanente: UNA fila por IP y grupo (para la capa «IPs de grupos»)
        for group, role, victim, jips, url in part:
            for ip in jips:
                c = _GEO_CACHE.get(ip)
                if c:
                    reg.append({"ip": ip, "grp": group, "kind": GROUP_KIND.get(group, ""),
                                "role": role, "cc": _GEO_CC.get(ip, ""), "lat": c[0], "lon": c[1],
                                "source": "Archivo local de Andrómeda" if url == "local" else "Lista propia de Andrómeda" if url == "seed" else url.split("/")[2],
                                "url": url if url.startswith("http") else "", "conf": "reportada" if url in ("local", "seed") else "feed", "live": False})
        try:
            await asyncio.to_thread(db_upsert_group_ips, reg)
        except sqlite3.Error as e:
            log.warning(f"[GRUPOS] no se pudo guardar el registro de IPs: {e}")
        _GIPS_DIAG["geo"] = sum(1 for ip in allips if _GEO_CACHE.get(ip))

    for part in (seed_jobs, feed_jobs):          # primero lo pequeño y local: aunque los feeds tarden o se corten, el mapa ya tiene algo
        if part:
            try:
                await register(part)
            except Exception as e:
                errors.append(f"registro: {type(e).__name__}: {e}")
                _GIPS_DIAG["err"] = "; ".join(errors)[:240]
    today = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    out = []
    for group, role, victim, ips, url in jobs:
        cl: dict = {}
        for ip in ips:
            c = _GEO_CACHE.get(ip)
            if not c:
                continue
            cl.setdefault((_GEO_CC.get(ip, ""), round(c[0] / 4), round(c[1] / 4)), []).append((ip, c))
        for (cc, _, _), items in sorted(cl.items(), key=lambda kv: -len(kv[1]))[:25]:
            la = sum(c[0] for _, c in items) / len(items)
            lo = sum(c[1] for _, c in items) / len(items)
            cname = COUNTRY_DB[cc][0] if cc in COUNTRY_DB else "ubicación aprox."
            attacker = victim is not None
            dom = _KIND_DOMAIN.get(GROUP_KIND.get(group, ""), "ddos")
            tags = [dom, f"grupo:{group}", "ioc-feed", f"ips:{len(items)}", "at:src"]
            if victim and cc in COUNTRY_DB and cc != victim:
                tags.append(flow_tag(cc, victim))
            ents = [group, cname] + ([COUNTRY_DB[victim][0]] if victim in COUNTRY_DB else [])
            out.append(_mk(dom, "Grupos · IPs", la, lo,
                           "ALTA" if attacker else "MEDIA" if url != "local" else "BAJA",
                           f"{group}: {len(items)} IP · {cname} ({today})",
                           f"{role}. Ejemplos: {', '.join(ip for ip, _ in items[:5])}" + (f" · víctima: {COUNTRY_DB[victim][0]}" if victim in COUNTRY_DB else ""),
                           url if url.startswith("http") else "", ents, tags, fixed=True))
    if errors and not seed_jobs and len(feed_jobs) == 0:          # sin semillas y ningún feed respondió: ahí sí es un fallo de la fuente
        raise RuntimeError("ningún feed de grupos respondió: " + "; ".join(errors)[:260])
    return out

