# ── Anti falsos positivos ──
# 1) Un mensaje que HABLA de un grupo (acusaciones, atribuciones, análisis de prensa) no es una reivindicación del grupo.
_REPORT_RX = re.compile(r"acusan|acusad|atribuy|atribuid|atribuci[oó]n|supuest|presunt|patrocinad|respaldad|vinculad|apuntan a|se[ñn]alan a|responsabiliz|seg[uú]n (?:fuentes|medios|investig|expertos)|"
                        r"medios occidentales|investigaciones? (?:preliminar|apunta)|los investigadores|"
                        r"alleged|allegedly|blamed|blames|attribut|accused|accuses|linked to|suspected|believed to|reportedly|according to|researchers|investigators|analysts|"
                        r"soup[cç]onn|impute|zugeschrieben|beschuldig|attribuit|sospett", re.I)
_FIRST_PERSON_RX = re.compile(r"reivindic|\bclaims?\b|claimed|took responsibility|\bwe (?:have )?(?:hacked|attacked|downed|took|are attacking)|\bour (?:attack|team|ddos)|"
                              r"nosotros|hemos (?:hackeado|atacado|derribado)|nos responsabilizamos|hacked by|ddos(?:ed)? by|мы |взломал|атакова|ответственность", re.I)
_REPORT_SOFT = re.compile(r"seg[uú]n (?:fuentes|medios|investig|expertos)|investigaciones? (?:preliminar|apunta)|los investigadores|reportedly|according to|researchers|investigators|analysts", re.I)
def _is_report(text: str, press: bool = False) -> bool:
    """press=True: en prensa «según investigadores…» acompaña a incidentes reales, así que solo cuentan las acusaciones/atribuciones explícitas."""
    m = _REPORT_RX.search(text)
    if m and press and _REPORT_SOFT.fullmatch(m.group(0)):
        m = next((x for x in _REPORT_RX.finditer(text) if not _REPORT_SOFT.fullmatch(x.group(0))), None)
    return bool(m) and not _FIRST_PERSON_RX.search(text)

# 2) Un grupo no ataca a sus aliados (se descartan esos países como víctima). Lista ampliable.
_ALLIED_PAIRS = [{"RU", "BY"}, {"RU", "KP"}, {"RU", "IR"}, {"RU", "CN"}, {"RU", "SY"}, {"KP", "CN"}, {"KP", "IR"}, {"CN", "IR"}, {"IR", "SY"},
                 {"US", "IL"}, {"US", "GB"}, {"US", "CA"}, {"US", "AU"}, {"US", "NZ"}]
def _allied(a: Optional[str], b: Optional[str]) -> bool:
    return bool(a and b and (a == b or {a, b} in _ALLIED_PAIRS))

@db_write
def db_clean_false_claims() -> int:
    """Limpieza de reivindicaciones ya guardadas que ahora se descartan (informes/atribuciones, o ataques de un grupo a su aliado)."""
    try:
        conn = db_conn()
        rows = conn.execute("SELECT id, source, description, tags FROM events WHERE tags LIKE '%reivindicado%' AND tags LIKE '%grupo:%'").fetchall()
        bad = []
        for i, src, desc, tags in rows:
            m = _FLOW_RX.search(tags or "")
            if (m and _allied(m.group(1), m.group(2))) or _is_report(desc or "", str(src or "").endswith("Prensa")):
                bad.append(i)
        for k in range(0, len(bad), 500):
            conn.execute(f"DELETE FROM events WHERE id IN ({','.join('?' * len(bad[k:k + 500]))})", bad[k:k + 500])
        conn.commit(); conn.close()
        if bad:
            log.info(f"[DETECTOR] {len(bad)} reivindicaciones dudosas retiradas (informes/atribuciones o ataques a aliados)")
        return len(bad)
    except Exception as e:
        log.warning(f"[DETECTOR] limpieza: {type(e).__name__}: {e}")
        return 0

def _claim_victims(text: str, home: Optional[str]) -> list[str]:
    """Países objetivo citados en una reivindicación: banderas (peso 2), dominios con ccTLD y nombres de país."""
    w: dict[str, float] = {}
    for m in _FLAG.finditer(text):
        a, b = (chr(ord(ch) - 0x1F1E6 + 65) for ch in m.group(0))
        iso = a + b
        if iso in COUNTRY_DB:
            w[iso] = w.get(iso, 0) + 2
    for d in dict.fromkeys(m.group(0).lower() for m in _DOMAIN.finditer(text)):
        iso = _tld_country(d)
        if iso:
            w[iso] = w.get(iso, 0) + 1
    for _, _, iso in _nations(text):
        w[iso] = w.get(iso, 0) + 1
    if home:
        for k in [k for k in w if _allied(home, k)]:
            w.pop(k, None)
    return [k for k, _ in sorted(w.items(), key=lambda kv: -kv[1])[:3]]

