# ══════════════════════════════════════════════════════════════════════════════
# DETECTOR DE DENUNCIAS (la lógica de «buscar» de Andrómeda, ligera)
#   Recorre canales públicos de Telegram (t.me/s/, solo lectura) y feeds de seguridad, y en cada mensaje/noticia:
#   detecta el grupo (catálogo + canal) o amenaza (botnet/ransomware/APT), clasifica el TIPO de ataque, marca salud/energía,
#   extrae las IPs citadas (→ registro del mapa de IPs por grupo) y los países víctima (→ punto y flujo en el mapa).
#   Cada denuncia queda en la tabla group_detections (pestaña «🛰 Detector») AUNQUE no se pueda ubicar en el mapa.
#   Los canales se recorren por tandas rotativas (NEXUS_TG_PER_RUN) y los que no existen se saltan solos: no sobrecarga la máquina.
#   Honestidad: es lo que el grupo/la prensa DICE; no se verifica y no se traduce (no hay traductor gratuito fiable).
# ══════════════════════════════════════════════════════════════════════════════
TG_CHANNELS = list(dict.fromkeys(TG_CHANNELS + TG_ANDROMEDA_CHANNELS))
TG_PER_RUN = int(os.getenv("NEXUS_TG_PER_RUN", "60"))            # canales por pasada (rotan; 595 canales ≈ 10 pasadas)
GROUPS_FAST_MINUTES = float(os.getenv("NEXUS_GROUPS_MINUTES", "5"))
_TG_STATE: dict[str, dict] = {}                                    # canal -> {last, empty, dead_until, err}
_TG_BLOCK_UNTIL = 0.0                                              # tras un 429 de Telegram se espera un poco
_TG_BOOT = {"done": False}
TG_BUDGET_S = 100            # segundos de lectura por pasada: al agotarse se guarda lo leído y el resto sigue en la siguiente (antes: la pasada entera caducaba a los 150 s y NO se guardaba nada)
TG_CHUNK = 6                 # canales por tanda (se guarda tras cada tanda)
TG_CH_TIMEOUT = 28           # tope por canal

def _tg_boot() -> None:
    """Una sola vez: recupera el estado de los canales (motivos, reintentos) y los canales añadidos a mano, que antes se perdían al reiniciar."""
    if _TG_BOOT["done"]:
        return
    _TG_BOOT["done"] = True
    try:
        for c in json.loads(kv_get("tg_user", "[]") or "[]"):
            if re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{4,31}", str(c)) and c not in TG_CHANNELS:
                TG_CHANNELS.append(c)
        for c in json.loads(kv_get("tg_user_war", "[]") or "[]"):
            if re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{4,31}", str(c)) and c not in WAR_TG_CHANNELS:
                WAR_TG_CHANNELS.append(c)
        st = json.loads(kv_get("tg_state", "{}") or "{}")
        for c, v in st.items():
            if isinstance(v, dict) and c not in _TG_STATE:
                _TG_STATE[c] = {k: v[k] for k in ("last", "empty", "dead_until", "err", "reason", "n") if k in v}
    except Exception as e:
        log.debug(f"[TG] estado no recuperado: {e}")

def _tg_state_save() -> None:
    try:
        keep = {c: {k: v for k, v in st.items() if k in ("last", "empty", "dead_until", "err", "reason", "n", "info")} for c, st in list(_TG_STATE.items())[:1500]}
        kv_set("tg_state", json.dumps(keep))
    except Exception as e:
        log.debug(f"[TG] estado no guardado: {e}")

_RSS_STATE: dict[str, float] = {}
RSS_MIN_MINUTES = 20.0
_RUN_BOOST = {"n": 0}                                              # «Escanear ahora» sube temporalmente las tandas

_THREAT_KW = re.compile(
    r"ransomware|ddos|d\.?d\.?o\.?s|attack|ataque|hack|breach|malware|botnet|exploit|vulnerab|cyber|ciber|leak|compromis|phishing|"
    r"troyano|trojan|backdoor|zero-?day|ransom|dump|deface|extort|взлом|ддос|атак|слив|stealer|ransomw|intrusi|filtraci|brecha|0-?day", re.I)

def _words_rx(words: list[str]) -> re.Pattern:
    return re.compile("|".join(re.escape(w.lower()) for w in sorted(set(words), key=len, reverse=True)))
_HEALTH_RX = _words_rx(_HEALTH_WORDS)
_ENERGY_RX = _words_rx(_ENERGY_WORDS)

_THREAT_RX: list[tuple[str, str, re.Pattern]] = []
for _k, _names in _THREAT_NAMES.items():
    for _n in _names:
        _p = _actor_rx(_n)
        if _p:
            _THREAT_RX.append((_n, _k, re.compile(r"(?<![a-z0-9])" + _p + r"(?![a-z0-9])", re.I)))
for _n, _k in (("ShinyHunters", "cibercrimen"), ("Scattered Lapsus$ Hunters", "cibercrimen"), ("Lizard Squad", "hacktivista"),
               ("LunarisSec", "hacktivista"), ("Team R70", "hacktivista"), ("TeamTNT", "cibercrimen"), ("KaliCartel", "cibercrimen"),
               ("Palach Pro", "hacktivista"), ("IT Army of Ukraine", "hacktivista"), ("AnonGhost", "hacktivista"),
               ("Tegal Cyber Team", "hacktivista"), ("Kromsec", "hacktivista"), ("Team PCP", "cibercrimen")):
    _THREAT_RX.append((_n, _k, re.compile(r"(?<![a-z0-9])" + _actor_rx(_n) + r"(?![a-z0-9])", re.I)))
    GROUP_KIND.setdefault(_n, _k)

_ATYPE_DOMAIN = {"ddos": "ddos", "ransomware": "ransomware", "phishing": "phishing", "bruteforce": "bruteforce",
                 "malware": "malware", "botnet": "malware", "exploit": "exploit"}

def classify_attack_type(t: str) -> str:
    """Tipo de ataque (misma lista que Andrómeda): ddos, ransomware, phishing, bruteforce, malware, botnet, escaneo, filtración, exploit,
    infraestructura_critica, gobierno, militar, hackeo o ataque."""
    t = t.lower()
    def has(*ws): return any(w in t for w in ws)
    if has("ddos", "denegación de servicio", "denegacion de servicio", "denial of service", "layer 7", "layer7", "flood", "ataque de saturación",
           "sitio caído", "killnet", "noname057", "noname05716", "darkstorm", "anonymous sudan", "rootsec", "ддос", "check-host", "down!"):
        return "ddos"
    if has("ransomware", "ransom") or any(n.lower() in t for n in _THREAT_NAMES["ransomware"]):
        return "ransomware"
    if has("phishing", "vishing", "smishing"):
        return "phishing"
    if has("bruteforce", "brute force", "brute-force", "fuerza bruta"):
        return "bruteforce"
    if has("malware", "troyano", "trojan", "backdoor", "gusano", "worm", "stealer"):
        return "malware"
    if has("botnet", "mirai", "gafgyt") or any(n.lower() in t for n in _THREAT_NAMES["botnet"]):
        return "botnet"
    if has("port scan", "scanning", "nmap", "escaneo", "vulnerability scan"):
        return "escaneo"
    if has("breach", "filtración", "filtracion", "data leak", "leaked", "dump", "слив", "base de datos filtrada"):
        return "filtración"
    if has("exploit", "zero-day", "zero day", "0day", "vulnerabilidad", "cve-"):
        return "exploit"
    if has("infraestructura crítica", "infraestructura critica", "critical infrastructure", "red eléctrica", "power grid", "scada"):
        return "infraestructura_critica"
    if has("gobierno", "government", "ministerio", ".gov", "ministry"):
        return "gobierno"
    if has("militar", "military", "ejército", "ejercito", "defense", "defensa"):
        return "militar"
    if has("hackeo", "hack", "compromised", "intrusión", "intrusion", "deface"):
        return "hackeo"
    return "ataque"

_STOP_CAND = set("""the and for with this that from have been will your they their about after into over more than when what which who
were there here also just only some such very much many most other another these those would could should while because between during
under again against before above below being doing having does did can may might must shall not nor yet but all any each every both few
las los una unos unas del por con para que como pero sus sus este esta estos estas fue han hay muy mas más son era ser sin sobre entre
hasta desde cuando donde quien cual todo todos toda todas otro otra otros otras the attack attacks hacked hacker hackers leaked data
ddos ransomware malware breach cyber team group hacking telegram channel https http www com download join follow subscribe chat news""".split())

def scan_text(text: str, chan: str = "") -> Optional[dict]:
    """Analiza un mensaje/noticia. None = no habla de amenazas. Si no hay grupo, devuelve groups=[] (sirve para descubrir candidatos)."""
    if not text or len(text) < 15 or not _THREAT_KW.search(text):
        return None
    groups: list[tuple[str, str]] = []
    g = identify_group(text)
    if g:
        groups.append((g, GROUP_KIND.get(g, "")))
    if chan:
        g2 = identify_group(chan, loose=True)
        if g2 and all(g2 != x[0] for x in groups):
            groups.append((g2, GROUP_KIND.get(g2, "")))
    for name, kind, rx in _THREAT_RX:
        if len(groups) >= 3:
            break
        if rx.search(text) and all(name != x[0] for x in groups):
            groups.append((name, kind))
    low = text.lower()
    ips = _ips_in(text)
    return {"groups": groups[:3], "atype": classify_attack_type(text), "health": bool(_HEALTH_RX.search(low)),
            "energy": bool(_ENERGY_RX.search(low)), "ips": ips if len(ips) <= 40 else [], "report": _is_report(text)}

def _cand_words(text: str) -> list[str]:
    """Candidatos a grupo nuevo: palabras con mayúscula/dígitos/guion bajo (Team_R70, Lunaris…) que no son comunes ni países ni grupos conocidos."""
    out = []
    for w in dict.fromkeys(re.findall(r"\b[A-Z][A-Za-z0-9_]{3,20}\b|\b[a-z]{3,12}\d{2,4}\b", text)):
        lw = w.lower()
        if lw in _STOP_CAND or _nat_iso(lw) or identify_group(w, loose=True) or w.isupper() and len(w) <= 4:
            continue
        out.append(w)
    return out[:12]

# ── almacenamiento ──
@db_write
def db_save_detections(rows: list[dict]) -> int:
    if not rows:
        return 0
    conn = db_conn()
    n = 0
    for r in rows:
        try:
            conn.execute("""INSERT INTO group_detections (ts,grp,kind,atype,src_kind,source,title,url,victims,nips,health,energy,detected)
                            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                         (r["ts"], r["grp"], r.get("kind", ""), r["atype"], r["src_kind"], r["source"], r["title"][:240], r["url"],
                          ",".join(r.get("victims", [])), int(r.get("nips", 0)), int(bool(r.get("health"))), int(bool(r.get("energy"))),
                          datetime.now(timezone.utc).isoformat()))
            n += 1
        except sqlite3.IntegrityError:
            pass          # la misma URL+grupo ya estaba
    conn.commit()
    conn.close()
    return n

@db_write
def db_bump_candidates(words: Counter) -> None:
    if not words:
        return
    now = datetime.now(timezone.utc).isoformat()
    conn = db_conn()
    conn.executemany("""INSERT INTO group_candidates (word,freq,last_seen) VALUES (?,?,?)
                        ON CONFLICT(word) DO UPDATE SET freq=freq+excluded.freq, last_seen=excluded.last_seen""",
                     [(w, int(c), now) for w, c in words.items()])
    conn.execute("DELETE FROM group_candidates WHERE word NOT IN (SELECT word FROM group_candidates ORDER BY freq DESC LIMIT 400)")
    conn.commit()
    conn.close()

def db_detector(group: str = "", atype: str = "", src: str = "", hours: int = 168, limit: int = 150) -> dict:
    since = (datetime.now(timezone.utc) - timedelta(hours=max(1, hours))).isoformat()
    conn = db_conn()
    q, p = "SELECT ts,grp,kind,atype,src_kind,source,title,url,victims,nips,health,energy FROM group_detections WHERE ts > ?", [since]
    for col, val in (("grp", group), ("atype", atype), ("src_kind", src)):
        if val:
            q += f" AND {col} = ?"
            p.append(val)
    q += " ORDER BY ts DESC LIMIT ?"
    p.append(max(1, min(limit, 500)))
    rows = [dict(zip(("ts", "grp", "kind", "atype", "src_kind", "source", "title", "url", "victims", "nips", "health", "energy"), r))
            for r in conn.execute(q, p).fetchall()]
    for r in rows:
        r["url"] = _safe_url(r["url"])
        r["victims"] = [COUNTRY_DB[v][0] for v in r["victims"].split(",") if v in COUNTRY_DB]
    total = conn.execute("SELECT COUNT(*) FROM group_detections").fetchone()[0]
    day = conn.execute("SELECT COUNT(*) FROM group_detections WHERE ts > ?", ((datetime.now(timezone.utc) - timedelta(hours=24)).isoformat(),)).fetchone()[0]
    groups = [{"name": r[0], "n": r[1]} for r in conn.execute(
        "SELECT grp, COUNT(*) FROM group_detections WHERE ts > ? GROUP BY grp ORDER BY COUNT(*) DESC LIMIT 60", (since,)).fetchall()]
    types = [{"name": r[0], "n": r[1]} for r in conn.execute(
        "SELECT atype, COUNT(*) FROM group_detections WHERE ts > ? GROUP BY atype ORDER BY COUNT(*) DESC", (since,)).fetchall()]
    cands = [{"word": r[0], "n": r[1]} for r in conn.execute(
        "SELECT word, freq FROM group_candidates WHERE freq >= 3 ORDER BY freq DESC LIMIT 30").fetchall()]
    conn.close()
    now = time.time()
    dead = sum(1 for s in _TG_STATE.values() if s.get("dead_until", 0) > now)
    scanned = sum(1 for s in _TG_STATE.values() if s.get("last"))
    return {"rows": rows, "total": total, "day": day, "groups": groups, "types": types, "cands": cands,
            "channels": {"total": len(TG_CHANNELS), "scanned": scanned, "dead": dead, "feeds": len(GROUP_RSS_FEEDS)},
            "blocked": _TG_BLOCK_UNTIL > now}

