_TG_GATE: dict = {"t": 0.0, "lock": None}
TG_REASONS = {"ok": "✔ leyendo", "vacio": "⏸ sin mensajes en la vista pública", "sin_vista": "🚫 canal sin vista web pública (privado, restringido o con la vista desactivada)",
              "grupo": "👥 grupo público: Telegram no publica su contenido en la web (hace falta cuenta)", "no_existe": "❓ no existe (o es un usuario/bot sin mensajes públicos)",
              "perfil": "👤 es un perfil/bot: no tiene mensajes públicos",
              "restringido": "🚫 acceso denegado (403)", "limite": "⏳ Telegram limitó las peticiones (429)", "red": "⚠ fallo de red/tiempo", "": "· aún sin leer"}

# ── Lectura pasiva de t.me/s con la lógica de Andrómeda: cabeceras de navegador completas, «identidad» (User-Agent + cookies + idioma + referer) que se
#    renueva al primer 429 y cada 25-60 peticiones, 4 intentos con espera 2/4/8 s (el canal NO se da por muerto por un 429) y concurrencia adaptativa
#    (empieza en 2, sube hasta 4 si Telegram responde bien y baja a la mitad al primer 429/fallo). Sin cuenta, sin sesión de Telegram.
_TG_LANGS = ["es-ES,es;q=0.9,en;q=0.8", "en-US,en;q=0.9", "en-GB,en;q=0.9,es;q=0.6", "ru-RU,ru;q=0.9,en;q=0.8", "fr-FR,fr;q=0.9,en;q=0.8", "de-DE,de;q=0.9,en;q=0.8"]
_TG_REFS = [None, None, "https://t.me/", "https://www.google.com/", "https://duckduckgo.com/", "https://www.bing.com/"]
_TG_ID: dict = {"c": None, "n": 0, "limit": 40}
_TG_THR: dict = {"until": 0.0}
_TG_STATS = {"rot": 0, "n429": 0}

def _tg_identity(rotate: bool = False) -> dict:
    i = _TG_ID
    if i["c"] is None or rotate or i["n"] >= i["limit"]:
        old = i["c"]
        i.update(ua=random.choice(UA_POOL), lang=random.choice(_TG_LANGS), ref=random.choice(_TG_REFS), dnt=random.random() < 0.3, n=0,
                 limit=random.randint(25, 60), c=httpx.AsyncClient(timeout=20, follow_redirects=True))
        if old is not None:
            _TG_STATS["rot"] += 1
            try:
                asyncio.get_running_loop().create_task(old.aclose())
            except Exception:
                pass
    i["n"] += 1
    return i

class _TGGate:
    def __init__(self, limit: int = 2, maxl: int = 4):
        self.limit, self.max, self.inflight, self.ok, self.cv = limit, maxl, 0, 0, None
    async def acquire(self) -> None:
        if self.cv is None:
            self.cv = asyncio.Condition()
        async with self.cv:
            while self.inflight >= self.limit:
                await self.cv.wait()
            self.inflight += 1
    async def release(self, good: bool) -> None:
        async with self.cv:
            self.inflight -= 1
            if good:
                self.ok += 1
                if self.ok >= 8 and self.limit < self.max:
                    self.limit, self.ok = self.limit + 1, 0
            else:
                self.limit, self.ok = max(1, self.limit // 2), 0
            self.cv.notify_all()
_TG_GATE = _TGGate()

async def _tg_http(url: str, timeout: float = 20) -> httpx.Response:
    """GET a t.me como un navegador (misma idea que _tg_get de Andrómeda). Devuelve la respuesta (también 404); solo lanza error si se agotan los 4 intentos."""
    last = "red"
    for intento in range(4):
        d = _TG_THR["until"] - time.time()
        if d > 0:
            await asyncio.sleep(min(d, 3.0))
        ident = _tg_identity(rotate=(intento > 0))
        h = {"User-Agent": ident["ua"], "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
             "Accept-Language": ident["lang"], "Upgrade-Insecure-Requests": "1", "Cache-Control": "max-age=0"}
        if ident.get("ref"):
            h["Referer"] = ident["ref"]
        if ident.get("dnt"):
            h["DNT"] = "1"
        await _TG_GATE.acquire()
        resp, err, good = None, None, False
        try:
            await asyncio.sleep(random.uniform(0.03, 0.2))
            resp = await ident["c"].get(url, headers=h, timeout=timeout)
            good = resp.status_code not in (403, 429) and resp.status_code < 500
        except (httpx.HTTPError, asyncio.TimeoutError) as e:
            err = e
        finally:
            await _TG_GATE.release(good)
        if resp is None:
            last = type(err).__name__
            if intento == 3:
                raise err
            await asyncio.sleep(2 * (2 ** intento))
            continue
        if resp.status_code == 429 or (resp.status_code == 403 and intento == 0):
            _TG_STATS["n429"] += 1
            wait = min(2 * (2 ** intento) + random.uniform(0, 1), 15.0)
            _TG_THR["until"] = max(_TG_THR["until"], time.time() + min(wait * 0.5, 3.0))      # pausa común corta: no se lanzan todos a la vez tras un 429
            last = str(resp.status_code)
            await asyncio.sleep(wait)
            continue
        return resp
    raise RuntimeError(f"HTTP {last}: Telegram limitó la lectura tras 4 intentos con identidades distintas")

def _tg_record(ch: str, total: Optional[int] = None, exc: Optional[Exception] = None) -> None:
    """Anota el resultado de leer un canal (estado, motivo legible y cuándo reintentar). Un canal solo se aparta si el PROBLEMA ES DEL CANAL, nunca por la red."""
    global _TG_BLOCK_UNTIL
    st = _TG_STATE.setdefault(ch, {})
    st["last"] = time.time()
    _tgp_schedule()                                    # guarda en segundo plano lo leído hasta ahora
    if exc is None:
        st["err"] = ""
        st["n"] = total or 0
        if not total:
            st["empty"] = st.get("empty", 0) + 1
            st["reason"] = "vacio"
            if st["empty"] >= 3:
                st["dead_until"] = time.time() + 30 * 60           # solo espaciar: se vuelve a mirar en media hora
        else:
            st["empty"] = 0
            st["reason"] = "ok"
            st["dead_until"] = 0
        return
    msg = str(exc)
    st["err"] = type(exc).__name__
    if "429" in msg:
        _TG_BLOCK_UNTIL = time.time() + 90
        st["reason"] = "limite"
    elif "sin vista pública" in msg or "404" in msg:
        info = getattr(exc, "info", None) or {}
        kind = info.get("kind", "")
        # el perfil que Telegram devolvió dice POR QUÉ no hay vista: grupo, perfil/bot, nada, o canal sin vista web. Se reintenta con calma (12-24 h).
        st["reason"] = {"grupo": "grupo", "nada": "no_existe", "perfil": "perfil"}.get(kind, "sin_vista")
        st["dead_until"] = time.time() + (24 if kind in ("grupo", "nada", "perfil") else 12) * 3600
        if info:
            st["info"] = {**info, "t": time.time()}
    elif "403" in msg:
        st["reason"] = "restringido"
        st["dead_until"] = time.time() + 60 * 60
    elif re.search(r"\b(4\d\d|5\d\d)\b", msg):
        st["reason"] = "red"
        st["dead_until"] = time.time() + 15 * 60
    else:
        st["reason"] = "red"                                       # DNS / tiempo agotado: es la conexión, no el canal

# Descubrimiento por menciones: los canales que otros canales públicos ya citan (t.me/<canal>) y que se repiten ≥2 veces se añaden solos a la lista (máx. 100; NEXUS_TG_DISCOVER=0 lo apaga).
_TG_DISC: dict = {"loaded": False, "n": {}, "added": []}
_TG_DISC_RX = re.compile(r"(?:https?://)?(?:t|telegram)\.me/(?:s/)?([A-Za-z][A-Za-z0-9_]{4,31})(?![A-Za-z0-9_])")
_TG_DISC_SKIP = {"joinchat", "addstickers", "proxy", "socks", "share", "iv", "login", "setlanguage", "addtheme", "bg", "invoice", "boost", "telegram", "durov", "username", "contact"}
TG_DISCOVER_MAX = 100

def _tg_discover(texts: list[str]) -> None:
    if os.getenv("NEXUS_TG_DISCOVER", "1") == "0":
        return
    if not _TG_DISC["loaded"]:
        _TG_DISC["loaded"] = True
        try:
            d = json.loads(kv_get("tg_discovered", "{}") or "{}")
            _TG_DISC["n"], _TG_DISC["added"] = dict(d.get("n", {})), list(d.get("added", []))
            for c in _TG_DISC["added"]:
                if c not in TG_CHANNELS:
                    TG_CHANNELS.append(c)
        except Exception:
            pass
    known = {c.lower() for c in TG_CHANNELS} | {c.lower() for c in WAR_TG_CHANNELS}
    changed = False
    for t in texts:
        for m in _TG_DISC_RX.finditer(t):
            c = m.group(1)
            if c.lower() in _TG_DISC_SKIP or c.lower() in known or c.lower().endswith("bot"):
                continue
            _TG_DISC["n"][c] = _TG_DISC["n"].get(c, 0) + 1
            changed = True
            if _TG_DISC["n"][c] >= 2 and len(_TG_DISC["added"]) < TG_DISCOVER_MAX:
                _TG_DISC["added"].append(c)
                TG_CHANNELS.append(c)
                known.add(c.lower())
    if len(_TG_DISC["n"]) > 3000:
        _TG_DISC["n"] = dict(sorted(_TG_DISC["n"].items(), key=lambda kv: -kv[1])[:1000])
    if changed:
        try:
            kv_set("tg_discovered", json.dumps({"n": _TG_DISC["n"], "added": _TG_DISC["added"]}))
        except Exception:
            pass

# ─── ★ NUEVO · TELEGRAM PASIVO v2 ────────────────────────────────────────────────────────────────────────────────────────────────
# 1) Cuando t.me/s/<canal> redirige al perfil, ese perfil YA estaba descargado: se lee para saber POR QUÉ no se puede (grupo, perfil, no existe,
#    canal sin vista web) en vez de apartar el canal con un «sin vista» genérico.  2) Cada publicación leída (también las de solo foto/vídeo y las
#    antiguas) se guarda completa: texto, vistas, medios, reenvío y vista previa del enlace.  3) Búsqueda por NOMBRE: se prueban variantes del
#    nombre en t.me (sin cuenta) y se dice cuáles existen y cuáles se pueden leer.  4) Pestaña «📡 Telegram» con todo eso.
TG_KEEP_DAYS = max(2, int(os.getenv("NEXUS_TG_KEEP_DAYS", "21") or 21))
_TG_POSTBUF: list = []
_TGP_DONE: dict = {}
_TGP_STATE: dict = {"timer": None, "purge": 0.0, "lock": threading.Lock()}
_TG_SUBS = ("subscriber", "suscriptor", "подписчик", "abonn", "abonnent", "iscritt", "assinante", "abone")
_TG_MEMB = ("member", "miembro", "участник", "membre", "mitglied", "membri", "membro", "üye")

def _tg_views(s) -> int:
    t = _str(s).strip().upper().replace(",", ".").replace(" ", "").replace("\u00a0", "")
    mult = 1000 if t.endswith("K") else 1_000_000 if t.endswith("M") else 1
    try:
        return int(float(t.rstrip("KM")) * mult)
    except ValueError:
        return 0

def _tg_rich(blk: str, chan: str, mid: int) -> dict:
    """Todo lo visible de una publicación de la vista pública: texto completo, hora, vistas, medios, reenvío y vista previa de enlace."""
    txt = re.search(r'tgme_widget_message_text[^"]*"[^>]*>(.*?)</div>', blk, re.S)
    body = ""
    if txt:
        raw = txt.group(1)
        body = _strip_html(re.sub(r"<br\s*/?>", "\n", raw))
        links = [htmllib.unescape(h) for h in re.findall(r'href="([^"]+)"', raw) if h.startswith("http") and "t.me/" not in h]
        if links:
            body = (body + "\n" + " ".join(links)).strip()
    ts = ""
    tm = _TG_TIME.search(blk)
    if tm:
        try:
            ts = datetime.fromisoformat(tm.group(1)).astimezone(timezone.utc).isoformat()
        except ValueError:
            ts = ""
    v = re.search(r'tgme_widget_message_views">([^<]*)<', blk)
    media = [k for k, pat in (("foto", "tgme_widget_message_photo_wrap"), ("vídeo", "tgme_widget_message_video_wrap|tgme_widget_message_roundvideo"),
                              ("archivo", "tgme_widget_message_document"), ("audio", "tgme_widget_message_voice"), ("encuesta", "tgme_widget_message_poll"),
                              ("enlace", "tgme_widget_message_link_preview")) if re.search(pat, blk)]
    fwd = re.search(r'tgme_widget_message_forwarded_from_name[^>]*>(.*?)</', blk, re.S)
    lp: dict = {}
    if "tgme_widget_message_link_preview" in blk:
        for k, cl in (("s", "link_preview_site_name"), ("t", "link_preview_title"), ("d", "link_preview_description")):
            m = re.search(r'%s[^>]*>(.*?)</div>' % cl, blk, re.S)
            if m:
                lp[k] = _strip_html(m.group(1))[:240]
        u = re.search(r'tgme_widget_message_link_preview"[^>]*href="([^"]+)"', blk)
        if u:
            lp["u"] = htmllib.unescape(u.group(1))[:300]
    return {"chan": chan, "id": mid, "ts": ts, "text": body[:4000], "views": _tg_views(v.group(1)) if v else 0, "media": ",".join(media),
            "fwd": _strip_html(fwd.group(1))[:80] if fwd else "", "lp": json.dumps(lp, ensure_ascii=False) if lp else "",
            "reply": 1 if "tgme_widget_message_reply" in blk else 0}

def _tg_profile(html: str) -> dict:
    """Perfil público t.me/<nombre>: lo que Telegram devuelve cuando NO hay vista web. Dice qué es (canal, grupo, perfil/bot, nada) y su tamaño."""
    def cls(c: str) -> str:
        m = re.search(r'class="%s"[^>]*>(.*?)</div>' % c, html, re.S)
        return _strip_html(m.group(1)).strip() if m else ""
    t_div = cls("tgme_page_title")                     # existe solo si el usuario/canal/grupo EXISTE (si no, Telegram solo pone «Contact @nombre» en og:title)
    title = t_div
    if not title:
        m = re.search(r'<meta property="og:title" content="([^"]*)"', html)
        title = htmllib.unescape(m.group(1)).strip() if m else ""
    extra, desc = cls("tgme_page_extra"), cls("tgme_page_description")
    low = extra.lower()
    n = 0
    m = re.search(r"(\d[\d\s.,\u00a0]*)", extra)
    if m:
        n = int(re.sub(r"\D", "", m.group(1)) or 0)
    if any(w in low for w in _TG_SUBS):
        kind = "canal"
    elif any(w in low for w in _TG_MEMB):
        kind = "grupo"
    elif t_div and (desc or extra):
        kind = "perfil"
    else:
        kind = "nada"
    return {"kind": kind, "title": title[:120], "n": n, "desc": desc[:300]}

def _tg_chaninfo(html: str) -> dict:
    """Datos del canal en su vista web: título, suscriptores y descripción."""
    t = re.search(r'tgme_channel_info_header_title[^>]*>(?:<span[^>]*>)?(.*?)</', html, re.S)
    d = re.search(r'tgme_channel_info_description[^>]*>(.*?)</div>', html, re.S)
    subs = 0
    for m in re.finditer(r'<span class="counter_value">([^<]*)</span>\s*<span class="counter_type">([^<]*)</span>', html):
        if any(w in m.group(2).lower() for w in _TG_SUBS + _TG_MEMB):
            subs = _tg_views(m.group(1))
    return {"kind": "canal", "title": _strip_html(t.group(1))[:120] if t else "", "n": subs, "desc": _strip_html(d.group(1))[:300] if d else "", "view": True}

def _tg_note_info(ch: str, html: str) -> None:
    st = _TG_STATE.setdefault(ch, {})
    if (st.get("info") or {}).get("t", 0) > time.time() - 6 * 3600:
        return
    info = _tg_chaninfo(html)
    info["t"] = time.time()
    st["info"] = info

def _tgp_init(conn) -> None:
    conn.execute("CREATE TABLE IF NOT EXISTS tg_posts (chan TEXT NOT NULL, mid INTEGER NOT NULL, ts TEXT, text TEXT, views INTEGER DEFAULT 0, media TEXT, "
                 "fwd TEXT, lp TEXT, reply INTEGER DEFAULT 0, seen_at TEXT, PRIMARY KEY (chan, mid))")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_tgp_ts ON tg_posts(ts)")

def tg_posts_flush() -> int:
    """Guarda en la base de datos lo leído (solo lo nuevo o lo que cambió de vistas) y poda lo antiguo. Se ejecuta en un hilo, nunca en el bucle de lectura."""
    with _TGP_STATE["lock"]:
        buf = list(_TG_POSTBUF)
        del _TG_POSTBUF[:len(buf)]
        _TGP_STATE["timer"] = None
        now_iso = datetime.now(timezone.utc).isoformat()
        rows = []
        for p in buf:
            key, sig = (p["chan"], p["id"]), (p["views"], len(p["text"]))
            if _TGP_DONE.get(key) == sig:
                continue
            _TGP_DONE[key] = sig
            rows.append((p["chan"], p["id"], p["ts"] or now_iso, p["text"], p["views"], p["media"], p["fwd"], p["lp"], p["reply"], now_iso))
        if len(_TGP_DONE) > 30000:
            _TGP_DONE.clear()
        purge = time.time() - _TGP_STATE["purge"] > 3600
        if not rows and not purge:
            return 0
        try:
            conn = db_conn()
            try:
                _tgp_init(conn)
                if rows:
                    conn.executemany(
                        "INSERT INTO tg_posts (chan, mid, ts, text, views, media, fwd, lp, reply, seen_at) VALUES (?,?,?,?,?,?,?,?,?,?) "
                        "ON CONFLICT(chan, mid) DO UPDATE SET views=excluded.views, media=excluded.media, lp=excluded.lp, "
                        "text=CASE WHEN length(excluded.text) > length(tg_posts.text) THEN excluded.text ELSE tg_posts.text END", rows)
                if purge:
                    _TGP_STATE["purge"] = time.time()
                    conn.execute("DELETE FROM tg_posts WHERE ts < ?", ((datetime.now(timezone.utc) - timedelta(days=TG_KEEP_DAYS)).isoformat(),))
                conn.commit()
            finally:
                conn.close()
        except Exception as e:
            log.warning(f"[TG] no se guardaron las publicaciones: {type(e).__name__}: {e}")
            return 0
        return len(rows)

def _tgp_schedule() -> None:
    """Programa el guardado unos segundos después, en un hilo: lo leído no se pierde y la lectura no espera a la base de datos."""
    if _TG_POSTBUF and _TGP_STATE["timer"] is None:
        t = threading.Timer(5.0, tg_posts_flush)
        t.daemon = True
        _TGP_STATE["timer"] = t
        t.start()

def tg_posts_view(ch: str = "", q: str = "", hours: int = 72, det_only: bool = False, limit: int = 120) -> dict:
    """Lo que dicen los canales: publicaciones guardadas, con filtro por canal, texto y ventana; cada una con lo que el detector ve en ella."""
    since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()
    sql, args = "SELECT chan, mid, ts, text, views, media, fwd, lp, reply FROM tg_posts WHERE ts >= ?", [since]
    if ch:
        sql += " AND chan = ? COLLATE NOCASE"
        args.append(ch)
    if q:
        sql += " AND text LIKE ? ESCAPE '\\'"
        args.append(f"%{_like(q)}%")
    sql += " ORDER BY ts DESC LIMIT ?"
    args.append(int(limit) * (5 if det_only else 1))
    rows, chans = [], []
    conn = db_conn()
    try:
        _tgp_init(conn)
        rows = [dict(r) for r in conn.execute(sql, args).fetchall()]
        chans = [dict(r) for r in conn.execute("SELECT chan, COUNT(*) AS n, MAX(ts) AS last FROM tg_posts WHERE ts >= ? GROUP BY chan ORDER BY n DESC LIMIT 400", (since,)).fetchall()]
    finally:
        conn.close()
    posts = []
    for r in rows:
        try:
            sc = scan_text(r["text"] or "", r["chan"])
        except Exception:
            sc = None
        if det_only and not (sc and sc.get("groups")):
            continue
        try:
            lp = json.loads(r["lp"]) if r["lp"] else {}
        except ValueError:
            lp = {}
        txt = r["text"] or ""
        posts.append({"chan": r["chan"], "mid": r["mid"], "ts": _ts16(r["ts"]), "text": txt, "short": txt[:420], "more": len(txt) > 420, "views": r["views"] or 0,
                      "media": [m for m in (r["media"] or "").split(",") if m], "fwd": r["fwd"] or "", "lp": lp, "reply": bool(r["reply"]),
                      "url": f"https://t.me/{r['chan']}/{r['mid']}", "groups": [g for g, _ in (sc or {}).get("groups", [])][:3],
                      "atype": _str((sc or {}).get("atype")) if sc else "", "nips": len((sc or {}).get("ips", []) or []) if sc else 0, "report": bool(sc and sc.get("report"))})
        if len(posts) >= limit:
            break
    return {"posts": posts, "chans": chans, "ch": ch, "q": q, "h": hours, "det": det_only, "keep": TG_KEEP_DAYS, "total": len(posts), "channels": tg_channels_view()}

def tg_channels_view() -> list[dict]:
    """Todos los canales vigilados con su estado REAL (por qué se leen o no), tamaño y cuántas publicaciones hay guardadas."""
    _tg_boot()
    now = time.time()
    chans = list(dict.fromkeys(list(TG_CHANNELS) + list(WAR_TG_CHANNELS)))
    posts: dict = {}
    try:
        conn = db_conn()
        try:
            _tgp_init(conn)
            posts = {r[0].lower(): (r[1], r[2]) for r in conn.execute("SELECT chan, COUNT(*), MAX(ts) FROM tg_posts GROUP BY chan").fetchall()}
        finally:
            conn.close()
    except Exception:
        pass
    out = []
    for c in chans:
        st = _TG_STATE.get(c, {})
        info = st.get("info") or {}
        np_, last = posts.get(c.lower(), (0, ""))
        out.append({"ch": c, "reason": st.get("reason", ""), "why": TG_REASONS.get(st.get("reason", ""), st.get("reason", "")),
                    "ago": _ago(datetime.fromtimestamp(st["last"], timezone.utc).isoformat()) if st.get("last") else "—",
                    "retry": (f"en {int((st['dead_until'] - now) / 3600) + 1} h" if st.get("dead_until", 0) > now else "ya"),
                    "title": info.get("title", ""), "n": info.get("n", 0), "kind": info.get("kind", ""), "posts": np_, "last_post": _ts16(last), "war": c in WAR_TG_CHANNELS})
    order = {"ok": 0, "": 1, "vacio": 2, "limite": 3, "red": 4, "sin_vista": 5, "grupo": 6, "perfil": 7, "no_existe": 8, "restringido": 9}
    out.sort(key=lambda x: (order.get(x["reason"], 9), -x["posts"], x["ch"].lower()))
    return out

_TG_SUFFIX = ("", "_official", "official", "_channel", "channel", "_chat", "chat", "_news", "news", "_team", "team", "_en", "_eng", "_ru", "_es",
              "_reserve", "_backup", "_new", "tg", "_tg")

def tg_candidates(q: str, limit: int = 36) -> list[str]:
    """Variantes de usuario de Telegram a partir de un nombre libre («NoName057(16)» → noname05716, noname057_16, noname057_16_official…)."""
    import unicodedata
    s = unicodedata.normalize("NFKD", q or "").encode("ascii", "ignore").decode()
    toks = [t for t in re.split(r"[^A-Za-z0-9]+", s) if t]
    if not toks:
        return []
    bases = [b for b in dict.fromkeys(["".join(toks), "_".join(toks)]) if b]
    if len(toks) >= 2 and toks[-1].isdigit():
        bases.append("".join(toks[:-1]) + "_" + toks[-1])
    known = {c.lower() for c in list(TG_CHANNELS) + list(WAR_TG_CHANNELS)}
    seen: set = set()
    out: list[str] = []
    for suf in _TG_SUFFIX:
        for b in bases:
            c = b + suf
            lc = c.lower()
            if re.fullmatch(r"[A-Za-z][A-Za-z0-9_]{4,31}", c) and lc not in known and lc not in seen:
                seen.add(lc)
                out.append(c)
                if len(out) >= limit:
                    return out
    return out

async def tg_probe(cands: list[str], budget: float = 40.0) -> list[dict]:
    """Comprueba en vivo qué candidatos existen (una petición a t.me/s cada uno: da perfil y vista a la vez). Pasivo: sin cuenta ni sesión.
    Devuelve lo que haya encontrado aunque se agote el tiempo."""
    found: list[dict] = []
    sem = asyncio.Semaphore(4)

    async def one(c: str) -> None:
        async with sem:
            try:
                r = await _tg_http(f"https://t.me/s/{quote(c, safe='_-.')}")
            except Exception:
                return
            if r.status_code >= 400:
                return
            if "/s/" not in str(r.url.path):
                p = _tg_profile(r.text)
                if p["kind"] != "nada":
                    found.append({"ch": c, "view": False, "posts": 0, "last": [], **p})
                return
            info = _tg_chaninfo(r.text)
            msgs, total = _tg_parse_html(r.text, c, rich=False)
            found.append({"ch": c, "view": True, "posts": total, **info, "last": [{"ts": _ts16(m.get("ts")), "text": m["text"][:200]} for m in msgs[:3]]})

    try:
        await asyncio.wait_for(asyncio.gather(*[one(c) for c in cands], return_exceptions=True), timeout=budget)
    except (asyncio.TimeoutError, TimeoutError):
        pass
    found.sort(key=lambda x: (not x["view"], -(x.get("n") or 0)))
    return found

