def tg_report() -> dict:
    """Estado de los canales de Telegram para la pestaña 🩺 Fuentes: cuántos se leen y por qué los demás no."""
    _tg_boot()
    now = time.time()
    chans = list(dict.fromkeys(list(TG_CHANNELS) + list(WAR_TG_CHANNELS)))
    cnt: Counter = Counter()
    bad = []
    for c in chans:
        st = _TG_STATE.get(c, {})
        r = st.get("reason", "")
        cnt[r] += 1
        if r not in ("ok", ""):
            bad.append({"ch": c, "why": TG_REASONS.get(r, r), "ago": _ago(datetime.fromtimestamp(st["last"], timezone.utc).isoformat()) if st.get("last") else "—",
                        "retry": (f"en {int((st['dead_until'] - now) / 3600) + 1} h" if st.get("dead_until", 0) > now else "ya")})
    order = {"limite": 0, "red": 1, "vacio": 2, "restringido": 3, "sin_vista": 4}
    bad.sort(key=lambda b: (order.get(next((k for k, v in TG_REASONS.items() if v == b["why"]), ""), 9), b["ch"]))
    return {"total": len(chans), "ok": cnt["ok"], "pending": cnt[""], "bad": bad[:80], "nbad": len(bad), "disc": len(_TG_DISC["added"]),
            "blocked": max(0, int(_TG_BLOCK_UNTIL - now))}

class _TGNoView(RuntimeError):
    pass

_TG_BRIDGE_OFF: dict = {}          # puente RSS -> hasta cuándo no se consulta (429/403/caído)

async def _tg_channel(ch: str) -> tuple[list[dict], int]:
    """(mensajes nuevos, nº total de mensajes en la página). El total distingue «canal sin mensajes» de «nada nuevo»."""
    # Cadena de Andrómeda: 1) vista directa t.me/s  2) versión embed (+JSON embebido)  3) puentes RSS (tg.i-c-a.su, rsshub, rss-bridge)
    direct_err: Optional[Exception] = None
    try:
        r = await _tg_http(f"https://t.me/s/{quote(ch, safe='_-.')}")
        if r.status_code >= 400:
            raise RuntimeError(f"HTTP {r.status_code}")
        if r.status_code < 400 and "/s/" not in str(r.url.path):
            # t.me/s/<canal> redirige al perfil: el canal NO ofrece vista web pública. Ni el embed ni los puentes lo arreglan: no se insiste.
            prof = _tg_profile(r.text)                 # ese perfil ya estaba descargado: dice si es canal, grupo, perfil/bot o no existe
            e_ = _TGNoView(f"sin vista pública [{prof['kind']}]: t.me/s redirige al perfil ({prof.get('title') or 'sin título'})")
            e_.info = {**prof, "view": False}
            raise e_
        html = r.text
        try:
            _tg_note_info(ch, html)
        except Exception:
            pass
        out, total = _tg_parse_html(html, ch)
        if total:
            return out, total
        if "tgme_channel_info" in html or "tgme_channel_history" in html:
            return [], 0                                       # canal con vista pública pero sin mensajes
        direct_err = RuntimeError("HTTP 404 sin vista pública (canal restringido, borrado o sin preview)")
    except _TGNoView:
        raise
    except Exception as e:
        direct_err = e
    return await _tg_fallbacks(ch, direct_err)

async def _tg_fallbacks(ch: str, direct_err: Exception) -> tuple[list[dict], int]:
    """Solo si la vista directa FALLÓ por red/tiempo (no si el canal está vacío o restringido): embed y puentes RSS, con tope de tiempo."""
    try:
        return await asyncio.wait_for(_tg_fallbacks_inner(ch, direct_err), 25)
    except asyncio.TimeoutError:
        raise direct_err

async def _tg_fallbacks_inner(ch: str, direct_err: Exception) -> tuple[list[dict], int]:
    out, total = [], 0
    try:
        emb = (await _tg_http(f"https://t.me/s/{quote(ch, safe='_-.')}?embed=1&mode=tme")).text
        out, total = _tg_parse_html(emb, ch)
        if not total:
            for body in re.findall(r'<script[^>]*type=["\']application/json["\'][^>]*>(.*?)</script>', emb, re.S | re.I):
                try:
                    data = json.loads(body)
                except Exception:
                    continue
                for m in (data.get("messages") or []) if isinstance(data, dict) else []:
                    if not (m.get("message") and m.get("id")) or (ch, int(m["id"])) in _TG_SEEN:
                        total += 1 if m.get("id") else 0
                        continue
                    total += 1
                    age = (time.time() - float(m["date"])) / 3600 if m.get("date") else 0.0
                    if age <= TG_MAX_AGE_H:
                        out.append({"chan": ch, "id": int(m["id"]), "text": _strip_html(str(m["message"])), "age": age,
                                    "ts": (datetime.now(timezone.utc) - timedelta(hours=age)).isoformat()})
        if total:
            return out, total
    except Exception:
        pass
    for tpl in ("https://tg.i-c-a.su/rss/{}?limit=100", "https://rsshub.app/telegram/channel/{}", "https://rss-bridge.su/telegram/channel/{}"):
        host = tpl.split("/")[2]
        if _TG_BRIDGE_OFF.get(host, 0) > time.time():
            continue                                           # este puente dio 429/403 hace poco: no se le insiste (el log mostraba decenas de 429 seguidos)
        try:
            ents = await _fetch_rss(tpl.format(ch))
        except Exception:
            _TG_BRIDGE_OFF[host] = time.time() + 1500
            continue
        for e in ents:
            mm = re.search(r"/(\d+)/?(?:\?.*)?$", e.get("link") or "")
            txt = _strip_html(e.get("summary", "") or e.get("title", ""))
            if not (mm and txt):
                continue
            total += 1
            mid = int(mm.group(1))
            age = _entry_age_hours(e)
            if (ch, mid) in _TG_SEEN or age > TG_MAX_AGE_H:
                continue
            out.append({"chan": ch, "id": mid, "text": txt[:4000], "age": age, "ts": (datetime.now(timezone.utc) - timedelta(hours=age)).isoformat()})
        if total:
            return out, total
    if direct_err is not None:
        raise direct_err                                       # ninguna vía funcionó: el error real de red
    return [], 0

def _tg_parse_html(html: str, ch: str, rich: bool = True) -> tuple[list[dict], int]:
    """Parseo de la vista pública t.me/s (también sirve para la variante embed). Mismo corte por bloques que tg_parse de Andrómeda."""
    out, total = [], 0
    for blk in html.split('<div class="tgme_widget_message_wrap')[1:]:
        dp = re.search(r'data-post="([^"/]+)/(\d+)"', blk)
        if not dp:
            continue
        chan, mid = dp.group(1), int(dp.group(2))
        total += 1
        if rich and len(_TG_POSTBUF) < 20000:            # se guarda TODA publicación vista (también las de solo foto/vídeo y las antiguas), para la pestaña 📡 Telegram
            try:
                _TG_POSTBUF.append(_tg_rich(blk, chan, mid))
            except Exception:
                pass
        if (chan, mid) in _TG_SEEN:
            continue
        txt = re.search(r'tgme_widget_message_text[^"]*"[^>]*>(.*?)</div>', blk, re.S)
        if not txt:
            continue
        raw = txt.group(1)
        links = [h for h in re.findall(r'href="([^"]+)"', raw) if h.startswith("http") and "t.me/" not in h]
        body = _strip_html(re.sub(r"<br\s*/?>", "\n", raw))
        if links:
            body = (body + "\n" + " ".join(htmllib.unescape(l) for l in links)).strip()
        age = 0.0
        tm = _TG_TIME.search(blk)
        if tm:
            try:
                age = (datetime.now(timezone.utc) - datetime.fromisoformat(tm.group(1))).total_seconds() / 3600
            except ValueError:
                pass
        if age > TG_MAX_AGE_H:
            continue
        out.append({"chan": chan, "id": mid, "text": body[:4000], "age": age,
                    "ts": (datetime.now(timezone.utc) - timedelta(hours=age)).isoformat()})
    return out, total

def _tg_due(ch: str, now: float) -> bool:
    s = _TG_STATE.get(ch, {})
    return s.get("dead_until", 0) <= now and now - s.get("last", 0) >= TG_MIN_MINUTES * 60

def _event_from_claim(group: str, kind: str, atype: str, text: str, src_label: str, url: str, key: str, health: bool, energy: bool) -> list[dict]:
    """Eventos de mapa (uno por país víctima) si el texto reivindica un ataque/intrusión y nombra víctimas."""
    if _is_report(text, src_label.endswith("Prensa")):         # noticia/atribución SOBRE el grupo, no reivindicación suya: se guarda como detección pero no pinta mapa ni arcos
        return [], []
    is_ddos = atype == "ddos" or bool(_CLAIM_DDOS.search(text))
    if not is_ddos and not _CLAIM_HACK.search(text) and atype in ("ataque", "escaneo"):
        return [], []
    home = GROUP_HOME.get(group)
    vics = _claim_victims(text, home)
    out = []
    dom = "ddos" if is_ddos else _ATYPE_DOMAIN.get(atype, "ciberataque")
    for v in vics:
        c = country_coords(v)
        if not c:
            continue
        la, lo = jitter_coords(c[0], c[1], f"{key}{v}", deg=1.6)
        tags = [dom, f"grupo:{group}", "reivindicado"] + (["salud"] if health else []) + (["energia"] if energy else []) + ([flow_tag(home, v)] if home else [])
        out.append(_mk(dom, src_label, la, lo, "ALTA" if (health or energy) else "MEDIA",
                       f"{group} reivindica {'DDoS' if is_ddos else atype} contra {COUNTRY_DB[v][0]} · {key}",
                       text[:300], url, [group, COUNTRY_DB[v][0]], tags))
    return out, vics

async def _tg_process(batches: list) -> list[dict]:
    """Procesa y GUARDA lo leído de una tanda de canales (detecciones, IPs, eventos de mapa). Se llama por tandas pequeñas: si el tiempo se acaba, lo ya procesado no se pierde."""
    out: list[dict] = []
    det: list[dict] = []
    reported: list[tuple[str, str, list[str], str]] = []
    cands: Counter = Counter()
    if len(_TG_SEEN) > 60000:
        _TG_SEEN.clear()
    try:
        _tg_discover([mm["text"] for msgs in batches for mm in msgs])
    except Exception as e:
        log.debug(f"[TG] descubrimiento: {e}")
    for msgs in batches:
        for mm in msgs:
            _TG_SEEN.add((mm["chan"], mm["id"]))
            text = mm["text"]
            sc = scan_text(text, mm["chan"])
            if not sc:
                continue
            url = f"https://t.me/{mm['chan']}/{mm['id']}"
            if not sc["groups"]:
                cands.update(_cand_words(text))
                continue
            group, kind = sc["groups"][0]
            evs, vics = _event_from_claim(group, kind, sc["atype"], text, "Grupos · Telegram", url, f"{mm['chan']}/{mm['id']}", sc["health"], sc["energy"])
            out.extend(evs)
            for g, k in sc["groups"]:
                det.append({"ts": mm["ts"], "grp": g, "kind": k, "atype": sc["atype"], "src_kind": "telegram", "source": "@" + mm["chan"],
                            "title": ("ℹ Informe/atribución (no es reivindicación): " if sc.get("report") else "") + text, "url": url, "victims": vics,
                            "nips": len(sc["ips"]), "health": sc["health"], "energy": sc["energy"]})
                if sc["ips"] and not sc.get("report"):
                    reported.append((g, k, sc["ips"], url))
    try:
        await asyncio.to_thread(db_save_detections, det)
        await asyncio.to_thread(db_bump_candidates, cands)
    except sqlite3.Error as e:
        log.warning(f"[DETECTOR] no se guardaron las detecciones: {e}")
    if reported:
        try:
            await geo_batch([ip for _, _, ips, _ in reported for ip in ips])
            reg = [{"ip": ip, "grp": g, "kind": k or GROUP_KIND.get(g, ""), "role": "IP citada en canal público (no verificada: puede ser víctima)",
                    "cc": _GEO_CC.get(ip, ""), "lat": _GEO_CACHE[ip][0], "lon": _GEO_CACHE[ip][1], "source": "Telegram (t.me/s)", "url": u, "conf": "reportada", "live": True}
                   for g, k, ips, u in reported for ip in ips if ip in _GEO_CACHE]
            await asyncio.to_thread(db_upsert_group_ips, reg)
        except Exception as e:
            log.warning(f"[GRUPOS] IPs de Telegram no registradas: {type(e).__name__}: {e}")
    return out

# ─── ★ NUEVO · buscador de canales de Telegram (comprobar en vivo uno que NO está registrado y añadirlo a la vigilancia) ───
_TG_NAME_RX = re.compile(r"[A-Za-z][A-Za-z0-9_]{4,31}")

def tg_parse_query(q: str) -> Optional[str]:
    q = (q or "").strip()
    m = re.search(r"(?:t\.me|telegram\.me)/(?:s/)?([A-Za-z][A-Za-z0-9_]{4,31})(?![A-Za-z0-9_])", q)
    if m:
        return m.group(1)
    q = q.lstrip("@")
    return q if _TG_NAME_RX.fullmatch(q) else None

def _tg_preview(html: str) -> dict:
    """Resumen de la vista pública t.me/s/<canal> SIN tocar el filtro de «ya vistos»: título, nº de mensajes visibles y los 3 últimos."""
    tt = re.search(r'tgme_channel_info_header_title[^>]*>(.*?)</div>', html, re.S) or re.search(r'<meta property="og:title" content="([^"]*)"', html)
    last, total = [], 0
    for blk in html.split('<div class="tgme_widget_message_wrap')[1:]:
        if not re.search(r'data-post="[^"/]+/\d+"', blk):
            continue
        total += 1
        tx = re.search(r'tgme_widget_message_text[^"]*"[^>]*>(.*?)</div>', blk, re.S)
        tm = _TG_TIME.search(blk)
        last.append({"ts": (tm.group(1)[:16].replace("T", " ") if tm else ""), "text": _strip_html(re.sub(r"<br\s*/?>", " ", tx.group(1)))[:300] if tx else "(sin texto: foto, vídeo o archivo)"})
    return {"title": _strip_html(tt.group(1))[:80] if tt else "", "n": total, "last": last[-12:][::-1],
            "has_view": ("tgme_channel_history" in html or "tgme_channel_info" in html or total > 0)}

async def tg_lookup(q: str) -> dict:
    _tg_boot()
    q = (q or "").strip()[:120]
    low = q.lstrip("@").lower()
    name = tg_parse_query(q)
    allc = list(dict.fromkeys(list(TG_CHANNELS) + list(WAR_TG_CHANNELS)))
    low_set = {c.lower() for c in allc}
    reg = [{"ch": c, "why": TG_REASONS.get(_TG_STATE.get(c, {}).get("reason", ""), "pendiente de leer"), "war": c in WAR_TG_CHANNELS} for c in allc if low and low in c.lower()][:20]
    res = {"q": q, "name": name, "known": bool(name and name.lower() in low_set), "registered": reg,
           "mentions": [{"ch": c, "n": n} for c, n in sorted(_TG_DISC["n"].items(), key=lambda kv: -kv[1]) if low and low in c.lower() and c.lower() not in low_set][:10], "live": None}
    if name:
        try:
            r = await asyncio.wait_for(_tg_http(f"https://t.me/s/{quote(name, safe='_-.')}"), 30)
            if r.status_code >= 400:
                res["live"] = {"ok": False, "why": f"HTTP {r.status_code}: el canal no existe, es privado o no tiene vista pública"}
            elif "/s/" not in str(r.url.path):
                res["live"] = {"ok": False, "why": "el canal existe pero NO ofrece vista web pública (t.me/s redirige al perfil): sin cuenta de Telegram no se puede leer su contenido"}
            else:
                pv = _tg_preview(r.text)
                if pv["has_view"]:
                    res["live"] = {"ok": True, **pv}
                else:
                    res["live"] = {"ok": False, "why": "t.me respondió pero sin vista pública (canal restringido, borrado o sin preview web)"}
        except Exception as e:
            res["live"] = {"ok": False, "why": f"{type(e).__name__}: {str(e) or 'sin respuesta de t.me en 30 s (¿red bloqueada?)'}"}
    return res

def tg_add_channel(name: str, war: bool = False) -> dict:
    _tg_boot()
    name = tg_parse_query(name) or ""
    if not name:
        raise ValueError("nombre de canal no válido (5-32 caracteres, letras, números y _)")
    added = False
    if name.lower() not in {c.lower() for c in TG_CHANNELS}:
        TG_CHANNELS.append(name)
        added = True
    user = json.loads(kv_get("tg_user", "[]") or "[]")
    if name not in user:
        user.append(name)
        kv_set("tg_user", json.dumps(user[-300:]))
    if war and name not in WAR_TG_CHANNELS:
        WAR_TG_CHANNELS.append(name)
        uw = json.loads(kv_get("tg_user_war", "[]") or "[]")
        if name not in uw:
            uw.append(name)
            kv_set("tg_user_war", json.dumps(uw[-100:]))
    _TG_STATE.pop(name, None)                  # se lee en la próxima pasada
    return {"ok": True, "name": name, "added": added, "war": bool(war)}

async def tg_scan_now(name: str) -> dict:
    """Escanea YA un canal (registrado o no) con el mismo motor pasivo del detector: reivindicaciones, grupos, IPs y eventos de mapa. No necesita cuenta de Telegram."""
    name = tg_parse_query(name) or ""
    if not name:
        raise ValueError("nombre de canal no válido")
    for k in [k for k in _TG_SEEN if k[0] == name][:5000]:
        _TG_SEEN.discard(k)                       # se relee entero aunque ya se hubiera visto algo
    msgs, total = await asyncio.wait_for(_tg_channel(name), 60)
    evs = await _tg_process([msgs]) if msgs else []
    saved = 0
    if evs:
        now = datetime.now(timezone.utc).isoformat()
        for ev in evs:
            ev.setdefault("timestamp", now); ev.setdefault("sentiment", 0.0); ev.setdefault("entities", ""); ev.setdefault("tags", "")
        evs = dedupe_events(enrich_events(sanitize_events(evs)))
        saved = await asyncio.to_thread(db_save_events, "TGSCAN" + datetime.now(timezone.utc).strftime("%H%M%S"), evs)
    return {"ok": True, "name": name, "messages": len(msgs), "page_total": total, "events": len(evs), "saved": saved,
            "sample": [{"ts": m.get("ts", ""), "text": (m.get("text") or "")[:240], "url": f"https://t.me/{name}/{m.get('id')}"} for m in msgs[:12]]}

def tg_remove_channel(name: str) -> bool:
    name = tg_parse_query(name) or ""
    user = json.loads(kv_get("tg_user", "[]") or "[]")
    if name not in user:
        return False                           # solo se quitan los que añadió el usuario (los de serie no)
    kv_set("tg_user", json.dumps([c for c in user if c != name]))
    uw = json.loads(kv_get("tg_user_war", "[]") or "[]")
    kv_set("tg_user_war", json.dumps([c for c in uw if c != name]))
    for lst in (TG_CHANNELS, WAR_TG_CHANNELS):
        while name in lst:
            lst.remove(name)
    _TG_STATE.pop(name, None)
    return True

async def fetch_group_claims() -> list[dict]:
    """Escanea una tanda de canales públicos de Telegram: detecciones (todas) + eventos de mapa (las que nombran víctimas)."""
    global _TG_BLOCK_UNTIL
    if os.getenv("NEXUS_TG_OFF"):
        return []
    _tg_boot()
    now = time.time()
    if now < _TG_BLOCK_UNTIL:
        raise RuntimeError(f"Telegram limitó las peticiones (429): reintento en {int(_TG_BLOCK_UNTIL - now)} s")
    per_run = max(TG_PER_RUN, _RUN_BOOST["n"])
    batch = sorted((c for c in TG_CHANNELS if _tg_due(c, now)), key=lambda c: _TG_STATE.get(c, {}).get("last", 0))[:per_run]
    sem = asyncio.Semaphore(3)
    errors: list[str] = []
    ok = 0

    async def one(ch):
        nonlocal ok
        if time.time() < _TG_BLOCK_UNTIL:
            return []
        async with sem:
            try:
                msgs, total = await asyncio.wait_for(_tg_channel(ch), TG_CH_TIMEOUT)     # un canal colgado no puede bloquear a los demás
                _tg_record(ch, total=total)
                ok += 1
                return msgs
            except Exception as e:
                _tg_record(ch, exc=e)
                errors.append(f"{ch}: {type(e).__name__}")
                log.debug(f"[TG] {ch}: {e}")
                return []
    t_start = time.monotonic()
    out: list[dict] = []
    for k in range(0, len(batch), TG_CHUNK):
        if k and time.monotonic() - t_start > TG_BUDGET_S:
            log.info(f"[TG] presupuesto de {TG_BUDGET_S} s agotado: {k}/{len(batch)} canales leídos y guardados; el resto va en la siguiente pasada")
            break
        part = await asyncio.gather(*(one(c) for c in batch[k:k + TG_CHUNK]))
        try:
            out.extend(await _tg_process(list(part)))
        except Exception as e:
            log.warning(f"[TG] procesado de tanda: {type(e).__name__}: {e}")
    _tg_state_save()
    if batch and ok == 0 and errors and not out and not all(x.endswith("_TGNoView") for x in errors):     # «sin vista pública» es del canal, no de tu red: no es un fallo de la fuente
        raise RuntimeError(f"ningún canal de Telegram respondió ({len(errors)} fallos, p. ej. {', '.join(errors[:3])}): ¿sin conexión o t.me bloqueado en tu red?")
    return out[:200]

# ── Feeds de seguridad (RSS) ──
async def fetch_group_rss() -> list[dict]:
    """Busca menciones de grupos/amenazas en los feeds de seguridad de Andrómeda (detecciones + eventos si nombran víctimas)."""
    now = time.time()
    due = [u for u in GROUP_RSS_FEEDS if now - _RSS_STATE.get(u, 0) >= RSS_MIN_MINUTES * 60]
    sem = asyncio.Semaphore(6)
    errors: list[str] = []
    ok = 0

    async def one(u):
        nonlocal ok
        async with sem:
            try:
                ents = await _fetch_rss(u)
                _RSS_STATE[u] = time.time()
                ok += 1
                return u, ents
            except Exception as e:
                _RSS_STATE[u] = time.time()
                errors.append(f"{u.split('/')[2]}: {type(e).__name__}")
                return u, []
    out, det = [], []
    reported: list[tuple[str, str, list[str], str]] = []
    cands: Counter = Counter()
    for u, ents in await asyncio.gather(*(one(u) for u in due)):
        host = u.split("/")[2].replace("www.", "")
        for e in ents[:40]:
            if _entry_age_hours(e) > 96:
                continue
            title = _strip_html(e.get("title", ""))
            text = f"{title}. {_strip_html(e.get('summary', ''))[:500]}"
            sc = scan_text(text)
            link = e.get("link") or ""
            if not sc or not link:
                continue
            if not sc["groups"]:
                cands.update(_cand_words(text))
                continue
            t = e.get("published_parsed")
            ts = datetime.fromtimestamp(calendar.timegm(t), timezone.utc).isoformat() if t else datetime.now(timezone.utc).isoformat()
            group, kind = sc["groups"][0]
            evs, vics = _event_from_claim(group, kind, sc["atype"], text, "Grupos · Prensa", link, host, sc["health"], sc["energy"])
            for ev in evs:
                ev["title"] = f"{group}: {title}"[:200]
            out.extend(evs)
            for g, k in sc["groups"]:
                det.append({"ts": ts, "grp": g, "kind": k, "atype": sc["atype"], "src_kind": "rss", "source": host, "title": title, "url": link,
                            "victims": vics, "nips": len(sc["ips"]), "health": sc["health"], "energy": sc["energy"]})
                if sc["ips"]:
                    reported.append((g, k, sc["ips"], link))
    try:
        await asyncio.to_thread(db_save_detections, det)
        await asyncio.to_thread(db_bump_candidates, cands)
    except sqlite3.Error as e:
        log.warning(f"[DETECTOR] no se guardaron las detecciones RSS: {e}")
    if reported:
        try:
            await geo_batch([ip for _, _, ips, _ in reported for ip in ips])
            db_upsert_group_ips([{"ip": ip, "grp": g, "kind": k or GROUP_KIND.get(g, ""), "role": "IP citada en una noticia (no verificada: puede ser víctima)",
                                  "cc": _GEO_CC.get(ip, ""), "lat": _GEO_CACHE[ip][0], "lon": _GEO_CACHE[ip][1], "source": "Prensa/RSS", "url": u, "conf": "reportada", "live": True}
                                 for g, k, ips, u in reported for ip in ips if ip in _GEO_CACHE])
        except Exception as e:
            log.warning(f"[GRUPOS] IPs de RSS no registradas: {type(e).__name__}: {e}")
    if due and ok == 0 and errors:
        raise RuntimeError(f"ningún feed respondió ({len(errors)} fallos): {', '.join(errors[:4])}")
    return out[:150]


# ══════════════════════════════════════════════════════════════════════════════
# MONITOR DDoS (lo que hace Andrómeda al arrancar): trae IPs FRESCAS de listas vivas de atacantes y las ATRIBUYE a grupos
#   · por IP exacta (listas de grupos: CERT suizo/NoName, Killnet, lo captado en Telegram/prensa) o por RANGO (CIDR de NoName)
#   · ThreatFox reciente: IPs de botnets/familias conocidas (Mirai, etc.) por su nombre
#   Solo se guarda lo que coincide con un grupo (no las ~100.000 IPs de las listas): ligero. Las IPs son TEMPORALES (NEXUS_GROUP_IP_KEEP_DAYS).
# ══════════════════════════════════════════════════════════════════════════════
LIVE_IP_FEEDS = [
    ("Blocklist.de · bots", "https://lists.blocklist.de/lists/bots.txt"),
    ("Blocklist.de · ssh", "https://lists.blocklist.de/lists/ssh.txt"),
    ("Blocklist.de · apache", "https://lists.blocklist.de/lists/apache.txt"),
    ("Blocklist.de · mail", "https://lists.blocklist.de/lists/mail.txt"),
    ("Blocklist.de · ftp", "https://lists.blocklist.de/lists/ftp.txt"),
    ("CI Army", "http://cinsscore.com/list/ci-badguys.txt"),
    ("GreenSnow", "http://blocklist.greensnow.co/greensnow.txt"),
    ("ET compromised", "https://rules.emergingthreats.net/blockrules/compromised-ips.txt"),
    ("BruteforceBlocker", "https://danger.rulez.sk/projects/bruteforceblocker/blist.php"),
    ("Binary Defense", "https://www.binarydefense.com/banlist.txt"),
    ("Feodo", "https://feodotracker.abuse.ch/downloads/ipblocklist.csv"),
]
THREATFOX_RECENT = "https://threatfox.abuse.ch/export/csv/recent/"
GROUP_CIDR_FEEDS = [
    ("https://raw.githubusercontent.com/govcert-ch/CTI/main/NoName057-DDoS-CH-CIDRs-only-merged.txt", "NoName057(16)"),
    ("https://raw.githubusercontent.com/govcert-ch/CTI/main/20250120_NoName057-DDoS-CH_CIDR-only.csv", "NoName057(16)"),
]
DDOS_MON_MINUTES = float(os.getenv("NEXUS_DDOS_MON_MINUTES", "15"))
DDOS_MON_MAX_NEW_GEO = int(os.getenv("NEXUS_DDOS_MON_GEO", "600"))     # máx. IPs coincidentes que se geolocalizan por pasada
DDOS_MON: dict = {"last": None, "scanned": 0, "matched": 0, "new": 0, "feeds": {}, "ips_known": 0, "cidrs": 0, "running": False}
_DDOS_MON_LAST = [0.0]
_CIDR_CACHE: dict = {"t": 0.0, "iv": []}

def _ip_int(ip: str) -> int:
    a, b, c, d = (int(x) for x in ip.split("."))
    return (a << 24) | (b << 16) | (c << 8) | d

async def _group_cidrs() -> list[tuple[int, int, str]]:
    """Rangos (inicio, fin, grupo) ordenados; se refrescan cada 12 h."""
    if _CIDR_CACHE["iv"] and time.time() - _CIDR_CACHE["t"] < 12 * 3600:
        return _CIDR_CACHE["iv"]
    iv = []
    for url, group in GROUP_CIDR_FEEDS:
        try:
            r = await _get(url, timeout=30, follow_redirects=True)
        except Exception as e:
            log.warning(f"[MONITOR] CIDR {group}: {type(e).__name__}: {e}")
            continue
        for m in re.finditer(r"\b(\d{1,3}(?:\.\d{1,3}){3})/(\d{1,2})\b", r.text):
            try:
                net = ipaddress.ip_network(f"{m.group(1)}/{m.group(2)}", strict=False)
                if net.version == 4 and net.prefixlen >= 16:            # nunca rangos enormes
                    iv.append((int(net.network_address), int(net.broadcast_address), group))
            except ValueError:
                pass
    iv.sort()
    if iv:
        _CIDR_CACHE.update(t=time.time(), iv=iv)
    return iv

def _cidr_group(iv: list, starts: list, ipn: int) -> Optional[str]:
    i = bisect.bisect_right(starts, ipn) - 1
    for k in range(i, max(-1, i - 4), -1):        # rangos solapados: se miran unos pocos anteriores
        if iv[k][0] <= ipn <= iv[k][1]:
            return iv[k][2]
    return None

async def fetch_ddos_monitor() -> list[dict]:
    """Una pasada del monitor: IPs frescas de listas vivas que coinciden con un grupo -> registro temporal + eventos por grupo y país."""
    if time.time() - _DDOS_MON_LAST[0] < DDOS_MON_MINUTES * 60:
        return []
    _DDOS_MON_LAST[0] = time.time()
    DDOS_MON["running"] = True
    try:
        conn = db_conn()
        known = {r[0]: (r[1], r[2]) for r in conn.execute("SELECT ip, grp, kind FROM group_ips").fetchall()}
        conn.close()
        iv = await _group_cidrs()
        starts = [x[0] for x in iv]
        DDOS_MON.update(ips_known=len(known), cidrs=len(iv))
        hits: dict[str, tuple[str, str, str, str]] = {}      # ip -> (grupo, tipo, lista, cómo)
        feeds: dict = {}
        scanned = 0
        errors = []
        for name, url in LIVE_IP_FEEDS:
            try:
                r = await _get(url, timeout=40, follow_redirects=True)
                txt = r.text[:8_000_000]
            except Exception as e:
                feeds[name] = {"n": 0, "hit": 0, "err": f"{type(e).__name__}"}
                errors.append(name)
                continue
            n = h = 0
            for m in _IPV4.finditer(txt):
                ip = m.group(0)
                n += 1
                g = known.get(ip)
                how = "IP de la lista del grupo"
                if g is None and starts:
                    gname = _cidr_group(iv, starts, _ip_int(ip))
                    if gname:
                        g, how = (gname, GROUP_KIND.get(gname, "hacktivista")), "rango (CIDR) del grupo"
                if g and ip not in hits and _valid_public_ip(ip):
                    hits[ip] = (g[0], g[1] or GROUP_KIND.get(g[0], ""), name, how)
                    h += 1
            scanned += n
            feeds[name] = {"n": n, "hit": h, "err": ""}
        try:                                                  # ThreatFox: IPs de botnets/familias por nombre
            r = await _get(THREATFOX_RECENT, timeout=40, follow_redirects=True)
            n = h = 0
            for row in csvlib.reader(l for l in r.text.splitlines() if l and not l.startswith("#")):
                if len(row) < 8 or "ip" not in row[3].lower():
                    continue
                ip = row[2].strip().strip('"').split(":")[0]
                if not _IPV4.fullmatch(ip):
                    continue
                n += 1
                blob = " ".join(row[4:12] + row[-4:])
                gname = identify_group(blob)
                kind = GROUP_KIND.get(gname, "") if gname else ""
                if not gname:
                    for nm, kd, rx in _THREAT_RX:
                        if rx.search(blob):
                            gname, kind = nm, kd
                            break
                if gname and ip not in hits and _valid_public_ip(ip):
                    gname = ("Botnet " + gname) if kind == "botnet" and not gname.lower().startswith("botnet") else gname
                    GROUP_KIND.setdefault(gname, kind)
                    hits[ip] = (gname, kind, "ThreatFox (reciente)", "familia/etiqueta en ThreatFox")
                    h += 1
            scanned += n
            feeds["ThreatFox"] = {"n": n, "hit": h, "err": ""}
        except Exception as e:
            feeds["ThreatFox"] = {"n": 0, "hit": 0, "err": f"{type(e).__name__}"}
            errors.append("ThreatFox")
        DDOS_MON.update(last=datetime.now(timezone.utc).isoformat(), scanned=scanned, matched=len(hits), feeds=feeds,
                        new=sum(1 for ip in hits if ip not in known))
        if errors and len(errors) >= len(LIVE_IP_FEEDS) + 1:
            raise RuntimeError("ninguna lista viva respondió: " + ", ".join(errors[:4]))
        if not hits:
            return []
        sel = list(hits)[:DDOS_MON_MAX_NEW_GEO] if len(hits) > DDOS_MON_MAX_NEW_GEO else list(hits)
        await geo_batch(sel)
        rows, cl = [], {}
        for ip in sel:
            c = _GEO_CACHE.get(ip)
            if not c:
                continue
            g, kind, feed, how = hits[ip]
            url = next((u for n_, u in LIVE_IP_FEEDS if n_ == feed), THREATFOX_RECENT)
            rows.append({"ip": ip, "grp": g, "kind": kind, "role": f"IP activa en «{feed}» · {how}", "cc": _GEO_CC.get(ip, ""),
                         "lat": c[0], "lon": c[1], "source": feed, "url": url, "conf": "feed", "live": True})
            cl.setdefault((g, kind, _GEO_CC.get(ip, ""), round(c[0] / 4), round(c[1] / 4)), []).append((ip, c))
        await asyncio.to_thread(db_upsert_group_ips, rows)
        out = []
        today = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M")
        for (g, kind, cc, _, _), items in sorted(cl.items(), key=lambda kv: -len(kv[1]))[:25]:
            la = sum(c[0] for _, c in items) / len(items)
            lo = sum(c[1] for _, c in items) / len(items)
            cname = COUNTRY_DB[cc][0] if cc in COUNTRY_DB else "ubicación aprox."
            dom = _KIND_DOMAIN.get(kind, "ddos")
            out.append(_mk(dom, "Monitor DDoS", la, lo, "ALTA", f"{g}: {len(items)} IP activas · {cname} ({today})",
                           f"IPs frescas en listas vivas atribuidas al grupo. Ejemplos: {', '.join(ip for ip, _ in items[:5])}", "",
                           [g, cname], [dom, f"grupo:{g}", "ioc-feed", "en-vivo", f"ips:{len(items)}", "at:src"], fixed=True))
        return out
    finally:
        DDOS_MON["running"] = False


# ════════════════════════════════════════════════════════
# ★ NUEVO · FUENTES DE «QUÉ PASA EN EL MUNDO» (incendios, cortes de internet, clima espacial, aire, tsunamis)
# Cada una devuelve solo lo que trae coordenadas reales. Las que necesitan clave lanzan MissingKey (se ve como «sin clave», no como fallo).
# ════════════════════════════════════════════════════════
def _ms_to_str(ms) -> str:
    try:
        return datetime.fromtimestamp(float(ms) / 1000.0, timezone.utc).strftime("%Y-%m-%d %H:%M")
    except Exception:
        return "?"

def _fire_sev(acres: float, contained: float) -> str:
    sev = "CRITICA" if acres >= 100000 else "ALTA" if acres >= 10000 else "MEDIA" if acres >= 1000 else "BAJA"
    if contained < 20 and acres >= 1000 and sev in ("MEDIA", "ALTA"):
        sev = "ALTA" if sev == "MEDIA" else "CRITICA"            # grande y casi sin contener: un escalón más
    return sev

async def fetch_nifc() -> list[dict]:
    """NIFC (EE. UU.): incendios forestales activos con superficie y % de contención. Solo los de >= 100 acres."""
    r = await _get("https://services3.arcgis.com/T4QMspbfLg3qTGWY/arcgis/rest/services/WFIGS_Incident_Locations_Current/FeatureServer/0/query",
                   params={"where": "IncidentTypeCategory='WF' AND IncidentSize>=100", "outFields": "IncidentName,IncidentSize,PercentContained,POOState,POOCounty,FireDiscoveryDateTime",
                           "outSR": "4326", "f": "json", "resultRecordCount": 400, "orderByFields": "IncidentSize DESC"}, timeout=30)
    j = r.json()
    if j.get("error"):
        raise RuntimeError("NIFC: " + str(j["error"].get("message", j["error"]))[:120])
    out = []
    for f in j.get("features", []):
        a, g = f.get("attributes") or {}, f.get("geometry") or {}
        try:
            la, lo = float(g["y"]), float(g["x"])
        except (KeyError, TypeError, ValueError):
            continue
        acres, cont = _num(a.get("IncidentSize")), _num(a.get("PercentContained"), 0.0)
        name = _str(a.get("IncidentName")).title() or "sin nombre"
        st = _str(a.get("POOState")).replace("US-", "")
        out.append(_mk("incendio", "NIFC", la, lo, _fire_sev(acres, cont), f"Incendio forestal «{name}» ({st or 'EE. UU.'})",
                       f"{acres:,.0f} acres · {cont:.0f}% contenido · condado {_str(a.get('POOCounty')) or '?'} · iniciado {_ms_to_str(a.get('FireDiscoveryDateTime'))} UTC",
                       "https://www.nifc.gov/fire-information/nfn", ["Estados Unidos"], ["incendio", "fuego", "oficial", f"acres:{acres:.0f}"], fixed=True))
    return out

async def fetch_calfire() -> list[dict]:
    """CAL FIRE: incidentes activos de California (incendios y otros) con acres y contención."""
    try:
        r = await _get("https://www.fire.ca.gov/umbraco/api/IncidentApi/List?inactive=false", headers=RSS_HEADERS, timeout=30)
    except httpx.HTTPStatusError as ex:
        if ex.response.status_code not in (403, 404):
            raise
        r = await _get("https://incidents.fire.ca.gov/umbraco/api/IncidentApi/List?inactive=false", headers={"Accept": _BROWSER_ACCEPT, "Referer": "https://www.fire.ca.gov/"}, timeout=30)    # dominio actual de CAL FIRE
    out = []
    for it in r.json() if isinstance(r.json(), list) else []:
        try:
            la, lo = float(it["Latitude"]), float(it["Longitude"])
        except (KeyError, TypeError, ValueError):
            continue
        if not (31 < la < 43 and -126 < lo < -113):
            continue
        acres, cont = _num(it.get("AcresBurned")), _num(it.get("PercentContained"), 0.0)
        name = _str(it.get("Name")) or "sin nombre"
        out.append(_mk("incendio", "CAL FIRE", la, lo, _fire_sev(acres, cont), f"Incendio «{name}» (California)",
                       f"{acres:,.0f} acres · {cont:.0f}% contenido · {_str(it.get('County'))} · actualizado {_str(it.get('Updated'))[:16].replace('T', ' ')}",
                       "https://www.fire.ca.gov" + _str(it.get("Url")), ["California"], ["incendio", "fuego", "oficial", f"acres:{acres:.0f}"], fixed=True))
    return out

async def fetch_cloudflare_outages() -> list[dict]:
    """Cloudflare Radar: cortes de internet de los últimos 7 días (apagones, censura, cables cortados). Usa el mismo token que el DDoS."""
    if not CLOUDFLARE_API_TOKEN:
        raise MissingKey("CLOUDFLARE_API_TOKEN")
    r = await _get("https://api.cloudflare.com/client/v4/radar/annotations/outages", params={"dateRange": "7d", "limit": 60, "format": "json"},
                   headers={"Authorization": f"Bearer {CLOUDFLARE_API_TOKEN}"}, timeout=30)
    out = []
    for a in (r.json().get("result") or {}).get("annotations", []) or []:
        det = (a.get("locationsDetails") or [{}])[0]
        iso = _str(det.get("code") or ((a.get("locations") or [""])[0])).upper()
        cc = country_coords(iso)
        if not cc:
            continue
        la, lo = jitter_coords(cc[0], cc[1], f"cfout{iso}", 0.6)
        cname = COUNTRY_DB[iso][0] if iso in COUNTRY_DB else _str(det.get("name")) or iso
        o = a.get("outage") or {}
        cause = _str(o.get("outageCause")).replace("_", " ").lower()
        start = _str(a.get("startDate"))[:10]
        end = _str(a.get("endDate"))
        out.append(_mk("internet", "Cloudflare Radar", la, lo, "ALTA" if (a.get("scope") or "").lower() in ("country", "") and not end else "MEDIA",
                       f"Corte de internet · {cname} ({start})",
                       f"Causa: {cause or 'sin especificar'} · {_str(o.get('outageType')) or _str(a.get('eventType'))} · inicio {_str(a.get('startDate'))[:16].replace('T', ' ')} UTC"
                       + (" · en curso" if not end else f" · fin {end[:16].replace('T', ' ')} UTC") + f" · {_str(a.get('description'))[:120]}",
                       _str(a.get("linkedUrl")) or "https://radar.cloudflare.com/outage-center", [cname], ["internet", "corte", "cloudflare", "ubicacion-aprox"], fixed=True))
    return out

async def fetch_ioda() -> list[dict]:
    """IODA (Georgia Tech): cortes de internet por país detectados con tráfico BGP / sondas activas. Sin clave."""
    now = int(time.time())
    r = await _get("https://api.ioda.inetintel.cc.gatech.edu/v2/outages/events", params={"from": now - 86400, "until": now, "entityType": "country", "limit": 60}, timeout=30)
    out, seen = [], set()
    data = r.json().get("data") if isinstance(r.json(), dict) else None
    for it in data or []:
        loc = _str(it.get("location") or (it.get("entity") or {}).get("code"))
        iso = loc.split("/")[-1].upper()
        cc = country_coords(iso)
        if not cc or iso in seen:
            continue
        try:
            score = float(it.get("score") or 0)
        except (TypeError, ValueError):
            score = 0.0
        seen.add(iso)
        la, lo = jitter_coords(cc[0], cc[1], f"ioda{iso}", 0.6)
        cname = COUNTRY_DB[iso][0]
        out.append(_mk("internet", "IODA", la, lo, "ALTA" if score >= 1e6 else "MEDIA", f"Caída de conectividad · {cname}",
                       f"Detectada por IODA (señales BGP / sondeo activo) en las últimas 24 h · puntuación {score:,.0f} · inicio {_ms_to_str(float(it.get('start') or 0) * 1000)} UTC",
                       f"https://ioda.inetintel.cc.gatech.edu/country/{iso}", [cname], ["internet", "corte", "ioda", "ubicacion-aprox"], fixed=True))
    return out

async def fetch_spaceweather() -> list[dict]:
    """NOAA SWPC: tormentas geomagnéticas (G), de radiación solar (S) y apagones de radio (R) en curso (escala 1-5). Es un fenómeno GLOBAL:
    el punto se coloca en la sede de NOAA SWPC (Boulder) como ancla de referencia, no como ubicación del fenómeno."""
    r = await _get("https://services.swpc.noaa.gov/products/noaa-scales.json", timeout=20)
    cur = (r.json() or {}).get("0") or {}
    names = {"G": ("tormenta geomagnética", "auroras, fallos de GPS y red eléctrica"), "S": ("tormenta de radiación solar", "riesgo para satélites y aviación polar"),
             "R": ("apagón de radio solar", "pérdida de HF en el lado diurno")}
    out = []
    for k, (nm, eff) in names.items():
        try:
            lvl = int((cur.get(k) or {}).get("Scale") or 0)
        except (TypeError, ValueError):
            lvl = 0
        if lvl < 1:
            continue
        sev = "CRITICA" if lvl >= 4 else "ALTA" if lvl == 3 else "MEDIA" if lvl == 2 else "BAJA"
        out.append(_mk("espacio", "NOAA SWPC", 40.015, -105.27, sev, f"Clima espacial: {nm} {k}{lvl} (global)",
                       f"Nivel {k}{lvl} de 5 · efectos posibles: {eff} · observado {_str(cur.get('DateStamp'))} {_str(cur.get('TimeStamp'))} UTC · "
                       "el punto es la sede de NOAA SWPC (referencia fija: el fenómeno es mundial)",
                       "https://www.swpc.noaa.gov/", [], ["clima-espacial", f"escala:{k}{lvl}", "ancla-fija", "global"], fixed=True))
    return out

async def fetch_openaq() -> list[dict]:
    """OpenAQ v3: estaciones con PM2.5 >= 150 µg/m³ (insalubre o peor) en las últimas 6 h, agrupadas por celdas de 1°. Los valores > 1500 se descartan (sensor averiado)."""
    if not OPENAQ_KEY:
        raise MissingKey("OPENAQ_API_KEY")
    since = (datetime.now(timezone.utc) - timedelta(hours=6)).strftime("%Y-%m-%dT%H:%M:%SZ")
    r = await _get("https://api.openaq.org/v3/parameters/2/latest", params={"limit": 1000, "datetime_min": since}, headers={"X-API-Key": OPENAQ_KEY}, timeout=40)
    cells: dict = {}
    for it in r.json().get("results", []) or []:
        v = _num(it.get("value"), -1)
        c = it.get("coordinates") or {}
        if not (150 <= v <= 1500) or c.get("latitude") is None:
            continue
        la, lo = float(c["latitude"]), float(c["longitude"])
        k = (round(la), round(lo))
        cur = cells.get(k)
        if not cur or v > cur[0]:
            cells[k] = (v, la, lo, _str((it.get("datetime") or {}).get("utc"))[:16].replace("T", " "), 1 + (cur[4] if cur else 0))
        else:
            cells[k] = cur[:4] + (cur[4] + 1,)
    out = []
    for (kla, klo), (v, la, lo, when, n) in sorted(cells.items(), key=lambda kv: -kv[1][0])[:60]:
        sev = "CRITICA" if v >= 350 else "ALTA" if v >= 250 else "MEDIA"
        out.append(_mk("aire", "OpenAQ", float(kla), float(klo), sev, f"Aire peligroso · PM2.5 elevado ({kla}°, {klo}°)",
                       f"PM2.5 máx. {v:.0f} µg/m³ (la OMS recomienda < 15 de media diaria) · {n} estación(es) en la zona · medido {when} UTC",
                       "https://explore.openaq.org/", [], ["aire", "pm25", f"pm25:{v:.0f}", "ubicacion-aprox"], fixed=True))
    return out

_TSU_FEEDS = ("https://www.tsunami.gov/events/xml/PHEBAtom.xml", "https://www.tsunami.gov/events/xml/PAAQAtom.xml")
_TSU_OFF = re.compile(r"no tsunami (threat|warning|watch|advisory)|not (a )?threat|cancel", re.I)
_TSU_ON = re.compile(r"tsunami (warning|watch|advisory)|tsunami threat", re.I)

async def fetch_tsunami() -> list[dict]:
    """Boletines de tsunami de NOAA (centros PTWC y NTWC). Solo los que declaran aviso, vigilancia o amenaza; los de «sin amenaza» se ignoran."""
    out = []
    for url in _TSU_FEEDS:
        try:
            entries = await _fetch_rss(url)
        except Exception as ex:
            log.warning(f"[tsunami] {url.rsplit('/', 1)[-1]}: {type(ex).__name__}")
            continue
        for e in entries:
            if _entry_age_hours(e) > 48:
                continue
            text = _strip_html(f"{e.get('title', '')} {e.get('summary', '')}")
            if _TSU_OFF.search(text) or not _TSU_ON.search(text):
                continue
            la = lo = None
            pt = e.get("georss_point")
            if pt:
                try:
                    a, b = str(pt).replace(",", " ").split()[:2]
                    la, lo = float(a), float(b)
                except Exception:
                    la = lo = None
            if la is None:
                g = geocode_text(text, None, key=text)
                if not g:
                    continue
                la, lo = g[0], g[1]
            low = text.lower()
            sev = "CRITICA" if "warning" in low else "ALTA" if "watch" in low else "MEDIA"
            out.append(_mk("terremoto", "NOAA Tsunami", la, lo, sev, _strip_html(e.get("title", ""))[:160] or "Boletín de tsunami", text[:280],
                           _str(e.get("link")) or "https://www.tsunami.gov/", [], ["tsunami", "oceano", "oficial"], fixed=True))
    return out

# ════════════════════════════════════════════════════════
# ★ NUEVO · RADIACIÓN Y NUCLEAR · DESASTRES NATURALES (ronda 4)
# Fuentes SIN clave. Ninguna se ha podido probar contra el servidor real desde el entorno de desarrollo: si alguna cambia, saldrá en 🩺 Fuentes.
# Lo que NO tiene API pública (NukeMonitor, uRADMonitor, Radiation Network, REM-JRC, Watchers SAM, RAR…) está en la lista «Recursos externos» de la pestaña WAR.
# ════════════════════════════════════════════════════════
async def fetch_bfs_odl() -> list[dict]:
    """BfS (Alemania) · red ODL de ~1 700 sondas de dosis gamma ambiental (µSv/h, media horaria), datos abiertos WFS. Solo se emiten las sondas ANORMALES:
    el fondo natural es 0,05-0,25 µSv/h. Ojo: la lluvia puede subir una sonda unas décimas (lavado de radón) y una sonda averiada da picos; las no validadas nunca pasan de ALTA."""
    r = await _get("https://www.imis.bfs.de/ogc/opendata/ows", params={"service": "WFS", "version": "1.1.0", "request": "GetFeature",
                   "typeName": "opendata:odlinfo_odl_1h_latest", "outputFormat": "application/json"}, timeout=60)
    rows = []
    for f in r.json().get("features", []):
        p, g = f.get("properties") or {}, (f.get("geometry") or {}).get("coordinates") or []
        if len(g) < 2:
            continue
        v = _num(p.get("value"), -1.0)
        if v < 0.40:
            continue
        rows.append((v, p, float(g[1]), float(g[0])))
    rows.sort(key=lambda x: -x[0])
    out = []
    for v, p, la, lo in rows[:40]:
        validated = str(p.get("validated", "")) == "1"
        sev = "CRITICA" if (v >= 2.5 and validated) else "ALTA" if v >= 1.0 else "MEDIA"
        name = _str(p.get("name")) or _str(p.get("kenn")) or "sonda"
        out.append(_mk("radiacion", "BfS ODL (Alemania)", la, lo, sev, f"Radiación gamma elevada · {name}",
                       f"{v:.2f} µSv/h (fondo normal 0,05-0,25) · medida {_str(p.get('end_measure'))[:16]} · {'validada' if validated else 'sin validar'}. "
                       "La lluvia o una sonda defectuosa pueden dar picos: contrasta con las sondas vecinas.",
                       "https://odlinfo.bfs.de/ODL/EN/topics/data-interface/data-interface_node.html", [], ["radiacion", "dosis-gamma", "red-oficial", f"usv:{v:.2f}"], fixed=True))
    return out

_NUC_SITES = [("Punggye-ri (Corea del Norte)", 41.28, 129.08, 2.5), ("Lop Nur (China)", 41.72, 88.35, 2.5), ("Semipalátinsk (Kazajistán)", 50.43, 78.43, 2.5),
              ("Nueva Zembla (Rusia)", 73.37, 54.97, 2.5), ("Nevada (EE. UU.)", 37.12, -116.05, 3.0), ("Pokhran (India)", 27.07, 71.75, 3.0),
              ("Chagai (Pakistán)", 28.83, 64.93, 3.0)]
async def fetch_nuc_sitios() -> list[dict]:
    """Sismos recientes (USGS) a ≤ 60 km de los antiguos/actuales polígonos de pruebas nucleares. Un sismo cerca de un polígono NO es una prueba:
    casi siempre es natural. Sirve para fijarse en el que tenga características de explosión (somero, magnitud súbita). Las explosiones ya etiquetadas
    por USGS salen aparte en la fuente «explosiones»."""
    start = (datetime.now(timezone.utc) - timedelta(days=3)).strftime("%Y-%m-%dT%H:%M:%S")
    async def one(site):
        name, la, lo, mm = site
        r = await _get("https://earthquake.usgs.gov/fdsnws/event/1/query", params={"format": "geojson", "starttime": start, "latitude": la, "longitude": lo,
                       "maxradiuskm": 60, "minmagnitude": mm, "orderby": "time", "limit": 20}, timeout=30)
        return name, r.json().get("features", [])
    res = await asyncio.gather(*(one(s) for s in _NUC_SITES), return_exceptions=True)
    if all(isinstance(x, Exception) for x in res):
        raise res[0]
    out = []
    for x in res:
        if isinstance(x, Exception):
            continue
        name, feats = x
        for f in feats:
            p, g = f.get("properties") or {}, (f.get("geometry") or {}).get("coordinates") or []
            if len(g) < 2 or "nuclear" in _str(p.get("type")):
                continue
            mag = _num(p.get("mag"), 0.0)
            dep = _num(g[2] if len(g) > 2 else 0)
            out.append(_mk("explosion", "USGS · sitios de pruebas", float(g[1]), float(g[0]), "ALTA" if mag >= 4.0 else "MEDIA",
                           f"Sismo cerca del sitio de pruebas {name} · M{mag:.1f}",
                           f"{_ms_to_str(p.get('time'))} UTC · profundidad {dep:.0f} km · tipo USGS «{_str(p.get('type'))}». Probablemente NATURAL: solo vigilancia; una explosión real suele ser muy somera.",
                           _str(p.get("url")) or "https://earthquake.usgs.gov/", [], ["sensor-sismico", "sitio-pruebas", "posible-prueba", f"mag:{mag:.1f}"], fixed=True))
    return out

_NUC_TOPIC = re.compile(r"radiation|radioactiv|radiolog|nuclear (?:power )?(?:plant|station|reactor|facility|site|test|accident|incident)|reactor|\bIAEA\b|\bCTBTO\b|Zaporizhzhia|Zaporizhia|Chernobyl|Chornobyl|Fukushima|"
                        r"radiaci[oó]n|radiactiv|central nuclear|\bOIEA\b|Tchernobyl|Strahlung|radioaktiv|Atomkraftwerk|centrale nucléaire|radiation sickness", re.I)
_NUC_INCIDENT = re.compile(r"leak|spike|elevated|alert|incident|accident|emergency|scram|shut ?down|shut down|blackout|shell|drone|attack|strike|explosion|fire|detect|test|evacuat|warning|"
                           r"fuga|alerta|incidente|accidente|emergencia|apag|ataque|explosi[oó]n|incendio|detect|prueba|evacua|Alarm|Unfall|Störfall|Leck|fuite|alerte|accident", re.I)
_NUC_HARD = re.compile(r"radiation (?:leak|spike|increase|levels? (?:rise|rose|elevated|increased))|radioactive (?:leak|release|cloud)|nuclear (?:accident|emergency)|plant (?:shelled|struck|attacked|hit)|"
                       r"drone (?:hits?|strikes?|attacks?) .{0,40}(?:nuclear|reactor)|fuga radiactiva|emergencia nuclear|accidente nuclear", re.I)
def make_nuc_collector(name: str, url: str, limit: int = 30, max_age_h: float = 48):
    last = [0.0]
    async def _collector() -> list[dict]:
        if time.time() - last[0] < WAR_POLL_MIN * 60:
            return []
        last[0] = time.time()
        out = []
        for e in await _fetch_rss(url):
            if _entry_age_hours(e) > max_age_h:
                continue
            title = _strip_html(e.get("title", ""))
            summ = _strip_html(e.get("summary", ""))[:300]
            link = e.get("link") or ""
            if not title or entertainment_noise(link, title):
                continue
            text = f"{title}. {summ}"
            if not (_NUC_TOPIC.search(text) and _NUC_INCIDENT.search(title)):
                continue
            g = war_geocode(text, title)
            if not g:
                continue
            hard = bool(_NUC_HARD.search(text))
            out.append(_mk("radiacion", name, g[0], g[1], "ALTA" if hard else "MEDIA", title, summ or g[2], link, [g[2]],
                           ["radiacion", "nuclear-seguridad", "prensa"] + (["guerra:nuclear"] if re.search(r"shell|drone|attack|strike|ataque|Beschuss|\bwar\b|guerra", text, re.I) else [])))
            if len(out) >= limit:
                break
        return out
    _collector.__name__ = "fetch_nuc_" + re.sub(r"\W+", "_", name.lower())
    return _collector

