_NWS_KEY = re.compile(r"tornado|hurricane|typhoon|tropical storm|storm surge|flash flood|blizzard|ice storm|excessive heat|extreme heat|tsunami|extreme wind|dust storm|volcano|earthquake|avalanche|extreme cold|wind chill", re.I)
def _ring_center(coords) -> Optional[tuple[float, float]]:
    try:
        ring = coords[0][0] if isinstance(coords[0][0][0], (list, tuple)) else coords[0]
        xs = [float(c[0]) for c in ring]; ys = [float(c[1]) for c in ring]
        return sum(ys) / len(ys), sum(xs) / len(xs)
    except Exception:
        return None
async def fetch_nws_severe() -> list[dict]:
    """Servicio Meteorológico de EE. UU. (NWS): solo avisos GRAVES de verdad (tornado, huracán, riada repentina, ventisca, calor extremo, tsunami…).
    Los avisos sin polígono (por zonas) no traen coordenadas y se omiten. Hay otra fuente «noaa» antigua con los 100 primeros avisos sin filtrar."""
    r = await _get("https://api.weather.gov/alerts/active", params={"status": "actual", "message_type": "alert,update", "severity": "Extreme,Severe"},
                   headers={"Accept": "application/geo+json"}, timeout=40)
    out, seen = [], set()
    for f in r.json().get("features", []):
        p = f.get("properties") or {}
        ev = _str(p.get("event"))
        if not _NWS_KEY.search(ev):
            continue
        g = f.get("geometry") or {}
        c = _ring_center(g.get("coordinates")) if g.get("type") in ("Polygon", "MultiPolygon") else None
        if not c:
            continue
        area = _str(p.get("areaDesc"))[:90]
        title = f"{ev} · {area}"
        if title in seen:
            continue
        seen.add(title)
        emerg = bool(re.search(r"emergency", ev + " " + _str(p.get("headline")), re.I))
        sev = "CRITICA" if emerg or re.search(r"tornado warning|hurricane warning|tsunami warning|extreme wind", ev, re.I) else "ALTA" if _str(p.get("severity")) == "Extreme" else "MEDIA"
        dom = "terremoto" if re.search(r"tsunami|earthquake", ev, re.I) else "evento_natural" if re.search(r"volcano|avalanche", ev, re.I) else "meteorologico"
        tags = ["desastre", "alerta-oficial", "nws"] + (["ciclon"] if re.search(r"hurricane|typhoon|tropical", ev, re.I) else [])
        out.append(_mk(dom, "NWS (EE. UU.)", c[0], c[1], sev, title[:180], (_str(p.get("headline")) or _str(p.get("description")))[:300],
                       "https://www.weather.gov/", [], tags, fixed=True))
        if len(out) >= 120:
            break
    return out

async def fetch_volcanes_usgs() -> list[dict]:
    """Volcanes de EE. UU. con alerta ELEVADA (nivel WATCH/WARNING, código naranja/rojo), del sistema HANS del USGS. Endpoint sin verificar en vivo."""
    r = await _get("https://volcanoes.usgs.gov/hans-public/api/volcano/getElevatedVolcanoes", timeout=30)
    data = r.json()
    items = data if isinstance(data, list) else (data.get("volcanoes") or data.get("data") or [])
    out = []
    for v in items:
        la, lo = v.get("latitude", v.get("lat")), v.get("longitude", v.get("lon", v.get("lng")))
        if la in (None, "") or lo in (None, ""):
            continue
        name = _str(v.get("volcano_name") or v.get("name")) or "volcán"
        lvl = _str(v.get("alert_level") or v.get("alertLevel")).upper()
        col = _str(v.get("color_code") or v.get("colorCode")).upper()
        sev = "ALTA" if (lvl == "WARNING" or col == "RED") else "MEDIA"
        out.append(_mk("evento_natural", "USGS Volcanes", float(la), float(lo), sev, f"Volcán {name}: alerta {lvl or '?'} / código {col or '?'}",
                       _str(v.get("synopsis") or v.get("notice_type_cd"))[:300], _str(v.get("notice_url")) or "https://volcanoes.usgs.gov/", [], ["volcan", "alerta-oficial", "desastre"], fixed=True))
    return out

