async def fetch_estado_aws() -> list[dict]:
    """AWS Health Dashboard (RSS público): eventos recientes por servicio y región; se omiten los ya resueltos."""
    out = []
    for e in await _fetch_rss("https://status.aws.amazon.com/rss/all.rss"):
        if _entry_age_hours(e) > 8:
            continue
        title = _strip_html(e.get("title", ""))
        summ = _strip_html(e.get("summary", ""))[:300]
        if not title or re.search(r"operating normally|\[RESOLVED\]|resolved", f"{title} {summ[:80]}", re.I):
            continue
        reg = next((k for k in _AWS_REGIONS if k in f"{title} {e.get('link','')} {e.get('id','')} {summ}".lower()), "us-east-1")
        la, lo = jitter_coords(*_AWS_REGIONS[reg], f"aws{reg}", 0.05)
        sev = "ALTA" if re.search(r"disruption|outage|unavailab|increased (?:error|fault)", title + summ, re.I) else "MEDIA"
        out.append(_mk("internet", "Estado AWS", la, lo, sev, f"Caída de servicio · AWS ({reg}): {title}", summ, e.get("link") or "https://health.aws.amazon.com/health/status",
                       ["Amazon Web Services"], ["internet", "servicio", "caida", "oficial", "ubicacion-aprox", "aws"], fixed=True))
        if len(out) >= 25:
            break
    return out

