def _make_google_status(name: str, url: str, base: str, lat: float, lon: float, tag: str):
    async def _collector() -> list[dict]:
        r = await _get(url, timeout=25)
        out = []
        for inc in (r.json() if r.text.strip().startswith("[") else []) or []:
            if not isinstance(inc, dict) or inc.get("end"):
                continue                                                     # solo incidentes aún abiertos
            svc = _str(inc.get("service_name")) or ", ".join(_str(x.get("title")) for x in (inc.get("affected_products") or [])[:3] if isinstance(x, dict))
            desc = _strip_html(_str(inc.get("external_desc")))[:200]
            sev = {"high": "ALTA", "medium": "MEDIA", "low": "MEDIA"}.get(_str(inc.get("severity")).lower(), "MEDIA")
            la, lo = jitter_coords(lat, lon, f"g{tag}", 0.05)
            uri = _str(inc.get("uri"))
            out.append(_mk("internet", f"Estado {name}", la, lo, sev, f"Caída de servicio · {name}: {svc or desc[:80]}", desc, (base + uri) if uri else base,
                           ["Google"], ["internet", "servicio", "caida", "oficial", "ubicacion-aprox", tag], fixed=True))
            if len(out) >= 25:
                break
        return out
    _collector.__name__ = "fetch_estado_" + tag
    return _collector

