_SVC_PROV = [(n, re.compile(rx, re.I), la, lo) for n, rx, la, lo in _SVC_PROV]
_SVC_OUT = re.compile(r"\boutage|went down|goes down|is down|are down|\bdown for\b|down globally|service disruption|disruption|not working|knocked offline|went offline|goes offline|Downdetector|"
                      r"ca[ií]da|ca[ií]do|se cae|ca[ií]da global|sin servicio|interrupci[oó]n|panne|st[oö]rung|Ausfall|disservizio|"
                      r"users? (?:report|reported|reporting)|thousands of users", re.I)
_SVC_NOT = re.compile(r"\b(?:power outage|blackout|apag[oó]n el[eé]ctrico|electricity|planned|scheduled maintenance|stock|shares|price|earnings|opinion|how to|"
                      r"ca[ií]da de (?:ventas|precios|acciones|bolsa|ingresos)|falls?|plunge|slump)\b", re.I)
_SVC_BIG = re.compile(r"thousands|millions|global|worldwide|widespread|major|massive|nationwide|miles de|millones|mundial|masiv", re.I)

def make_outage_news_collector(name: str, query: str, **kw):
    async def _collector() -> list[dict]:
        out, seen = [], set()
        for e in await _fetch_rss(_gnews(query, 1, **kw)):
            if _entry_age_hours(e) > 30:
                continue
            title = _strip_html(e.get("title", ""))
            if not title or not _SVC_OUT.search(title) or _SVC_NOT.search(title):
                continue
            prov = next(((n, la, lo) for n, rx, la, lo in _SVC_PROV if rx.search(title)), None)
            if not prov:
                continue
            key = (prov[0], re.sub(r"\W+", " ", title.lower())[:50])
            if key in seen:
                continue
            seen.add(key)
            la, lo = jitter_coords(prov[1], prov[2], f"svcn{prov[0]}", 0.05)
            out.append(_mk("internet", name, la, lo, "ALTA" if _SVC_BIG.search(title) else "MEDIA", f"Caída de servicio · {prov[0]}: {title}",
                           _strip_html(e.get("summary", ""))[:250], e.get("link") or "", [prov[0]],
                           ["internet", "servicio", "caida", "prensa", "sin-verificar", "ubicacion-aprox", re.sub(r"\W+", "-", prov[0].lower())], fixed=True))
            if len(out) >= 30:
                break
        return out
    _collector.__name__ = "fetch_" + re.sub(r"\W+", "_", name.lower())
    return _collector

