def make_arrest_collector(label: str, q: str, hl: str, gl: str, ceid: str):
    base = make_rss_collector("Detenciones · " + label, _gnews(q, 4, hl, gl, ceid), "terrorismo", "MEDIA", limit=60, max_age_h=168)
    async def _c() -> list[dict]:
        out = []
        for ev in await base():
            a = arrest_classify(f"{ev['title']}. {ev['description']}")
            if a:
                ev["domain"] = "detencion_terror"
                ev["severity"] = "ALTA" if a == "celula" else "MEDIA"
                tg = _str(ev.get("tags"))
                ev["tags"] = (tg + "," if tg else "") + "detencion,terror:detencion" + (",celula" if a == "celula" else "")
                out.append(ev)
        return out
    _c.__name__ = "fetch_detenciones_" + re.sub(r"\W+", "_", label.lower())
    return _c

