def make_bomb_collector(label: str, q: str, hl: str, gl: str, ceid: str, iso):
    base = make_rss_collector("Alerta bomba · " + label, _gnews(q, 3, hl, gl, ceid), "alerta_bomba", "MEDIA", default_iso=iso, limit=60, max_age_h=120)
    async def _c() -> list[dict]:
        out = []
        for ev in await base():
            r = bombscare_classify(f"{ev['title']}. {ev['description']}")
            if r:
                ev["domain"] = "alerta_bomba"
                ev["severity"] = r[1]
                tg = _str(ev.get("tags"))
                ev["tags"] = (tg + "," if tg else "") + f"alerta-bomba,bomba:{r[0]}"
                out.append(ev)
        return out
    _c.__name__ = "fetch_bomba_" + re.sub(r"\W+", "_", label.lower())
    return _c

