ECO_MODE = os.getenv("NEXUS_ECO", "").strip().lower() in ("1", "true", "si", "sí", "yes", "on")
_ECO_LAST: dict = {}
def _eco_skip(kind: str, every_min: int) -> bool:
    """Modo ECO (opcional, NEXUS_ECO=1): sin NINGÚN panel abierto, los barridos automáticos se espacian (rápidos 30 min, completo 60 min).
    Con un panel abierto, o con el ECO apagado (por defecto), todo funciona igual que siempre."""
    if not ECO_MODE or WS_MGR.connections:
        _ECO_LAST[kind] = time.time()
        return False
    if time.time() - _ECO_LAST.get(kind, 0) < every_min * 60:
        return True
    _ECO_LAST[kind] = time.time()
    return False

async def run_fast_groups() -> None:
    """Pasada frecuente y ligera SOLO del detector de denuncias (Telegram + feeds de seguridad)."""
    if SWEEP_LOCK.locked() or SWEEP_INTERVAL["minutes"] == 0 or _eco_skip("groups", 30):     # modo MANUAL (0): ningún carril automático
        return
    try:
        await run_full_sweep(only=GROUP_FAST_SOURCES)
    except Exception as e:
        log.warning(f"[DETECTOR] pasada rápida: {type(e).__name__}: {e}")


