# § 9. LLM (múltiples prompts)
# ═══════════════════════════════════════════════════════════════════════

LLM_PROMPTS = {
    "brief": (
        "Eres analista OSINT senior. Genera un resumen ejecutivo en español "
        "(máx. 3 párrafos) identificando patrones, riesgos y acciones sugeridas. "
        "Sé conciso y directo.\n\nDatos:\n{data}\n\nCorrelaciones:\n{corrs}"
    ),
    "threat": (
        "Eres analista de ciberinteligencia. Identifica la amenaza más crítica "
        "de este lote y explica su impacto potencial en 2 párrafos.\n\n{data}"
    ),
    "geo": (
        "Eres analista geopolítico. Resume los eventos geopolíticos más "
        "relevantes y su posible evolución.\n\n{data}"
    ),
}

def generate_llm_brief(df: pd.DataFrame, corrs: list[dict], prompt_type: str = "brief", lang: str = "es") -> str:
    """Función síncrona (llamada OpenAI bloqueante): invocar con asyncio.to_thread desde código async."""
    if LLM_CLIENT is None or df.empty:
        return "Análisis LLM no disponible (falta API key o datos)."
    cache_key = f"llm:{prompt_type}:{lang}:{hashlib.md5(df.head(30).to_json().encode()).hexdigest()}"
    cached = cache_get(cache_key)
    if cached:
        return cached
    sample = df.head(30)[["domain", "source", "severity", "title"]].to_string(index=False)
    corr_txt = "\n".join(c["description"] for c in corrs[:5]) or "Sin correlaciones."
    prompt = LLM_PROMPTS.get(prompt_type, LLM_PROMPTS["brief"]).format(data=sample, corrs=corr_txt)
    prompt += "\n\nWrite the whole answer in English." if lang == "en" else "\n\nResponde íntegramente en español."
    try:
        resp = LLM_CLIENT.chat.completions.create(
            model="gpt-4o-mini",
            messages=[{"role": "user", "content": prompt}],
            temperature=0.3,
        )
        out = resp.choices[0].message.content
        cache_set(cache_key, out)
        return out
    except Exception as e:
        return f"Error LLM: {e}"


