# § 10. ALERTAS Y BOT DE TELEGRAM
# ═══════════════════════════════════════════════════════════════════════

def _md_escape(s) -> str:
    """Escapa los caracteres especiales del Markdown (legacy) de Telegram."""
    return re.sub(r"([_*`\[])", r"\\\1", str(s))

def _md_unescape(s: str) -> str:
    return re.sub(r"\\([_*`\[])", r"\1", s)

async def tg_send(text: str, keyboard: Optional[InlineKeyboardMarkup] = None) -> None:
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT_ID:
        return
    bot = Bot(token=TELEGRAM_TOKEN)
    try:
        await bot.send_message(
            chat_id=TELEGRAM_CHAT_ID, text=text,
            parse_mode=ParseMode.MARKDOWN, reply_markup=keyboard,
        )
    except Exception as e:
        log.warning(f"[TG] Markdown falló ({e}); reintentando en texto plano")
        try:
            await bot.send_message(
                chat_id=TELEGRAM_CHAT_ID, text=_md_unescape(text), reply_markup=keyboard,
            )
        except Exception as e2:
            log.warning(f"[TG] {e2}")

async def _reply(u: Update, text: str, md: bool = True, **kw) -> None:
    """Responde tanto a comandos como a callbacks (u.message es None en callbacks)."""
    msg = u.effective_message
    if msg is None:
        return
    if md:
        try:
            await msg.reply_text(text, parse_mode=ParseMode.MARKDOWN, **kw)
            return
        except Exception as e:
            log.debug(f"[TG] Markdown falló: {e}")
            text = _md_unescape(text)
    await msg.reply_text(text, **kw)

TG_ALERTS_MODE = (os.getenv("NEXUS_TG_ALERTS", "critical").strip().lower() or "critical")      # critical (por defecto) | all | off
TG_MAX_PER_HOUR = max(1, int(float(os.getenv("NEXUS_TG_MAX_PER_HOUR", "6") or 6)))
_TG_SENT_TS: list = []          # instantes de los avisos enviados en la última hora (límite anti-spam)
_TG_HELD = {"n": 0}             # alarmas retenidas por el límite: salen resumidas en el siguiente aviso

def _tg_muted() -> bool:
    try:
        return float(kv_get("tg_mute_until", "0") or 0) > time.time()
    except Exception:
        return False

def _tg_authorized(u: Update) -> bool:
    ch = u.effective_chat
    return bool(TELEGRAM_CHAT_ID and ch and str(ch.id) == str(TELEGRAM_CHAT_ID).strip())

def _tg_guard(fn):
    """Solo TU chat puede dar órdenes al bot (antes cualquiera que lo encontrase podía lanzar /sweep o bajar el /export)."""
    async def wrapper(u: Update, c: ContextTypes.DEFAULT_TYPE):
        if not _tg_authorized(u):
            if not TELEGRAM_CHAT_ID and u.effective_chat:
                await _reply(u, f"Tu chat_id es {u.effective_chat.id}. Pégalo en el .env como TELEGRAM_CHAT_ID=… y reinicia NEXUS para activar el bot.", md=False)
            return
        return await fn(u, c)
    wrapper.__name__ = getattr(fn, "__name__", "tg_handler")
    return wrapper

def _tg_alarm_text(items: list[dict], held: int = 0) -> str:
    lines = [f"🚨 *{len(items) + held} alarma(s) NEXUS*"]
    for e in items[:6]:
        k = alarm_kind(_str(e.get("tags"))) or "alarma"
        where = f" · {_md_escape(_str(e.get('source')))}"
        lines.append(f"• [{_md_escape(k)}] {_md_escape(_str(e.get('title'))[:140])}{where}")
    rest = max(0, len(items) - 6) + held
    if rest:
        lines.append(f"…y {rest} más (míralas en el panel 🚨)")
    return "\n".join(lines)

async def tg_alarm_dispatch(events: list[dict]) -> None:
    """Modo «critical»: SOLO eventos nuevos con etiqueta alarma:*; un mensaje por barrido; máximo TG_MAX_PER_HOUR mensajes por hora."""
    items = [e for e in events if e.get("_new") and "alarma:" in _str(e.get("tags"))]
    if not items or _tg_muted():
        return
    now = time.time()
    _TG_SENT_TS[:] = [t for t in _TG_SENT_TS if now - t < 3600]
    if len(_TG_SENT_TS) >= TG_MAX_PER_HOUR:
        _TG_HELD["n"] += len(items)
        return
    held, _TG_HELD["n"] = _TG_HELD["n"], 0
    _TG_SENT_TS.append(now)
    await tg_send(_tg_alarm_text(items, held))

async def cmd_alarmas(u: Update, c: ContextTypes.DEFAULT_TYPE):
    h = 6
    try:
        h = max(1, min(72, int((c.args or ["6"])[0])))
    except Exception:
        pass
    d = await asyncio.to_thread(db_alarms, h, 12)
    if not d["n"]:
        await _reply(u, f"✅ Sin alarmas en las últimas {h} h.", md=False)
        return
    await _reply(u, f"🚨 {d['n']} alarma(s) en {h} h · " + ", ".join(f"{k}:{v}" for k, v in d["kinds"].items()) + "\n" +
                 "\n".join(f"• [{i['k']}] {i['t'][:120]} ({i['src']}, {i['a']})" for i in d["items"][:12]), md=False)

