async def cmd_silencio(u: Update, c: ContextTypes.DEFAULT_TYPE):
    try:
        h = float((c.args or ["1"])[0])
    except Exception:
        h = 1.0
    if h <= 0:
        kv_set("tg_mute_until", "0"); await _reply(u, "🔔 Avisos reactivados.", md=False)
    else:
        h = min(h, 72); kv_set("tg_mute_until", str(time.time() + h * 3600)); await _reply(u, f"🔕 Avisos silenciados {h:g} h (/silencio 0 para reactivar).", md=False)

