async def dispatch_alerts(events: list[dict], corrs: list[dict], anomalies: list[dict]) -> None:
    if not TELEGRAM_TOKEN or TG_ALERTS_MODE == "off":
        return
    if TG_ALERTS_MODE != "all":
        await tg_alarm_dispatch(events)
        return
    # Solo C2 realmente nuevos (insertados en este barrido), no todos los de la blocklist
    c2 = [e for e in events if e["source"] == "Feodo" and e.get("_new")]
    if c2:
        await tg_send(f"🚨 *{len(c2)} nuevos C2*\n" + "\n".join(_md_escape(e["title"]) for e in c2[:5]))
    dd = [e for e in events if e.get("domain") in ("ddos", "malware") and e.get("_new")
          and e.get("severity") in ("ALTA", "CRITICA") and e.get("source") != "Feodo"]
    if dd:
        await tg_send(f"🛡 *{len(dd)} nuevos DDoS/malware*\n" + "\n".join(_md_escape(e["title"]) for e in dd[:5]))
    if anomalies:
        top = anomalies[0]
        await tg_send(f"📊 *Anomalía detectada*\n{_md_escape(top['description'])}")
    if corrs:
        top = sorted(corrs, key=lambda c: c["score"], reverse=True)[:3]
        kb = InlineKeyboardMarkup([[
            InlineKeyboardButton("📊 Ver dashboard", callback_data="open:dashboard"),
            InlineKeyboardButton("📈 Ver correlaciones", callback_data="open:corr"),
        ]])
        await tg_send("🔗 *Correlaciones top*\n" + "\n".join(_md_escape(c["description"]) for c in top), kb)


