def export_csv_path() -> str:
    df = db_query_events(hours=24, limit=10000)
    path = os.path.join(tempfile.gettempdir(), f"nexus_events_{datetime.now().strftime('%Y%m%d_%H%M%S')}.csv")
    df.to_csv(path, index=False)
    return path

def export_geojson(df: pd.DataFrame) -> str:
    features = []
    for _, r in df.iterrows():
        features.append({
            "type": "Feature",
            "geometry": {"type": "Point", "coordinates": [float(r["lon"]), float(r["lat"])]},
            "properties": {
                "domain": r["domain"], "source": r["source"],
                "severity": r["severity"], "title": r["title"],
                "description": r["description"], "url": r["url"],
                "timestamp": r["timestamp"],
            },
        })
    return json.dumps({"type": "FeatureCollection", "features": features}, ensure_ascii=False)

def export_kml(df: pd.DataFrame) -> str:
    placemarks = []
    for _, r in df.iterrows():
        placemarks.append(
            f"<Placemark><name>{_xml_escape(r['title'])}</name>"
            f"<description>{_xml_escape(r['description'])}</description>"
            f"<Point><coordinates>{r['lon']},{r['lat']},0</coordinates></Point>"
            f"</Placemark>"
        )
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<kml xmlns="http://www.opengis.net/kml/2.2"><Document>'
        + "".join(placemarks) + "</Document></kml>"
    )

def export_markdown(df: pd.DataFrame, corrs: pd.DataFrame) -> str:
    lines = [f"# Reporte OSINT — {datetime.now().strftime('%Y-%m-%d %H:%M')}\n"]
    lines.append(f"**Total eventos:** {len(df)}  |  **Correlaciones:** {len(corrs)}\n")
    lines.append("## Eventos por severidad\n")
    for sev in ["CRITICA", "ALTA", "MEDIA", "BAJA"]:
        n = len(df[df["severity"] == sev])
        lines.append(f"- **{sev}**: {n}")
    lines.append("\n## Top 10 eventos de severidad CRITICA/ALTA\n")
    high = df[df["severity"].isin(["CRITICA", "ALTA"])].head(10)
    for _, r in high.iterrows():
        lines.append(f"- `[{r['source']}]` **{r['title']}** — {_str(r['description'])[:100]}")
    lines.append("\n## Correlaciones\n")
    for _, r in corrs.head(10).iterrows():
        lines.append(f"- {r['description']}")
    return "\n".join(lines)

def _xml_escape(s) -> str:
    return (_str(s)).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


