# § 12. BARRIDO COMPLETO
# ═══════════════════════════════════════════════════════════════════════

SOURCE_LAST: dict[str, dict] = {}   # último resultado por fuente (nº de eventos y error), para la pestaña «Fuentes»
SOURCE_TIMEOUT = 90
SOURCE_TIMEOUTS = {"gdelt_crime": 300, "grupos_ips": 120, "grupos_telegram": 190, "grupos_rss": 120, "ddos_monitor": 240}   # GDELT: 6 consultas espaciadas ≥5,5 s (y reintentos si responde 429)

SOURCE_CONCURRENCY = max(4, int(os.getenv("NEXUS_SOURCE_CONCURRENCY", "32")))   # fuentes a la vez (antes: las ~120 de golpe; saturaba red y CPU al arrancar)
_SOURCE_SEM: Optional[tuple] = None

_NET_FAILS: list = []          # instantes de los últimos ConnectTimeout/ConnectError
_NET_DOWN_UNTIL = 0.0

# Fuentes que NUNCA se apagan ni se pausan: si fallan, se reintentan en el siguiente ciclo (un grupo o canal que da error no frena al resto).
SOFT_SOURCES = {"grupos_telegram", "grupos_ips", "grupos_rss"}
_NET_PROBE_T = 0.0

def _net_probe_sync() -> tuple[bool, str]:
    """¿Funciona de verdad la red local? TCP a tres IPs públicas (sin DNS) y una resolución DNS. Si alguna cosa falla, es TU red; si todo responde,
    los 25 fallos eran de fuentes concretas (lentas o bloqueadas) y no hay motivo para pausar nada."""
    import socket as _s
    tcp = False
    for host in ("1.1.1.1", "8.8.8.8", "9.9.9.9"):
        try:
            with _s.create_connection((host, 443), timeout=2.5):
                tcp = True
                break
        except OSError:
            continue
    try:
        _s.getaddrinfo("example.com", 443, type=_s.SOCK_STREAM)
        dns = True
    except OSError:
        dns = False
    return (tcp and dns), f"TCP {'ok' if tcp else 'FALLA'} · DNS {'ok' if dns else 'FALLA'}"

def _net_note_fail() -> None:
    """Anota un fallo de CONEXIÓN. La decisión de pausar la toma _net_check(), que antes comprueba si la red está caída de verdad."""
    now = time.time()
    _NET_FAILS.append(now)
    while _NET_FAILS and now - _NET_FAILS[0] > 60:
        _NET_FAILS.pop(0)

async def _net_check() -> None:
    """25+ fallos de conexión en 60 s: se comprueba la red. Caída → se pausa el sondeo 2 min (y se vuelve a comprobar cada 20 s para reanudar
    en cuanto vuelva). Funciona → NO se pausa: antes se pausaba todo aunque la red estuviera bien y las fuentes se quedaban vacías."""
    global _NET_DOWN_UNTIL, _NET_PROBE_T
    now = time.time()
    if len(_NET_FAILS) < 25 or now <= _NET_DOWN_UNTIL or now - _NET_PROBE_T < 45:
        return
    _NET_PROBE_T = now
    ok, det = await asyncio.to_thread(_net_probe_sync)
    if ok:
        _NET_FAILS.clear()
        log.warning(f"[RED] 25+ fallos de conexión en 60 s, pero tu red responde ({det}): son fuentes concretas lentas o bloqueadas. No pauso nada.")
    else:
        _NET_DOWN_UNTIL = time.time() + 120
        log.warning(f"[RED] 25+ fallos de conexión en 60 s y tu red NO conecta ({det}). Pauso el sondeo 2 min y compruebo cada 20 s para reanudar al volver.")

async def run_source(name: str, fn: callable) -> tuple[str, list[dict], Optional[str]]:
    global _SOURCE_SEM, _NET_DOWN_UNTIL, _NET_PROBE_T
    if circuit_is_open(name) and name not in SOFT_SOURCES:
        return (name, [], "circuit_open")
    if time.time() < _NET_DOWN_UNTIL and name not in SOFT_SOURCES:
        if time.time() - _NET_PROBE_T > 20:                    # durante la pausa se vuelve a comprobar la red cada 20 s para reanudar en cuanto vuelva
            _NET_PROBE_T = time.time()
            ok, det = await asyncio.to_thread(_net_probe_sync)
            if ok:
                _NET_DOWN_UNTIL = 0.0
                _NET_FAILS.clear()
                log.warning(f"[RED] la red ha vuelto ({det}): reanudo el sondeo de fuentes")
        if time.time() < _NET_DOWN_UNTIL:
            SOURCE_LAST[name] = {"n": 0, "err": "pausada: la red local no conecta (se comprueba cada 20 s y se reanuda sola)", "t": datetime.now(timezone.utc).isoformat()}
            return (name, [], "red caída")
    loop = asyncio.get_running_loop()
    if _SOURCE_SEM is None or _SOURCE_SEM[0] is not loop:
        _SOURCE_SEM = (loop, asyncio.Semaphore(SOURCE_CONCURRENCY))
    async with _SOURCE_SEM[1]:
        return await _run_source_inner(name, fn)

async def _run_source_inner(name: str, fn: callable) -> tuple[str, list[dict], Optional[str]]:
    t0 = time.time()
    try:
        data = await asyncio.wait_for(fn(), timeout=SOURCE_TIMEOUTS.get(name, SOURCE_TIMEOUT))
        dur = int((time.time() - t0) * 1000)
        circuit_record(name, True, dur)
        SOURCE_LAST[name] = {"n": len(data or []), "err": None, "t": datetime.now(timezone.utc).isoformat()}
        return (name, data, None)
    except MissingKey as e:
        SOURCE_LAST[name] = {"n": 0, "err": f"sin clave: pon {e.env} en el .env", "t": datetime.now(timezone.utc).isoformat()}
        return (name, [], None)
    except Exception as e:
        dur = int((time.time() - t0) * 1000)
        tmo = SOURCE_TIMEOUTS.get(name, SOURCE_TIMEOUT)
        if isinstance(e, (asyncio.TimeoutError, TimeoutError)) and dur / 1000.0 > tmo + 3:
            # el temporizador saltó TARDE: el servidor estuvo bloqueado (BD, otro proceso…), no la fuente. No se castiga ni se pausa.
            SOURCE_LAST[name] = {"n": 0, "err": "interrumpida por un bloqueo local (no cuenta como fallo de la fuente)", "t": datetime.now(timezone.utc).isoformat()}
            log.warning(f"[{name}] interrumpida por bloqueo local ({dur / 1000:.0f}s): no se marca como fallo")
            return (name, [], "bloqueo local")
        net_err = type(e).__name__ in ("ConnectTimeout", "ConnectError", "ReadTimeout", "ConnectionError")
        if type(e).__name__ in ("ConnectTimeout", "ConnectError"):
            _net_note_fail()
            await _net_check()
        if net_err and time.time() < _NET_DOWN_UNTIL:
            pass                                               # tu red está caída: no es culpa de la fuente (ni cuenta como fallo ni abre el circuito)
        else:
            circuit_record(name, False, dur)
            if name in SOFT_SOURCES:
                CIRCUIT_OPEN.pop(name, None)                   # Telegram/IPs/RSS nunca se «apagan»: se reintentan en cada ciclo
        if isinstance(e, (asyncio.TimeoutError, TimeoutError)) and not str(e):
            msg = f"TimeoutError: sin respuesta en {int(dur / 1000)} s (servidor lento o bloqueado desde tu red)"
        else:
            msg = f"{type(e).__name__}: {str(e) or repr(e) or 'sin detalle (¿sin conexión / DNS / tiempo agotado?)'}"
        SOURCE_LAST[name] = {"n": 0, "err": msg[:160], "t": datetime.now(timezone.utc).isoformat()}
        log.warning(f"[{name}] {msg}")
        return (name, [], msg)

VALID_SEVERITIES = set(SEVERITY_ORDER)

_CYBER_RULES = [   # (dominio, regex) — el primero que coincide gana
    ("ddos", re.compile(r"\bddos\b|denial[- ]of[- ]service|\bbooter\b|\bstresser\b|\bsyn flood|\budp flood|\bhttp flood|\bamplification attack", re.I)),
    ("ransomware", re.compile(r"ransomware|ransom note|lockbit|blackcat|alphv|\bakira\b|\bplay ransomware|clop\b|black ?basta|\bryuk\b|\bconti\b|double extortion", re.I)),
    ("phishing", re.compile(r"phishing|spear-?phish|smishing|vishing|credential harvest|fake login|\bbec\b|business email compromise|quishing", re.I)),
    ("bruteforce", re.compile(r"brute[- ]?force|fuerza bruta|password spray|credential stuffing|ssh (login|attack)|rdp (attack|brute)|\bbruteforce", re.I)),
    ("exploit", re.compile(r"\bexploit|zero[- ]?day|\b0[- ]?day|remote code execution|\brce\b|privilege escalation|actively exploited|proof[- ]of[- ]concept|\bcve-\d{4}-\d+", re.I)),
    ("malware", re.compile(
        r"malware|botnet|\bc2\b|command and control|command-and-control|trojan|backdoor|\bstealer\b|infostealer|\bloader\b|\brat\b|\bworm\b|rootkit|spyware|"
        r"emotet|qakbot|qbot|dridex|trickbot|icedid|mirai|cobalt ?strike|asyncrat|agent ?tesla|lokibot|redline|raccoon|formbook|njrat|remcos|"
        r"bumblebee|pikabot|smokeloader|guloader|lumma|vidar|wiper", re.I)),
]

def refine_cyber_domain(e: dict) -> None:
    """★ NUEVO: reparte el cajón genérico «ciberataque/cibercrimen» en DDoS, ransomware, phishing, fuerza bruta,
    exploit y malware/botnet según el texto del evento. Lo que no encaja se queda como estaba."""
    if e.get("domain") not in ("ciberataque", "cibercrimen"):
        return
    text = f"{e.get('title','')} {e.get('description','')} {e.get('tags','')}"
    for dom, rx in _CYBER_RULES:
        if rx.search(text):
            e["domain"] = dom
            return

# ─── ★ NUEVO: evaluación de severidad ciber (BAJA / MEDIA / ALTA / CRÍTICA) ───
# Antes casi todo salía «ALTA» o «MEDIA» porque cada colector ponía una severidad fija. Ahora se puntúa cada evento ciber.
_CRIT_INFRA = re.compile(r"hospital|health ?care|clinic|medical|energy|power (grid|plant)|electric|water (utility|system)|nuclear|pipeline|airport|airline|railway|port authority|government|ministry|parliament|military|defen[cs]e|\bbank|financial|scada|\bics\b|critical infrastructure|telecom|election|salud|banco|gobierno|ministerio|eléctric", re.I)
_SCALE = re.compile(r"record|massive|largest|biggest|tbps|gbps|million|billion|thousands|nationwide|widespread|worldwide|global|mass[- ]exploitation|millones|masiv", re.I)
_ACTIVE = re.compile(r"actively exploited|in the wild|zero[- ]?day|\b0[- ]?day|known exploited|\bkev\b|remote code execution|\brce\b", re.I)
_NOTORIOUS = re.compile(r"lockbit|blackcat|alphv|\bclop\b|black ?basta|\bapt ?\d+|lazarus|sandworm|volt typhoon|salt typhoon|fancy bear|cozy bear|killnet|noname057|anonymous sudan|emotet|qakbot|qbot|cobalt ?strike|trickbot|dridex|icedid|mirai|lumma|redline|stuxnet|industroyer|pegasus", re.I)
_BASE_SCORE = {"bruteforce": 0.0, "ciberataque": 0.5, "phishing": 1.0, "cibercrimen": 1.0, "malware": 1.5, "ddos": 1.5,
               "exploit": 2.0, "ransomware": 2.5, "vulnerabilidad": 3.0}

def assess_severity(e: dict) -> None:
    """Puntúa el evento según tipo, infraestructura crítica afectada, escala, explotación activa y actor/familia conocidos."""
    if e.get("_fixed_sev") or e.get("domain") not in _BASE_SCORE:
        return
    text = f"{e.get('title','')} {e.get('description','')} {e.get('tags','')}"
    sc = _BASE_SCORE[e["domain"]]
    if _CRIT_INFRA.search(text): sc += 1.5
    if _SCALE.search(text): sc += 1.0
    if _ACTIVE.search(text): sc += 1.0
    if _NOTORIOUS.search(text): sc += 1.0
    if e["domain"] == "vulnerabilidad" and re.search(r"ransomware: ?known", text, re.I): sc += 1.5
    sc += {"BAJA": -0.5, "MEDIA": 0.0, "ALTA": 0.7, "CRITICA": 2.0}.get(e.get("severity"), 0.0)
    e["severity"] = "CRITICA" if sc >= 4.5 else "ALTA" if sc >= 3.0 else "MEDIA" if sc >= 1.8 else "BAJA"

