_DOMAIN_ATTACK_DEFAULT = {
    "ddos": ["T1498"], "ransomware": ["T1486"], "phishing": ["T1566"], "bruteforce": ["T1110"],
    "exploit": ["T1190"], "vulnerabilidad": ["T1190"], "malware": [],
}
ATTACK_DOMAINS = set(CYBER_DOMAINS)

def tag_attack(e: dict) -> None:
    """Añade a `tags` los IDs de técnicas ATT&CK (T1110, T1486…) que encajan con el evento (máx. 4)."""
    if e.get("domain") not in ATTACK_DOMAINS:
        return
    text = f"{e.get('title','')} {e.get('description','')} {e.get('tags','')}"
    found = list(_DOMAIN_ATTACK_DEFAULT.get(e["domain"], []))
    for tid, (_, _, rx) in ATTACK_TECHNIQUES.items():
        if tid not in found and rx.search(text):
            found.append(tid)
    # un C2 de malware sin otro dato: al menos Application Layer Protocol
    if e["domain"] == "malware" and not found:
        found.append("T1071")
    found = found[:4]
    if found:
        have = set(_str(e.get("tags")).split(","))
        e["tags"] = ",".join(x for x in [_str(e.get("tags"))] + [f for f in found if f not in have] if x)

# ══════════════════════════════════════════════════════════════════════════════
# FLUJOS REALES origen → víctima
#   Un evento solo dibuja arco si lleva la etiqueta  flow:XX>YY  (ISO2 origen > ISO2 víctima).
#   Esa etiqueta solo la ponen datos que de verdad traen los dos extremos:
#     · Cloudflare Radar  /attacks/layerN/top/attacks  (pares origen→objetivo medidos por Cloudflare)
#     · Noticias/avisos de ciberseguridad que ATRIBUYEN un ataque a un país/grupo y nombran a la víctima
#     (los conflictos NO dibujan arcos: solo ciberataques)
#   Sin los dos extremos NO hay arco (una IP maliciosa suelta no tiene víctima conocida).
# ══════════════════════════════════════════════════════════════════════════════
_FLOW_RX = re.compile(r"(?:^|,)flow:([A-Z]{2})>([A-Z]{2})(?=,|$)")

def flow_tag(src: str, dst: str) -> str:
    return f"flow:{src}>{dst}"

