def _arc_target() -> list[float]:
    """Destino de los arcos (por defecto Washington D.C.). NEXUS_ARC_TARGET="lat,lon"."""
    try:
        la, lo = [float(x) for x in os.getenv("NEXUS_ARC_TARGET", "38.9072,-77.0369").split(",")]
        return [la, lo]
    except Exception:
        return [38.9072, -77.0369]

MAP_MAX_POINTS = int(os.getenv("NEXUS_MAP_POINTS", "6000"))
MAP_MAX_CORR = int(os.getenv("NEXUS_MAP_CORR", "100"))        # solo las correlaciones más fuertes (el resto sigue en la pestaña Correl.)

def sym_kind(domain: str, tags: str) -> str:
    """Símbolo del mapa (en vez de punto): boom explosión · misil · dron · ataque · sismo · rad radiación. '' = punto normal."""
    if domain == "maritimo":
        if re.search(r"(?:^|,)rumbo:\d+", tags or ""):
            if "militar" in (tags or ""):
                return "barcoM"
            m = re.search(r"(?:^|,)tipo:([APCTV])", tags or "")
            return "barco" + m.group(1) if m else "barco"
        return "barco0"
    m = re.search(r"(?:^|,)ataque:([\w]+)", tags or "")
    if m:
        k = m.group(1)
        return "boom" if k == "explosion" else "misil" if k == "misil" else "dron" if k == "dron" else "ataque"
    if "detencion" in (tags or "") and domain in ("terrorismo", "detencion_terror"):
        return "xred"
    if domain == "alerta_bomba":
        return "mochila"
    if domain == "explosion":
        return "boom"
    if domain == "terremoto":
        return "sismo"
    if domain == "radiacion":
        return "rad"
    return ""

def _heading(tags: str) -> int:
    m = re.search(r"(?:^|,)rumbo:(\d+)", tags or "")
    return int(m.group(1)) % 360 if m else -1

def _parse_ts(ts) -> Optional[datetime]:
    """Fecha ISO → datetime con zona, SIN pandas (pd.to_datetime por fila costaba ~0,7 ms: 12 000 llamadas = 3 s en cada cambio de filtro)."""
    if isinstance(ts, datetime):
        return ts if ts.tzinfo else ts.replace(tzinfo=timezone.utc)
    try:
        t = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
        return t if t.tzinfo else t.replace(tzinfo=timezone.utc)
    except Exception:
        try:
            t = pd.to_datetime(ts, utc=True, errors="coerce")
            return None if pd.isna(t) else t.to_pydatetime()
        except Exception:
            return None

def _age_hours(ts) -> float:
    t = _parse_ts(ts)
    return 99.0 if t is None else max(0.0, (datetime.now(timezone.utc) - t).total_seconds() / 3600.0)

def build_map_payload(df: pd.DataFrame, corrs: list[dict], max_points: int = MAP_MAX_POINTS,
                      flow_df: Optional[pd.DataFrame] = None, kin_df: Optional[pd.DataFrame] = None) -> dict:
    """JSON compacto para el mapa: máx. `max_points` puntos, priorizando severidad y relevancia."""
    pts: list[dict] = []
    total = 0
    air_hist: dict = {}                                      # avión -> [(ts, la, lo)] para dibujar su estela. FUERA del if: con la ventana sin eventos (BD recién
    #                                                          reiniciada) daba UnboundLocalError y el mapa entero devolvía 500
    if df is not None and not df.empty:
        total = len(df)
        rows = []
        seen_ship: set = set()
        seen_air: dict = {}                                  # avión militar -> nº de avistamientos (un avión = UN punto: su última posición)
        _doms = set(df["domain"].astype(str))
        for r in sorted(df.to_dict("records"), key=lambda x: _str(x.get("timestamp")), reverse=(True)) if ("maritimo" in _doms or "vuelo_militar" in _doms) else df.to_dict("records"):
            if _str(r.get("domain")) == "vuelo_militar":
                tg_ = _str(r.get("tags"))
                mh = re.search(r"(?:^|,)hex:([0-9A-Fa-f]+)", tg_)
                key = ("h" + mh.group(1).upper()) if mh else ("t" + _str(r.get("title")))      # filas antiguas sin hex: indicativo + tipo
                la_, lo_ = _num(r.get("lat"), float("nan")), _num(r.get("lon"), float("nan"))
                if math.isfinite(la_) and math.isfinite(lo_):
                    air_hist.setdefault(key, []).append((_str(r.get("timestamp")), la_, lo_, _str(r.get("title"))[:40]))
                seen_air[key] = seen_air.get(key, 0) + 1
                if seen_air[key] > 1:
                    continue
                r["_sg"] = key
            if _str(r.get("domain")) == "maritimo":          # un barco = UNA flecha (su última posición), no una por barrido
                mm = re.search(r"(?:^|,)mmsi:(\d+)", _str(r.get("tags")))
                if mm:
                    if mm.group(1) in seen_ship:
                        continue
                    seen_ship.add(mm.group(1))
            la, lo = _num(r.get("lat"), float("nan")), _num(r.get("lon"), float("nan"))
            if not (math.isfinite(la) and math.isfinite(lo)) or abs(la) > 90 or abs(lo) > 180:
                continue
            if abs(la) < 0.01 and abs(lo) < 0.01:
                continue
            sev = _str(r.get("severity")) or "MEDIA"
            rows.append((SEVERITY_ORDER.get(sev, 1), relevance_score(r), la, lo, sev, r))
        rows.sort(key=lambda x: (-x[0], -x[1]))
        ships = [x for x in rows if _str(x[5].get("domain")) == "maritimo"]
        if ships and len(rows) > max_points:      # cupo reservado: los barcos (casi todos BAJA) no deben quedar fuera por la prensa de mayor severidad
            quota = min(len(ships), max(150, max_points // 3))
            others = [x for x in rows if _str(x[5].get("domain")) != "maritimo"]
            rows = others[:max_points - quota] + ships[:quota]
        for _, rel, la, lo, sev, r in rows[:max_points]:
            _sg = seen_air.get(r.get("_sg"), 0) if r.get("_sg") else 0
            pts.append({
                "id": int(_num(r.get("id"))), "la": round(la, 4), "lo": round(lo, 4),
                "d": _str(r.get("domain")), "s": sev, "src": _str(r.get("source")),
                "t": _str(r.get("title"))[:140], "ds": _str(r.get("description"))[:200],
                "u": _safe_url(r.get("url")), "r": round(rel, 1), "a": _ago(r.get("timestamp")), "ts": _str(r.get("timestamp"))[:19],
                "k": sym_kind(_str(r.get("domain")), _str(r.get("tags"))), "hd": _heading(_str(r.get("tags"))), "h": round(min(_age_hours(r.get("timestamp")), 99.0), 1),
                "cf": event_conf(_str(r.get("tags")), _str(r.get("source"))),
                **({"sg": _sg} if _sg > 1 else {}),
            })
    trails = []                                              # estela de cada avión militar visto en ≥2 posiciones distintas (la más antigua → la última)
    for key, h in air_hist.items():
        h.sort(key=lambda x: x[0])
        path, last = [], None
        for ts_, la_, lo_, _t in h:
            if (la_, lo_) != last:
                path.append([round(lo_, 3), round(la_, 3)]); last = (la_, lo_)
        if len(path) >= 2:
            trails.append({"p": path[-14:], "n": h[-1][3], "k": len(h), "t0": h[0][0][:16], "t1": h[-1][0][:16]})
    trails.sort(key=lambda x: -x["k"])
    cs = []
    for c in corrs or []:
        la, lo = _num(c.get("lat"), float("nan")), _num(c.get("lon"), float("nan"))
        if math.isfinite(la) and math.isfinite(lo):
            cs.append({"la": round(la, 3), "lo": round(lo, 3), "sc": _num(c.get("score")),
                       "ds": _str(c.get("description"))[:240], "da": _str(c.get("domain_a")), "db": _str(c.get("domain_b")),
                       "sa": _str(c.get("source_a")), "sb": _str(c.get("source_b"))})
    flows = flows_from_df(flow_df if flow_df is not None else df)       # ciber: SOLO flujos con origen y víctima reales (etiqueta flow:XX>YY)
    flows += flows_from_df(kin_df if kin_df is not None else df, 40, kinetic=True)    # ataques militares (prensa): quién → a quién
    cs.sort(key=lambda c: -c["sc"])
    return {"points": pts, "corr": cs[:MAP_MAX_CORR], "flows": flows, "trails": trails[:150], "total": total, "shown": len(pts),
            "arc_target": _arc_target(), "arc_domains": ARC_DOMAINS}


