# ═══════════════════════════════════════════════════════════════════════
# § 15. FASTAPI
# ═══════════════════════════════════════════════════════════════════════

_BG_TASKS: list = []
_INSTANCE_LOCK_FH = None

def _single_instance_check() -> None:
    """Dos NEXUS (p. ej. dg.py y nexus.py) usando la MISMA base de datos se bloquean entre sí («database is locked» y el panel se cuelga).
    Se avisa claramente; no se impide arrancar (puede que uses otra carpeta a propósito)."""
    global _INSTANCE_LOCK_FH
    try:
        import fcntl
        fh = open(str(DB_PATH) + ".lock", "w")
        try:
            fcntl.flock(fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
            fh.write(str(os.getpid())); fh.flush()
            _INSTANCE_LOCK_FH = fh
        except OSError:
            other = ""
            try:
                other = open(str(DB_PATH) + ".lock").read().strip()
            except Exception:
                pass
            log.error("[ARRANQUE] ¡OTRO NEXUS YA ESTÁ USANDO ESTA MISMA BASE DE DATOS" + (f" (proceso {other})" if other else "") + "! "
                      "Los dos se bloquean entre sí: «database is locked», barridos que fallan y panel colgado. "
                      "Cierra el otro (en Linux/Termux: pkill -f nexus.py ; pkill -f dg.py) y deja solo uno.")
    except Exception:
        pass

async def _loop_watchdog() -> None:
    """Avisa en el log cuando el servidor se queda bloqueado más de 2 s (así se ve QUÉ lo cuelga: barrido, BD, etc.)."""
    last_warn = 0.0
    while True:
        t = time.monotonic()
        await asyncio.sleep(1.0)
        lag = time.monotonic() - t - 1.0
        if lag > 2.0 and time.monotonic() - last_warn > 20:
            last_warn = time.monotonic()
            log.warning(f"[RENDIMIENTO] el servidor estuvo bloqueado {lag:.1f}s (barrido en curso: {SWEEP_STATE.get('running')})")


def migrate_domains_v1() -> None:
    """Una sola vez: lo ya guardado se reclasifica a los dominios nuevos (detenciones terroristas y alertas de bomba) para encontrarlo por Modo/Dominio."""
    try:
        if kv_get("mig_dom_v1"):
            return
        conn = db_conn()
        n1 = conn.execute("UPDATE events SET domain='detencion_terror' WHERE domain='terrorismo' AND tags LIKE '%detencion%'").rowcount
        rows = conn.execute("SELECT id,title,description,severity,tags,domain FROM events WHERE domain IN ('noticias','crimen','crimen_urbano','terrorismo','disturbios','alerta_civil','geopolitica') "
                            "AND (title LIKE '%sospechos%' OR title LIKE '%suspicious%' OR title LIKE '%bomb%' OR title LIKE '%bomba%' OR title LIKE '%TEDAX%' OR title LIKE '%artefacto%' "
                            "OR title LIKE '%explosive device%' OR title LIKE '%colis suspect%' OR title LIKE '%Bombendrohung%' OR title LIKE '%allarme bomba%' OR title LIKE '%falsa alarma%' OR title LIKE '%artificier%')").fetchall()
        n2 = 0
        for r in rows:
            e = {"domain": r["domain"], "severity": r["severity"], "title": r["title"] or "", "description": r["description"] or "", "tags": r["tags"] or ""}
            bombscare_mark(e)
            if e["domain"] == "alerta_bomba":
                conn.execute("UPDATE events SET domain=?, severity=?, tags=? WHERE id=?", (e["domain"], e["severity"], e["tags"], r["id"]))
                n2 += 1
        conn.commit()
        conn.close()
        kv_set("mig_dom_v1", "1")
        log.info(f"[MIGRACIÓN] {n1} detenciones y {n2} alertas de bomba reclasificadas a sus dominios nuevos")
    except Exception as ex:
        log.warning(f"[MIGRACIÓN] dominios: {type(ex).__name__}: {ex}")


def migrate_dups_v1() -> None:
    """Una sola vez: colapsa las historias repetidas que ya había guardadas de detenciones y alertas de bomba (misma noticia en varios medios = un solo punto)."""
    try:
        if kv_get("mig_dups_v1"):
            return
        conn = db_conn()
        removed = 0
        for dom in ("detencion_terror", "alerta_bomba"):
            rows = conn.execute("SELECT id,title,lat,lon,timestamp,tags FROM events WHERE domain=? ORDER BY id ASC", (dom,)).fetchall()
            kept: list = []
            for r in rows:
                tk = _story_tokens(r["title"])
                try:
                    ep = datetime.fromisoformat(r["timestamp"].replace("Z", "+00:00")).timestamp()
                except Exception:
                    ep = 0.0
                hit = None
                if len(tk) >= 3:
                    for k in kept:
                        inter = len(tk & k["tk"])
                        if abs(k["ep"] - ep) <= 96 * 3600 and abs(k["la"] - r["lat"]) <= 4 and abs(k["lo"] - r["lon"]) <= 4 and \
                           ((inter >= 4 and inter / max(1, len(tk | k["tk"])) >= 0.5) or (inter >= 3 and len(tk) <= 5 and inter / max(1, len(tk | k["tk"])) >= 0.75)):
                            hit = k
                            break
                if hit:
                    hit["n"] += 1
                    conn.execute("DELETE FROM events WHERE id=?", (r["id"],))
                    removed += 1
                else:
                    kept.append({"id": r["id"], "tk": tk, "ep": ep, "la": r["lat"], "lo": r["lon"], "n": 1, "tags": r["tags"] or ""})
            for k in kept:
                if k["n"] > 1:
                    tg = re.sub(r"(?:^|,)fuentes:\d+", "", k["tags"]).strip(",")
                    conn.execute("UPDATE events SET tags=? WHERE id=?", ((tg + "," if tg else "") + f"fuentes:{k['n']}", k["id"]))
        conn.commit()
        conn.close()
        kv_set("mig_dups_v1", "1")
        log.info(f"[MIGRACIÓN] {removed} duplicados de detenciones/alertas de bomba colapsados")
    except Exception as ex:
        log.warning(f"[MIGRACIÓN] duplicados: {type(ex).__name__}: {ex}")

@asynccontextmanager
async def lifespan(app: FastAPI):
    _t0 = time.time()
    _single_instance_check()
    init_db()
    init_geo()
    migrate_domains_v1()
    migrate_dups_v1()
    log.info(f"[ARRANQUE] base de datos lista en {time.time() - _t0:.1f}s")
    log_keys_status()

    # ★ NUEVO: cargar watchlist persistida
    watchlist_load()

    if TELEGRAM_TOKEN:
        start_tg()
        if TG_APP:
            await TG_APP.initialize()
            await TG_APP.start()
            await TG_APP.updater.start_polling()

    try:
        apply_sweep_interval(int(kv_get("sweep_minutes", str(SWEEP_INTERVAL["minutes"]))))
    except Exception as e:
        log.warning(f"[SWEEP] intervalo: {e}"); apply_sweep_interval(15)
    SCHEDULER.add_job(
        run_fast_news, IntervalTrigger(minutes=max(1.0, NEWS_FAST_MINUTES)), id="sweep_news",
        replace_existing=True, max_instances=1,
    )
    SCHEDULER.add_job(
        run_fast_groups, IntervalTrigger(minutes=max(2.0, GROUPS_FAST_MINUTES)), id="sweep_groups",
        replace_existing=True, max_instances=1,
    )
    SCHEDULER.add_job(
        lambda: db_prune(), IntervalTrigger(hours=6), id="db_prune", replace_existing=True,
    )
    SCHEDULER.add_job(
        watchlist_save, IntervalTrigger(minutes=10), id="wl_persist", replace_existing=True,
    )
    SCHEDULER.start()
    # primer barrido: se retrasa unos segundos para que el panel cargue ANTES, y se salta si ya hubo uno hace menos de 5 minutos
    try:
        _last = db_stats().get("last_sweep")
        _dt = datetime.fromisoformat(_last) if _last else None
        if _dt is not None and _dt.tzinfo is None:
            _dt = _dt.replace(tzinfo=timezone.utc)
        _recent = bool(_dt) and (datetime.now(timezone.utc) - _dt).total_seconds() < 300
    except Exception:
        _recent = False
    if _recent:
        log.info("[SWEEP] barrido reciente en la base de datos: no se repite al arrancar")
    else:
        asyncio.get_running_loop().call_later(8, start_sweep_background)

    # limpieza de reivindicaciones dudosas: recorre la tabla entera, así que va en segundo plano y tarde (antes bloqueaba el arranque)
    async def _bg_clean():
        await asyncio.sleep(90)
        t = time.time()
        await asyncio.to_thread(db_clean_false_claims)
        log.info(f"[ARRANQUE] limpieza en segundo plano terminada en {time.time() - t:.1f}s")
    _BG_TASKS.append(asyncio.ensure_future(_bg_clean()))
    _BG_TASKS.append(asyncio.ensure_future(_loop_watchdog()))
    log.info(f"[ARRANQUE] listo en {time.time() - _t0:.1f}s")
    log.info("NEXUS listo · http://127.0.0.1:8000")
    yield
    for t in _BG_TASKS:
        t.cancel()

    watchlist_save()
    SCHEDULER.shutdown(wait=False)
    if TG_APP:
        await TG_APP.updater.stop()
        await TG_APP.stop()
        await TG_APP.shutdown()
    if GEO_READER:
        GEO_READER.close()
    await HTTP.aclose()


app = FastAPI(title="NEXUS OSINT", version="3.1", lifespan=lifespan)
app.add_middleware(
    CORSMiddleware, allow_origins=["*"], allow_methods=["*"], allow_headers=["*"],
)


# ─── helpers de presentación ─────────────────────────────────────────

def _safe_url(u) -> str:
    """Solo http(s): los enlaces vienen de feeds externos y no deben poder ser javascript:."""
    u = _str(u).strip()
    return u if re.match(r"^https?://", u, re.IGNORECASE) else ""

def _ago(ts) -> str:
    t = _parse_ts(ts)
    if t is None:
        return ""
    s = max(int((datetime.now(timezone.utc) - t).total_seconds()), 0)
    if s < 60:
        return f"{s}s"
    if s < 3600:
        return f"{s // 60}m"
    if s < 86400:
        return f"{s // 3600}h"
    return f"{s // 86400}d"

def _domain_color(domain: str) -> str:
    c = DOMAIN_PALETTE.get(domain, {}).get("color", [150, 150, 170, 255])
    return f"rgb({c[0]},{c[1]},{c[2]})"

def _filters(domain: str, severity: str, group: str = "") -> tuple[Optional[list[str]], Optional[list[str]]]:
    return (resolve_domains(domain, group), [severity] if severity else None)

def _group_count(col: str, hours: int, domains, severities, search) -> dict:
    conn = db_conn()
    where, p = _build_where(hours, domains, severities, None, search)
    rows = conn.execute(f"SELECT {col}, COUNT(*) FROM events{where} GROUP BY {col}", p).fetchall()
    conn.close()
    return {r[0]: r[1] for r in rows}

def _feed_rows(df: pd.DataFrame, sort: str = "recent", limit: int = 150) -> list[dict]:
    if df.empty:
        return []
    rows = []
    for r in df.to_dict("records"):
        rows.append({
            "severity": _str(r.get("severity")) or "MEDIA",
            "source": _str(r.get("source")),
            "domain": _str(r.get("domain")),
            "color": _domain_color(_str(r.get("domain"))),
            "title": _str(r.get("title"))[:200] or "(sin título)",
            "description": _str(r.get("description"))[:220],
            "url": _safe_url(r.get("url")),
            "lat": _num(r.get("lat")), "lon": _num(r.get("lon")),
            "ago": _ago(r.get("timestamp")),
            "relevance": relevance_score(r),
            "_id": r.get("id", 0), "id": int(_num(r.get("id"))),
        })
    if sort == "severity":
        rows.sort(key=lambda x: (-SEVERITY_ORDER.get(x["severity"], 1), -x["relevance"], -_num(x["_id"])))
    elif sort == "relevance":
        rows.sort(key=lambda x: (-x["relevance"], -_num(x["_id"])))
    else:
        rows.sort(key=lambda x: -_num(x["_id"]))
    return rows[:limit]

def render_feed(df: pd.DataFrame, sort: str = "recent") -> str:
    if sort not in ("recent", "severity", "relevance"):
        sort = "recent"
    return PARTIAL_FEED.render(rows=_feed_rows(df, sort), sort=sort)

def _ticker_html(df: pd.DataFrame) -> str:
    if df.empty:
        return "<span class='ticker-item'>Sin eventos recientes.</span>"
    parts = []
    for _, r in df.head(30).iterrows():
        sev = htmllib.escape(_str(r["severity"]))
        sev_class = f"ticker-sev-{sev}"
        parts.append(
            f"<span class='ticker-item'>"
            f"<span class='{sev_class}'>●</span> "
            f"<b style='color:var(--cyan)'>{htmllib.escape(_str(r['source']))}</b>"
            f" · {htmllib.escape(_str(r['title'])[:80])}"
            f"</span>"
        )
    return "".join(parts) * 2

def _boot_json() -> str:
    data = {
        "palette": {d: m["color"] for d, m in DOMAIN_PALETTE.items()},
        "sevColors": SEV_COLORS,
        "deckUrls": DECK_URLS,
        "i18n": I18N_EN, "i18nRx": I18N_RX_EN,
        "landUrl": LAND_URL,
        "satGroups": [{"k": k, "label": v[0], "c": list(v[2])} for k, v in SAT_GROUPS.items()],
        "satUrls": ["https://cdn.jsdelivr.net/npm/satellite.js@5.0.0/dist/satellite.min.js", "https://unpkg.com/satellite.js@5.0.0/dist/satellite.min.js",
                    "https://cdnjs.cloudflare.com/ajax/libs/satellite.js/4.1.3/satellite.min.js"],
        "cartoKey": CARTO_KEY or "",
        "owmKey": OWM_KEY or "",
    }
    return json.dumps(data).replace("</", "<\\/")


