# ─── ★ NUEVO · SATÉLITES EN ÓRBITA: elementos orbitales públicos de CelesTrak (TLE) → el navegador calcula la posición en vivo (SGP4) ───
SAT_GROUPS = {   # clave: (etiqueta, grupo CelesTrak, color RGB)
    "stations":   ("🛰 Estaciones (ISS, Tiangong)", "stations", (255, 255, 255)),
    "visual":     ("👁 Los 100 más brillantes", "visual", (255, 235, 120)),
    "military":   ("🎖 Militares", "military", (255, 60, 60)),
    "gps":        ("📍 GPS", "gps-ops", (60, 200, 255)),
    "glonass":    ("📍 GLONASS", "glo-ops", (255, 120, 60)),
    "galileo":    ("📍 Galileo", "galileo", (80, 120, 255)),
    "beidou":     ("📍 BeiDou", "beidou", (255, 80, 200)),
    "weather":    ("⛅ Meteorológicos", "weather", (120, 255, 160)),
    "resource":   ("🌍 Observación de la Tierra", "resource", (80, 255, 120)),
    "science":    ("🔬 Científicos", "science", (190, 140, 255)),
    "geo":        ("🛰 Geoestacionarios", "geo", (255, 180, 60)),
    "starlink":   ("📡 Starlink", "starlink", (200, 220, 255)),
    "oneweb":     ("📡 OneWeb", "oneweb", (150, 200, 255)),
    "iridium":    ("📡 Iridium NEXT", "iridium-NEXT", (170, 255, 255)),
    "planet":     ("📷 Planet", "planet", (120, 255, 220)),
    "radar":      ("📡 Radar (SAR)", "radar", (255, 150, 150)),
    "cubesat":    ("▫ CubeSats", "cubesat", (210, 210, 210)),
    "debris":     ("☄ Restos (Cosmos 1408, Fengyun-1C…)", "cosmos-1408-debris", (255, 110, 0)),
    "active":     ("🌐 TODOS los activos (~10 000)", "active", (0, 255, 200)),
}
SAT_TTL = 6 * 3600                 # CelesTrak pide no consultar el mismo grupo más de una vez cada 2 h
_SAT_CACHE: dict = {}              # clave -> (epoch, [[nombre, l1, l2], ...])
_SAT_LOCK = asyncio.Lock()

def _parse_tles(txt: str) -> list[list[str]]:
    ls = [l.rstrip() for l in (txt or "").splitlines() if l.strip()]
    out = []
    i = 0
    while i + 2 < len(ls):
        if ls[i + 1].startswith("1 ") and ls[i + 2].startswith("2 "):
            out.append([ls[i].strip()[:40], ls[i + 1][:69], ls[i + 2][:69]])
            i += 3
        else:
            i += 1
    return out

async def sat_group(key: str) -> list[list[str]]:
    meta = SAT_GROUPS.get(key)
    if not meta:
        raise ValueError("grupo de satélites desconocido")
    now = time.time()
    c = _SAT_CACHE.get(key)
    if c and now - c[0] < SAT_TTL:
        return c[1]
    async with _SAT_LOCK:
        c = _SAT_CACHE.get(key)
        if c and time.time() - c[0] < SAT_TTL:
            return c[1]
        if not c:                                         # tras un reinicio: lo último guardado (aunque esté algo viejo) sirve para pintar ya
            try:
                raw = kv_get("sat_" + key)
                if raw:
                    d = json.loads(raw)
                    c = (float(d["t"]), d["tles"])
                    _SAT_CACHE[key] = c
                    if time.time() - c[0] < SAT_TTL:
                        return c[1]
            except Exception:
                c = None
        err = None
        for host in ("celestrak.org", "celestrak.com"):
            try:
                r = await HTTP.get(f"https://{host}/NORAD/elements/gp.php?GROUP={meta[1]}&FORMAT=tle", timeout=30)
                if r.status_code == 200:
                    tl = _parse_tles(r.text)
                    if tl:
                        _SAT_CACHE[key] = (time.time(), tl)
                        try:
                            kv_set("sat_" + key, json.dumps({"t": time.time(), "tles": tl}))
                        except Exception:
                            pass
                        return tl
                    err = "respuesta sin elementos orbitales (CelesTrak limitó la petición o cambió el grupo)"
                else:
                    err = f"HTTP {r.status_code}"
            except Exception as e:
                err = f"{type(e).__name__}: {str(e) or 'sin respuesta'}"
        if c:
            return c[1]                                   # CelesTrak no responde: se usa lo último guardado
        raise RuntimeError(err or "sin respuesta")

@app.get("/api/sats")
async def api_sats(groups: str = ""):
    keys = [k for k in dict.fromkeys(x.strip() for x in groups.split(",")) if k][:6]
    out, errs = {}, {}
    for k in keys:
        try:
            out[k] = await sat_group(k)
        except Exception as e:
            errs[k] = str(e)[:160]
    return {"groups": out, "errors": errs}

@app.get("/api/map")
async def api_map(hours: int = 6, domain: str = "", group: str = "", severity: str = "", q: str = ""):
    """Datos compactos para deck.gl (máx. NEXUS_MAP_POINTS puntos)."""
    domains, severities = _filters(domain, severity, group)
    df = db_query_events(hours=hours, domains=domains, severities=severities, search=q or None, limit=8000)
    if (not domains or "maritimo" in domains) and not df.empty:
        # los barcos van aparte: cada barrido añade cientos de filas y la prensa (carril rápido cada pocos minutos) los empujaba fuera de las 4000 más recientes
        sh = db_query_events(hours=hours, domains=["maritimo"], severities=severities, search=q or None, limit=3000)
        if not sh.empty:
            df = pd.concat([df[df["domain"] != "maritimo"], sh], ignore_index=True)
    corr_df = db_query_correlations(hours=hours)
    flow_df = None
    if not q:      # los arcos no dependen del límite de puntos: consulta propia solo de ciberataques con flujo
        fd = [d for d in (domains or CYBER_DOMAINS) if d in CYBER_DOMAINS]
        flow_df = db_query_events(hours=hours, domains=fd, severities=severities, search="flow:", limit=3000) if fd else None
    kin_df = None
    if not q:      # arcos de ATAQUES militares (conflicto/geopolítica/explosión con etiqueta flow: y ataque:)
        kd = [d for d in (domains or ["conflicto", "geopolitica", "explosion"]) if d in ("conflicto", "geopolitica", "explosion")]
        kin_df = db_query_events(hours=hours, domains=kd, severities=severities, search="ataque:", limit=1500) if kd else None
    return build_map_payload(df, corr_df.to_dict("records") if not corr_df.empty else [], flow_df=flow_df, kin_df=kin_df)


