def war_sections(df: pd.DataFrame) -> list[dict]:
    def tg(d, s):
        return d["tags"].astype(str).str.contains(s, regex=False) if not d.empty else pd.Series([], dtype=bool)
    if df.empty:
        return []
    alarms = df[tg(df, "alarma:")]
    civil = df[df["domain"] == "alerta_civil"]
    geo = df[df["domain"] == "geopolitica"]
    esc = geo[tg(geo, "guerra:nuclear") | tg(geo, "guerra:escalada") | tg(geo, "guerra:movilizacion")]
    dip = geo.drop(esc.index)
    fight = df[df["domain"].isin(["conflicto", "terrorismo"])]
    sev_rank = {"CRITICA": 0, "ALTA": 1, "MEDIA": 2, "BAJA": 3}
    fight = fight.assign(_r=fight["severity"].map(sev_rank).fillna(3)).sort_values(["_r", "id"], ascending=[True, False]).drop(columns="_r")
    spec = [("alarm", "🚨", "Alarmas", "Alarmas", "CRITICA", alarms, "Lo que pide atención inmediata: ataques masivos, amenaza nuclear, movilización, órdenes de evacuación."),
            ("civil", "🏛", "Avisos de gobiernos a la población", "Avisos civiles", "MEDIA", civil, "Gobiernos y agencias que recomiendan provisiones, refugios o preparación (no implica guerra inminente)."),
            ("esc", "☢", "Escalada, nuclear y movilización", "Escalada", "ALTA", esc, ""),
            ("fight", "💥", "Combates y ataques", "Combates", "ALTA", fight, "Ordenados por gravedad."),
            ("dip", "🕊", "Diplomacia, sanciones y alto el fuego", "Diplomacia", "BAJA", dip, "")]
    return [{"key": k, "icon": ic, "title": t, "short": sh, "chip": ch, "n": int(len(d)),
             "rows": _war_rows_keep_order(d) if k == "fight" else _feed_rows(d, "recent", 25), "hint": h}
            for k, ic, t, sh, ch, d, h in spec]

def _war_rows_keep_order(d: pd.DataFrame, limit: int = 25) -> list[dict]:
    rows = _feed_rows(d.head(limit), "recent", limit)
    order = {int(_num(i)): n for n, i in enumerate(d.head(limit)["id"])}
    rows.sort(key=lambda r: order.get(r["id"], 999))
    return rows

@app.get("/partial/war", response_class=HTMLResponse)
async def partial_war(hours: int = 6, q: str = ""):
    hours = max(1, min(int(hours), 720))
    df = await asyncio.to_thread(db_query_events, hours=hours, domains=DOMAIN_GROUPS["war"], search=q or None, limit=1500)
    secs = await asyncio.to_thread(war_sections, df)     # CPU en hilo: el bucle de eventos no se bloquea
    try:
        countries = [c["name"] for c in await asyncio.to_thread(country_risk, df, 6)] if not df.empty else []
    except Exception:
        countries = []
    try:
        radar = await asyncio.to_thread(war_radar)
    except Exception as ex:
        log.warning(f"[war] radar: {type(ex).__name__}: {ex}")
        radar = None
    try:
        ndf = await asyncio.to_thread(db_query_events, hours=max(hours, 24), domains=["radiacion"], search=q or None, limit=300)
        if not ndf.empty:
            ndf = ndf[ndf["source"].astype(str) != "Safecast"].assign(_r=lambda d: d["severity"].map({"CRITICA": 0, "ALTA": 1, "MEDIA": 2, "BAJA": 3}).fillna(3)).sort_values(["_r", "id"], ascending=[True, False])
        nuc = _feed_rows(ndf.head(25), "recent", 25) if not ndf.empty else []
        order = {int(_num(i)): n for n, i in enumerate(ndf.head(25)["id"])} if not ndf.empty else {}
        nuc.sort(key=lambda r: order.get(r["id"], 999))
    except Exception as ex:
        log.warning(f"[war] radiación: {type(ex).__name__}: {ex}")
        nuc = []
    try:
        sdf = await asyncio.to_thread(db_query_events, hours=max(hours, 24), domains=["conflicto", "geopolitica", "explosion"], search="ataque:", limit=400)
        strikes = _feed_rows(sdf, "recent", 40) if not sdf.empty else []
        tgs = {int(_num(i)): _str(t) for i, t in zip(sdf["id"], sdf["tags"])} if not sdf.empty else {}
        for r in strikes:
            tg = tgs.get(r["id"], "")
            m, f = re.search(r"ataque:(\w+)", tg), _FLOW_RX.search(tg)
            lab = {"explosion": "💥 explosión", "misil": "🚀 misil", "dron": "🛩 dron", "aereo": "✈ aéreo", "naval": "⚓ naval"}.get(m.group(1) if m else "", "🎯 ataque")
            r["description"] = (lab + (f" · {COUNTRY_DB[f.group(1)][0]} → {COUNTRY_DB[f.group(2)][0]}" if f else "") + (" · " + r["description"] if r["description"] else ""))[:260]
    except Exception as ex:
        log.warning(f"[war] ataques: {type(ex).__name__}: {ex}")
        strikes = []
    res: dict = {}
    for g, n, u, w in EXTERNAL_RESOURCES:
        res.setdefault(g, []).append({"name": n, "url": u, "what": w})
    return PARTIAL_WAR.render(sections=secs, total=int(len(df)), hours=hours, countries=countries, radar=radar, nuc=nuc, strikes=strikes, resources=list(res.items()))

# ════════════════════════════════════════════════════════
# ★ NUEVO · pestañas ⚖ COMPARAR (periodo actual vs anterior) y 🕒 LÍNEA DE TIEMPO (grupo / país / palabra)
# ════════════════════════════════════════════════════════
def _delta_rows(cur: Counter, prev: Counter, top: int = 12) -> list[dict]:
    keys = set(cur) | set(prev)
    rows = []
    for k in keys:
        a, b = int(cur.get(k, 0)), int(prev.get(k, 0))
        pct = round(100.0 * (a - b) / b) if b else (100 if a else 0)
        rows.append({"k": k, "now": a, "before": b, "diff": a - b, "pct": pct, "new": b == 0 and a > 0, "gone": a == 0 and b > 0})
    rows.sort(key=lambda r: (-(r["now"] + r["before"]), r["k"]))
    return rows[:top]

def compare_periods(hours: int, domains, severities, q: str) -> dict:
    hours = max(1, min(int(hours), 168))
    df = db_query_events(hours=hours * 2, domains=domains, severities=severities, search=q or None, limit=60000)
    out = {"hours": hours, "n_now": 0, "n_before": 0, "domains": [], "severities": [], "sources": [], "groups": [], "alarms": (0, 0), "new_sources": [], "gone_sources": [], "capped": False}
    if df is None or df.empty:
        return out
    out["capped"] = len(df) >= 60000
    ts = _dt(df["timestamp"])
    cut = pd.Timestamp.now(tz="UTC") - pd.Timedelta(hours=hours)
    cur, prev = df[ts >= cut], df[ts < cut]
    out["n_now"], out["n_before"] = int(len(cur)), int(len(prev))
    def cnt(frame, col):
        return Counter(_str(x) for x in frame[col].tolist() if _str(x))
    def grp(frame):
        c = Counter()
        for t in frame["tags"].tolist():
            for m in re.findall(r"grupo:([^,]+)", _str(t)):
                c[m.strip()] += 1
        return c
    out["domains"] = _delta_rows(cnt(cur, "domain"), cnt(prev, "domain"), 14)
    sv = _delta_rows(cnt(cur, "severity"), cnt(prev, "severity"), 4)
    out["severities"] = sorted(sv, key=lambda r: ["CRITICA", "ALTA", "MEDIA", "BAJA"].index(r["k"]) if r["k"] in ("CRITICA", "ALTA", "MEDIA", "BAJA") else 9)
    sc, sp = cnt(cur, "source"), cnt(prev, "source")
    out["sources"] = _delta_rows(sc, sp, 12)
    out["new_sources"] = sorted([k for k in sc if k not in sp], key=lambda k: -sc[k])[:8]
    out["gone_sources"] = sorted([k for k in sp if k not in sc], key=lambda k: -sp[k])[:8]
    out["groups"] = _delta_rows(grp(cur), grp(prev), 10)
    al = lambda fr: int(sum(1 for t in fr["tags"].tolist() if "alarma:" in _str(t)))
    out["alarms"] = (al(cur), al(prev))
    return out

def timeline_data(days: int, domains, severities, q: str) -> dict:
    days = max(1, min(int(days), 90))
    df = db_query_events(hours=days * 24, domains=domains, severities=severities, search=q or None, limit=2500)
    res = {"days": days, "q": q, "n": 0, "perday": [], "groups": [], "byday": [], "capped": False}
    if df is not None and not df.empty:
        res["capped"] = len(df) >= 2500
        df = df.assign(_ts=_dt(df["timestamp"])).dropna(subset=["_ts"]).sort_values("_ts", ascending=False)
        res["n"] = int(len(df))
        today = pd.Timestamp.now(tz="UTC").normalize()
        per = Counter(d.strftime("%Y-%m-%d") for d in df["_ts"])
        res["perday"] = [{"d": (today - pd.Timedelta(days=i)).strftime("%m-%d"), "n": per.get((today - pd.Timedelta(days=i)).strftime("%Y-%m-%d"), 0)} for i in range(min(days, 30) - 1, -1, -1)]
        mx = max([p["n"] for p in res["perday"]] + [1])
        for p in res["perday"]:
            p["pct"] = max(3, int(100 * p["n"] / mx)) if p["n"] else 0
        byday: dict = {}
        for r in df.head(600).to_dict("records"):
            day = r["_ts"].strftime("%Y-%m-%d")
            byday.setdefault(day, []).append({"hm": r["_ts"].strftime("%H:%M"), "severity": _str(r.get("severity")) or "MEDIA", "source": _str(r.get("source")),
                "domain": _str(r.get("domain")), "color": _domain_color(_str(r.get("domain"))), "title": _str(r.get("title"))[:190] or "(sin título)",
                "url": _safe_url(r.get("url")), "lat": _num(r.get("lat")), "lon": _num(r.get("lon")), "id": int(_num(r.get("id")))})
        res["byday"] = [{"day": d, "rows": rows} for d, rows in byday.items()]
    gdf = db_query_events(hours=max(72, days * 24), search="grupo:", limit=4000)
    if gdf is not None and not gdf.empty:
        c = Counter(m.strip() for t in gdf["tags"].tolist() for m in re.findall(r"grupo:([^,]+)", _str(t)))
        res["groups"] = [k for k, _ in c.most_common(10)]
    return res

