@app.get("/partial/compare", response_class=HTMLResponse)
async def partial_compare(hours: int = 24, domain: str = "", group: str = "", severity: str = "", q: str = ""):
    domains, severities = _filters(domain, severity, group)
    c = await asyncio.to_thread(compare_periods, hours, domains, severities, q)
    return PARTIAL_COMPARE.render(c=c)

@app.get("/partial/timeline", response_class=HTMLResponse)
async def partial_timeline(days: int = 3, domain: str = "", group: str = "", severity: str = "", q: str = ""):
    domains, severities = _filters(domain, severity, group)
    t = await asyncio.to_thread(timeline_data, days, domains, severities, q)
    return PARTIAL_TIMELINE.render(t=t)

# ════════════════════════════════════════════════════════
# ★ NUEVO · INFORME DE SITUACIÓN exportable (HTML imprimible / Markdown)
# ════════════════════════════════════════════════════════
def report_delta(hours: int, war_level, touch: bool = True) -> Optional[dict]:
    """«Qué cambió desde tu última visita»: compara con la visita anterior al informe (se guarda en la base; una visita nueva cuenta si pasaron >30 min de la última)."""
    now = datetime.now(timezone.utc)
    try:
        seen = json.loads(kv_get("report_seen") or "{}")
    except Exception:
        seen = {}
    cur = seen.get("cur")
    try:
        cur_dt = datetime.fromisoformat(cur) if cur else None
    except Exception:
        cur_dt = None
    if cur_dt is None:
        seen = {"cur": now.isoformat(), "war": war_level}
    elif (now - cur_dt).total_seconds() > 1800:
        seen = {"cur": now.isoformat(), "war": war_level, "prev": cur, "prev_war": seen.get("war")}
    if touch:
        try:
            kv_set("report_seen", json.dumps(seen))
        except Exception:
            pass
    prev = seen.get("prev")
    if not prev:
        return None
    try:
        prev_dt = datetime.fromisoformat(prev)
    except Exception:
        return None
    back_h = max(1, min(720, int((now - prev_dt).total_seconds() // 3600) + 2))
    df = db_query_events(hours=back_h, limit=6000)
    out = {"since": prev_dt.strftime("%Y-%m-%d %H:%M UTC"), "ago_h": round((now - prev_dt).total_seconds() / 3600, 1), "n": 0, "sev": {}, "alarms": {}, "terror": 0,
           "services": [], "war": ({"prev": seen.get("prev_war"), "now": war_level} if seen.get("prev_war") not in (None, war_level) and war_level is not None else None), "top": []}
    if df is None or df.empty:
        return out
    ts = _dt(df["timestamp"])
    d = df[ts > pd.Timestamp(prev_dt)]
    out["n"] = int(len(d))
    out["sev"] = {k: int(v) for k, v in d["severity"].value_counts().items() if k in ("CRITICA", "ALTA")}
    tags = d["tags"].fillna("").astype(str)
    for t in tags:
        k = alarm_kind(t)
        if k:
            out["alarms"][k] = out["alarms"].get(k, 0) + 1
    out["terror"] = int(((d["domain"] == "terrorismo") & d["severity"].isin(["CRITICA", "ALTA"])).sum())
    provs = []
    for t, tg in zip(d["title"].fillna("").astype(str), tags):
        if ",caida" in "," + tg or tg.startswith("caida"):
            m = re.match(r"Caída de servicio · ([^:(]+)", t)
            if m and m.group(1).strip() not in provs:
                provs.append(m.group(1).strip())
    out["services"] = provs[:10]
    imp = d[d["severity"].isin(["CRITICA"]) | (tags.str.contains("alarma:"))].head(40)
    out["top"] = [{"sev": r["sev"], "t": r["t"][:140], "src": r["src"], "n": r["n"]} for r in group_items(
        [{"sev": _str(r.get("severity")), "t": _str(r.get("title")), "la": _num(r.get("lat")), "lo": _num(r.get("lon")), "src": _str(r.get("source"))} for r in imp.to_dict("records")])[:6]]
    return out

def report_services(hours: int) -> list[dict]:
    """Caídas de servicios (Microsoft, AWS, Cloudflare…) vistas en la ventana, agrupadas por proveedor."""
    df = db_query_events(hours=hours, domains=["internet"], search="caida", limit=600)
    if df is None or df.empty:
        return []
    by: dict = {}
    for r in df.to_dict("records"):
        tg = _str(r.get("tags"))
        if "caida" not in tg:
            continue
        m = re.match(r"Caída de servicio · ([^:(]+)", _str(r.get("title")))
        prov = m.group(1).strip() if m else "Otros"
        g = by.setdefault(prov, {"prov": prov, "n": 0, "sev": "BAJA", "srcs": [], "t": "", "u": "", "ts": "", "cf": ""})
        g["n"] += 1
        if SEVERITY_ORDER.get(_str(r.get("severity")), 0) > SEVERITY_ORDER.get(g["sev"], 0):
            g["sev"] = _str(r.get("severity"))
        sname = _str(r.get("source"))
        if sname not in g["srcs"]:
            g["srcs"].append(sname)
        if not g["ts"] or _str(r.get("timestamp")) > g["ts"]:
            g["ts"], g["t"], g["u"] = _str(r.get("timestamp")), _str(r.get("title"))[:150], _safe_url(r.get("url"))
        c = event_conf(tg, sname)
        if c in ("of", "es") or not g["cf"]:
            g["cf"] = c or g["cf"]
    out = sorted(by.values(), key=lambda g: (-SEVERITY_ORDER.get(g["sev"], 0), -g["n"]))
    for g in out:
        g["ts"] = g["ts"][:16].replace("T", " ")
        g["srcs"] = g["srcs"][:4]
    return out[:20]

def build_report(hours: int = 24, touch: bool = True) -> dict:
    hours = max(1, min(int(hours), 720))
    now = datetime.now(timezone.utc)
    r: dict = {"hours": hours, "generated": now.strftime("%Y-%m-%d %H:%M UTC")}
    sev = _group_count("severity", hours, None, None, None)
    dom = _group_count("domain", hours, None, None, None)
    r["total"] = int(sum(sev.values()))
    r["by_severity"] = [(k, sev.get(k, 0)) for k in ("CRITICA", "ALTA", "MEDIA", "BAJA") if sev.get(k)]
    r["by_domain"] = sorted(dom.items(), key=lambda kv: -kv[1])[:14]
    try:
        r["war"] = war_radar()
    except Exception:
        r["war"] = None
    try:
        r["alarms"] = db_alarms(hours=min(hours, 72), limit=25)
    except Exception:
        r["alarms"] = {"n": 0, "items": [], "kinds": {}}
    df = db_query_events(hours=hours, severities=["CRITICA", "ALTA"], limit=3000)
    top = []
    if df is not None and not df.empty:
        df = df.assign(_r=df["severity"].map({"CRITICA": 0, "ALTA": 1}).fillna(2))
        df = df.sort_values(["_r", "relevance"], ascending=[True, False]) if "relevance" in df.columns else df.sort_values("_r")
        for x in df.head(400).to_dict("records"):
            top.append({"sev": _str(x.get("severity")), "dom": _str(x.get("domain")), "src": _str(x.get("source")), "t": _str(x.get("title"))[:170],
                        "u": _safe_url(x.get("url")), "ts": _str(x.get("timestamp"))[:16].replace("T", " "), "lat": _num(x.get("lat")), "lon": _num(x.get("lon")),
                        "cf": event_conf(_str(x.get("tags")), _str(x.get("source")))})
    grp = group_items(top, lat="lat", lon="lon")                 # antes se cortaba en 20: ahora 60 destacados + hasta 200 en el anexo
    r["top"], r["more"], r["top_total"] = grp[:60], grp[60:260], len(grp)
    cd = db_query_correlations(hours=hours, limit=25)
    r["corr"] = [{"score": int(_num(x.get("score"))), "desc": _str(x.get("description"))[:260]} for x in cd.to_dict("records")] if cd is not None and not cd.empty else []
    try:
        r["anoms"] = enrich_anomalies(max(hours, 24), 40)          # agrupadas y con su fuente y sus eventos
    except Exception as e:                                         # el informe sale igual, solo sin el detalle de las anomalías
        log.warning(f"[INFORME] anomalías enriquecidas: {type(e).__name__}: {e}")
        r["anoms"] = []
    r["anom"] = [a["desc"] for a in r["anoms"][:5]]                # compatibilidad con lo que ya lo leía
    try:
        d = ddos_dossier(days=max(1, min(30, hours // 24 or 1)))
        r["ddos"] = d if d.get("n") else None
    except Exception:
        r["ddos"] = None
    try:
        r["services"] = report_services(hours)
    except Exception:
        r["services"] = []
    try:
        r["delta"] = report_delta(hours, (r.get("war") or {}).get("level"), touch)
    except Exception:
        r["delta"] = None
    nd = db_query_events(hours=hours, domains=["radiacion", "explosion"], limit=300)
    cited = []
    for lst in ([i.get("srcs") or [i.get("src")] for i in (r["alarms"].get("items") or [])] + [i.get("srcs") or [i.get("src")] for i in r["top"]]
                + [g.get("srcs") or [] for g in r.get("services") or []]):
        for sname in lst:
            if sname and sname not in cited:
                cited.append(sname)
    r["cited"] = cited[:40]
    r["nuc"] = [{"sev": _str(x.get("severity")), "src": _str(x.get("source")), "t": _str(x.get("title"))[:150], "ts": _str(x.get("timestamp"))[:16].replace("T", " ")}
                for x in (nd.sort_values("severity").head(8).to_dict("records") if nd is not None and not nd.empty else [])
                if _str(x.get("source")) != "Safecast"]
    for key, fn, empty in (("sources", lambda: report_sources(hours, r["total"]), []), ("domains", lambda: report_domains(hours, list(r["by_domain"])), []),
                           ("series", lambda: report_series(hours), None), ("health", report_health, {})):
        try:
            r[key] = fn()
        except Exception as e:
            log.warning(f"[INFORME] sección «{key}»: {type(e).__name__}: {e}")
            r[key] = empty
    return r

# ─── ★ NUEVO · INFORME «RECOPILADO»: cada anomalía con su fuente y sus eventos, fuentes, dominios, serie temporal y anexo ───
# La tabla `anomalies` solo guarda (hora, dominio, métrica, valor, z, frase): no sabe qué fuente ni qué eventos la provocaron, y cada barrido
# vuelve a insertar la misma. Aquí se AGRUPAN las repetidas y se buscan, en la base de eventos y en la ventana de cada anomalía, sus causas.
ANOM_KIND_ES = {"event_count": "Pico de actividad", "new_entity": "Entidad nueva", "critica_burst": "Ráfaga de CRÍTICOS",
                "neg_sentiment_burst": "Ráfaga de sentimiento negativo"}
_SEV_RANK = {"CRITICA": 0, "ALTA": 1, "MEDIA": 2, "BAJA": 3}
_ANOM_CACHE: dict = {}

def _ok_ts(v) -> bool:
    try:
        return v is not None and not pd.isna(v)
    except (TypeError, ValueError):
        return False

def _ts16(v) -> str:
    if not _ok_ts(v):
        return ""
    if isinstance(v, (int, float)):
        return datetime.fromtimestamp(float(v), timezone.utc).strftime("%Y-%m-%d %H:%M")
    return _str(v)[:16].replace("T", " ")

def _like(s: str) -> str:
    return s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")

def _ev_brief(x: dict) -> dict:
    return {"sev": _str(x.get("severity")), "dom": _str(x.get("domain")), "src": _str(x.get("source")), "t": _str(x.get("title"))[:170] or "(sin título)",
            "u": _safe_url(x.get("url")), "ts": _ts16(x.get("timestamp")), "id": int(_num(x.get("id")))}

def _ev_rank(df: pd.DataFrame) -> pd.DataFrame:
    """Críticos primero y, dentro de cada nivel, lo más reciente."""
    if df is None or df.empty:
        return df
    d = df.assign(_r=df["severity"].map(_SEV_RANK).fillna(4))
    return d.sort_values(["_r", "id"], ascending=[True, False]) if "id" in d.columns else d.sort_values("_r")

def _events_window(t0: str, t1: str, domain: Optional[str] = None, severity: Optional[str] = None,
                   entity: Optional[str] = None, neg: bool = False, limit: int = 400) -> pd.DataFrame:
    """Eventos entre dos instantes (ISO, como se guardan). Consulta con índice por fecha: barata aunque la base sea grande."""
    q, p = "SELECT * FROM events WHERE timestamp >= ? AND timestamp <= ?", [t0, t1]
    if domain:
        q += " AND domain = ?"; p.append(domain)
    if severity:
        q += " AND severity = ?"; p.append(severity)
    if entity:
        q += " AND entities LIKE ? ESCAPE '\\'"; p.append(f"%{_like(entity)}%")
    if neg:
        q += " AND sentiment < -8"
    q += " ORDER BY id DESC LIMIT ?"; p.append(int(limit))
    conn = db_conn()
    try:
        df = pd.read_sql(q, conn, params=p)
    finally:
        conn.close()
    return apply_mutes(df)

def _anom_detail(g: dict) -> dict:
    pk, m, dom = g["peak"], g["metric"], g["dom"]
    t = pk.get("_ts")
    rel = pd.DataFrame()
    if _ok_ts(t):
        iso = lambda dt: dt.isoformat()
        H = pd.Timedelta
        try:
            if m == "new_entity":
                ent = _str(pk.get("description")).split(":", 1)[-1].strip()
                if ent:
                    rel = _events_window(iso(t - H(hours=3)), iso(t + H(hours=1)), entity=ent)
            elif m == "critica_burst":
                rel = _events_window(iso(t - H(hours=2)), iso(t + H(minutes=30)), severity="CRITICA")
            elif m == "neg_sentiment_burst":
                rel = _events_window(iso(t - H(hours=1, minutes=30)), iso(t + H(minutes=30)), neg=True)
            else:
                rel = _events_window(iso(t - H(hours=2)), iso(t + H(minutes=30)), domain=dom if dom and dom not in ("global", "cross-domain") else None)
        except Exception as e:                                   # una anomalía sin detalle es mejor que un informe roto
            log.warning(f"[INFORME] sin detalle para la anomalía {m}/{dom}: {type(e).__name__}: {e}")
            rel = pd.DataFrame()
    has = rel is not None and not rel.empty
    sev = {k: int((rel["severity"] == k).sum()) for k in ("CRITICA", "ALTA")} if has else {}
    return {"kind": m, "kind_es": ANOM_KIND_ES.get(m, m), "dom": dom, "z": round(g["z"], 1), "n": g["n"], "value": round(_num(pk.get("value")), 1),
            "desc": _str(pk.get("description"))[:240], "first": _ts16(g["first"]), "last": _ts16(g["last"]), "peak": _ts16(t),
            "rel": int(len(rel)) if has else 0,
            "srcs": [{"src": k, "n": int(v)} for k, v in rel["source"].value_counts().head(6).items()] if has else [],
            "ev": [_ev_brief(x) for x in _ev_rank(rel).head(8).to_dict("records")] if has else [],
            "sev": sev, "top_sev": "CRITICA" if sev.get("CRITICA") else "ALTA" if sev.get("ALTA") else ""}

def enrich_anomalies(hours: int = 24, limit: int = 40) -> list[dict]:
    """Anomalías AGRUPADAS (cada barrido repite la misma) y con sus causas: qué fuentes y qué eventos. Caché de 45 s."""
    hours = max(24, min(int(hours), 720))
    ck = (hours, int(limit))
    hit = _ANOM_CACHE.get(ck)
    if hit and time.time() - hit[0] < 45:
        return hit[1]
    out: list[dict] = []
    an = db_query_anomalies(hours=hours, limit=1500)
    if an is not None and not an.empty:
        an = an.assign(_ts=_dt(an["timestamp"]))
        groups: dict = {}
        for x in an.to_dict("records"):
            m, dom = _str(x.get("metric")) or "event_count", _str(x.get("domain"))
            key = (m, dom, _str(x.get("description")) if m == "new_entity" else "")
            z, ts = _num(x.get("zscore")), x.get("_ts")
            g = groups.get(key)
            if g is None:
                g = groups[key] = {"metric": m, "dom": dom, "n": 0, "z": z, "peak": x, "first": ts, "last": ts}
            g["n"] += 1
            if z > g["z"]:
                g["z"], g["peak"] = z, x
            if _ok_ts(ts):
                if not _ok_ts(g["first"]) or ts < g["first"]:
                    g["first"] = ts
                if not _ok_ts(g["last"]) or ts > g["last"]:
                    g["last"] = ts
        for g in sorted(groups.values(), key=lambda g: (-g["z"], -g["n"]))[:int(limit)]:
            out.append(_anom_detail(g))
    if len(_ANOM_CACHE) > 12:
        _ANOM_CACHE.clear()
    _ANOM_CACHE[ck] = (time.time(), out)
    return out

def report_sources(hours: int, total: int, top: int = 15) -> list[dict]:
    """Fuentes más activas (recuento exacto en SQL) con su mezcla de críticos/altos y su último evento."""
    cnt = _group_count("source", hours, None, None, None)
    rows = sorted(cnt.items(), key=lambda kv: -kv[1])[:top]
    since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()
    info: dict = {}
    conn = db_conn()
    try:
        for s_, sv_, n_, mx_ in conn.execute(
                "SELECT source, severity, COUNT(*), MAX(timestamp) FROM events WHERE timestamp > ? GROUP BY source, severity", (since,)).fetchall():
            d = info.setdefault(s_, {"CRITICA": 0, "ALTA": 0, "last": ""})
            if sv_ in ("CRITICA", "ALTA"):
                d[sv_] = int(n_)
            if mx_ and mx_ > d["last"]:
                d["last"] = mx_
    finally:
        conn.close()
    mx = rows[0][1] if rows else 1
    return [{"src": k, "n": int(v), "pct": round(100 * v / max(total, 1), 1), "w": max(2, int(100 * v / max(mx, 1))),
             "crit": info.get(k, {}).get("CRITICA", 0), "alta": info.get(k, {}).get("ALTA", 0), "last": _ts16(info.get(k, {}).get("last"))}
            for k, v in rows]

def report_domains(hours: int, counts: list, topn: int = 8, per: int = 8) -> list[dict]:
    """Por cada dominio grande: recuento exacto, fuentes que más aportan y sus eventos más graves/recientes."""
    out = []
    for dom, n in counts[:topn]:
        sev = _group_count("severity", hours, [dom], None, None)
        df = db_query_events(hours=hours, domains=[dom], limit=800)
        if df is None or df.empty:
            continue
        out.append({"dom": dom, "n": int(n), "crit": int(sev.get("CRITICA", 0)), "alta": int(sev.get("ALTA", 0)),
                    "srcs": [{"src": k, "n": int(v)} for k, v in df["source"].value_counts().head(4).items()],
                    "ev": [_ev_brief(x) for x in _ev_rank(df).head(per).to_dict("records")]})
    return out

def report_series(hours: int) -> Optional[dict]:
    """Eventos por hora (o por día en ventanas largas): todos y solo críticos/altos, para ver CUÁNDO pasó cada cosa."""
    hourly = hours <= 72
    nb = hours if hourly else max(2, hours // 24)
    step = timedelta(hours=1) if hourly else timedelta(days=1)
    now = datetime.now(timezone.utc)
    keys = [((now - step * i).strftime("%Y-%m-%dT%H") if hourly else (now - step * i).strftime("%Y-%m-%d")) for i in range(nb - 1, -1, -1)]
    width = 13 if hourly else 10
    since = (now - step * nb).isoformat()
    allc, hic = {}, {}
    conn = db_conn()
    try:
        for b, hi, n in conn.execute(f"SELECT substr(timestamp,1,{width}) AS b, (severity IN ('CRITICA','ALTA')) AS hi, COUNT(*) FROM events "
                                     "WHERE timestamp > ? GROUP BY b, hi", (since,)).fetchall():
            allc[b] = allc.get(b, 0) + n
            if hi:
                hic[b] = hic.get(b, 0) + n
    finally:
        conn.close()
    va, vh = [allc.get(k, 0) for k in keys], [hic.get(k, 0) for k in keys]
    if not any(va):
        return None
    mx = max(va)
    def pts(v):
        return " ".join(f"{(i * 100 / max(1, len(v) - 1)):.1f},{(28 - 26 * x / max(mx, 1)):.1f}" for i, x in enumerate(v))
    pk = va.index(mx)
    return {"all": pts(va), "hi": pts(vh), "max": mx, "unit": "hora" if hourly else "día", "n": len(va),
            "start": keys[0].replace("T", " ") + (":00" if hourly else ""), "end": keys[-1].replace("T", " ") + (":00" if hourly else ""),
            "at": keys[pk].replace("T", " ") + (":00" if hourly else "")}

def report_health() -> dict:
    """Fuentes con problemas: son puntos ciegos (no aportan eventos a este informe)."""
    bad = []
    for name, h in list(SOURCE_HEALTH.items()):
        ok, fail = int(h.get("ok") or 0), int(h.get("fail") or 0)
        if fail and (name in CIRCUIT_OPEN or fail / max(1, ok + fail) >= 0.2):
            bad.append({"src": name, "ok": ok, "fail": fail, "open": name in CIRCUIT_OPEN, "last_fail": _ts16(h.get("last_fail"))})
    bad.sort(key=lambda b: (not b["open"], -b["fail"]))
    return {"total": len(SOURCE_HEALTH), "bad": bad[:12]}

def _md_anoms(r: dict) -> list[str]:
    an = r.get("anoms") or []
    if not an:
        return (["## Anomalías", ""] + [f"- {x}" for x in r.get("anom") or []] + [""]) if r.get("anom") else []
    o = [f"## Anomalías ({len(an)}, agrupadas)", ""]
    for a in an:
        o.append(f"- **z={a['z']}** · {a['kind_es']} · {a['dom']} — {a['desc']}" + (f" _(×{a['n']}, {a['first']} → {a['last']})_" if a["n"] > 1 else ""))
        if a["srcs"]:
            o.append("  - Fuentes: " + ", ".join(f"{s['src']} ({s['n']})" for s in a["srcs"]) + f" · {a['rel']} eventos")
        for e in a["ev"][:5]:
            o.append(f"  - {e['sev']} · {e['t']} — {e['src']}, {e['ts']} UTC" + (f" ({e['u']})" if e["u"] else ""))
    return o + [""]

def _md_extra(r: dict) -> list[str]:
    o: list[str] = []
    sr = r.get("series")
    if sr:
        o += [f"_Pico de actividad: {sr['max']} eventos por {sr['unit']} el {sr['at']} UTC._", ""]
    if r.get("sources"):
        o += ["## Fuentes más activas", "", "| Fuente | Eventos | % | Críticos | Altos | Último |", "|---|---:|---:|---:|---:|---|"]
        o += [f"| {s['src']} | {s['n']} | {s['pct']}% | {s['crit']} | {s['alta']} | {s['last']} |" for s in r["sources"]] + [""]
    if r.get("domains"):
        o += ["## Recopilado por dominio", ""]
        for d in r["domains"]:
            o.append(f"### {d['dom']} — {d['n']} eventos ({d['crit']} críticos, {d['alta']} altos) · " + ", ".join(f"{s['src']} ({s['n']})" for s in d["srcs"]))
            o += [f"- {e['sev']} · {e['t']} — {e['src']}, {e['ts']} UTC" + (f" ({e['u']})" if e["u"] else "") for e in d["ev"]] + [""]
    h = r.get("health") or {}
    if h.get("bad"):
        o += [f"## Salud de fuentes ({len(h['bad'])} con problemas, de {h['total']})", ""]
        o += [f"- {b['src']}: {b['ok']} ok · {b['fail']} fallos" + (" · circuito abierto" if b["open"] else "") + (f" · último fallo {b['last_fail']}" if b["last_fail"] else "")
              for b in h["bad"]] + [""]
    if r.get("more"):
        o += [f"## Anexo: más críticos y altos ({len(r['more'])})", ""]
        o += [f"- {t['sev']} · {t['dom']} · {t['t']} — {t['src']}" + (f" +{t['n'] - 1} fuentes" if t["n"] > 1 else "") + f", {t['ts']} UTC" + (f" ({t['u']})" if t["u"] else "")
              for t in r["more"]] + [""]
    return o

def report_markdown(r: dict) -> str:
    o = [f"# Informe de situación NEXUS", f"_Generado {r['generated']} · ventana de {r['hours']} h · {r['total']} eventos_", ""]
    w = r.get("war")
    if w:
        o += [f"## Nivel de tensión (WAR): {w['level']}/5 · {w['label']}", ""] + [f"- {x}" for x in (w.get("digest") or w.get("reasons") or [])[:8]] + [""]
    dl = r.get("delta")
    if dl:
        o += [f"## 🔄 Qué cambió desde tu última visita ({dl['since']}, hace {dl['ago_h']} h)", "", f"- {dl['n']} eventos nuevos" + "".join(f" · {k} {v}" for k, v in dl["sev"].items())]
        if dl["alarms"]:
            o += ["- Alarmas nuevas: " + ", ".join(f"{k} {v}" for k, v in dl["alarms"].items())]
        if dl["terror"]:
            o += [f"- Terrorismo (ALTA/CRÍTICA): {dl['terror']}"]
        if dl["services"]:
            o += ["- Caídas de servicios: " + ", ".join(dl["services"])]
        if dl["war"]:
            o += [f"- Nivel WAR: {dl['war']['prev']} → {dl['war']['now']}/5"]
        o += [""]
    a = r["alarms"]
    o += [f"## 🚨 Alarmas ({a['n']})", ""] + ([f"- [{i['k']}] {i['t']} — {i['src']}, {i['ts']} UTC" for i in a["items"][:20]] or ["- Sin alarmas en la ventana."]) + [""]
    if r.get("services"):
        o += [f"## 🔌 Caídas de servicios ({len(r['services'])} proveedores)", ""] + [f"- **{g['sev']}** · {g['prov']} — {g['t']} ({g['n']} aviso(s), {', '.join(g['srcs'])}, {g['ts']} UTC)" for g in r["services"]] + [""]
    o += ["## Eventos por severidad", ""] + [f"- {k}: {v}" for k, v in r["by_severity"]] + ["", "## Eventos por dominio", ""] + [f"- {k}: {v}" for k, v in r["by_domain"]] + [""]
    o += ["## Eventos críticos y altos destacados", ""] + [f"- **{t['sev']}** · {t['dom']} · {t['t']} — {t['src']}, {t['ts']} UTC" + (f" ({t['u']})" if t["u"] else "") + (f" · +{t['n'] - 1} fuentes" if t.get("n", 1) > 1 else "") for t in r["top"]] + [""]
    if r.get("cited"):
        o += ["## Fuentes citadas", "", ", ".join(r["cited"]), ""]
    o += ["## Correlaciones principales", ""] + ([f"- ({c['score']}) {c['desc']}" for c in r["corr"]] or ["- Ninguna."]) + [""]
    o += _md_anoms(r)
    d = r.get("ddos")
    if d:
        o += [f"## DDoS ({d['n']} eventos)", "", "- Grupos: " + ", ".join(f"{g['k']} ({g['n']})" for g in d["groups"][:6]),
              "- Vectores: " + ", ".join(f"{g['k']} ({g['n']})" for g in d["vectors"][:6]), "- Objetivos: " + ", ".join(f"{g['k']} ({g['n']})" for g in d["targets"][:6]), ""]
    if r["nuc"]:
        o += ["## Radiación y explosiones", ""] + [f"- {n['sev']} · {n['t']} — {n['src']}, {n['ts']} UTC" for n in r["nuc"]] + [""]
    o += _md_extra(r)
    o += ["---", "_Informe automático con datos abiertos. Los niveles y correlaciones son heurísticos: sirven para saber dónde mirar, no son una prueba._"]
    return "\n".join(o)

REPORT_TPL = Template(r"""<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Informe de situación NEXUS</title>
<style>
:root{--bg:#fff;--fg:#1a1d24;--dim:#5b6472;--line:#d9dde4;--acc:#0b5cad;--crit:#b00020;--alta:#c25b00;--med:#8a6d00}
@media (prefers-color-scheme: dark){:root{--bg:#10131a;--fg:#e6e9ef;--dim:#9aa4b5;--line:#2a3140;--acc:#6db3ff;--crit:#ff6b81;--alta:#ffa24d;--med:#e6c200}}
@media print{:root{--bg:#fff;--fg:#000;--dim:#444;--line:#bbb;--acc:#003d7a}.noprint{display:none}body{font-size:11px;max-width:none;padding:0}h2{break-after:avoid}tr{break-inside:avoid}@page{margin:12mm}}
body{background:var(--bg);color:var(--fg);font:14px/1.5 system-ui,Segoe UI,Roboto,sans-serif;max-width:900px;margin:0 auto;padding:16px}
h1{font-size:1.6em;margin:.2em 0}h2{font-size:1.1em;margin:1.4em 0 .4em;border-bottom:1px solid var(--line);padding-bottom:3px}
.meta{color:var(--dim)}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid var(--line);padding:4px 6px;text-align:left;vertical-align:top;font-size:.92em}
.CRITICA{color:var(--crit);font-weight:700}.ALTA{color:var(--alta);font-weight:600}.MEDIA{color:var(--med)}.pill{display:inline-block;border:1px solid var(--line);border-radius:10px;padding:0 8px;margin:2px 4px 2px 0}
a{color:var(--acc)}.bar{display:flex;gap:8px;margin:8px 0}.btn{border:1px solid var(--line);background:none;color:var(--fg);padding:4px 10px;border-radius:6px;cursor:pointer;text-decoration:none}
.lvl{font-size:1.2em;font-weight:700}
details.an,details.dm,details.anx{border:1px solid var(--line);border-radius:8px;margin:6px 0;padding:0}
details>summary{cursor:pointer;padding:6px 10px}details[open]>summary{border-bottom:1px solid var(--line)}
.anb{padding:6px 10px}.anb table{margin-top:6px}.z{display:inline-block;background:var(--alta);color:#fff;border-radius:6px;padding:0 6px;font-weight:700;font-size:.85em}
.flt{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:6px 0}.flt input,.flt select{background:var(--bg);color:var(--fg);border:1px solid var(--line);border-radius:6px;padding:4px 8px}
.flt input{flex:1;min-width:180px}.btn.on{background:var(--acc);color:#fff}
.num{text-align:right;font-variant-numeric:tabular-nums}.barc{width:28%}.bar2{height:8px;background:var(--acc);border-radius:4px}
.spk svg{width:100%;height:60px;display:block}.spk polyline{fill:none;vector-effect:non-scaling-stroke}.spk .s1{stroke:var(--dim);stroke-width:1.5}.spk .s2{stroke:var(--crit);stroke-width:1.6}
[hidden]{display:none!important}
</style></head><body>
<div class="bar noprint"><a class="btn" href="#" onclick="window.print();return false">🖨 Imprimir / guardar PDF</a><a class="btn" href="/api/report?hours={{ r.hours }}&fmt=md&download=1">⬇ Markdown</a><a class="btn" href="/api/report?hours={{ r.hours }}&download=1&peek=1">⬇ HTML de una página</a>
{% for h in (6, 24, 72, 168) %}<a class="btn" href="/api/report?hours={{ h }}">{{ h }} h</a>{% endfor %}</div>
<h1>Informe de situación NEXUS</h1>
<div class="meta">Generado {{ r.generated }} · ventana de {{ r.hours }} h · {{ r.total }} eventos</div>
{% if r.delta %}<h2>🔄 Qué cambió desde tu última visita <span class="meta">({{ r.delta.since }} · hace {{ r.delta.ago_h }} h)</span></h2>
<ul><li><b>{{ r.delta.n }}</b> eventos nuevos{% for k, v in r.delta.sev.items() %} · <b class="{{ k }}">{{ k }}</b> {{ v }}{% endfor %}</li>
{% if r.delta.alarms %}<li>🚨 Alarmas nuevas: {% for k, v in r.delta.alarms.items() %}<span class="pill">{{ k }} <b>{{ v }}</b></span>{% endfor %}</li>{% endif %}
{% if r.delta.terror %}<li>Terrorismo (ALTA/CRÍTICA): <b>{{ r.delta.terror }}</b></li>{% endif %}
{% if r.delta.services %}<li>Caídas de servicios: {{ r.delta.services|join(", ") }}</li>{% endif %}
{% if r.delta.war %}<li>Nivel de tensión WAR: {{ r.delta.war.prev }} → <b>{{ r.delta.war.now }}</b>/5</li>{% endif %}
{% for x in r.delta.top %}<li class="meta"><span class="{{ x.sev }}">{{ x.sev }}</span> {{ x.t }}{% if x.n > 1 %} <b>×{{ x.n }} fuentes</b>{% endif %}</li>{% endfor %}</ul>
{% elif r.delta is none %}<p class="meta noprint">Primera visita guardada: la próxima vez verás aquí qué cambió.</p>{% endif %}
{% if r.war %}<h2>Nivel de tensión (WAR)</h2><div class="lvl">{{ r.war.level }}/5 · {{ r.war.label }}</div>
<ul>{% for x in (r.war.digest or r.war.reasons)[:8] %}<li>{{ x }}</li>{% endfor %}</ul>{% endif %}
<h2>🚨 Alarmas ({{ r.alarms.n }})</h2>
{% if r.alarms["items"] %}<table>{% for i in r.alarms["items"][:20] %}<tr><td class="{{ i.sev }}">{{ i.k }}</td><td>{% if i.u %}<a href="{{ i.u }}" rel="noopener noreferrer">{{ i.t }}</a>{% else %}{{ i.t }}{% endif %}</td><td>{{ i.src }}{% if i.n > 1 %} <b>+{{ i.n - 1 }} fuentes</b>{% endif %}{% if i.cf %} <span class="meta">· {{ CONF[i.cf] }}</span>{% endif %}</td><td>{{ i.ts }} UTC</td></tr>{% endfor %}</table>{% else %}<p class="meta">Sin alarmas en la ventana.</p>{% endif %}
{% if r.services %}<h2>🔌 Caídas de servicios ({{ r.services|length }} proveedores)</h2>
<table>{% for g in r.services %}<tr><td class="{{ g.sev }}">{{ g.sev }}</td><td><b>{{ g.prov }}</b></td><td>{% if g.u %}<a href="{{ g.u }}" rel="noopener noreferrer">{{ g.t }}</a>{% else %}{{ g.t }}{% endif %}</td><td>{{ g.n }} aviso(s) · {{ g.srcs|join(", ") }}{% if g.cf %} · <span class="meta">{{ CONF[g.cf] }}</span>{% endif %}</td><td>{{ g.ts }} UTC</td></tr>{% endfor %}</table>
<p class="meta">Ubicadas en la sede del proveedor; «oficial» = página de estado del propio proveedor, el resto es prensa sin verificar.</p>{% endif %}
<h2>Resumen</h2>
<div>{% for k, v in r.by_severity %}<span class="pill"><b class="{{ k }}">{{ k }}</b> {{ v }}</span>{% endfor %}</div>
<div>{% for k, v in r.by_domain %}<span class="pill">{{ k }} <b>{{ v }}</b></span>{% endfor %}</div>
{% if r.series %}<div class="spk"><svg viewBox="0 0 100 30" preserveAspectRatio="none" role="img" aria-label="Eventos por {{ r.series.unit }}"><polyline class="s1" points="{{ r.series.all }}"/><polyline class="s2" points="{{ r.series.hi }}"/></svg>
<div class="meta">Eventos por {{ r.series.unit }} (gris: todos · rojo: críticos y altos) · pico de {{ r.series.max }} el {{ r.series.at }} UTC · {{ r.series.start }} → {{ r.series.end }}</div></div>{% endif %}
<h2>Críticos y altos destacados <span class="meta">({{ r.top|length }}{% if r.top_total and r.top_total > r.top|length %} de {{ r.top_total }}; el resto, en el anexo{% endif %})</span></h2>
<div class="flt noprint"><input id="q" type="search" placeholder="Filtrar por texto, fuente o dominio…" aria-label="Filtrar el informe"><button type="button" class="btn" data-sev="CRITICA">CRÍTICA</button><button type="button" class="btn" data-sev="ALTA">ALTA</button><select id="dom" aria-label="Filtrar por dominio"><option value="">todos los dominios</option>{% for k, v in r.by_domain %}<option value="{{ k }}">{{ k }} ({{ v }})</option>{% endfor %}</select><span id="cnt" class="meta"></span></div>
<table>{% for t in r.top %}<tr data-flt data-s="{{ (t.t ~ ' ' ~ t.src ~ ' ' ~ t.dom ~ ' ' ~ t.srcs|join(' '))|lower }}" data-sev="{{ t.sev }}" data-dom="{{ t.dom }}"><td class="{{ t.sev }}">{{ t.sev }}</td><td>{{ t.dom }}</td><td>{% if t.u %}<a href="{{ t.u }}" rel="noopener noreferrer">{{ t.t }}</a>{% else %}{{ t.t }}{% endif %}</td><td>{{ t.src }}{% if t.n > 1 %} <b>+{{ t.n - 1 }} fuentes</b>{% endif %}{% if t.cf %} <span class="meta">· {{ CONF[t.cf] }}</span>{% endif %}</td><td>{{ t.ts }}</td></tr>{% endfor %}</table>
<h2>Correlaciones principales</h2>
{% if r.corr %}<ul>{% for c in r.corr %}<li><b>({{ c.score }})</b> {{ c.desc }}</li>{% endfor %}</ul>{% else %}<p class="meta">Ninguna.</p>{% endif %}
{% if r.anoms %}<h2>📈 Anomalías ({{ r.anoms|length }}) <span class="meta">· agrupadas: cada barrido repetía la misma</span></h2>
<p class="meta noprint">Pulsa una anomalía para ver de qué fuentes y qué eventos sale.</p>
{% for a in r.anoms %}<details class="an" data-flt data-s="{{ (a.kind_es ~ ' ' ~ a.dom ~ ' ' ~ a.desc ~ ' ' ~ a.srcs|map(attribute='src')|join(' '))|lower }}" data-sev="{{ a.top_sev }}" data-dom="{{ a.dom }}">
<summary><span class="z">z={{ a.z }}</span> <b>{{ a.kind_es }}</b> · {{ a.dom }} — {{ a.desc }}{% if a.n > 1 %} <span class="meta">· ×{{ a.n }} · {{ a.first }} → {{ a.last }}</span>{% endif %}{% if a.top_sev %} <b class="{{ a.top_sev }}">{{ a.top_sev }}</b>{% endif %}</summary>
<div class="anb">{% if a.srcs %}<div>Fuentes implicadas ({{ a.rel }} eventos): {% for s in a.srcs %}<span class="pill">{{ s.src }} <b>{{ s.n }}</b></span>{% endfor %}</div>{% else %}<div class="meta">Sin eventos asociados en la base de datos (puede que ya se hayan purgado).</div>{% endif %}
{% if a.ev %}<table>{% for e in a.ev %}<tr><td class="{{ e.sev }}">{{ e.sev }}</td><td>{% if e.u %}<a href="{{ e.u }}" rel="noopener noreferrer">{{ e.t }}</a>{% else %}{{ e.t }}{% endif %}</td><td>{{ e.src }}</td><td>{{ e.ts }}</td></tr>{% endfor %}</table>{% endif %}</div></details>{% endfor %}{% endif %}
{% if r.sources %}<h2>Fuentes más activas</h2>
<table>{% for s in r.sources %}<tr><td>{{ s.src }}</td><td class="num">{{ s.n }}</td><td class="num">{{ s.pct }}%</td><td class="barc"><div class="bar2" style="width:{{ s.w }}%"></div></td><td>{% if s.crit %}<b class="CRITICA">{{ s.crit }} crít.</b> {% endif %}{% if s.alta %}<b class="ALTA">{{ s.alta }} alt.</b>{% endif %}</td><td class="meta">{{ s.last }}</td></tr>{% endfor %}</table>{% endif %}
{% if r.domains %}<h2>Recopilado por dominio</h2>
{% for d in r.domains %}<details class="dm" data-flt data-s="{{ (d.dom ~ ' ' ~ d.srcs|map(attribute='src')|join(' '))|lower }}" data-sev="{{ 'CRITICA' if d.crit else ('ALTA' if d.alta else '') }}" data-dom="{{ d.dom }}"><summary><b>{{ d.dom }}</b> — {{ d.n }} eventos{% if d.crit %} · <b class="CRITICA">{{ d.crit }} críticos</b>{% endif %}{% if d.alta %} · <b class="ALTA">{{ d.alta }} altos</b>{% endif %} <span class="meta">· {% for s in d.srcs %}{{ s.src }} ({{ s.n }}){% if not loop.last %}, {% endif %}{% endfor %}</span></summary>
<div class="anb"><table>{% for e in d.ev %}<tr><td class="{{ e.sev }}">{{ e.sev }}</td><td>{% if e.u %}<a href="{{ e.u }}" rel="noopener noreferrer">{{ e.t }}</a>{% else %}{{ e.t }}{% endif %}</td><td>{{ e.src }}</td><td>{{ e.ts }}</td></tr>{% endfor %}</table></div></details>{% endfor %}{% endif %}
{% if r.health and r.health.bad %}<h2>🩺 Salud de fuentes <span class="meta">({{ r.health.bad|length }} con problemas, de {{ r.health.total }})</span></h2>
<table>{% for h in r.health.bad %}<tr><td>{{ h.src }}{% if h.open %} <b class="ALTA">circuito abierto</b>{% endif %}</td><td>{{ h.ok }} ok · {{ h.fail }} fallos</td><td class="meta">{{ h.last_fail }}</td></tr>{% endfor %}</table>
<p class="meta">Una fuente que falla es un punto ciego: no aporta eventos a este informe.</p>{% endif %}
{% if r.ddos %}<h2>DDoS ({{ r.ddos.n }} eventos)</h2>
<p>Grupos: {% for g in r.ddos.groups[:6] %}<span class="pill">{{ g.k }} {{ g.n }}</span>{% endfor %}<br>Vectores: {% for g in r.ddos.vectors[:6] %}<span class="pill">{{ g.k }} {{ g.n }}</span>{% endfor %}<br>Objetivos: {% for g in r.ddos.targets[:6] %}<span class="pill">{{ g.k }} {{ g.n }}</span>{% endfor %}</p>{% endif %}
{% if r.nuc %}<h2>Radiación y explosiones</h2><table>{% for n in r.nuc %}<tr><td class="{{ n.sev }}">{{ n.sev }}</td><td>{{ n.t }}</td><td>{{ n.src }}</td><td>{{ n.ts }}</td></tr>{% endfor %}</table>{% endif %}
{% if r.cited %}<h2>Fuentes citadas</h2><p class="meta">{{ r.cited|join(" · ") }}</p>{% endif %}
{% if r.more %}<h2>Anexo · más críticos y altos <span class="meta">({{ r.more|length }})</span></h2>
<details class="anx"><summary>Mostrar la lista completa del anexo</summary><table>{% for t in r.more %}<tr data-flt data-s="{{ (t.t ~ ' ' ~ t.src ~ ' ' ~ t.dom ~ ' ' ~ t.srcs|join(' '))|lower }}" data-sev="{{ t.sev }}" data-dom="{{ t.dom }}"><td class="{{ t.sev }}">{{ t.sev }}</td><td>{{ t.dom }}</td><td>{% if t.u %}<a href="{{ t.u }}" rel="noopener noreferrer">{{ t.t }}</a>{% else %}{{ t.t }}{% endif %}</td><td>{{ t.src }}{% if t.n > 1 %} <b>+{{ t.n - 1 }} fuentes</b>{% endif %}</td><td>{{ t.ts }}</td></tr>{% endfor %}</table></details>{% endif %}
<p class="meta" style="margin-top:2em">Informe automático con datos abiertos. Los niveles y correlaciones son heurísticos: sirven para saber dónde mirar, no son una prueba.</p>
<script>
(function () {
  var q = document.getElementById('q'), dm = document.getElementById('dom'), cnt = document.getElementById('cnt');
  var rows = [].slice.call(document.querySelectorAll('[data-flt]')), sev = '';
  var chips = [].slice.call(document.querySelectorAll('button[data-sev]'));
  function apply() {
    var t = q ? q.value.trim().toLowerCase() : '', d = dm ? dm.value : '', n = 0;
    rows.forEach(function (r) {
      var ok = (!t || (r.getAttribute('data-s') || '').indexOf(t) > -1) && (!sev || r.getAttribute('data-sev') === sev) && (!d || r.getAttribute('data-dom') === d);
      r.hidden = !ok;
      if (ok) n++;
    });
    if (cnt) cnt.textContent = n + ' de ' + rows.length + ' elementos';
    var anx = document.querySelector('details.anx');
    if (anx && (t || sev || d)) anx.open = true;
  }
  if (q) q.addEventListener('input', apply);
  if (dm) dm.addEventListener('change', apply);
  chips.forEach(function (b) {
    b.addEventListener('click', function () {
      sev = (sev === b.getAttribute('data-sev')) ? '' : b.getAttribute('data-sev');
      chips.forEach(function (c) { c.classList.toggle('on', c.getAttribute('data-sev') === sev); });
      apply();
    });
  });
  var was = [];
  window.addEventListener('beforeprint', function () { was = []; [].forEach.call(document.querySelectorAll('details'), function (d) { was.push(d.open); d.open = true; }); });
  window.addEventListener('afterprint', function () { [].forEach.call(document.querySelectorAll('details'), function (d, i) { d.open = was[i]; }); });
  apply();
})();
</script>
</body></html>""", autoescape=True)

