@app.post("/api/fp")
async def api_fp_add(id: int = Form(...), user: str = Depends(require_user_or_local)):
    def work():
        conn = db_conn()
        try:
            r = conn.execute("SELECT source, title FROM events WHERE id = ?", (int(id),)).fetchone()
        finally:
            conn.close()
        if not r:
            return None
        rule = fp_add(r[0], r[1])
        return {"removed": db_fp_purge(rule["s"], rule["k"]), "source": rule["s"], "title": rule["t"]}
    res = await asyncio.to_thread(work)
    if res is None:
        raise HTTPException(404, "Evento no encontrado (puede que ya se haya borrado)")
    db_audit(user, "fp_add", f"{res['source']}: {res['title'][:80]}")
    return res

