@app.get("/api/tg/find")
async def api_tg_find(q: str = ""):
    """Busca un canal o grupo por NOMBRE aunque no esté en tu lista: prueba variantes del nombre en t.me (sin cuenta) y dice cuáles existen."""
    q = (q or "").strip()
    if len(q) < 3:
        raise HTTPException(status_code=400, detail="escribe al menos 3 letras: un nombre, un @usuario o un enlace t.me/…")
    cands: list[str] = []
    try:
        nm = tg_parse_query(q)
    except Exception:
        nm = None
    if isinstance(nm, (tuple, list)):
        nm = nm[0] if nm else None
    if isinstance(nm, str) and nm:
        cands.append(nm)
    low = {c.lower() for c in cands}
    for c in tg_candidates(q):
        if c.lower() not in low:
            cands.append(c)
            low.add(c.lower())
    cands = cands[:40]
    return {"q": q, "tried": len(cands), "found": await tg_probe(cands)}

