@app.get("/partial/sources", response_class=HTMLResponse)
async def partial_sources():
    needs_key = {
        "acled": not ACLED_EMAIL, "firms": not FIRMS_KEY, "opensky": not OPENSKY_USER,
        "maritime": not AISSTREAM_KEY, "adsb": not ADSB_KEY, "fred": not FRED_KEY,
        "eia": not EIA_KEY, "urlhaus": not ABUSECH_KEY, "threatfox": not ABUSECH_KEY,
        "malwarebazaar": not ABUSECH_KEY, "cloudflare_ddos": not CLOUDFLARE_API_TOKEN,
        "cloudflare_internet": not CLOUDFLARE_API_TOKEN, "openaq": not OPENAQ_KEY, "ucdp": not UCDP_KEY,
    }
    rows = []
    for src in SOURCES:
        h = SOURCE_HEALTH.get(src)
        if h is None:
            state = "idle"
        elif circuit_is_open(src):
            state = "open"
        elif h["fail"] > 0:
            state = "warn"
        else:
            state = "ok"
        rows.append({
            "name": src, "state": state, "needs_key": needs_key.get(src, False),
            "ok": h["ok"] if h else 0, "fail": h["fail"] if h else 0,
            "avg_ms": h["avg_ms"] if h else 0,
            "last_ok": (_ago(h["last_ok"]) + " atrás") if h and h["last_ok"] else "—",
            "n": SOURCE_LAST.get(src, {}).get("n"), "err": SOURCE_LAST.get(src, {}).get("err"),
            "note": (SOURCE_LAST.get(src, {}).get("err") or
                     (("falta la API key en .env" if needs_key.get(src) else "respondió vacía: sin datos nuevos, sin ubicación o filtrados")
                      if SOURCE_LAST.get(src, {}).get("n") == 0 else "")),
        })
    return PARTIAL_SOURCES.render(rows=rows, errors=list(SWEEP_STATE.get("source_errors") or [])[:15], keys=keys_status(), tg=tg_report()) + PARTIAL_FP.render(rules=list(reversed(fp_rules())))


