# ─── ★ NUEVO: riesgo por país e IOC ──────────────────────────────────

_SEV_PTS = {"CRITICA": 5.0, "ALTA": 3.0, "MEDIA": 1.5, "BAJA": 0.5}

# ─── ★ NUEVO · silenciar fuente o país durante un tiempo (no borra nada: solo se oculta de mapa, listas, alarmas y JARVIS; caduca solo) ───
_MUTE_CACHE: dict = {"t": 0.0, "v": []}

def mutes_active() -> list[dict]:
    if time.time() - _MUTE_CACHE["t"] < 5:
        return _MUTE_CACHE["v"]
    try:
        raw = json.loads(kv_get("mutes") or "[]")
    except Exception:
        raw = []
    now = time.time()
    act = [m for m in raw if isinstance(m, dict) and m.get("until", 0) > now and m.get("kind") in ("source", "country") and m.get("value")]
    _MUTE_CACHE.update(t=time.time(), v=act)
    return act

def mutes_save(lst: list[dict]) -> None:
    kv_set("mutes", json.dumps(lst[-60:], ensure_ascii=False))
    _MUTE_CACHE["t"] = 0.0

def mute_add(kind: str, value: str, hours: float = 24) -> dict:
    kind, value = _str(kind), _str(value).strip()[:80]
    if kind not in ("source", "country") or not value:
        raise ValueError("kind debe ser source o country y value no puede ir vacío")
    hours = max(0.25, min(float(hours), 24 * 14))
    lst = [m for m in mutes_active() if not (m["kind"] == kind and m["value"] == value)]
    m = {"kind": kind, "value": value, "until": time.time() + hours * 3600}
    lst.append(m)
    mutes_save(lst)
    return m

def mute_remove(kind: str, value: str) -> bool:
    cur = mutes_active()
    new = [m for m in cur if not (m["kind"] == kind and m["value"] == value)]
    mutes_save(new)
    return len(new) < len(cur)

def apply_mutes(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or df.empty:
        return df
    act = mutes_active()
    if not act:
        return df
    keep = pd.Series(True, index=df.index)
    srcs = {m["value"] for m in act if m["kind"] == "source"}
    ctry = [m["value"] for m in act if m["kind"] == "country"]
    if srcs and "source" in df.columns:
        keep &= ~df["source"].isin(srcs)
    if ctry and "entities" in df.columns:
        ent = df["entities"].fillna("").astype(str).map(lambda x: {e.strip() for e in x.split(",")})
        for c in ctry:
            keep &= ~ent.map(lambda st, c=c: c in st)
    return df[keep]

def country_timeline(name: str, hours: int = 72, limit: int = 120) -> dict:
    """Secuencia cronológica de lo que ha pasado en/sobre un país (ataque → respuesta → alarma…), con duplicados agrupados."""
    hours = max(1, min(int(hours), 720))
    df = db_query_events(hours=hours, limit=8000)
    if df is None or df.empty:
        return {"country": name, "hours": hours, "n": 0, "items": [], "by_domain": {}}
    ent = df["entities"].fillna("").astype(str).map(lambda x: {e.strip() for e in x.split(",")})
    d = df[ent.map(lambda st: name in st)]
    d = d[d["severity"].isin(["CRITICA", "ALTA", "MEDIA"])].sort_values("id", ascending=False).head(600)
    rows = [{"sev": _str(r.get("severity")), "dom": _str(r.get("domain")), "src": _str(r.get("source")), "t": _str(r.get("title"))[:150], "u": _safe_url(r.get("url")),
             "ts": _str(r.get("timestamp"))[:16].replace("T", " "), "la": _num(r.get("lat")), "lo": _num(r.get("lon")), "k": alarm_kind(_str(r.get("tags"))),
             "cf": event_conf(_str(r.get("tags")), _str(r.get("source")))} for r in d.to_dict("records")]
    # el orden de prioridad para agrupar es el cronológico inverso; el grupo conserva la hora del más reciente
    items = group_items(rows)
    items.sort(key=lambda x: x["ts"])                       # cronológico ascendente: se lee como una secuencia
    by = Counter(x["dom"] for x in items)
    return {"country": name, "hours": hours, "n": len(rows), "items": items[-limit:], "by_domain": dict(by.most_common(8))}

def heat_matrix(hours: int = 24) -> dict:
    """Actividad por familia (filas) y hora (columnas, la última = ahora): dónde se concentra el ruido y cuándo."""
    hours = max(6, min(int(hours), 72))
    df = db_query_events(hours=hours, limit=20000)
    fams = list(FAMILIES)
    grid = [[0.0] * hours for _ in fams]
    if df is not None and not df.empty:
        ts = _dt(df["timestamp"])
        age = (pd.Timestamp.now(tz="UTC") - ts).dt.total_seconds() / 3600.0
        for dom, sv, a in zip(df["domain"].astype(str), df["severity"].astype(str), age):
            f = _FAMILY_OF.get(dom)
            if f is None or pd.isna(a) or a < 0 or a >= hours:
                continue
            grid[fams.index(f)][hours - 1 - int(a)] += _SEV_PTS.get(sv, 1.0)
    mx = max((v for row in grid for v in row), default=0.0)
    return {"hours": hours, "families": fams, "grid": [[round(v, 1) for v in row] for row in grid], "max": round(mx, 1)}

def country_risk(df: pd.DataFrame, top: int = 25) -> list[dict]:
    """Ranking de países: Σ (peso de severidad × peso del dominio) por país mencionado en 'entities'."""
    if df is None or df.empty:
        return []
    names = {v[0] for v in COUNTRY_DB.values()}
    agg: dict[str, dict] = {}
    for r in df.to_dict("records"):
        w = _SEV_PTS.get(_str(r.get("severity")), 1.0) * WEIGHTS.get(_str(r.get("domain")), 1)
        seen = {e.strip() for e in _str(r.get("entities")).split(",") if e.strip() in names}
        for c in seen:
            a = agg.setdefault(c, {"name": c, "n": 0, "score": 0.0, "dom": defaultdict(int)})
            a["n"] += 1; a["score"] += w; a["dom"][_str(r.get("domain"))] += 1
    rows = sorted(agg.values(), key=lambda a: -a["score"])[:top]
    mx = rows[0]["score"] if rows else 1
    return [{
        "name": a["name"], "n": a["n"], "score": round(a["score"], 1), "pct": max(4, int(100 * a["score"] / mx)),
        "top": ", ".join(d for d, _ in sorted(a["dom"].items(), key=lambda x: -x[1])[:2]),
    } for a in rows]

def ioc_classify(raw: str) -> tuple[str, str, list[tuple[str, str]]]:
    """Normaliza (refang) un indicador y devuelve (tipo, valor limpio, enlaces de consulta externos)."""
    v = (raw or "").strip().replace("[.]", ".").replace("(.)", ".").replace("[:]", ":")
    v = re.sub(r"^hxxp", "http", v, flags=re.IGNORECASE).strip(" <>\"'")
    q = quote(v, safe="")
    if re.fullmatch(r"CVE-\d{4}-\d{4,}", v, re.IGNORECASE):
        v = v.upper()
        return "CVE", v, [("NVD", f"https://nvd.nist.gov/vuln/detail/{v}"), ("cve.org", f"https://www.cve.org/CVERecord?id={v}"),
                          ("Exploit-DB", f"https://www.exploit-db.com/search?cve={v}"), ("GitHub PoC", f"https://github.com/search?q={q}&type=repositories")]
    try:
        ipaddress.ip_address(v)
        return "IP", v, [("AbuseIPDB", f"https://www.abuseipdb.com/check/{q}"), ("VirusTotal", f"https://www.virustotal.com/gui/ip-address/{q}"),
                         ("Shodan", f"https://www.shodan.io/host/{q}"), ("GreyNoise", f"https://viz.greynoise.io/ip/{q}"),
                         ("OTX", f"https://otx.alienvault.com/indicator/ip/{q}"), ("ISC SANS", f"https://isc.sans.edu/ipinfo/{q}")]
    except ValueError:
        pass
    if re.fullmatch(r"[a-fA-F0-9]{32}|[a-fA-F0-9]{40}|[a-fA-F0-9]{64}", v):
        v = v.lower()
        return "HASH", v, [("VirusTotal", f"https://www.virustotal.com/gui/file/{v}"), ("MalwareBazaar", f"https://bazaar.abuse.ch/sample/{v}/"),
                           ("Hybrid Analysis", f"https://www.hybrid-analysis.com/search?query={v}"), ("OTX", f"https://otx.alienvault.com/indicator/file/{v}")]
    if re.match(r"^https?://", v, re.IGNORECASE):
        h = hashlib.sha256(v.encode()).hexdigest()
        return "URL", v, [("VirusTotal", f"https://www.virustotal.com/gui/url/{h}"), ("urlscan", f"https://urlscan.io/search/#{q}"),
                          ("URLhaus", f"https://urlhaus.abuse.ch/browse.php?search={q}")]
    if re.fullmatch(r"(?:[a-z0-9-]+\.)+[a-z]{2,}", v, re.IGNORECASE):
        v = v.lower()
        return "DOMINIO", v, [("VirusTotal", f"https://www.virustotal.com/gui/domain/{q}"), ("urlscan", f"https://urlscan.io/search/#{q}"),
                              ("OTX", f"https://otx.alienvault.com/indicator/domain/{q}"), ("crt.sh", f"https://crt.sh/?q={q}"),
                              ("Whois", f"https://who.is/whois/{q}")]
    return "TEXTO", v, []

def db_search_ioc(value: str, limit: int = 60) -> pd.DataFrame:
    like = "%" + re.sub(r"[%_]", "", value) + "%"
    conn = db_conn()
    df = pd.read_sql(
        "SELECT * FROM events WHERE title LIKE ? OR description LIKE ? OR entities LIKE ? OR tags LIKE ? OR url LIKE ? "
        "ORDER BY id DESC LIMIT ?", conn, params=(like, like, like, like, like, limit),
    )
    conn.close()
    return df

