def build_groups(df: pd.DataFrame) -> list[dict]:
    agg: dict = {}
    if df is not None and not df.empty:
        for r in df.to_dict("records"):
            tg = _str(r.get("tags")).split(",")
            g = next((t[6:] for t in tg if t.startswith("grupo:")), "")
            if not g:
                continue
            a = agg.setdefault(g, {"n": 0, "ips": 0, "claims": 0, "c": Counter()})
            a["n"] += 1
            ip = next((t[4:] for t in tg if t.startswith("ips:")), "")
            a["ips"] += int(ip) if ip.isdigit() else 0
            a["claims"] += 1 if "reivindicado" in tg else 0
            fl = _FLOW_RX.search(_str(r.get("tags")))
            if fl and ("reivindicado" in tg or "ioc-feed" in tg):
                a["c"][COUNTRY_DB[fl.group(2)][0]] += 1          # víctima del flujo
            else:
                ents = [e for e in _str(r.get("entities")).split(",") if e and e != g and not e.startswith("ip:")]
                if ents:
                    a["c"][ents[-1]] += 1
    out = []
    for g, a in agg.items():
        h = GROUP_HOME.get(g)
        out.append({"name": g, "kind": GROUP_KIND.get(g, ""), "home": COUNTRY_DB[h][0] if h in COUNTRY_DB else "—",
                    "n": a["n"], "ips": a["ips"], "claims": a["claims"], "top": ", ".join(k for k, _ in a["c"].most_common(4))})
    out.sort(key=lambda r: -(r["n"] + r["ips"] / 10))
    return out

