async def api_group_ips(group: str = "", limit: int = 6000, hist: int = 0):
    """IPs atribuidas a grupos (una por punto), por defecto solo las FRESCAS (vistas en vivo en las últimas NEXUS_GROUP_FRESH_HOURS);
    hist=1 añade las de listas históricas. Resumen por grupo ordenado por nombre. Independiente de la ventana de tiempo del mapa."""
    ips, groups = await asyncio.to_thread(db_group_ips, group.strip()[:80], limit, 0 if hist else GROUP_FRESH_HOURS)
    out = {"ips": ips, "groups": groups}
    if not ips:
        out["diag"] = dict(_GIPS_DIAG)                          # por qué está vacío (feeds caídos, sin ubicación…): la interfaz lo cuenta
    return out

