def _detector_ctx(group: str, atype: str, src: str, hours: int) -> dict:
    d = db_detector(group, atype, src, max(hours, 168))
    for r in d["rows"]:
        r["ago"] = _ago(r["ts"])
    m = dict(DDOS_MON)
    m["ago"] = _ago(m["last"]) if m.get("last") else ""
    ips, summ = db_group_ips("", 20000, GROUP_FRESH_HOURS)
    sample: dict = {}
    for x in ips:
        sample.setdefault(x["g"], []).append(f"{x['ip']} ({x['cc'] or '?'})")
    gips = [dict(g, sample=", ".join(sample.get(g["name"], [])[:6])) for g in summ]
    return {"d": d, "m": m, "gips": gips, "f": {"group": group, "atype": atype, "src": src}, "keep": GROUP_IP_KEEP_DAYS, "fresh": int(GROUP_FRESH_HOURS)}

