_SCAN_TASK: dict = {"t": None, "res": None}

async def _detector_scan_job() -> None:
    try:
        global _TG_BLOCK_UNTIL
        _RUN_BOOST["n"] = 150
        _DDOS_MON_LAST[0] = 0.0
        _RSS_STATE.clear()
        _TG_BLOCK_UNTIL = 0.0                      # la orden manual manda: se ignoran pausas, canales apartados y el cortacircuitos
        for st in _TG_STATE.values():
            st["last"] = 0
            st["dead_until"] = 0
            st["empty"] = 0
        for n in GROUP_FAST_SOURCES:
            CIRCUIT_OPEN.pop(n, None)
            SOURCE_HEALTH[n]["fail"] = 0
        _SCAN_TASK["res"] = None
        await run_full_sweep(only=GROUP_FAST_SOURCES)
        _SCAN_TASK["res"] = {n: dict(SOURCE_LAST.get(n, {})) for n in sorted(GROUP_FAST_SOURCES)}
    except Exception as e:
        log.warning(f"[DETECTOR] escaneo manual: {type(e).__name__}: {e}")
    finally:
        _RUN_BOOST["n"] = 0

@app.post("/api/detector/scan")
async def api_detector_scan(user: str = Depends(require_user_or_local)):
    """«Escanear ahora»: lanza en segundo plano canales de Telegram + feeds de seguridad + monitor DDoS y responde al instante."""
    t = _SCAN_TASK["t"]
    if t and not t.done():
        return {"started": False}
    _SCAN_TASK["t"] = asyncio.ensure_future(_detector_scan_job())
    db_audit(user, "detector_scan", "")
    return {"started": True}

@app.get("/api/detector/scan/status")
async def api_detector_scan_status():
    """Estado del «Escanear ahora»: si sigue corriendo y qué dijo cada fuente (errores reales incluidos)."""
    t = _SCAN_TASK["t"]
    return {"running": bool(t and not t.done()), "result": _SCAN_TASK.get("res")}

