# ─── ★ NUEVO: analítica (panel JARVIS) y ATT&CK ─────────────────────

FAMILIES = {
    "Ciber": CYBER_DOMAINS + ["internet"],
    "Crimen": ["crimen", "crimen_urbano", "terrorismo", "sanciones"],
    "Conflicto": ["conflicto", "disturbios", "humanitario", "vuelo_militar", "alerta_viaje", "geopolitica", "alerta_civil", "explosion"],
    "Naturaleza": ["terremoto", "incendio", "meteorologico", "evento_natural", "radiacion", "salud", "espacio", "aire"],
    "Economía": ["economia", "energia", "mercado", "maritimo", "vuelo", "cripto"],
    "Mundo": ["noticias"],
}
_FAMILY_OF = {d: f for f, ds in FAMILIES.items() for d in ds}
_TECH_RE = re.compile(r"\bT\d{4}\b")

def _attack_counts(df: pd.DataFrame) -> dict[str, int]:
    cnt: dict[str, int] = defaultdict(int)
    if df is None or df.empty or "tags" not in df.columns:
        return cnt
    for t in df["tags"].fillna(""):
        for tid in set(_TECH_RE.findall(t)):
            if tid in ATTACK_TECHNIQUES:
                cnt[tid] += 1
    return cnt

def _weighted(df: pd.DataFrame) -> float:
    if df is None or df.empty:
        return 0.0
    return float(sum(_SEV_PTS.get(sv, 1.0) * WEIGHTS.get(d, 1) for sv, d in zip(df["severity"], df["domain"])))

def _section_line(label: str, n: int, prev: int, sev: dict, ctry: list, sc) -> str:
    """Una frase por sección (reglas simples, sin IA): cuánto, cómo va respecto a antes, dónde y lo más grave."""
    if not n:
        return f"{label}: sin eventos en la ventana."
    hard = sev.get("CRITICA", 0) + sev.get("ALTA", 0)
    top = ctry[0]["name"] if ctry else ""
    tr = "sube" if n > prev else "baja" if n < prev else "estable"
    return (f"{label}: {n} eventos ({tr} frente a {prev}); {hard} de gravedad ALTA/CRÍTICA" + (f", el foco principal es {top}" if top else "") +
            (f"; hay {sev['CRITICA']} CRÍTICO(S)." if sev.get("CRITICA") else "."))

def _hud_extras(cur: pd.DataFrame, prev: pd.DataFrame, hours: int, score: float, pscore: float, level: str) -> dict:
    """Capas de lectura del panel JARVIS: qué ha cambiado, por dónde van los ataques, qué grupos están activos y un resumen en frases
    (reglas simples sobre los mismos datos: sin IA, sin red, sin coste)."""
    def dom_counts(d):
        return {} if d.empty else {k: int(v) for k, v in d["domain"].value_counts().items()}
    c, p = dom_counts(cur), dom_counts(prev)
    movers = []
    for dom in set(c) | set(p):
        a_, b_ = c.get(dom, 0), p.get(dom, 0)
        if abs(a_ - b_) >= 3:
            movers.append({"name": dom, "n": a_, "prev": b_, "delta": a_ - b_,
                           "pct": round(100.0 * (a_ - b_) / b_) if b_ else None})
    movers.sort(key=lambda m: -abs(m["delta"]))
    movers = movers[:6]

    corridors = [{"s": f["sn"], "t": f["tn"], "sc": f["sc"], "tc": f["tc"], "d": f["d"], "n": f["n"]}
                 for f in flows_from_df(cur, 8)]

    groups = []
    if not cur.empty:
        gc: dict = {}
        for tg, dom in zip(cur["tags"].fillna("").astype(str), cur["domain"].astype(str)):
            for m in re.finditer(r"(?:^|,)grupo:([^,]+)", tg):
                g = gc.setdefault(m.group(1), {"ev": 0, "dom": {}})
                g["ev"] += 1
                g["dom"][dom] = g["dom"].get(dom, 0) + 1
        fresh = {}
        try:
            fresh = {x["name"]: x["n"] for x in db_group_ips("", 1, GROUP_FRESH_HOURS)[1]}
        except Exception:
            pass
        for name, g in gc.items():
            groups.append({"name": name, "ev": g["ev"], "ips": fresh.get(name, 0),
                           "type": max(g["dom"], key=g["dom"].get)})
        groups.sort(key=lambda x: (-(x["ev"] + x["ips"]), x["name"].lower()))
        groups = groups[:8]

    reading = []
    d_sc = round(score - pscore, 1)
    reading.append(f"Nivel {level} ({score:.0f}/100), " +
                   (f"{abs(d_sc):.0f} puntos {'más alto' if d_sc > 0 else 'más bajo'} que la ventana anterior." if abs(d_sc) >= 1 else "estable respecto a la ventana anterior."))
    up = [m for m in movers if m["delta"] > 0]
    if up:
        m = up[0]
        reading.append(f"Mayor subida: {m['name']} ({m['prev']} → {m['n']}" + (f", +{m['pct']}%" if m['pct'] is not None else ", nuevo") + ").")
    if corridors:
        k = corridors[0]
        reading.append(f"Corredor de ciberataque más activo: {k['s']} → {k['t']} ({k['d']}, {k['n']} eventos).")
    if groups:
        g = groups[0]
        reading.append(f"Grupo más activo: {g['name']} ({g['ev']} eventos" + (f", {g['ips']} IPs frescas" if g['ips'] else "") + ").")
    sections = []
    for key, label, doms in (("terrorismo", "Terrorismo", ["terrorismo", "detencion_terror", "alerta_bomba"]), ("disturbios", "Revueltas callejeras", ["disturbios"]),
                             ("crimen_urbano", "Crimen urbano", ["crimen_urbano"]),
                             ("cripto", "Cripto", ["cripto"])):
        sc = cur[cur["domain"].isin(doms)] if not cur.empty else cur
        sp = prev[prev["domain"].isin(doms)] if not prev.empty else prev
        latest = []
        if not sc.empty:
            for r in sc.sort_values("id", ascending=False).head(8).to_dict("records"):
                latest.append({"sev": _str(r.get("severity")), "src": _str(r.get("source")), "t": _str(r.get("title"))[:110],
                               "u": _safe_url(r.get("url")), "id": int(_num(r.get("id")))})
        sev = {} if sc.empty else {k: int(v) for k, v in sc["severity"].value_counts().items()}
        ctry = country_risk(sc, 6)
        sections.append({"key": key, "label": label, "n": int(len(sc)), "prev": int(len(sp)), "sev": sev,
                         "countries": ctry, "latest": latest, "line": _section_line(label, len(sc), len(sp), sev, ctry, sc)})
    # caídas de servicios (Microsoft, AWS, Cloudflare…): los «países» son proveedores
    sv_cur = cur[cur["tags"].fillna("").astype(str).str.contains("caida", regex=False)] if not cur.empty else cur
    sv_prev = prev[prev["tags"].fillna("").astype(str).str.contains("caida", regex=False)] if not prev.empty else prev
    provs: dict = {}
    for t, sv_ in zip(sv_cur["title"].astype(str), sv_cur["severity"].astype(str)) if not sv_cur.empty else []:
        m = re.match(r"Caída de servicio · ([^:(]+)", t)
        if m:
            provs[m.group(1).strip()] = provs.get(m.group(1).strip(), 0) + _SEV_PTS.get(sv_, 1.0)
    plist = [{"name": k, "score": round(v, 1), "n": 1, "pct": 50, "top": ""} for k, v in sorted(provs.items(), key=lambda kv: -kv[1])[:6]]
    sv_latest = [{"sev": _str(r.get("severity")), "src": _str(r.get("source")), "t": _str(r.get("title"))[:110], "u": _safe_url(r.get("url")), "id": int(_num(r.get("id")))}
                 for r in (sv_cur.sort_values("id", ascending=False).head(8).to_dict("records") if not sv_cur.empty else [])]
    sv_sev = {} if sv_cur.empty else {k: int(v) for k, v in sv_cur["severity"].value_counts().items()}
    sections.append({"key": "servicios", "label": "Caídas de servicios", "n": int(len(sv_cur)), "prev": int(len(sv_prev)), "sev": sv_sev, "clab": "Proveedores afectados",
                     "countries": plist, "latest": sv_latest,
                     "line": (f"{len(provs)} proveedor(es) con incidencias: {', '.join(list(provs)[:4])}." if provs else "Sin caídas de servicios detectadas en la ventana.")})
    try:
        terr = next(x for x in sections if x["key"] == "terrorismo")
        if terr["n"]:
            reading.append(terr["line"])
        if provs:
            reading.append(sections[-1]["line"])
    except StopIteration:
        pass
    return {"movers": movers, "corridors": corridors, "groups": groups, "reading": reading, "sections": sections}

def _DOM_LABEL(d: str) -> str:
    return (DOMAIN_PALETTE.get(d) or {}).get("label") or d.replace("_", " ").capitalize()

_ANALYTICS_CACHE: dict = {}      # (horas, dominios) → (instante, resultado): JARVIS repite la misma consulta pesada cada pocos segundos
def build_analytics(hours: int, domains: Optional[list[str]]) -> dict:
    key = (int(hours), tuple(domains or ()))
    hit = _ANALYTICS_CACHE.get(key)
    if hit and time.time() - hit[0] < 40:
        return hit[1]
    res = _build_analytics(hours, domains)
    if len(_ANALYTICS_CACHE) > 24:
        _ANALYTICS_CACHE.clear()
    _ANALYTICS_CACHE[key] = (time.time(), res)
    return res

def _build_analytics(hours: int, domains: Optional[list[str]]) -> dict:
    """Todo lo que pinta el panel JARVIS en un solo JSON (ventana actual vs. ventana anterior de igual tamaño)."""
    hours = max(1, min(int(hours), 2160))
    df2 = db_query_events(hours=hours * 2, domains=domains, limit=15000 if hours <= 72 else 80000)
    for col in ("entities", "tags", "source", "severity", "domain", "title", "timestamp"):
        if col not in df2.columns:
            df2[col] = ""
    now = datetime.now(timezone.utc)
    if df2.empty:
        cur, prev = df2, df2
    else:
        ts = _dt(df2["timestamp"])
        df2 = df2.assign(_ts=ts)
        cut = now - timedelta(hours=hours)
        cur, prev = df2[df2["_ts"] >= cut], df2[df2["_ts"] < cut]
    # índice de amenaza 0-100 (relativo: saturación suave sobre la carga ponderada por hora)
    rate = _weighted(cur) / hours
    score = round(100 * (1 - math.exp(-rate / 80.0)), 1)
    prate = _weighted(prev) / hours
    pscore = round(100 * (1 - math.exp(-prate / 80.0)), 1)
    level = "CRÍTICO" if score >= 75 else "ALTO" if score >= 50 else "MODERADO" if score >= 25 else "BAJO"

    def n(mask_df: pd.DataFrame, **cond) -> int:
        return int(len(mask_df))
    def by_dom(d: pd.DataFrame, doms) -> int:
        return 0 if d.empty else int(d["domain"].isin(doms).sum())
    def tagc(d: pd.DataFrame, tag: str) -> int:
        return 0 if d.empty else int(d["tags"].fillna("").str.contains(tag, case=False, regex=False).sum())
    def ips(d: pd.DataFrame) -> int:
        if d.empty:
            return 0
        found = set()
        for e in d["entities"].fillna(""):
            found.update(x for x in e.split(",") if x.startswith("ip:"))
        return len(found)
    ind = [
        ("C2 / botnets", lambda d: tagc(d, "c2") + tagc(d, "botnet")),
        ("Malware", lambda d: by_dom(d, ["malware"])),
        ("DDoS", lambda d: by_dom(d, ["ddos"])),
        ("Fuerza bruta", lambda d: by_dom(d, ["bruteforce"])),
        ("Exploits / 0-day", lambda d: by_dom(d, ["exploit"]) + tagc(d, "0day")),
        ("Ransomware", lambda d: by_dom(d, ["ransomware"])),
        ("Phishing", lambda d: by_dom(d, ["phishing"])),
        ("Vulnerab. (KEV)", lambda d: by_dom(d, ["vulnerabilidad"])),
        ("IPs únicas", ips),
        ("Crimen", lambda d: by_dom(d, FAMILIES["Crimen"])),
        ("Conflicto", lambda d: by_dom(d, FAMILIES["Conflicto"])),
        ("Críticos", lambda d: 0 if d.empty else int((d["severity"] == "CRITICA").sum())),
    ]
    kpis = [{"name": nm, "n": f(cur), "prev": f(prev)} for nm, f in ind]

    # línea temporal: 24 cubos por familia
    B = 24
    labels, series = [], {f: [0] * B for f in FAMILIES}
    start = now - timedelta(hours=hours)
    step = timedelta(hours=hours) / B
    for i in range(B):
        t = start + step * (i + 1)
        labels.append(t.astimezone().strftime("%H:%M" if hours <= 48 else "%d/%m"))
    idx_list: list[int] = []
    if not cur.empty:
        idx = ((cur["_ts"] - start) / step).astype("float").clip(0, B - 1e-9).astype(int)
        idx_list = [int(i) for i in idx]
        for fam_dom, i in zip(cur["domain"], idx):
            f = _FAMILY_OF.get(fam_dom)
            if f:
                series[f][int(i)] += 1
    fam_tot = {f: sum(v) for f, v in series.items()}

    def _hex(dom: str) -> str:
        c = (DOMAIN_PALETTE.get(dom) or {}).get("color") or [150, 190, 255]
        return "#%02x%02x%02x" % (int(c[0]), int(c[1]), int(c[2]))

    def _panel(key: str, title: str, groups: list) -> dict:
        """Recuadro temático: serie apilada por grupo + indicadores (total, ritmo, pico, críticos, país y fuente líderes…)."""
        all_doms = [d for _, _, ds in groups for d in ds]
        tot_series = [0] * B
        out_g = []
        sev_arr = cur["severity"].to_numpy() if not cur.empty else None
        dom_arr = cur["domain"].to_numpy() if not cur.empty else None
        grand = 0
        for name, color, ds in groups:
            ser = [0] * B
            n = crit = high = 0
            if not cur.empty:
                m = np.isin(dom_arr, ds)
                n = int(m.sum())
                crit = int((m & (sev_arr == "CRITICA")).sum())
                high = int((m & (sev_arr == "ALTA")).sum())
                for i in np.nonzero(m)[0]:
                    ser[idx_list[i]] += 1
            for i in range(B):
                tot_series[i] += ser[i]
            grand += n
            out_g.append({"name": name, "color": color, "dom": ds[0] if len(ds) == 1 else "", "n": n,
                          "prev": by_dom(prev, ds), "crit": crit, "high": high, "series": ser})
        for g in out_g:
            g["share"] = round(100.0 * g["n"] / grand, 1) if grand else 0.0
        sub = cur[cur["domain"].isin(all_doms)] if not cur.empty else cur
        prev_sub_n = by_dom(prev, all_doms)
        peak_i = int(np.argmax(tot_series)) if grand else -1
        top_c = country_risk(sub, 1) if grand else []
        top_s = sub["source"].value_counts().head(1) if grand else []
        lead = max(out_g, key=lambda g: g["n"]) if grand else None
        ips_n = ips(sub) if grand else 0
        stats = {"total": grand, "prev": prev_sub_n, "rate": round(grand / hours, 1),
                 "peak": labels[peak_i] if peak_i >= 0 else "—", "peak_n": tot_series[peak_i] if peak_i >= 0 else 0,
                 "crit": sum(g["crit"] for g in out_g), "high": sum(g["high"] for g in out_g),
                 "country": top_c[0]["name"] if top_c else "—",
                 "source": (str(top_s.index[0]) if len(top_s) else "—"),
                 "lead": lead["name"] if lead and lead["n"] else "—", "ips": ips_n,
                 "srcs": int(sub["source"].nunique()) if grand else 0,
                 "countries": int(len(country_risk(sub, 50))) if grand else 0}
        return {"key": key, "title": title, "groups": out_g, "stats": stats}

    FAM_HEX = {"Ciber": "#00d4ff", "Crimen": "#ff005c", "Conflicto": "#ff7a00", "Naturaleza": "#00ff9f", "Economía": "#8b5cf6", "Mundo": "#aabee0"}
    try:
        famstats = _panel("familias", "Actividad por familia", [(f, FAM_HEX.get(f, "#fff"), ds) for f, ds in FAMILIES.items()])
        themes = [_panel(k, t, [(_DOM_LABEL(d), _hex(d), [d]) for d in ds]) for k, t, ds in (
            ("ciber", "Ciberataques · DDoS, malware, ransomware, phishing…", FAMILIES["Ciber"]),
            ("naturaleza", "Naturaleza · clima y desastres", FAMILIES["Naturaleza"]),
            ("economia", "Economía · mercados, energía, cripto", FAMILIES["Economía"]),
            ("war", "⚔ WAR · guerra y geopolítica", DOMAIN_GROUPS["war"]),
            ("conflicto", "Conflicto · guerra, disturbios, vuelos militares", FAMILIES["Conflicto"]),
            ("crimen", "Crimen · terrorismo, crimen urbano, sanciones", FAMILIES["Crimen"]))]
    except Exception as e:
        log.warning(f"[JARVIS] paneles: {type(e).__name__}: {e}")
        famstats, themes = {"groups": [], "stats": {}}, []

    # ── ★ Paneles nuevos de JARVIS: salud de fuentes · correlaciones · tendencia por familia · movimiento militar ──
    try:
        _srcs_all = list(SOURCES)
        _ok = _warn = _open = _idle = _nokey = _empty = 0
        _worst = []
        for _s in _srcs_all:
            _h = SOURCE_HEALTH.get(_s); _l = SOURCE_LAST.get(_s) or {}
            _err = str(_l.get("err") or "")
            if _h is None and not _l:
                _idle += 1; continue
            if "sin clave" in _err or "falta la API key" in _err:
                _nokey += 1; continue
            if circuit_is_open(_s):
                _open += 1; _worst.append({"name": _s, "err": _err[:110] or "circuit breaker abierto", "st": "open"}); continue
            if _err and not _l.get("n"):
                _warn += 1; _worst.append({"name": _s, "err": _err[:110], "st": "warn"}); continue
            _ok += 1
            if not _l.get("n"):
                _empty += 1
        _tot_ok = sum(h["ok"] for h in SOURCE_HEALTH.values()); _tot_fail = sum(h["fail"] for h in SOURCE_HEALTH.values())
        health = {"total": len(_srcs_all), "ok": _ok, "warn": _warn, "open": _open, "idle": _idle, "nokey": _nokey, "empty": _empty,
                  "pct": round(100.0 * _tot_ok / max(1, _tot_ok + _tot_fail), 1), "worst": _worst[:8]}
    except Exception as e:
        log.warning(f"[JARVIS] salud: {type(e).__name__}: {e}"); health = {}
    try:
        _cdf = db_query_correlations(hours=hours, min_score=0, limit=12)
        corr_live = [{"a": _DOM_LABEL(str(r["domain_a"])), "b": _DOM_LABEL(str(r["domain_b"])), "sa": str(r["source_a"])[:24], "sb": str(r["source_b"])[:24],
                      "score": int(r["score"]), "la": float(r["lat"]), "lo": float(r["lon"]), "t": str(r["timestamp"])[:16].replace("T", " ")}
                     for r in _cdf.to_dict("records")]
    except Exception as e:
        log.warning(f"[JARVIS] correlaciones: {type(e).__name__}: {e}"); corr_live = []
    try:
        trend = []
        _n = min(B, 8)
        for _f, _ser in series.items():
            _y = np.array(_ser[-_n:], dtype=float)
            if len(_y) < 3:
                continue
            _x = np.arange(len(_y), dtype=float)
            _m = float(np.polyfit(_x, _y, 1)[0]) if _y.any() else 0.0
            _proj = max(0.0, float(_y[-3:].mean()) + _m)
            _prev_avg = float(np.array(_ser[:-_n], dtype=float).mean()) if len(_ser) > _n else float(_y.mean())
            _rec = float(_y.mean())
            trend.append({"f": _f, "now": int(_y[-1]), "avg": round(_rec, 1), "base": round(_prev_avg, 1),
                          "pct": round(100.0 * (_rec - _prev_avg) / max(_prev_avg, 1.0), 0), "proj": round(_proj, 1),
                          "dir": "up" if _m > 0.15 * max(1.0, _rec) else ("dn" if _m < -0.15 * max(1.0, _rec) else "flat"), "spark": [int(v) for v in _ser[-12:]]})
    except Exception as e:
        log.warning(f"[JARVIS] tendencia: {type(e).__name__}: {e}"); trend = []
    try:
        def _mil_block(c_, p_, mask_fn, uniq_air=False):
            mc = c_[mask_fn(c_)] if not c_.empty else c_
            mp = p_[mask_fn(p_)] if not p_.empty else p_
            if uniq_air:                                     # un avión = UNO, aunque lo hayan visto en 20 barridos (hex ICAO; si no, indicativo+tipo)
                def _ukey(d_):
                    if d_.empty:
                        return d_
                    k_ = d_["tags"].fillna("").astype(str).str.extract(r"(?:^|,)hex:([0-9A-Fa-f]+)", expand=False)
                    k_ = k_.fillna(d_["title"].fillna("").astype(str))
                    return d_.assign(_k=k_).sort_values("id", ascending=False).drop_duplicates("_k")
                mc, mp = _ukey(mc), _ukey(mp)
            lat = [{"t": _str(r.get("title"))[:90], "src": _str(r.get("source")), "la": float(_num(r.get("lat"))), "lo": float(_num(r.get("lon"))),
                    "id": int(_num(r.get("id"))), "sev": _str(r.get("severity"))}
                   for r in (mc.sort_values("id", ascending=False).head(6).to_dict("records") if not mc.empty else [])]
            return {"n": int(len(mc)), "prev": int(len(mp)), "latest": lat}
        _tg = lambda d_: d_["tags"].fillna("").astype(str)
        military = {
            "flights": _mil_block(cur, prev, lambda d_: d_["domain"] == "vuelo_militar", uniq_air=True),
            "ships": _mil_block(cur, prev, lambda d_: (d_["domain"] == "maritimo") & _tg(d_).str.contains("militar", regex=False)),
            "ships_all": int((cur["domain"] == "maritimo").sum()) if not cur.empty else 0}
    except Exception as e:
        log.warning(f"[JARVIS] militar: {type(e).__name__}: {e}"); military = {}

    cnt = _attack_counts(cur)
    tact = {tid: 0 for tid, _, _ in ATTACK_TACTICS}
    for tid, c in cnt.items():
        tact[ATTACK_TECHNIQUES[tid][0]] += c
    techs = sorted(({"id": k, "name": ATTACK_TECHNIQUES[k][1], "tactic": ATTACK_TECHNIQUES[k][0], "n": v}
                    for k, v in cnt.items()), key=lambda x: -x["n"])[:12]

    countries = country_risk(cur, 8)
    srcs = [] if cur.empty else [{"name": k, "n": int(v)} for k, v in cur["source"].value_counts().head(8).items()]
    sev = {} if cur.empty else {k: int(v) for k, v in cur["severity"].value_counts().items()}
    latest = []
    if not cur.empty:
        top = cur[cur["severity"].isin(["CRITICA", "ALTA"])].sort_values("id", ascending=False).head(14)
        for r in top.to_dict("records"):
            latest.append({"sev": r["severity"], "src": _str(r["source"]), "t": _str(r["title"])[:90], "d": _str(r["domain"])})
    try:
        extra = _hud_extras(cur, prev, hours, score, pscore, level)
    except Exception as e:           # el panel nunca debe romperse por estos añadidos
        log.warning(f"[JARVIS] extras: {type(e).__name__}: {e}")
        extra = {"movers": [], "corridors": [], "groups": [], "reading": [], "sections": []}
    # ── ★ Comparar: ahora vs tramo anterior vs misma ventana hace 7 días (mismos 24 cubos) ──
    try:
        def _bucketed(df_, t0):
            arr = [0] * B; fam = {f: [0] * B for f in FAMILIES}
            if df_ is not None and not df_.empty:
                tt = _dt(df_["timestamp"])
                ix = ((tt - t0) / step).astype("float").clip(0, B - 1e-9)
                for d_, i_, ok_ in zip(df_["domain"], ix, tt.notna()):
                    if not ok_ or i_ != i_:
                        continue
                    arr[int(i_)] += 1
                    f_ = _FAMILY_OF.get(d_)
                    if f_:
                        fam[f_][int(i_)] += 1
            return arr, fam
        def _between(t0_, t1_):
            c_ = db_conn()
            try:
                d_ = pd.read_sql("SELECT timestamp, domain FROM events WHERE timestamp >= ? AND timestamp < ? LIMIT 60000", c_, params=(t0_.isoformat(), t1_.isoformat()))
            finally:
                c_.close()
            return d_[d_["domain"].isin(domains)] if domains else d_
        w0 = start - timedelta(days=7)
        cur_t, cur_f = _bucketed(cur, start)
        prv_t, prv_f = _bucketed(prev, start - timedelta(hours=hours))
        wk_t, wk_f = _bucketed(_between(w0, w0 + timedelta(hours=hours)), w0)
        compare = {"labels": labels, "now": cur_t, "prev": prv_t, "week": wk_t,
                   "tot": [sum(cur_t), sum(prv_t), sum(wk_t)],
                   "fam": [{"f": f_, "now": sum(cur_f[f_]), "prev": sum(prv_f[f_]), "week": sum(wk_f[f_])} for f_ in FAMILIES]}
    except Exception as e:
        log.warning(f"[JARVIS] comparar: {type(e).__name__}: {e}"); compare = {}
    # ── ★ Resumen en texto ampliado (qué sube · dónde mirar primero) ──
    try:
        rd = list(extra.get("reading") or [])
        up = sorted([t for t in trend if t["pct"] > 20 and t["avg"] >= 1], key=lambda t: -t["pct"])
        if up:
            rd.append("Sube más: " + ", ".join(f"{t['f']} (+{int(t['pct'])} %)" for t in up[:3]) + ".")
        if countries:
            rd.append(f"Dónde mirar primero: {countries[0]['name']}" + (f" y {countries[1]['name']}" if len(countries) > 1 else "") + " (mayor riesgo ponderado).")
        ncrit = int((cur["severity"] == "CRITICA").sum()) if not cur.empty else 0
        if ncrit:
            rd.append(f"{ncrit} evento(s) CRÍTICO(S) en la ventana.")
        if corr_live:
            c0 = corr_live[0]; rd.append(f"Correlación más fuerte: {c0['a']} ↔ {c0['b']} (puntuación {c0['score']}, {c0['t']} UTC).")
        if health.get("warn") or health.get("open"):
            rd.append(f"Fuentes: {health.get('ok', 0)} vivas, {health.get('warn', 0)} con fallo y {health.get('open', 0)} pausadas.")
        extra = {**extra, "reading": rd}
    except Exception as e:
        log.warning(f"[JARVIS] resumen: {type(e).__name__}: {e}")
    return {
        **extra,
        "hours": hours, "total": int(len(cur)), "prev_total": int(len(prev)),
        "threat": {"score": score, "prev": pscore, "level": level},
        "kpis": kpis, "labels": labels, "series": series, "families": fam_tot, "famstats": famstats, "themes": themes,
        "health": health, "corr_live": corr_live, "trend": trend, "military": military, "compare": compare,
        "tactics": [{"id": tid, "name": nm, "short": sh, "n": tact[tid]} for tid, nm, sh in ATTACK_TACTICS],
        "techniques": techs, "countries": countries, "sources": srcs, "severity": sev, "latest": latest,
        "generated": now.isoformat(),
    }

# ── Criptomonedas (top 10 por capitalización): CoinGecko y, si falla, CoinPaprika. Sin clave. Caché de 2 min ──
CRYPTO_CACHE: dict = {"ts": 0.0, "data": []}

def _parse_coingecko(rows: list) -> list[dict]:
    out = []
    for r in rows[:10]:
        out.append({"sym": _str(r.get("symbol")).upper(), "name": _str(r.get("name")), "price": _num(r.get("current_price")),
                    "c1h": r.get("price_change_percentage_1h_in_currency"), "c24h": r.get("price_change_percentage_24h_in_currency", r.get("price_change_percentage_24h")),
                    "c7d": r.get("price_change_percentage_7d_in_currency")})
    return out

def _parse_paprika(rows: list) -> list[dict]:
    out = []
    for r in rows[:10]:
        q = (r.get("quotes") or {}).get("USD") or {}
        out.append({"sym": _str(r.get("symbol")).upper(), "name": _str(r.get("name")), "price": _num(q.get("price")),
                    "c1h": q.get("percent_change_1h"), "c24h": q.get("percent_change_24h"), "c7d": q.get("percent_change_7d")})
    return out

async def fetch_crypto() -> list[dict]:
    if CRYPTO_CACHE["data"] and time.time() - CRYPTO_CACHE["ts"] < 120:
        return CRYPTO_CACHE["data"]
    data, err = [], []
    try:
        r = await _get("https://api.coingecko.com/api/v3/coins/markets", params={"vs_currency": "usd", "order": "market_cap_desc", "per_page": 10, "page": 1,
                       "sparkline": "false", "price_change_percentage": "1h,24h,7d"}, headers=RSS_HEADERS)
        data = _parse_coingecko(r.json())
    except Exception as e:
        err.append(f"coingecko: {type(e).__name__}")
    if not data:
        try:
            r = await _get("https://api.coinpaprika.com/v1/tickers", params={"quotes": "USD", "limit": 10}, headers=RSS_HEADERS)
            data = _parse_paprika(r.json())
        except Exception as e:
            err.append(f"coinpaprika: {type(e).__name__}")
    if data:
        def fx(v):
            try:
                return None if v is None else round(float(v), 2)
            except (TypeError, ValueError):
                return None
        for d in data:
            d["c1h"], d["c24h"], d["c7d"] = fx(d["c1h"]), fx(d["c24h"]), fx(d["c7d"])
        CRYPTO_CACHE.update(ts=time.time(), data=data)
        return data
    log.warning("[CRYPTO] sin datos: " + "; ".join(err))
    return CRYPTO_CACHE["data"]          # último valor conocido (puede estar vacío)

@app.get("/api/crypto")
async def api_crypto():
    d = await fetch_crypto()
    return {"coins": d, "updated": CRYPTO_CACHE["ts"], "stale": bool(d) and time.time() - CRYPTO_CACHE["ts"] > 300}


_ATTACK_DOMS = {"ddos", "malware", "bruteforce", "exploit", "ransomware", "phishing", "ciberataque", "cibercrimen", "vulnerabilidad"}

def ip_check(raw: str) -> dict:
    """¿Aparece esta IP en lo que NEXUS ha recogido? Eventos, listas de grupos y detecciones. Solo lectura."""
    try:
        addr = ipaddress.ip_address((raw or "").strip().strip("[]"))
    except ValueError:
        return {"error": "Eso no parece una IP válida (IPv4 o IPv6)."}
    ip = str(addr)
    rx = (re.compile(r"(?<![\d.])" + re.escape(ip) + r"(?!\d|\.\d)") if addr.version == 4
          else re.compile(r"(?<![0-9a-fA-F:])" + re.escape(ip) + r"(?![0-9a-fA-F:])", re.I))
    conn = db_conn()
    try:
        like = f"%{ip}%"
        rows = conn.execute("SELECT id,timestamp,domain,source,severity,title,description,url,lat,lon,entities FROM events "
                            "WHERE entities LIKE ? OR title LIKE ? OR description LIKE ? ORDER BY id DESC LIMIT 600", (like, like, like)).fetchall()
        gips = conn.execute("SELECT grp,kind,role,cc,source,url,conf,first_seen,last_seen,live_seen FROM group_ips WHERE ip=?", (ip,)).fetchall()
        dets = conn.execute("SELECT ts,grp,atype,source,title,url FROM group_detections WHERE title LIKE ? ORDER BY id DESC LIMIT 20", (like,)).fetchall()
    finally:
        conn.close()
    evs = [dict(r) for r in rows if rx.search(re.sub(r"\bip:", "ip ", f"{r['entities']} {r['title']} {r['description']}"))]
    dom_c = Counter(e["domain"] for e in evs); src_c = Counter(e["source"] for e in evs); sev_c = Counter(e["severity"] for e in evs)
    ts = sorted(e["timestamp"] for e in evs)
    groups = [dict(g) for g in gips]
    found = bool(evs or groups or dets)
    notes = []
    if addr.is_private or addr.is_loopback or addr.is_link_local:
        notes.append("Es una IP privada/local: no aparece en fuentes públicas. Para saber si tu conexión está señalada, busca tu IP pública.")
    if found:
        if any(d in _ATTACK_DOMS for d in dom_c) or groups:
            notes.append("Ojo: las fuentes de NEXUS suelen listar IPs ORIGEN de ataques o infraestructura comprometida (botnets, C2, escaneo). "
                         "Que aparezca no significa que seas víctima: puede significar que tu IP (o un dispositivo de tu red) está señalada como emisora.")
        else:
            notes.append("Aparece mencionada en eventos recogidos; revisa el contexto de cada uno.")
        verdict = "REGISTRADA"
    else:
        verdict = "SIN REGISTROS"
        notes.append("No aparece en lo que NEXUS tiene guardado (ventana de retención limitada). Eso NO garantiza que esté limpia: solo que estas fuentes no la han listado.")
    return {"ip": ip, "verdict": verdict, "found": found, "n_events": len(evs), "first": ts[0] if ts else "", "last": ts[-1] if ts else "",
            "domains": dom_c.most_common(8), "sources": src_c.most_common(8), "severities": dict(sev_c),
            "events": [{"id": e["id"], "ts": e["timestamp"], "d": e["domain"], "src": e["source"], "sev": e["severity"], "t": _str(e["title"])[:140],
                        "u": _safe_url(e["url"]), "la": e["lat"], "lo": e["lon"]} for e in evs[:25]],
            "groups": [{k: _str(v) for k, v in g.items()} for g in groups[:15]],
            "detections": [{k: _str(v) for k, v in dict(d).items()} for d in dets[:10]], "notes": notes}

