@app.get("/api/myip")
async def api_myip():
    """IP pública de la máquina donde corre NEXUS (si NEXUS corre en tu equipo, es la tuya)."""
    for url in ("https://api.ipify.org?format=json", "https://ipv4.icanhazip.com"):
        try:
            r = await HTTP.get(url, timeout=8)
            t = r.text.strip()
            try:
                t = r.json().get("ip", t)
            except Exception:
                pass
            ipaddress.ip_address(t)
            return {"ip": t}
        except Exception:
            continue
    return {"ip": "", "error": "No se pudo averiguar tu IP pública (sin salida a internet o servicio caído)."}

@app.get("/api/corr_related")
async def api_corr_related(lat: float, lon: float, da: str = "", sa: str = "", db: str = "", sb: str = "", hours: int = 24):
    """Eventos que forman una correlación: mismos dominios/fuentes y a menos de CORR_MAX_DIST_DEG del centro."""
    def work() -> dict:
        out = []
        for dom, src in ((da, sa), (db, sb)):
            if not dom:
                continue
            df = db_query_events(hours=max(1, min(hours, 720)), domains=[dom], limit=3000)
            if df.empty:
                continue
            df = df[df["source"] == src] if src and (df["source"] == src).any() else df
            df = df.assign(_d=np.hypot(df["lat"].astype(float) - lat, df["lon"].astype(float) - lon))
            df = df[df["_d"] <= CORR_MAX_DIST_DEG + 0.5].sort_values("_d").head(12)
            for r in df.to_dict("records"):
                out.append({"id": int(r["id"]), "la": float(r["lat"]), "lo": float(r["lon"]), "d": r["domain"], "src": _str(r["source"]),
                            "sev": _str(r["severity"]), "t": _str(r["title"])[:120], "u": _safe_url(r.get("url")), "side": "a" if dom == da else "b"})
        return {"points": out, "radius_deg": CORR_MAX_DIST_DEG}
    return await asyncio.to_thread(work)

