@app.get("/partial/attack", response_class=HTMLResponse)
async def partial_attack(hours: int = 24, domain: str = "", group: str = "", severity: str = "", q: str = ""):
    domains, severities = _filters(domain, severity, group)
    df = db_query_events(hours=hours, domains=domains or CYBER_DOMAINS, severities=severities, limit=8000)
    cnt = _attack_counts(df)
    mx = max(cnt.values()) if cnt else 1
    tactics = []
    for tid, nm, _ in ATTACK_TACTICS:
        techs = sorted(((k, v) for k, v in cnt.items() if ATTACK_TECHNIQUES[k][0] == tid), key=lambda x: -x[1])
        tactics.append({"id": tid, "name": nm, "n": sum(v for _, v in techs), "techs": [
            {"id": k, "name": ATTACK_TECHNIQUES[k][1], "n": v, "pct": max(4, int(100 * v / mx))} for k, v in techs]})
    tactics.sort(key=lambda t: -t["n"])
    return PARTIAL_ATTACK.render(tactics=tactics, total=sum(cnt.values()))

