@db_write
def db_reset_data() -> dict:
    """Borra los datos acumulados (eventos no protegidos, correlaciones, anomalías, barridos…). NUNCA toca: intel de cibercrimen,
    registro de IPs de grupos, detecciones, nombres de grupos, caché de geolocalización, ajustes ni auditoría."""
    conn = db_conn()
    out = {}
    try:
        keep = protected_events_sql()
        out["eventos_borrados"] = conn.execute(f"DELETE FROM events WHERE NOT {keep}").rowcount
        out["eventos_conservados"] = conn.execute("SELECT COUNT(*) FROM events").fetchone()[0]
        for t in ("correlations", "anomalies", "sweeps", "source_health", "group_candidates"):
            out[t] = conn.execute(f"DELETE FROM {t}").rowcount
        conn.commit()
        try:
            conn.execute("PRAGMA wal_checkpoint(TRUNCATE)")
        except Exception:
            pass
    finally:
        conn.close()
    return out

@app.post("/api/admin/reset")
async def api_admin_reset(request: Request, user: str = Depends(require_user_or_local)):
    try:
        body = await request.json()
    except Exception:
        body = {}
    if str((body or {}).get("confirm", "")).strip().upper() != "BORRAR":
        raise HTTPException(400, "Falta la confirmación: escribe BORRAR")
    if SWEEP_LOCK.locked():
        raise HTTPException(409, "Hay un barrido en curso: espera a que termine y repite")
    async with SWEEP_LOCK:           # nada se escribe mientras se borra
        res = await asyncio.to_thread(db_reset_data)
        CIRCUIT_OPEN.clear(); SOURCE_LAST.clear()
        for h in SOURCE_HEALTH.values():
            h.update(ok=0, fail=0, last_ok=None, last_fail=None, avg_ms=0)
        DOMAIN_TREND.clear()
        SWEEP_STATE.update(last_result=None, last_error=None, source_errors=[])
    db_audit(user, "reset_datos", json.dumps(res))
    log.warning(f"[RESET] datos borrados por {user}: {res}")
    try:
        await WS_MGR.broadcast({"type": "reset"})
    except Exception:
        pass
    return {"ok": True, **res, "modo_proteccion": KEEP_CYBER}

