# ★ NUEVO: búsqueda facetada
@app.get("/api/search")
async def api_search(
    q: str = "",
    hours: int = 24,
    domain: str = "",
    severity: str = "",
    entity: str = "",
    min_relevance: float = 0.0,
    limit: int = 200,
):
    df = db_query_events(
        hours=hours,
        domains=[domain] if domain else None,
        severities=[severity] if severity else None,
        search=q or None,
        limit=limit,
    )
    if df.empty:
        return JSONResponse([])

    if entity:
        df = df[df["entities"].fillna("").str.contains(rf"\b{re.escape(entity)}\b", regex=True)]
    if min_relevance > 0 and not df.empty:
        df = df.copy()
        df["relevance"] = df.apply(lambda r: relevance_score(r.to_dict()), axis=1)
        df = df[df["relevance"] >= min_relevance]
    return JSONResponse(_records(df))


