@app.get("/api/entities")
async def api_entities(hours: int = 24, top: int = 30):
    df = db_query_events(hours=hours, limit=5000)
    if df.empty:
        return JSONResponse({"entities": []})
    counts: dict[str, int] = defaultdict(int)
    for s in df["entities"].fillna(""):
        for e in str(s).split(","):
            e = e.strip()
            if e:
                counts[e] += 1
    ranked = sorted(counts.items(), key=lambda x: -x[1])[:top]
    return JSONResponse({"entities": [{"name": k, "count": v} for k, v in ranked]})


