# ── EXPORTACIÓN ──────────────────────────────────────────────────────────────────────────────────────────
# /export/<formato>?hours=&domain=&group=&severity=&q=&limit=   (usa los MISMOS filtros que el panel; el menú los pasa solo)
# Formatos: csv · json · ndjson · geojson · kml · markdown · html · xlsx · ips · grupos_csv · grupos_json · zip (paquete)
EXPORT_LABELS = {"csv": "CSV", "json": "JSON", "ndjson": "NDJSON (1 evento por línea)", "geojson": "GeoJSON", "kml": "KML",
                 "markdown": "Markdown", "html": "Informe HTML", "xlsx": "Excel (.xlsx)", "ips": "Lista de IPs (.txt)",
                 "grupos_csv": "IPs de grupos (CSV)", "grupos_json": "IPs de grupos (JSON)", "zip": "Paquete ZIP (csv+json+geojson+md)"}

def _dl(data, filename: str, media: str) -> Response:
    if isinstance(data, str):
        data = data.encode("utf-8")
    return Response(content=data, media_type=media, headers={
        "Content-Disposition": f'attachment; filename="{filename}"', "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff"})

def _json_bytes(obj) -> bytes:
    return json.dumps(obj, ensure_ascii=False, default=str, indent=1).encode("utf-8")

def _export_ips(df: pd.DataFrame, group_rows: list[dict]) -> str:
    found: dict = {}
    if not df.empty and "entities" in df.columns:
        for e in df["entities"].fillna(""):
            for x in str(e).split(","):
                if x.startswith("ip:"):
                    found.setdefault(x[3:], "evento")
    for r in group_rows:
        found[r["ip"]] = r["g"]
    return "\n".join(f"{ip}" for ip in sorted(found)) + "\n"

def _export_html(df: pd.DataFrame, corr: pd.DataFrame, title: str) -> str:
    esc_ = htmllib.escape
    rows = []
    for r in df.head(2000).to_dict("records"):
        rows.append("<tr>" + "".join(f"<td>{esc_(_str(r.get(c))[:200])}</td>" for c in ("timestamp", "severity", "domain", "source", "title")) + "</tr>")
    crow = "".join(f"<li>{esc_(_str(r.get('description')))}</li>" for r in corr.head(30).to_dict("records")) if not corr.empty else ""
    return (f"<!doctype html><meta charset='utf-8'><title>{esc_(title)}</title><style>body{{font:14px system-ui;margin:24px;background:#fff;color:#111}}"
            "table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccc;padding:4px 8px;text-align:left;vertical-align:top}th{background:#eee}</style>"
            f"<h1>{esc_(title)}</h1><p>{len(df)} eventos · {len(corr)} correlaciones · generado {datetime.now().strftime('%Y-%m-%d %H:%M')}</p>"
            f"<h2>Correlaciones</h2><ul>{crow}</ul><h2>Eventos</h2><table><tr><th>Fecha</th><th>Sev.</th><th>Dominio</th><th>Fuente</th><th>Título</th></tr>"
            + "".join(rows) + "</table>")

def _export_xlsx(df: pd.DataFrame, corr: pd.DataFrame, group_rows: list[dict]) -> bytes:
    import openpyxl                                   # opcional: pip install openpyxl
    wb = openpyxl.Workbook()
    def sheet(name, frame_rows, cols):
        ws = wb.create_sheet(name)
        ws.append(cols)
        for r in frame_rows:
            ws.append([("" if r.get(c) is None else (r.get(c) if isinstance(r.get(c), (int, float)) else str(r.get(c))[:32000])) for c in cols])
        ws.freeze_panes = "A2"
    wb.remove(wb.active)
    ecols = [c for c in ("timestamp", "severity", "domain", "source", "title", "description", "lat", "lon", "tags", "entities", "url") if c in df.columns]
    sheet("Eventos", _records(df), ecols)
    ccols = [c for c in ("timestamp", "type", "description", "severity") if c in corr.columns] if not corr.empty else ["description"]
    sheet("Correlaciones", _records(corr), ccols)
    sheet("IPs grupos", group_rows, ["g", "ip", "k", "r", "cc", "la", "lo", "f", "s", "u"])
    out = io.BytesIO(); wb.save(out)
    return out.getvalue()

def _build_export(fmt: str, hours: int, domain: str, group: str, severity: str, q: str, limit: int, hist: int):
    """(bytes, nombre, mime). Síncrono: se ejecuta en un hilo."""
    stamp = datetime.now().strftime("%Y%m%d_%H%M")
    df = pd.DataFrame()
    if fmt not in ("grupos_csv", "grupos_json"):
        domains, severities = _filters(domain, severity, group)
        df = db_query_events(hours=hours, domains=domains, severities=severities, search=q or None, limit=limit)
    if fmt == "csv":
        return df.to_csv(index=False).encode("utf-8-sig"), f"nexus_events_{stamp}.csv", "text/csv; charset=utf-8"
    if fmt == "json":
        return _json_bytes(_records(df)), f"nexus_events_{stamp}.json", "application/json"
    if fmt == "ndjson":
        return ("\n".join(json.dumps(r, ensure_ascii=False, default=str) for r in _records(df)) + "\n").encode("utf-8"), f"nexus_events_{stamp}.ndjson", "application/x-ndjson"
    if fmt == "geojson":
        return export_geojson(df).encode("utf-8"), f"nexus_events_{stamp}.geojson", "application/geo+json"
    if fmt == "kml":
        return export_kml(df).encode("utf-8"), f"nexus_events_{stamp}.kml", "application/vnd.google-earth.kml+xml"
    corr = db_query_correlations(hours=hours)
    if fmt == "markdown":
        return export_markdown(df, corr).encode("utf-8"), f"nexus_report_{stamp}.md", "text/markdown; charset=utf-8"
    if fmt == "html":
        return _export_html(df, corr, "NEXUS · Informe OSINT").encode("utf-8"), f"nexus_report_{stamp}.html", "text/html; charset=utf-8"
    grows = db_group_ips("", 20000, 0 if hist else GROUP_FRESH_HOURS)[0]
    if fmt == "ips":
        return _export_ips(df, grows).encode("utf-8"), f"nexus_ips_{stamp}.txt", "text/plain; charset=utf-8"
    if fmt == "grupos_json":
        return _json_bytes(grows), f"nexus_ips_grupos_{stamp}.json", "application/json"
    if fmt == "grupos_csv":
        return (pd.DataFrame(grows).rename(columns={"g": "grupo", "k": "tipo", "r": "rol", "cc": "pais", "la": "lat", "lo": "lon", "f": "estado(l=viva,h=historica)",
                "s": "fuente", "u": "url", "rep": "reportada", "h": "horas_desde_visto"}).to_csv(index=False).encode("utf-8-sig"),
                f"nexus_ips_grupos_{stamp}.csv", "text/csv; charset=utf-8")
    if fmt == "xlsx":
        return _export_xlsx(df, corr, grows), f"nexus_{stamp}.xlsx", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    if fmt == "zip":
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
            z.writestr("events.csv", df.to_csv(index=False).encode("utf-8-sig"))
            z.writestr("events.json", _json_bytes(_records(df)))
            z.writestr("events.geojson", export_geojson(df))
            z.writestr("report.md", export_markdown(df, corr))
            z.writestr("ips_grupos.json", _json_bytes(grows))
        return buf.getvalue(), f"nexus_paquete_{stamp}.zip", "application/zip"
    raise KeyError(fmt)

@app.get("/export/{fmt}")
async def export_any(fmt: str, hours: int = 24, domain: str = "", group: str = "", severity: str = "", q: str = "",
                     limit: int = 20000, hist: int = 0):
    fmt = fmt.lower().strip()
    if fmt not in EXPORT_LABELS:
        raise HTTPException(404, "Formato desconocido. Disponibles: " + ", ".join(EXPORT_LABELS))
    try:
        data, name, mime = await asyncio.to_thread(_build_export, fmt, max(1, min(int(hours), 2160)), domain, group, severity, q,
                                                   max(1, min(int(limit), 50000)), hist)
    except ImportError:
        raise HTTPException(501, "Para exportar a Excel instala openpyxl:  pip install openpyxl")
    except HTTPException:
        raise
    except Exception as e:
        log.exception("[EXPORT] fallo")
        raise HTTPException(500, f"Error al exportar: {type(e).__name__}: {e}")
    db_audit("local", "export", f"{fmt} {len(data)} bytes")
    return _dl(data, name, mime)


WS_OPEN = os.getenv("NEXUS_WS_OPEN", "").strip().lower() in ("1", "true", "si", "sí", "yes", "on")   # = comportamiento antiguo (sin comprobar nada)

def _ws_allowed(ws) -> bool:
    """/ws ya no acepta a cualquiera: (1) el Origin tiene que ser el propio servidor (una web ajena abierta en tu navegador no puede escuchar),
    (2) desde este equipo entra sin clave (igual que el resto del panel) y desde fuera hace falta usuario/clave o token."""
    origin = ws.headers.get("origin")
    if origin and urlparse(origin).netloc != ws.headers.get("host", ""):
        return False
    if LOCAL_NOAUTH and _is_local(ws):
        return True
    auth = ws.headers.get("authorization", "")
    try:
        if auth.lower().startswith("basic "):
            u, _, pw = base64.b64decode(auth[6:]).decode("utf-8", "replace").partition(":")
            return _safe_eq(u, ADMIN_USER) and _safe_eq(pw, ADMIN_PASSWORD) and not _default_pw_blocked(ws)
        if auth.lower().startswith("bearer "):
            return bool(verify_token(auth[7:].strip()))
    except Exception:
        pass
    return False

@app.websocket("/ws")
async def websocket_endpoint(ws: WebSocket):
    if not WS_OPEN and not _ws_allowed(ws):
        log.warning(f"[WS] conexión rechazada desde {ws.client.host if ws.client else '?'} (origen/credenciales); NEXUS_WS_OPEN=1 para permitirla")
        await ws.close(code=1008)
        return
    await WS_MGR.connect(ws)
    try:
        while True:
            await ws.receive_text()
    except WebSocketDisconnect:
        WS_MGR.disconnect(ws)


# ─── ★ NUEVO · Threat Jarvis X: asistente de voz/IA local, incrustado en el panel ───
# Es un proceso aparte (su propio puerto, sus propios modelos): Nexus solo le da un hueco en pantalla, le pasa el token y, si quieres,
# lo arranca/apaga desde el botón. Si Jarvis X no está, Nexus funciona igual. Todo configurable por variables de entorno:
#   TJX_URL (http://127.0.0.1:8765) · TJX_HOME (~/.threat_jarvis_x) · TJX_SCRIPT (junto a nexus.py) · TJX_PYTHON (intérprete con sus dependencias)
TJX_URL = os.getenv("TJX_URL", "http://127.0.0.1:8765").rstrip("/")
TJX_HOME = Path(os.getenv("TJX_HOME", str(Path.home() / ".threat_jarvis_x")))
TJX_SCRIPT = Path(os.getenv("TJX_SCRIPT", str(Path(__file__).resolve().with_name("Threat_Jarvis_X.py"))))
_TJX_PROC: dict = {"p": None}

def _tjx_host_port() -> tuple[str, int]:
    """Dirección de Jarvis X. Él anota en TJX_HOME/port el puerto que de verdad ha cogido (si el 8765 estaba ocupado usa otro)."""
    u = urlparse(TJX_URL)
    port = u.port or 80
    try:
        pp = int((TJX_HOME / "port").read_text(encoding="utf-8").strip())
        if 1024 <= pp <= 65535:
            port = pp
    except (OSError, ValueError):
        pass
    return (u.hostname or ""), port

def _tjx_base() -> str:
    host, port = _tjx_host_port()
    return f"{urlparse(TJX_URL).scheme or 'http'}://{host}:{port}"

def _tjx_up() -> bool:
    """¿Hay un Jarvis X escuchando? Se comprueba que quien responde se identifica como TJX (no otro programa en ese puerto)."""
    host, port = _tjx_host_port()
    try:
        with socket.create_connection((host, port), timeout=0.6) as sk:
            sk.settimeout(1.0)
            sk.sendall(f"GET /favicon.ico HTTP/1.0\r\nHost: {host}:{port}\r\n\r\n".encode())
            head = sk.recv(1024).decode("latin-1", "replace").lower()
            return "server: tjx" in head
    except OSError:
        return False

def _tjx_token() -> str:
    try:
        return (TJX_HOME / "token").read_text(encoding="utf-8").strip()
    except OSError:
        return ""

@app.get("/api/jarvisx/url")
async def api_jarvisx_url(request: Request, user: str = Depends(require_user_or_local)):
    """Estado de Jarvis X y la URL (con su token) para el <iframe>. Solo con sesión o desde este equipo; nunca se expone a webs ajenas."""
    if _tjx_host_port()[0] not in LOOPBACK_HOSTS:
        return JSONResponse({"up": False, "error": "TJX_URL debe apuntar a este equipo (127.0.0.1)"}, status_code=400)
    up = await asyncio.to_thread(_tjx_up)
    tok = _tjx_token() if up else ""
    if up and tok:                                    # puente: Jarvis X necesita saber en qué puerto está ESTE Nexus
        try:
            await HTTP.post(f"{_tjx_base()}/api/action", json={"action": "set_nexus", "url": str(request.base_url).rstrip("/")},
                            headers={"X-Token": tok}, timeout=2)
        except Exception:
            pass                                      # versión antigua de Jarvis X o sin respuesta: no es grave
    return {"up": bool(up and tok), "url": f"{_tjx_base()}/?t={quote(tok)}" if (up and tok) else "",
            "no_token": bool(up and not tok), "can_start": bool(TJX_SCRIPT.is_file() and not up),
            "cmd": f"python3 {TJX_SCRIPT.name} --no-browser"}

@app.post("/api/jarvisx/start")
async def api_jarvisx_start(request: Request, user: str = Depends(require_user_or_local)):
    """Arranca Threat_Jarvis_X.py en segundo plano (sin ventana de navegador) y le dice dónde está Nexus."""
    import subprocess, sys
    if _tjx_host_port()[0] not in LOOPBACK_HOSTS:
        raise HTTPException(status_code=400, detail="TJX_URL debe apuntar a este equipo")
    if await asyncio.to_thread(_tjx_up):
        return {"ok": True, "already": True}
    if not TJX_SCRIPT.is_file():
        raise HTTPException(status_code=404, detail=f"No encuentro {TJX_SCRIPT.name}: ponlo junto a nexus.py o define TJX_SCRIPT")
    pr = _TJX_PROC["p"]
    if pr is not None and pr.poll() is None:
        return {"ok": True, "starting": True}
    # Entorno mínimo: Jarvis X no necesita (ni debe heredar) las claves de Nexus; solo las suyas
    keep = {"VT_API_KEY", "ABUSEIPDB_API_KEY", "OTX_API_KEY", "NVD_API_KEY"}
    env = {k: v for k, v in os.environ.items()
           if k in keep or k.startswith("TJX_") or not (_SECRET_NAME_RX.search(k) or k in ("ADMIN_USER", "ADMIN_PASSWORD", "JWT_SECRET"))}
    env["NEXUS_URL"] = str(request.base_url).rstrip("/")
    env["TJX_EMBED_ORIGINS"] = env["NEXUS_URL"] + "," + env["NEXUS_URL"].replace("127.0.0.1", "localhost")
    try:
        TJX_HOME.mkdir(parents=True, exist_ok=True)
        logf = open(TJX_HOME / "jarvisx.log", "ab")
        _TJX_PROC["p"] = subprocess.Popen(
            [os.getenv("TJX_PYTHON") or sys.executable, str(TJX_SCRIPT), "--no-browser", "--port", str(urlparse(TJX_URL).port or 8765)],
            cwd=str(TJX_SCRIPT.parent), env=env, stdin=subprocess.DEVNULL, stdout=logf, stderr=logf, start_new_session=True)
    except Exception as e:
        log.warning(f"[JARVIS X] no arranca: {type(e).__name__}: {e}")
        raise HTTPException(status_code=500, detail=f"No se pudo arrancar: {type(e).__name__}")
    return {"ok": True, "starting": True}

@app.post("/api/jarvisx/stop")
async def api_jarvisx_stop(user: str = Depends(require_user_or_local)):
    """Apaga Jarvis X (libera Whisper, Piper y su servidor). Ollama lo libera por su cuenta al caducar el keep_alive."""
    if _tjx_host_port()[0] not in LOOPBACK_HOSTS or not await asyncio.to_thread(_tjx_up):
        return {"ok": True, "already": True}
    try:
        r = await HTTP.post(f"{_tjx_base()}/api/action", json={"action": "shutdown"}, headers={"X-Token": _tjx_token()}, timeout=5)
        return {"ok": r.status_code == 200}
    except Exception as e:
        raise HTTPException(status_code=502, detail=f"Jarvis X no responde: {type(e).__name__}")

@app.post("/api/shutdown")
async def api_shutdown(user: str = Depends(require_user_or_local)):
    """Apaga NEXUS por completo (libera el puerto). Botón «⏻ Apagar» del menú."""
    db_audit(user, "shutdown", "")
    asyncio.get_running_loop().call_later(0.6, lambda: os.kill(os.getpid(), signal.SIGINT))
    return {"status": "apagando"}


def _free_port(host: str, port: int) -> int:
    """Si el puerto está ocupado (p. ej. una instancia anterior que no se cerró) usa el siguiente libre."""
    for p in range(port, port + 25):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sk:
            sk.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                sk.bind((host, p))
                return p
            except OSError:
                continue
    return port


def _port_is_free(host: str, p: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sk:
        sk.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            sk.bind((host, p))
            return True
        except OSError:
            return False

def _who_has_port(p: int) -> str:
    """Quién ocupa el puerto (mejor esfuerzo, con `ss`). Sirve para ver si es un Nexus anterior que no se cerró."""
    try:
        import subprocess
        out = subprocess.run(["ss", "-ltnp", f"sport = :{p}"], capture_output=True, text=True, timeout=3).stdout.strip().splitlines()
        return out[-1].strip() if len(out) > 1 else ""
    except Exception:
        return ""

def _pid_on_port(port: int) -> Optional[int]:
    """PID del proceso que ESCUCHA en ese puerto (Linux, sin permisos especiales: lee /proc). None si no se puede saber."""
    inodes = set()
    for f in ("/proc/net/tcp", "/proc/net/tcp6"):
        try:
            lines = open(f).read().splitlines()[1:]
        except OSError:
            continue
        for ln in lines:
            c = ln.split()
            if len(c) > 9 and c[3] == "0A" and int(c[1].rsplit(":", 1)[1], 16) == port:   # 0A = LISTEN
                inodes.add(c[9])
    if inodes:
        for pid in (d for d in os.listdir("/proc") if d.isdigit()):
            try:
                for fd in os.listdir(f"/proc/{pid}/fd"):
                    try:
                        lk = os.readlink(f"/proc/{pid}/fd/{fd}")
                    except OSError:
                        continue
                    if lk.startswith("socket:[") and lk[8:-1] in inodes:
                        return int(pid)
            except OSError:
                continue
    m = re.search(r"pid=(\d+)", _who_has_port(port))          # plan B: `ss`
    return int(m.group(1)) if m else None

def _is_old_nexus(pid: int) -> tuple[bool, str]:
    """¿Es un Nexus (o un programa de esta misma carpeta) del mismo usuario? Así no se cierra nada ajeno. Devuelve (sí/no, descripción)."""
    try:
        cmd = open(f"/proc/{pid}/cmdline", "rb").read().replace(b"\0", b" ").decode("utf-8", "replace").strip()
        same_user = os.stat(f"/proc/{pid}").st_uid == os.getuid()
        try:
            same_dir = os.path.realpath(f"/proc/{pid}/cwd") == str(Path(__file__).resolve().parent)
        except OSError:
            same_dir = False
    except OSError:
        return False, ""
    low = cmd.lower()
    looks_nexus = any(k in low for k in ("nexus", "dg.py", Path(__file__).name.lower(), "threat_jarvis_x"))
    return (same_user and "python" in low and (looks_nexus or same_dir)), cmd[:140]

def _take_over_port(host: str, want: int, mode: str = "1") -> bool:
    """El puerto lo ocupa una instancia anterior: se cierra (SIGTERM; si no obedece, SIGKILL) y NEXUS se queda con el puerto.
    mode «1» = solo Nexus/programas de esta carpeta del mismo usuario · «force» = cualquier proceso tuyo · «0» = nunca."""
    import signal as _sg
    if mode == "0":
        return False
    pid = _pid_on_port(want)
    if not pid or pid in (os.getpid(), os.getppid()):
        return False
    ours, desc = _is_old_nexus(pid)
    if not ours and mode != "force":
        log.warning(f"[NEXUS] el puerto {want} lo tiene el proceso {pid} ({desc or 'desconocido'}) y no parece un Nexus: no lo toco.")
        return False
    log.warning(f"[NEXUS] el puerto {want} lo tenía una instancia anterior (pid {pid}: {desc}). La cierro y me quedo con el puerto.")
    for sig, wait in ((_sg.SIGTERM, 9.0), (_sg.SIGKILL, 3.0)):
        try:
            os.kill(pid, sig)
        except ProcessLookupError:
            break
        except PermissionError:
            log.error(f"[NEXUS] sin permiso para cerrar el proceso {pid}."); return False
        t0 = time.time()
        while time.time() - t0 < wait:
            if _port_is_free(host, want):
                return True
            time.sleep(0.25)
    return _port_is_free(host, want)

def _claim_port(host: str, want: int, strict: bool = True, wait_s: float = 10.0) -> int:
    """NEXUS vive SIEMPRE en su puerto (8000): Jarvis X y el resto de piezas cuentan con él.
    Si lo ocupa un Nexus anterior (el caso típico: una ejecución que se quedó abierta) lo cierra y toma el puerto.
    Si lo ocupa otra cosa, espera unos segundos y, si sigue ocupado, para con un mensaje claro en vez de saltar a otro puerto.
    NEXUS_PORT_TAKEOVER: 1 (por defecto) solo cierra Nexus · force = cierra cualquier proceso tuyo que lo ocupe · 0 = no cierra nada.
    NEXUS_PORT_STRICT=0: comportamiento antiguo (usar el siguiente puerto libre)."""
    if not strict:
        return _free_port(host, want)
    if _port_is_free(host, want):
        return want
    if _take_over_port(host, want, os.getenv("NEXUS_PORT_TAKEOVER", "1").strip().lower()):
        return want
    t0, warned = time.time(), False
    while not _port_is_free(host, want):
        if not warned:
            log.warning(f"[NEXUS] el puerto {want} está ocupado: espero hasta {int(wait_s)} s por si se está liberando…")
            warned = True
        if time.time() - t0 >= wait_s:
            who = _who_has_port(want)
            log.error(f"[NEXUS] el puerto {want} sigue ocupado" + (f" por: {who}" if who else "") + f". NEXUS tiene que usar el {want}. "
                      "Si es un programa tuyo que quieres cerrar: NEXUS_PORT_TAKEOVER=force en el .env (cierra ese proceso al arrancar). "
                      "Si de verdad quieres otro puerto: NEXUS_PORT=<puerto>.")
            raise SystemExit(1)
        time.sleep(0.5)
    return want


if __name__ == "__main__":
    import uvicorn, threading
    host = os.getenv("NEXUS_HOST", "127.0.0.1")
    want = int(os.getenv("NEXUS_PORT", "8000"))
    port = _claim_port(host, want, os.getenv("NEXUS_PORT_STRICT", "1") != "0")
    if port != want:
        log.warning(f"[NEXUS] el puerto {want} estaba ocupado: uso el {port}")
    log.info(f"[NEXUS] abre http://{host}:{port}")
    server = uvicorn.Server(uvicorn.Config(app, host=host, port=port, log_level="info", timeout_graceful_shutdown=4))

    def _stop(signum=None, frame=None):
        # Cerrar la terminal (SIGHUP), kill (SIGTERM) o Ctrl+C: parada ordenada y, si algo queda colgado, se fuerza
        server.should_exit = True
        t = threading.Timer(8.0, lambda: os._exit(0)); t.daemon = True; t.start()

    for _sig in (getattr(signal, "SIGHUP", None), getattr(signal, "SIGTERM", None)):
        if _sig is not None:
            try:
                signal.signal(_sig, _stop)
            except (ValueError, OSError):
                pass
    try:
        server.run()
    finally:
        log.info("[NEXUS] cerrado: puerto liberado")
        os._exit(0)     # ningún hilo residual (scheduler, Telegram) mantiene vivo el proceso ni el puerto
